/* ÇEVİRİ fr · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("fr","olay",{
"KRONOLOJI_COK_ARABISTAN2:1538-01-01:0":{"b": ["Le Hadramaout devient un sandjak ottoman — l'administration intérieure reste aux chefs kathiris", "d80f8d20"], "d": ["Le Hadramaout, passé sous administration ottomane lors de l'expédition de Hadım Süleyman Pacha aux Indes, fut organisé en sandjak rattaché au Yémen. Mais, à l'intérieur du Hadramaout, ce sont les chefs de la tribu kathirie qui gardèrent de fait l'administration ; l'autorité ottomane resta limitée à la côte et au lien fiscal.", "93dd8a13"]},
"KRONOLOJI_COK_ARABISTAN2:1659-01-01:0":{"b": ["L'imam zaydite al-Mutawakkil ala Allah envahit le Hadramaout — le sultanat kathiri est soumis à l'imamat du Yémen", "21ad9c85"], "d": ["Après le retrait ottoman du Yémen en 1635, l'imamat zaydite se renforça et, sous l'imam al-Mutawakkil ala Allah, envoya une armée qui envahit le Hadramaout. La domination des Kathiris dans l'intérieur du Hadramaout resta ainsi soumise à l'imamat yéménite pendant près d'un demi-siècle ; lorsque l'influence des imams et des Kathiris s'affaiblit dans la première moitié du XVIIIe siècle, l'administration revint aux tribus locales.", "e5a06ff4"]},
"KRONOLOJI_COK_ARABISTAN2:1835-01-01:0":{"b": ["Abdallah ibn Rachid enlève l'émirat de Haïl à la famille Ibn Ali — fondation de l'émirat de Shammar (Rachidi)", "357cc1a0"], "d": ["Abdallah ibn Rachid, de la branche Abde, la plus importante de la tribu des Shammar, remporta en 1835 la lutte qu'il avait engagée avec son frère Ubayd contre la famille Ibn Ali, qui gouvernait Haïl, et s'empara de l'émirat. Grâce à sa position sur la route commerciale et de pèlerinage entre la Mésopotamie et le Hedjaz, Haïl devint le centre de la domination rachidide sur le Djebel Shammar, qui dura jusqu'en 1921.", "dc0300b5"]},
"OLAYLAR:1299-01:0":{"b": ["Fondation de la principauté ottomane", "9f0b7c0a"], "d": ["Le fait qu'Osman Gazi, de la tribu des Kayı, ait commencé à agir de manière indépendante dans la région de Söğüt et de Domaniç est tenu pour le point de départ traditionnel de la fondation de l'État ottoman ; certains historiens considèrent la victoire de Bapheus, en 1302, comme le véritable tournant. Grâce à sa position dans la zone marchesque byzantine, la principauté gagna rapidement en puissance par ses raids de ghaza. Dans ce contexte de dissolution de l'héritage seldjoukide, Osman Gazi rassembla autour de lui des ahis, des ghazis et des Turkmènes nomades ; le lien qu'il noua avec le cheikh Edebali est considéré comme le fondement de la légitimité spirituelle de la principauté. Autres lieux rattachés à la même date : İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Prise de Bursa", "98c727fa"], "d": ["Bursa, tenue en état de blocus pendant des années, se rendit à Orhan Gazi, qui dirigeait la phase finale du siège ; la ville devint la première grande capitale de la principauté. On rapporte que la nouvelle de la conquête fut portée à Osman Gazi sur son lit de mort ; conformément à son testament, Osman Gazi fut enterré à Bursa. La ville fut rapidement dotée de mosquées, d'imarets et de médersas, et devint le modèle de l'urbanisme ottoman des origines.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Prise de Nicée", "a846a811"], "d": ["Nicée (İznik, Nikaia), l'un des centres les plus importants de Byzance en Anatolie, perdit tout espoir de résister après la victoire de Pelekanon en 1329 et se rendit à Orhan Gazi. La première médersa ottomane y fut fondée et des savants tels que Dâvûd-i Kayserî commencèrent à y enseigner ; la ville devint le centre intellectuel de la période initiale. L'église Sainte-Sophie fut transformée en mosquée, offrant un des premiers exemples de la tradition de la conquête.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Prise d'İzmit", "06a35035"], "d": ["Avec la chute d'İzmit (Nicomédie), la dernière grande forteresse byzantine de la rive anatolienne passa elle aussi sous l'administration ottomane ; toute la péninsule de Kocaeli, jusqu'à la rive opposée de Constantinople, devint terre ottomane. La principauté, qui dominait ainsi l'ensemble des côtes sud et est de la Marmara, préparait de la sorte les bases de son passage en Roumélie.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Forteresse de Çimpe — passage en Roumélie", "c2f0a07d"], "d": ["Süleyman Pacha, fils d'Orhan Gazi, avait pris pour base en 1352 la forteresse de Çimpe, qui lui avait été donnée lors de la guerre civile byzantine ; après le grand tremblement de terre qui ruina Gallipoli en mars 1354, les forteresses évacuées furent rapidement fortifiées et la péninsule fut transformée en une tête de pont ottomane durable. Soutenue par l'installation de populations turkmènes amenées d'Anatolie, cette étape marque le début d'une présence ottomane sur le continent européen qui devait dépasser les 550 ans.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Prise d'Andrinople (Edirne)", "2f54ebb0"], "d": ["La prise d'Edirne (Andrinople, Adrianopolis), ville clé de la Thrace, détermina la base principale et l'orientation des conquêtes balkaniques ; la date de la conquête est discutée dans les sources, entre 1361 et 1369. La ville fut peu après érigée en capitale, proclamant que le centre de gravité de l'État s'était déplacé vers la Roumélie ; elle resta le siège du pouvoir (payitaht) pendant environ 90 ans, jusqu'à la prise de Constantinople.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Avènement de Murad Ier", "f8d48a26"], "d": ["Murad Ier (Hüdavendigâr), monté sur le trône à la mort d'Orhan Gazi, fit passer l'État, au cours de ses 27 années de règne, du statut de principauté marchesque à celui de charpente d'un empire. Avec le système du pençik, les bases du corps des janissaires furent posées, le régime du timar fut généralisé, le beylerbeylik de Roumélie fut créé et l'institution du vizirat fut renforcée. Les conquêtes balkaniques devinrent sous son règne une politique d'État systématique.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Première bataille de Kosovo — martyre de Murad Ier", "10b8ddc9"], "d": ["La coalition balkanique conduite par le knez Lazar fut définitivement vaincue dans la plaine de Kosovo ; la Serbie passa sous la suzeraineté ottomane. Murad Ier, qui parcourait le champ de bataille, fut poignardé par le noble serbe Miloš Obilić et tomba en martyr — il est le seul sultan ottoman mort sur un champ de bataille. Bayezid le Foudre fut mis à sa place dans le camp ; son frère Yakub Çelebi fut étranglé, ce qui constitue l'un des premiers exemples connus de la pratique du fratricide.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Victoire de Nicopolis", "75716e96"], "d": ["La grande armée croisée, réunie à l'appel du roi de Hongrie Sigismond et à laquelle participaient aussi des chevaliers français et bourguignons, fut lourdement défaite par Bayezid le Foudre devant Nicopolis, sur les bords du Danube. La victoire consolida la domination ottomane sur la Bulgarie ; pendant toute une génération, aucune grande croisade ne put être organisée en Europe.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Bataille d'Ankara — début de l'Interrègne", "b4a99d96"], "d": ["Dans la lourde défaite subie dans la plaine de Çubuk face à l'armée de Tamerlan, Bayezid le Foudre fut fait prisonnier et mourut en captivité quelques mois plus tard. Tamerlan fit renaître les principautés d'Anatolie ; les terres ottomanes furent morcelées entre les fils de Bayezid, et une lutte pour le trône qui devait durer 11 ans (l'Interrègne, Fetret Devri) commença. Cette période, la crise la plus grave que l'État ait connue depuis sa fondation, grava dans la mémoire ottomane l'importance de la structure centralisée. Autres établissements perdus à la même date : Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, la forteresse d'Aydos, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, l'île d'İmralı, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, Nicée (İznik), İzmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Stara Zagora (Eski Zağra), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Gotse Delchev), Drama, Gallipoli (Gelibolu), Çimpe, Andrinople (Edirne), Dimetoka, Kırklareli, Tekirdağ, Plovdiv (Filibe), Sofia, Niš, Vidin, Tărnovo, Varna, Şumnu, Silistra, Nicopolis (Niğbolu), Roussé (Rusçuk), Thessalonique, Serrès, Kavala, Skopje (Üsküp), Monastir, Ohrid, Yenişehir (Larissa), Trikala (Tırhala), Izdin (Lamia), Plevne, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M. Kemalpaşa), Mihaliç (Karacabey), Köstence, Gölyazı (Apollonia).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Çelebi Mehmed rétablit l'unité", "03413dfd"], "d": ["Dans le dernier règlement de comptes entre frères, Mehmed Ier, qui vainquit Mûsâ Çelebi à Çamurlu, réunit les terres du pays sous une seule autorité ; c'est pourquoi on le considère comme le « second fondateur de l'État ». Sous son règne, la structure usée de l'État fut réparée, les relations avec les beyliks d'Anatolie furent équilibrées et une politique de paix prudente fut suivie en Roumélie. Autres localités revenues, à la même date, de l'Interrègne à l'administration ottomane sur la carte : Absu (Hypsu), Adranos (Orhaneli), Akhisar (Pamukova).", "45315d2d"]},
"OLAYLAR:1416-05-01:0":{"b": ["Révolte du cheikh Bedreddin", "e0a072ca"], "d": ["Le mouvement religieux et social qui se développa autour du cheikh Bedreddin, grand juriste et mystique qui avait exercé la charge de cadi-asker pendant l'Interrègne, éclata en même temps que les soulèvements de Börklüce Mustafa à Karaburun et de Torlak Kemal à Manisa. Les révoltes furent réprimées dans le sang ; Bedreddin, capturé dans le Deliorman, fut exécuté à Serrès. L'événement, premier grand soulèvement social et mahdiste de l'histoire ottomane, laissa une trace profonde dans la littérature et l'historiographie.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Victoire de Varna", "f739eedc"], "d": ["L'armée croisée hungaro-polonaise, qui avait rompu la paix de Szeged et s'était avancée vers le sud, fut anéantie à Varna par Murad II, qui avait abdiqué mais était revenu à la tête de l'armée ; le jeune roi Ladislas III périt sur le champ de bataille. La victoire écarta la dernière grande chance d'intervention extérieure visant à liquider la présence ottomane dans les Balkans et assura la voie menant à la prise de Constantinople.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Seconde bataille de Kosovo", "ebe0b662"], "d": ["L'armée de János Hunyadi, qui voulait venger Varna, fut définitivement vaincue par Murad II lors d'un combat acharné de trois jours. C'est la dernière grande bataille rangée que les croisés aient engagée dans les Balkans contre les Ottomans ; avec cette victoire, la domination ottomane au sud du Danube s'établit de manière irréversible.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Conquête de Constantinople", "583d5e3e"], "d": ["Après un siège de cinquante-quatre jours (6 avril–29 mai 1453), l'armée ottomane franchit les murailles au matin du 29 mai et entra dans la ville ; le dernier empereur, Constantin XI, périt au combat et l'Empire romain d'Orient, vieux de 1100 ans, disparut de l'histoire. Le jeune sultan prit le titre de « Fâtih » (le Conquérant), fit de la ville sa capitale et transforma Sainte-Sophie en mosquée ; la ville fut rapidement ranimée par le repeuplement et les constructions. Selon le TDV, Silivri et Vize ne furent définitivement conquises qu'en 1453 ; selon l'article Limni du TDV, l'île passa sous l'administration ottomane immédiatement après la conquête et fut laissée à la famille Gattilusio moyennant tribut. Dans l'atlas, Silivri, Vize et Limni sont inscrites à cette date comme passant de Byzance à l'Empire ottoman (Limni tributaire). La fonte de canons gigantesques, le transport des navires par voie de terre et le dispositif de siège devant les murailles sont considérés comme le sommet de l'ingénierie militaire de l'époque. Dans l'historiographie européenne, la conquête compte parmi les dates symboliques de la fin du Moyen Âge.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Prise de Trébizonde", "15f52403"], "d": ["À l'issue de la difficile campagne de la mer Noire que Mehmed le Conquérant mena simultanément par terre et par mer, l'Empire grec de Trébizonde se rendit ; avec la liquidation de ce dernier vestige du monde byzantin en Anatolie, toute la côte méridionale de la mer Noire passa sous la domination ottomane. La fin de la dynastie des Comnènes renforça la prétention du Conquérant au titre de « souverain des deux mers et des deux terres ». Autres lieux rattachés à la même date : Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Conquête définitive de Silifke — la dernière résistance des Karamanides brisée", "d988bee4"], "d": ["La forteresse de Silifke s'était rendue une première fois à Gedik Ahmed Pacha en 1472, mais la même année le Karamanoğlu Kasım Bey, avec l'aide de la flotte croisée en Méditerranée, l'avait reprise. Après la victoire d'Otlukbeli, le Conquérant chargea son fils et Gedik Ahmed Pacha de s'emparer définitivement de la région ; avec l'aide des anciens artilleurs ottomans, le dépôt de poudre fut incendié et la forteresse tomba rapidement. La dernière résistance des Karamanides dans les montagnes du Taşeli et de l'İçel fut ainsi brisée ; la liquidation de la principauté devait s'achever en 1474.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Bataille d'Otlukbeli", "42c7194e"], "d": ["Uzun Hasan, souverain des Aqqoyunlu devenu une grande puissance en Orient et allié de Venise, subit une lourde défaite à Otlukbeli face à l'armée du Conquérant équipée d'armes à feu. La victoire scella la suprématie ottomane en Anatolie ; elle fut aussi une preuve précoce de la supériorité d'une armée centralisée usant du canon et du fusil sur une armée classique. Selon l'article Gümüşhane du TDV, la ville était sous domination aqqoyunlu depuis 1467 ; cette domination prit fin avec la défaite d'Otlukbeli et Gümüşhane passa définitivement sous domination ottomane.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["Mise de la Crimée sous protection ottomane", "44e3f7c8"], "d": ["La flotte placée sous le commandement de Gedik Ahmed Pacha conquit les villes de la côte méridionale de la Crimée, à commencer par Caffa, aux mains de Gênes ; ces côtes furent érigées en sandjak ottoman direct. Le khanat de Crimée devint avec Mengli Giray un État vassal privilégié reconnaissant la suzeraineté ottomane, et fut pendant trois siècles la pierre angulaire de la politique ottomane dans le Nord ; la mer Noire se transformait désormais, de fait, en mer intérieure ottomane. Autres lieux rattachés à la même date : Bahçesaray, Kertch, Azak (Azov).", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Mort du Conquérant — l'affaire du prince Djem", "190ecf01"], "d": ["À la mort soudaine du Conquérant en campagne, Bayezid II monta sur le trône ; son frère, le prince Djem, revendiquant le sultanat, fit dire la khutba et frapper monnaie en son nom à Bursa. Vaincu, il se réfugia d'abord chez les Mamelouks, puis chez les chevaliers de Rhodes ; devenu entre les mains des chevaliers et de la papauté un atout de marchandage de la diplomatie européenne, Djem mourut à Naples en 1495. Cette affaire contraignit la politique extérieure ottomane à la prudence pendant quinze ans.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Victoire de Çaldıran", "fea64ebb"], "d": ["Désireux de résoudre à la racine la menace créée en Anatolie par la propagande séfévide, le sultan Selim le Terrible infligea une lourde défaite à l'armée du chah Ismaïl dans la plaine de Çaldıran, grâce à la supériorité de son artillerie et de ses fusils. Tabriz fut occupée ; l'Anatolie orientale et sud-orientale ainsi que la ligne Mossoul–Diyarbakır furent rattachées à l'administration ottomane. Le ralliement des beys kurdes à l'Empire ottoman, obtenu par les efforts d'İdrîs-i Bitlisî, établit le cadre de la frontière orientale pour des siècles.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Victoire de Mardj Dabiq", "07d254d3"], "d": ["L'armée mamelouke fut dispersée en quelques heures à Mardj Dabiq, au nord d'Alep ; le vieux sultan Qansuh al-Ghawri mourut pendant la bataille. Cette victoire, qui ouvrit grand les portes d'Alep et de Damas, fit passer la Syrie, le Liban et la Palestine sous l'administration ottomane ; la voie de la campagne d'Égypte, qui devait mettre fin à l'État mamelouk, était ouverte.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ridaniyya — conquête de l'Égypte et califat", "caf378d6"], "d": ["L'armée ottomane, qui avait rapidement traversé le désert du Sinaï, perça la ligne de défense de Tomanbay à Ridaniyya et entra au Caire ; Tomanbay, qui poursuivait la résistance, fut capturé et exécuté, et l'État mamelouk disparut de l'histoire. L'Égypte, le Hedjaz et les villes saintes passèrent sous l'administration ottomane ; le calife abbasside et les saintes reliques furent emmenés à Istanbul. Avec le passage du califat à la dynastie ottomane, les sultans assumèrent la prétention à la direction du monde islamique ; le contrôle de la route des épices procura aussi à l'Empire de grands revenus. Autres lieux rattachés à la même date : Acre, Ma'an, Sidon, Kerak.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Avènement de Soliman le Législateur", "f6512269"], "d": ["Soliman Ier, monté sur le trône à la mort de Selim le Terrible en tant que seul fils mâle, connut un règne de 46 ans considéré comme le sommet politique, militaire, juridique et culturel de l'Empire. Les kanunnâme qui systématisèrent le droit coutumier (örf) lui valurent le surnom de « Kanunî » (le Législateur) ; en Occident, on le désigna sous le nom de « Magnifique ». Les œuvres de l'architecte Sinan, l'âge d'or de la littérature de divan et la suprématie de la flotte en Méditerranée sont les symboles de cette période.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Prise de Belgrade", "59ef5cec"], "d": ["Belgrade, que le Conquérant n'avait pu prendre en 1456 et que l'on tenait pour la « clé de l'Europe centrale », tomba lors de la première campagne de Soliman, à la suite d'un siège au confluent du Danube et de la Save. La ligne de défense méridionale de la Hongrie s'effondrait ; cette conquête ouvrit la porte de la campagne d'Europe centrale qui devait mener, cinq ans plus tard, à Mohács et, vingt ans plus tard, à l'annexion de Bude.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Prise de Rhodes", "807bbb1e"], "d": ["Rhodes, base des chevaliers de Saint-Jean qui menaçaient les routes maritimes de la Méditerranée orientale et l'itinéraire du pèlerinage, se rendit par capitulation (vire) après un siège sanglant de plusieurs mois ; les chevaliers furent autorisés à quitter librement l'île (ils s'établirent par la suite à Malte). La sécurité des côtes anatoliennes fut assurée et la ligne maritime Istanbul–Égypte passa sous le contrôle ininterrompu des Ottomans.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Bataille de Mohács", "f3418b0d"], "d": ["L'armée hongroise fut anéantie en environ deux heures dans la plaine de Mohács par le tir des canons et la supériorité de manœuvre ; le roi Louis II mourut dans un marais en s'enfuyant. Mohács, l'une des grandes batailles rangées les plus rapidement gagnées de l'histoire ottomane, mit fin de fait au royaume indépendant de Hongrie et ouvrit en Europe centrale l'ère de la rivalité ottomano-habsbourgeoise.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Premier siège de Vienne", "dc49ea4f"], "d": ["Lors de la campagne menée contre la mainmise des Habsbourg sur le trône de Hongrie, l'armée ottomane assiégea Vienne ; à cause de l'abandon des canons lourds en chemin, de l'hiver précoce et des difficultés de ravitaillement, le siège fut levé au bout de trois semaines. Bien que la ville n'ait pu être prise, l'influence ottomane sur la Hongrie fut préservée ; les abords de Vienne marquèrent la limite d'accès logistique de l'Empire en Europe centrale.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Prise de Bagdad — campagne des Deux Irak", "897092c3"], "d": ["Lors de la campagne organisée contre les « Deux Irak » (Irak arabe et Irak persan), on entra d'abord à Tabriz, puis, sans combat, à Bagdad ; la prise de l'ancienne capitale des Abbassides valut au souverain ottoman un grand prestige dans le monde islamique. Le mausolée de l'imam Abû Hanîfa fut restauré ; avec le rattachement de Bagdad et de Bassora, les terres ottomanes atteignirent le golfe Persique. Autres lieux rattachés à la même date : Kirkouk, Kerbela.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Victoire navale de Préveza", "30dc0f97"], "d": ["La flotte croisée constituée sous la direction du pape, bien que supérieure en nombre, fut dispersée au large de Préveza par la tactique de Barberousse, qui utilisa habilement le vent et la côte ; Andrea Doria quitta le champ de bataille. La victoire établit pour environ 33 ans une suprématie navale ottomane incontestée en Méditerranée ; elle est la date symbolique de la fête de la marine dans la tradition maritime turque. Autres lieux rattachés à la même date : Aden, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Annexion de Bude — la Hongrie, province ottomane", "db53b244"], "d": ["Soliman, parti en campagne à la suite du siège de Bude par les Habsbourg, délivra la ville, puis plaça la Hongrie centrale sous administration ottomane directe en créant le beylerbeylik de Bude ; la Transylvanie fut faite principauté autonome vassale de l'Empire. Cette organisation de la Hongrie en trois parties dura environ 150 ans et constitua la charpente durable de l'administration ottomane en Europe centrale.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Paix d'Amasya", "a5afe0d1"], "d": ["C'est le premier traité de paix officiel qui mit fin aux guerres ottomano-séfévides de longues années. Bagdad et l'Irak restèrent à l'Empire ottoman, et la frontière de l'Anatolie orientale fut pour la première fois reconnue de part et d'autre ; les Séfévides s'engagèrent à cesser la propagande chiite dans les terres ottomanes, et les Ottomans à garantir la sécurité du passage des pèlerins iraniens. Le traité fut le premier exemple de cadre juridique des relations entre les deux États.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Szigetvár — mort de Soliman le Législateur", "e2917ed2"], "d": ["Soliman, âgé de 72 ans, mourut sous sa tente quelques heures avant la chute de la forteresse de Szigetvár, qu'il assiégeait lors de sa treizième campagne ; Sokollu Mehmed Pacha cacha sa mort pendant des semaines pour éviter la dispersion de l'armée. La forteresse fut prise, mais l'État avait perdu son sultan au règne le plus long et le plus éclatant ; son fils Selim II monta sur le trône et le poids des grands vizirs dans l'administration de l'État commença à croître.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Conquête de Chypre", "e364a2b3"], "d": ["Un débarquement eut lieu en 1570 sur Chypre, alors sous administration vénitienne ; Nicosie tomba rapidement, tandis que Famagouste ne se rendit qu'en août 1571, après un siège de onze mois. L'île, d'importance critique pour la sécurité des routes commerciales et des routes du pèlerinage de la Méditerranée orientale, fut organisée en beylerbeylik et peuplée de populations venues d'Anatolie ; la conquête fut aussi le motif de la grande alliance croisée qui aboutit à Lépante.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Défaite de Lépante (İnebahtı)", "6a1d44a9"], "d": ["La flotte croisée, unie à la suite de la conquête de Chypre, surprit la flotte ottomane dans le golfe de Lépante et en détruisit la plus grande partie ; le grand amiral (kapudan-ı derya) Müezzinzâde Ali Pacha tomba en martyr et seule la flotte d'Uluç Ali échappa. Après le désastre, le grand vizir Sokollu Mehmed Pacha nomma Uluç Ali Pacha grand amiral, le chargea de rassembler la flotte dispersée et fit commencer la construction d'une nouvelle flotte dans tous les arsenaux, d'Istanbul à Alanya ; toutefois, la suprématie absolue en Méditerranée était psychologiquement ébranlée.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Bataille de Mezőkeresztes (Haçova)", "da308ec5"], "d": ["Lors de la plus grande bataille rangée de la Longue Guerre (1593–1606), l'armée, que Mehmed III commandait en personne, se ressaisit, à l'instant où elle était sur le point de se disperser, sur les conseils de Hoca Sâdeddin Efendi, et mit en déroute l'armée des Habsbourg. Elle est tenue pour la dernière grande bataille rangée classique gagnée par les Ottomans ; mais le fait qu'elle n'ait pas changé le cours général de la guerre fut aussi considéré comme un signe de l'usure du système militaire.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Traité de Zsitvatorok", "39c01142"], "d": ["Par le traité qui mit fin à treize ans de guerre épuisante, le souverain des Habsbourg fut pour la première fois reconnu comme l'égal du sultan sous le titre d'« empereur romain », et le tribut annuel fut supprimé. Les pertes territoriales furent presque nulles ; mais ce changement du langage diplomatique est lu comme le symbole de la fin de la prétention ottomane à une supériorité absolue face à l'Europe.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Traité de Qasr-i Chirin (Kasr-ı Şirin)", "c1acf3af"], "d": ["Signé à la suite de la reprise de Bagdad par Murad IV (1638), le traité mit fin à plus d'un siècle de guerres ottomano-séfévides. Bagdad et l'Irak restèrent définitivement à l'Empire ottoman, Erevan fut laissée aux Séfévides ; la ligne tracée, avec de légères modifications, devint le fondement de l'actuelle frontière turco-iranienne, tenue pour l'une des frontières les plus durables du monde. Le traité laissa aux Ottomans Bedre, Cessân, Mendelî, Derteng et Derne ; la forteresse frontière de Zencir devait être démolie, les villages situés à l'ouest revenant à l'Empire ottoman, ceux de l'est à l'Iran. Les environs de la forteresse de Zalim, près de Şehrizor, et Kızılca Kale restèrent aux Ottomans, Avroman et Mihriban à l'Iran ; les forteresses de Kotur, de Mâkû et de Mağazberd devaient être démolies par les deux parties.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Achèvement de la conquête de la Crète", "e0d85604"], "d": ["Le siège de Candie, dernier acte de la guerre de Crète commencée en 1645, s'acheva par la campagne résolue de trois ans de Fâzıl Ahmed Pacha ; le commandant vénitien Morosini remit la ville par traité. La lutte, qui dura environ un quart de siècle, entra dans l'histoire comme le plus long siège de l'histoire ottomane ; la dernière grande forteresse latine de la Méditerranée orientale passa sous l'administration ottomane. Trois petites forteresses rocheuses de la côte nord de l'île — Suda, Spinalonga et Grambousa — restaient encore à Venise ; comme elles sont établies sur des îlots distincts, elles ne peuvent être figurées sur la carte séparément du reste de la Crète.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Traité de Buczacz (Bucaş) — frontières les plus étendues", "b17b6e5a"], "d": ["Par le traité de Buczacz, signé après la conquête de Kamieniec lors de la campagne de Pologne, la Podolie fut rattachée à l'Empire ottoman et une partie de l'Ukraine fut placée sous protection. L'Empire atteignit ainsi ses frontières les plus étendues en Europe ; ce point est tenu pour le sommet de l'ère d'expansion et en même temps pour son dernier maillon.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Déroute du second siège de Vienne", "7d889252"], "d": ["Le siège de Vienne, qui durait depuis deux mois sous Merzifonlu Kara Mustafa Pacha, tourna à la déroute sous le coup soudain que le roi de Pologne Jean Sobieski porta depuis les hauteurs du Kahlenberg ; l'armée se retira en abandonnant ses bagages, et Merzifonlu fut exécuté à Belgrade. La guerre qui suivit, avec la Sainte-Ligue formée après la victoire, dura 16 ans ; cette déroute est désignée comme le moment où débuta le grand recul de l'histoire ottomane.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Prise de la forteresse de Grambousa — l'une des forteresses rocheuses de Crète restées à Venise", "3ddf9eeb"], "d": ["Bien que la conquête de la Crète soit considérée comme largement achevée avec la reddition de Candie en 1669, Grambousa, forteresse insulaire rocheuse à l'extrémité nord-ouest de l'île, resta vingt-trois ans de plus aux mains de Venise. Sa prise en 1692 éliminait l'un des trois vestiges vénitiens de Crète ; Suda et Spinalonga devaient attendre la campagne de Morée de 1715.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Traité de Karlowitz — première grande perte territoriale", "8f7e2546"], "d": ["Par Karlowitz, qui mit fin à seize années de guerres de la Sainte-Ligue, la Hongrie et la Transylvanie furent cédées à l'Autriche, la Podolie à la Pologne, la Morée et les côtes de Dalmatie à Venise. Pour la première fois dans l'histoire ottomane, un territoire de cette ampleur était perdu à la table des négociations et de façon durable ; le traité est considéré comme l'acte inaugural d'une ère nouvelle où l'Empire passa sur la défensive face à l'Europe, et comme un tournant de l'histoire de la diplomatie ottomane. Établissements changeant de mains le même jour dans l'atlas : Kostajnica et Jasenovac (de l'Empire ottoman aux Habsbourg ; le texte du traité laisse Castanoviz aux mains de l'empereur, la date de remise de Jasenovac n'est pas dans la source, la date du traité a été inscrite) ainsi que Préveza (de Venise à l'Empire ottoman ; TDV karlofca : en vertu de la clause signée le 24 Receb 1110 / 26 janvier 1699, les places occupées par Venise au nord du golfe de Naupacte furent restituées). L'atlas inscrit en outre Kostayniçe (Kostajnica) et Jasenovaç du côté des Habsbourg, Uman et Vinnitsa en Ukraine de la rive droite de l'Empire ottoman à la Pologne (TDV merzifonlu-kara-mustafa-pasa ; IEU Vinnytsia : domination turque 1672-99) et Nadin en Dalmatie à Venise (la date de remise propre à l'établissement n'est pas dans la source, la date du traité a été inscrite ; les bornes de période de Nadin n'ont pas été vérifiées par la source — approximation déclarée). Vonitsa, au nord du golfe de Naupacte, est elle aussi restituée de Venise à l'Empire ottoman (TDV karlofca) ; en Dalmatie, Vrana (Urana) figure parmi les places restées à Venise (borne de période non vérifiée — approximation déclarée).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Victoire du Prut", "2583572f"], "d": ["Dans la guerre déclenchée à propos du roi de Suède réfugié chez les Ottomans après la défaite de Poltava, l'armée du tsar Pierre Ier fut encerclée sur les bords du Prut et dut se rendre. Par le traité signé, Azak (Azov) fut reprise ; le fait de n'avoir pas détruit l'armée et d'avoir laissé le tsar en liberté est entré dans l'histoire comme une décision discutée depuis lors.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Prise des forteresses de Suda et de Spinalonga — effacement de la dernière trace vénitienne en Crète", "7261f7ba"], "d": ["Vingt-trois ans après la chute de Grambousa en 1692, les forteresses de Suda et de Spinalonga, les deux derniers points d'appui de Venise en Crète, furent elles aussi conquises, par une branche annexe de la campagne de Morée. La conquête de la Crète, commencée en 1645, fut ainsi achevée, au bout de quarante-six ans, jusqu'au dernier pouce de l'île.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Révolte de Patrona Halil", "100941a4"], "d": ["L'échec sur le front iranien, les impôts et la colère suscitée par le luxe de l'entourage du palais se transformèrent en un grand soulèvement sous la conduite de Patrona Halil, masseur de hammam. Le grand vizir İbrahim Pacha fut tué, Ahmed III fut déposé et l'Ère des tulipes prit fin ; le fait que les insurgés aient dominé la ville pendant des mois montra de manière saisissante la fragilité de l'autorité centrale.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Traité de Belgrade — reprise de Belgrade, de Smederevo et de la Serbie du Nord", "ba7f8e46"], "d": ["À l'issue de la guerre menée sur deux fronts contre l'Autriche et la Russie (1736–1739), Belgrade et la Serbie du Nord furent reprises ; la Russie accepta de démilitariser Azov et de ne pas entretenir de flotte en mer Noire. Considéré comme le dernier grand succès de la diplomatie et de l'armée ottomanes au XVIIIe siècle, le traité procura à l'Empire un quart de siècle de paix. Autres établissements revenant de l'Autriche à l'Empire ottoman le même jour dans l'atlas : Hisarcık (Grocka) (suit le sort de son centre principal, Belgrade ; TDV belgrad), Krayova (Craiova), Rimnik (Râmnicu Vâlcea) et Turnu Severin (retour de la Petite Valachie à l'Empire ottoman, sous vassalité valaque). Brod de Bosnie (Bosanski Brod) et Dubica de Bosnie (Bosanska Dubica), sur la bande de la Save, reviennent en revanche à l'Empire ottoman le 28 septembre 1739 dans l'atlas (TDV bosna-hersek ; TDV mahmud-i--osmanli : 28 septembre 1739). Târgu Jiu, en Petite Valachie, revient elle aussi à l'Empire ottoman le même jour.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Incendie de Çeşme", "840b30bd"], "d": ["La flotte russe, qui était entrée en Méditerranée avec le soutien des Anglais, attaqua avec des brûlots la flotte ottomane réfugiée dans le port de Çeşme et la brûla presque entièrement. La Russie apparaissait pour la première fois en Méditerranée comme grande puissance navale ; ce désastre fut l'un des coups qui décidèrent du sort de la guerre menant à Küçük Kaynarca en 1774, et mit en évidence la nécessité d'une réforme radicale de la flotte.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Traité de Küçük Kaynarca", "2776dcdb"], "d": ["Par Küçük Kaynarca, qui mit fin à la guerre de 1768–1774 et compte parmi les traités les plus lourds de l'histoire ottomane, le khanat de Crimée reçut l'« indépendance » — ce qui créait en fait une zone d'influence russe. La Russie s'établit sur la côte de la mer Noire et obtint pour ses navires marchands le droit de passage par les Détroits ainsi qu'une ambassade permanente à Istanbul ; la clause ambiguë de protection sur les sujets orthodoxes entrouvrit la porte aux prétextes d'intervention du siècle suivant. Pour la première fois, un territoire peuplé de musulmans sortait de la domination ottomane.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Annexion de la Crimée par la Russie", "bdf6faa8"], "d": ["La Crimée « indépendante » créée par Küçük Kaynarca (Koutchouk-Kaïnardji) fut annexée à la Russie par le manifeste de Catherine II, sous prétexte des troubles survenus sous le dernier khan, Şahin Giray (Chahine Giraï). Le partenariat ottoman-criméen de trois siècles prit fin ; la perte des steppes du nord fit disparaître la profondeur défensive d'Istanbul et déclencha la première grande vague de migration de dizaines de milliers de Tatars de Crimée vers les terres ottomanes. Ce jour-là, la péninsule de Crimée (Alouchta, Kefe/Caffa, Soudak, Yalta, Balaklava, Inkerman, Mangoup, Arabat) fut rattachée à la Russie ; Taman et le Kouban passèrent aussi à la Russie lors de la même annexion (TDV Kırım : 8 avril 1783 julien = 19 avril grégorien).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Selim III et le Nizâm-ı Cedîd", "d53aec21"], "d": ["Selim III, monté sur le trône en pleine guerre, comprit que les défaites étaient structurelles et lança, sous le nom de « Nizâm-ı Cedîd » (Ordre nouveau), un vaste programme de réformes : une armée nouvelle exercée à l'européenne, un trésor distinct qui la finançait (Îrâd-ı Cedîd), le renforcement des écoles d'ingénieurs et les premières ambassades permanentes dans les capitales européennes. Le programme est considéré comme le début de la tradition réformatrice turque moderne ; mais, du fait de la résistance des corps (ocak) et des notables provinciaux (âyan), il devait être renversé en 1807.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Liquidation des chevaliers de Malte — étape de la flotte française en route", "d62f901d"], "d": ["La flotte française en route pour l'Égypte fit escale à Malte, sur son chemin ; les chevaliers de Saint-Jean (de Malte) remirent l'île sans grande résistance. Le dernier bastion de l'ordre de chevalerie, chassé de Rhodes en 1522 et établi ici, prenait ainsi fin. Malte devait passer aux mains de l'Angleterre deux ans plus tard, tandis que Napoléon se dirigeait de l'île directement vers Alexandrie.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Invasion de l'Égypte par Napoléon", "93fede5f"], "d": ["L'armée du général Bonaparte débarqua à Alexandrie et envahit l'Égypte ; cette expédition, qui visait la route des Indes de l'Angleterre, fut la première attaque directe d'une puissance européenne contre les terres centrales de l'Empire ottoman. Le raid de Nelson à Aboukir et la défense d'Acre par Cezzâr Ahmed Pacha brisèrent la marche française ; l'occupation prit fin en 1801, mais dans le vide qu'elle laissa commencèrent l'ascension de Kavalalı Mehmed Ali Pacha et l'ère de la « Question d'Orient ».", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Pacte d'alliance (Sened-i İttifak)", "cce49ef5"], "d": ["Document signé entre le palais et les puissantes familles de notables provinciaux, sous la direction d'Alemdar Mustafa Pacha, âyan de Rusçuk qui avait porté Mahmud II sur le trône ; les âyan s'engageaient à la fidélité envers le sultan et à lui fournir des soldats, tandis que l'État reconnaissait leur existence et leurs droits. Comme il s'agit du premier exemple, dans l'histoire ottomane, d'une limitation de l'autorité du sultan par un document, certains historiens y voient le lointain commencement de la tradition constitutionnelle ; dans les faits, il devint inopérant en quelques mois.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Début de l'insurrection grecque", "a7293715"], "d": ["Le soulèvement préparé par l'organisation de la Filiki Eteria éclata d'abord en Valachie, puis, avec sa force principale, en Morée ; l'État, occupé par l'affaire d'Ali Pacha de Tepedelen, tarda à intervenir. Grâce à la vive sympathie de l'opinion publique européenne pour les Grecs (philhellénisme), l'insurrection devint rapidement une cause internationale ; ainsi fut allumée la mèche du premier mouvement d'indépendance réussi en terre ottomane à l'ère du nationalisme. Autres établissements perdus à la même date : Athènes, Patras, Thèbes, Livadia, Éleusis (Attique), Missolonghi.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Premier soulèvement armé en Morée", "77e6250f"], "d": ["Après la traversée du Prout, la révolte gagna la Morée : l'action armée engagée à Kalavryta (21 mars julien) fut suivie des mouvements de Patras, de Kalamata et de Mani ; en Morée, le mouvement se transforma rapidement en soulèvement général et l'administration ottomane perdit la plus grande partie de la péninsule. Autres localités perdues à la même date : Athènes, Balyabadra (Patras), İstefe (Thèbes), Livadia, Éleusis (Attique), Missolonghi.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Vak'a-i Hayriyye — abolition du corps des janissaires", "08c9372a"], "d": ["Les janissaires, qui s'étaient mutinés (renversement des marmites) contre l'instruction du corps des Eşkinci nouvellement créé, furent anéantis à coups de canon, dans leurs casernes de l'Et Meydanı, par des troupes fidèles que Mahmud II avait préparées d'avance ; le corps fut aboli avec toutes ses branches et les tekkes bektachis qui lui étaient liés. Cette opération, entrée dans l'histoire sous le nom d'« événement heureux », en liquidant une institution vieille de quatre siècles, ouvrit la voie à l'armée des Asâkir-i Mansûre-i Muhammediyye et à toutes les réformes centralisatrices qui suivirent.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Bataille navale de Navarin", "ee579e7f"], "d": ["La flotte ottomano-égyptienne, qui réprimait l'insurrection grecque, fut incendiée à Navarin par la flotte combinée anglo-franco-russe entrée dans le port sans déclaration de guerre ; près de soixante navires et des milliers de marins furent perdus. Écartée par la diplomatie européenne comme un « événement fâcheux », l'attaque garantit de fait l'indépendance grecque et ouvrit la voie à la guerre russo-ottomane de 1828–1829.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Édit du Tanzimat", "5042ce7b"], "d": ["Par le Hatt-ı Hümâyun lu à Gülhane, la sécurité de la vie, des biens et de l'honneur de tous les sujets, sans distinction de religion, fut placée sous la garantie de l'État ; furent proclamés les principes de justice dans l'impôt, d'ordre dans le service militaire et d'absence de peine sans jugement. L'édit, œuvre de Mustafa Reşid Pacha, est considéré comme le premier grand document à caractère constitutionnel de la modernisation ottomane et a donné son nom à l'ère de réformes du « Tanzimat » (1839–1876) ; une restructuration profonde de l'administration, du droit, de l'enseignement et des finances fut menée dans ce cadre.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Début de la guerre de Crimée", "3b9ca3c8"], "d": ["La crise née de la question des Lieux saints et de la prétention de la Russie à protéger les sujets orthodoxes se transforma en conflit ouvert par la déclaration de guerre ottomane ; après l'attaque de Sinope, l'Angleterre et la France (puis le Piémont) entrèrent en guerre aux côtés des Ottomans. La guerre, qui fut gagnée grâce au débarquement des armées alliées en Crimée et à la prise de Sébastopol, s'acheva par le traité de Paris de 1856 ; mais le premier emprunt extérieur contracté pendant les années de guerre (1854) enferma l'Empire dans une spirale de dépendance financière qui devait durer un demi-siècle.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Édit de réforme (Islahat Fermanı)", "78ff234d"], "d": ["L'édit, proclamé avant les négociations de paix de Paris, élargit les principes du Tanzimat et reconnut aux sujets non musulmans de larges droits d'égalité, y compris l'accès à la fonction publique, au service militaire et l'ouverture d'écoles ; les organisations communautaires furent réaménagées. Par le traité de Paris signé ensuite, l'État ottoman fut officiellement admis dans la famille du droit public européen et son intégrité territoriale fut placée sous la garantie collective des grandes puissances — garantie qui devait devenir, dans la pratique, une nouvelle porte ouverte aux interventions.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Kanûn-ı Esâsî — première monarchie constitutionnelle", "0fe052c1"], "d": ["Le jour de l'ouverture de la conférence internationale réunie à Istanbul pour discuter de la crise balkanique, la première constitution ottomane fut proclamée à coups de canon ; par le Kanûn-ı Esâsî, œuvre du mouvement des « Nouveaux Ottomans » conduit par Midhat Pacha, un parlement à deux chambres fut institué. Le Meclis-i Meb'ûsan s'ouvrit en mars 1877 ; mais Abdülhamid II, invoquant la guerre de 93, ajourna l'assemblée sans limite de durée en février 1878, et la constitution resta suspendue pendant trente ans.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["Guerre de 93 (guerre russo-ottomane de 1877–1878)", "5bd96af7"], "d": ["Dans la guerre appelée « guerre de 93 » parce qu'elle coïncidait avec l'année 1293 du calendrier rûmî, les armées russes attaquèrent sur deux fronts ; bien que la défense de Plevna par Gazi Osman Pacha et les batailles du Caucase d'Ahmed Muhtar Pacha soient devenues légendaires, le front s'effondra et les Russes avancèrent jusqu'à Yeşilköy (San Stefano, Ayastefanos). La guerre déclencha de grandes vagues d'émigration musulmane des Balkans et du Caucase vers Istanbul, dont les effets se prolongent jusqu'à nos jours ; la structure démographique et financière de l'Empire ne retrouva jamais son état antérieur.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Traité de Berlin", "47f76a49"], "d": ["Le Congrès de Berlin, qui révisa au nom de l'équilibre des grandes puissances la « Grande Bulgarie » créée par San Stefano, laissa néanmoins un bilan très lourd : la Serbie, le Monténégro et la Roumanie devinrent indépendants ; la principauté autonome de Bulgarie fut fondée ; la Bosnie-Herzégovine fut laissée à l'occupation autrichienne, Chypre à l'administration britannique, Kars-Ardahan-Batoum à la Russie. L'ordre ottoman de cinq cents ans en Roumélie fut en grande partie défait ; la « question d'Orient » devint un point permanent de l'ordre du jour de la diplomatie européenne. Autres établissements perdus à la même date : Plovdiv, Vidin, Tarnovo, Varna, Choumen, Silistra, Roustchouk, Bucarest, Iași, Constanța. La Roumanie, en contrepartie de la cession de la Bessarabie à la Russie, reçut Tulcea et la Dobroudja : Tulcea, Babadag, Măcin, Isaccea, Hârșova et Mangalia, en Dobroudja du Nord, passèrent à la Roumanie.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Occupation de la Tunisie et Dette publique ottomane (Düyûn-ı Umûmiyye)", "c7e25598"], "d": ["La France, prenant prétexte d'incidents à la frontière algérienne, occupa la Tunisie et la plaça sous son protectorat par le traité du Bardo ; la présence ottomane en Afrique du Nord se réduisit à la Tripolitaine. Par le décret de Muharrem promulgué la même année, l'Administration de la Dette publique ottomane (Düyûn-ı Umûmiyye), où étaient représentés les créanciers, fut instituée pour gérer les dettes extérieures en faillite : des revenus essentiels tels que le sel, le tabac et la soie furent directement rattachés à cette administration étrangère, et la souveraineté financière fut gravement restreinte. Autres établissements perdus à la même date : Kairouan, Gabès, Sfax, Djerba.", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Occupation britannique de l'Égypte", "f1269768"], "d": ["Le mouvement d'Urabi Pacha, qui s'était dressé en Égypte contre la faillite financière et le contrôle étranger, fut écrasé par la victoire de Tell el-Kébir de l'armée britannique débarquée après le bombardement d'Alexandrie, et Le Caire fut occupé. Bien que l'Égypte soit restée juridiquement rattachée à l'Empire ottoman, elle passa de fait sous administration britannique ; le contrôle du canal de Suez s'installa au centre de la stratégie impériale de la Grande-Bretagne.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Proclamation de la seconde monarchie constitutionnelle", "95ee2fd2"], "d": ["Face au mouvement qui avait grandi lorsque des officiers liés au Comité Union et Progrès avaient pris le maquis en Macédoine, Abdülhamid II remit en vigueur le Kanûn-ı Esâsî ; la « proclamation de la liberté » fut accueillie avec enthousiasme et l'on alla aux élections. Mais la stabilité ne vint pas : après la répression de l'incident du 31 Mars (avril 1909), Abdülhamid fut déposé ; l'indépendance de la Bulgarie, l'annexion de la Bosnie et l'orientation de la Crète vers la Grèce eurent lieu elles aussi au cours de ces mois agités.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Guerre de Tripolitaine", "ed441994"], "d": ["L'Italie, en quête de colonies, déclara la guerre à la Tripolitaine, dernière terre ottomane d'Afrique du Nord, et occupa les côtes ; l'État, privé de flotte, ne pouvant envoyer d'armée régulière, de jeunes officiers tels que Mustafa Kemal et Enver Bey gagnèrent secrètement la région et organisèrent avec les tribus senoussis une résistance efficace. Par le traité d'Ouchy (18 octobre 1912), signé à la suite du déclenchement de la guerre des Balkans, la Libye fut laissée à l'Italie ; l'Italie occupa en outre Rhodes et le Dodécanèse.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Traité de Londres — perte de la Roumélie", "f3f976df"], "d": ["Par le traité de Londres, qui mit fin à la première guerre balkanique, tous les territoires à l'ouest de la ligne Midye-Enez et les îles de la mer Égée furent perdus ; l'Albanie devint indépendante. De la Roumélie, centre de gravité démographique, économique et culturel de l'Empire depuis plus de cinq cents ans, il ne resterait que la Thrace orientale (Edirne fut reprise lors de la seconde guerre balkanique) ; la perte durcit profondément la politique de guerre et de peuplement de l'administration unioniste. Les localités suivantes, situées à l'ouest de la ligne Midye-Enez, furent perdues : Skopje, Köprülü (Veles), İştip (Štip), Strumica, Doïran, Gevgili (Gevgelija), Monastir, Ohrid, Debar (Dibra), Prizren, Pristina, Peć (Pejë), Yenipazar (Novi Pazar), la plaine du Kosovo (Kosovo Polje) ; Serrès, Drama, Kavala, Petritch, Nevrokop, Xanthi, Komotini, Dedeağaç, Didymoteicho, Çirmen, Ferecik (Feres), Sofulu (Soufli), Orestiada (Kumçiftliği), Praviște (Eleftheroupoli), Stérna, Távri, Umur Fakih (Fakia), Malak Dervent (Lalkovo) ; en Crète, La Canée, Candie, Crète (Rethymnon), Sitia et Sfakia.", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Entrée dans la Première Guerre mondiale", "05a0252e"], "d": ["L'admission dans le détroit des cuirassés Goeben et Breslau, échappés devant les Anglais et présentés comme achetés, attira peu à peu l'État aux côtés de l'Allemagne ; la guerre commença de fait lorsque la flotte placée sous le commandement de l'amiral Souchon bombarda les ports russes (29 octobre), et les déclarations réciproques vinrent au début de novembre. Malgré la proclamation du Grand Djihad, l'effet attendu ne se produisit pas ; pendant quatre ans, l'Empire s'engagea dans une guerre d'existence sur cinq fronts distincts, du Caucase à la Palestine.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Victoire des Dardanelles (Çanakkale)", "95d888e8"], "d": ["L'armada alliée, qui visait à faire tomber Istanbul et à joindre la Russie, fut repoussée du détroit le 18 mars par les lignes de mines et le feu des batteries ; la ligne posée par le mouilleur de mines Nusret décida du sort de la bataille. L'opération terrestre de Gallipoli, commencée en avril, fut elle aussi arrêtée à Anafartalar et à Conkbayırı ; les Alliés évacuèrent entièrement la péninsule en janvier 1916. Le nom du lieutenant-colonel Mustafa Kemal fut connu sur ce front ; cette victoire, acquise au prix d'environ un quart de million de martyrs et de disparus, est considérée comme le lieu de naissance des cadres et de l'esprit de la Lutte nationale.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Révolte du chérif Hussein", "75f7c58c"], "d": ["Le chérif Hussein, émir de La Mecque, se souleva, à la suite d'une correspondance secrète avec les Britanniques, sur la promesse d'un royaume arabe indépendant ; le chemin de fer du Hedjaz devint la cible de raids. Bien que la défense légendaire de Médine par Fahreddin Pacha, qui se prolongea au-delà de l'armistice, soit restée un symbole de résistance, la révolte, jointe à l'avancée britannique sur le front de Palestine, accéléra la dissolution de la domination ottomane dans les provinces arabes. Autres localités perdues à la même date : Hurma, Turaba.", "f7c6b3e9"]},
"OLAYLAR:1918-10-30:0":{"b": ["Armistice de Moudros", "9e87c767"], "d": ["L'État ottoman, dont les fronts avaient été coupés les uns des autres par l'effondrement de la Bulgarie, se retira de la guerre par l'armistice signé à bord du cuirassé Agamemnon. L'ouverture des Détroits et surtout l'article 7, qui permettait d'occuper les lieux dont la sécurité serait menacée, furent bientôt transformés en couverture juridique d'un partage de fait : Mossoul, Alexandrette, puis Izmir et Istanbul furent occupées. L'armistice est considéré comme l'acte de la fin de fait de l'Empire. Autres établissements perdus à la même date : Hama, Damas, Homs.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Mustafa Kemal à Samsun — Lutte nationale", "09a8f784"], "d": ["Dans le climat d'indignation créé par l'occupation d'Izmir, Mustafa Kemal Pacha, qui débarqua à Samsun en qualité d'inspecteur de la 9e armée, tourna sa mission officielle vers l'organisation de la résistance en Anatolie. La circulaire d'Amasya et les congrès d'Erzurum et de Sivas sont la suite de cette démarche ; le principe selon lequel « seules la détermination et la décision de la nation sauveront l'indépendance de la nation » devint le noyau du programme politique de la Lutte nationale.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Ouverture de la Grande Assemblée nationale de Turquie et Sèvres", "2008feec"], "d": ["À la suite de l'occupation officielle d'Istanbul et de la dissolution du Meclis-i Meb'ûsan, la Grande Assemblée nationale s'ouvrit à Ankara le 23 avril 1920 ; réunissant en elle des pouvoirs extraordinaires, l'assemblée devint le noyau du nouvel État fondé sur la volonté nationale. Le traité de Sèvres, signé en août par le gouvernement d'Istanbul, partageait l'Anatolie ; la Grande Assemblée déclara traîtres à la patrie ceux qui l'avaient signé, et Sèvres ne put jamais être appliqué.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Bataille de la Sakarya", "f2f970a6"], "d": ["L'offensive grecque, qui s'était approchée à 50 kilomètres d'Ankara, fut brisée lors du combat de 22 jours et 22 nuits mené par Mustafa Kemal Pacha, qui avait assumé le commandement en chef, selon l'ordre « il n'y a pas de ligne de défense, il y a une surface de défense ». L'armée grecque passa pour la première fois à la défensive stratégique ; la victoire valut à Mustafa Kemal les titres de gazi et de maréchal (müşir), et ouvrit la porte à l'accord d'Ankara avec la France ainsi qu'à la reconnaissance extérieure.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Grande Offensive et libération d'Izmir", "172a50c4"], "d": ["L'offensive lancée le 26 août au matin depuis Kocatepe aboutit, le 30 août, à la destruction des forces principales grecques à Dumlupınar, lors de la bataille du Commandant en chef ; dans la poursuite menée selon l'ordre « Armées, votre premier objectif est la Méditerranée, en avant ! », Izmir fut libérée le 9 septembre. Par l'armistice de Mudanya (11 octobre), la Thrace orientale fut récupérée sans combat ; la victoire militaire détermina le poids qu'aurait à la table des négociations le nouvel État qui serait établi à Lausanne.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Abolition du sultanat", "9f36a9f6"], "d": ["À la suite de l'invitation adressée aussi au gouvernement d'Istanbul pour les négociations de Lausanne, la Grande Assemblée nationale sépara, le 1er novembre 1922, le sultanat du califat et abolit le sultanat ; le règne de la dynastie ottomane, long de 623 ans, prit fin juridiquement. Mehmed VI Vahideddin quitta le pays le 17 novembre à bord d'un cuirassé britannique ; par décision de la Grande Assemblée, Abdülmecid Efendi fut porté à la charge de calife, laquelle devait être abolie à son tour le 3 mars 1924.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Traité de Lausanne", "38c27f7d"], "d": ["Par le traité de paix de Lausanne, signé au terme de huit mois de dures négociations, les frontières, la pleine indépendance et la souveraineté du nouvel État turc furent reconnues sur le plan international ; les capitulations furent abolies, la Dette publique ottomane fut engagée dans un processus de liquidation, et l'échange de populations fut réglé. Lausanne, qui annula de fait Sèvres, est considéré comme la victoire diplomatique de la Lutte nationale et comme le document extérieur fondateur de la République.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Proclamation de la République", "d5bfcdfb"], "d": ["La République fut proclamée lorsque la Grande Assemblée nationale adopta, par une modification constitutionnelle, la disposition selon laquelle « la forme de gouvernement de l'État turc est la république » ; Mustafa Kemal Pacha fut élu premier président. L'aventure ottomane de 624 ans, commencée en 1299 comme principauté marchesque, se refermait ainsi ; un État nouveau, où la souveraineté appartient sans condition ni réserve à la nation, était fondé sur l'héritage de l'Empire.", "f5cabb8c"]},
"OLAYLAR_0073_IRAN_YANYA:1820-03-01:0":{"b": ["Destitution de Tepedelenli Ali Pacha et début du siège de Ioannina", "e8a6530b"], "d": ["La politique de Mahmud II d'épuration des pouvoirs locaux atteignit Tepedelenli Ali Pacha, qui gouvernait Ioannina depuis trente-trois ans et tenait de fait la Thessalie et l'Épire. Le pacha fut destitué de la charge de chef des derbends et son fils Veli du pachalik de Tırhala ; comme l'on s'attendait qu'il n'obéirait pas, des forces furent envoyées contre lui. Hurşid Ahmed Pacha, chargé de cette mission, était en même temps gouverneur de Morée et avait reçu aussi le séraskérat de Roumélie ; tous les administrateurs civils et militaires de la région furent chargés de capturer Tepedelenli. Autrement dit, lorsque la révolte grecque éclata, le commandant qui aurait dû administrer la Morée et les forces placées sous ses ordres assiégeaient la forteresse de Ioannina. Le 23 mai 1820, Ali Pacha tint une réunion avec des Grecs à Ioannina, tenta d'établir sous son autorité une province grecque et leur apporta une aide en argent et en armes. En face, la force n'était pas négligeable : Ali Pacha disposait d'une armée de 30 000 à 40 000 hommes, dont 7 000 permanents, et d'une petite flotte ; la population sous son administration était estimée à 1,5-2 millions d'habitants et son revenu annuel à 4-5 millions de kuruş.", "d0250e2a"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:0":{"b": ["Début de la guerre ottomano-iranienne — perte de Kars et de Bayezid, siège d'Erzurum", "570b27bd"], "d": ["La deuxième année de la révolte grecque, la frontière orientale de l'empire se transforma en zone de guerre. Abbas Mirza, héritier qajar, prenant prétexte de la fouille par des représentants ottomans de la caravane où se trouvait l'épouse du chah partie en pèlerinage, franchit la frontière avec une grande force militaire ; il s'empara des vilayets de Kars et de Bayezid et mit le siège devant Erzurum. La force qui lui faisait face n'était pas une unité frontalière ordinaire : Abbas Mirza avait fait instruire l'armée d'Azerbaïdjan selon les méthodes européennes et avait fait établir à Tabriz une poudrerie et des fonderies de canons. L'Empire ottoman, lui, était alors occupé à l'ouest par la révolte de Morée, au nord-ouest par la résistance de Tepedelenli Ali Pacha à Ioannina, et ne disposait d'aucune armée instruite à l'européenne ; le corps des janissaires subsisterait jusqu'en 1826.", "88b4be76"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:1":{"b": ["Occupation iranienne de Souleimaniyeh et de Bagdad — siège de Kirkouk", "384d74e4"], "d": ["Parallèlement aux opérations d'Anatolie orientale, les forces iraniennes lancèrent une vaste attaque contre le nord de l'Irak et la province de Bagdad, sous administration ottomane. Bagdad était alors gouvernée par Kölemen Dâvud Pacha, gouverneur depuis 1817 ; le pacha disposait d'une force de 10 000 fantassins et artilleurs qu'il avait fait instruire par Deveaux, ancien aide de camp de Napoléon. Le centre de l'empire ne possédait pas encore une telle armée — les unités instruites à l'européenne n'étaient alors qu'entre les mains de puissants gouverneurs de province. Ce qui mit fin à la guerre ne fut pas une victoire ottomane : la résistance ottomane et l'épidémie qui frappa l'Azerbaïdjan contraignirent les forces iraniennes à se retirer.", "b60b096c"]},
"OLAYLAR_0073_IRAN_YANYA:1822-02-14:0":{"b": ["Mise à mort de Tepedelenli Ali Pacha — fin du siège de Ioannina", "da679150"], "d": ["La résistance à Ioannina dura près de deux ans et c'est précisément pendant cette période que la révolte grecque prit une ampleur générale. Lorsque Hurşid Pacha envoya des espions dans la forteresse et distribua grades et gratifications à ceux qui fuyaient, le nombre de soldats autour d'Ali Pacha tomba à quarante ou cinquante ; le pacha se retira au monastère Saint-Pantéléimon, sur le lac, avec la garantie que sa vie serait épargnée s'il se rendait. À ce moment, la famille de Hurşid Pacha était tombée aux mains des insurgés grecs ; pour pouvoir retourner au plus vite en Morée, il passa outre au sauf-conduit (emannâme) qu'il avait accordé et fit fabriquer un faux firman d'exécution. Lorsqu'on entra dans sa chambre, Ali Pacha répondit par les armes et fut tué dans l'affrontement qui s'ensuivit ; sa tête fut apportée à Istanbul le 24 février. Le siège avait aussi révélé la fissure au sein du commandement ottoman : lorsque la révolte de Morée devint plus dangereuse que l'affaire de Tepedelenli, Seyyid Ali Pacha fut nommé séraskier autonome de Morée ; Hurşid Pacha, que cela mécontentait, rejeta ses demandes de secours et tenta même de le faire passer pour un incapable aux yeux de l'État. À la fin de l'année où Ali Pacha fut éliminé, la plus forte forteresse de Morée, Nauplie (Anabolu), tomba.", "c7a915be"]},
"OLAYLAR_0073_IRAN_YANYA:1823-07-28:0":{"b": ["Traité d'Erzurum — retrait des forces iraniennes en soixante jours", "166373c3"], "d": ["La guerre, qui avait duré deux ans, prit fin par le traité de paix signé à Erzurum. Selon le traité, les forces iraniennes devaient se retirer dans un délai de soixante jours des terres qu'elles avaient occupées. Le traité ne traça pas de nouvelle frontière, il rétablit la situation d'avant-guerre ; les différends frontaliers entre les deux États dégénéreront de nouveau en affrontements en 1833-1842 et ne seront réglés qu'en 1847, par un second traité, signé lui aussi à Erzurum. La clôture du front oriental était la condition préalable pour que l'empire pût consacrer tout son poids à la révolte grecque.", "7c54983b"]},
"OLAYLAR_2S0920:0224-04-28:0":{"b": ["Bataille de Hormizdagân : Ardachir bat le roi parthe Artaban V — Ispahan entre dans le noyau sassanide", "3689fd45"], "d": ["Ardachir, souverain local du Fars, vainquit à Hürmüzgân le roi parthe Artaban V ; la dynastie parthe (arsacide) s'effondra et la dynastie sassanide s'éleva. L'atlas considère Ispahan comme territoire sassanide à partir de ce jour.", "3551fe9f"]},
"OLAYLAR_2S0920:1387-05-08:0":{"b": ["Passage de Karaferye (Véria) sous la domination ottomane", "b0ece3f3"], "d": ["La même année que la reddition de Thessalonique en 1387, Karaferye, à l'intérieur de la Basse-Macédoine, passa elle aussi sous la domination ottomane. La ville était le nœud de la route entre Thessalonique et la Thessalie.", "4e571f7b"]},
"OLAYLAR_2S0920:1506-07-08:0":{"b": ["Albert IV publie l'ordonnance de primogéniture des Wittelsbach — les duchés de Bavière se réunissent en un duché unique et indivisible", "86ee6f77"], "d": ["Après la guerre de Succession de Landshut (1503-1505), le duc Albert IV, qui avait de nouveau réuni les duchés de Bavière en une seule main, publia le 8 juillet 1506 l'ordonnance de primogéniture, qui prévoyait l'indivisibilité du pays et la transmission du trône au fils aîné. Les partages de la Bavière, qui duraient depuis 1255, prirent ainsi fin ; la Bavière, dont le centre était Munich, subsista parmi les États allemands comme un duché unique et indivisible.", "26058158"]},
"OLAYLAR_2S0920:1517-04-15:0":{"b": ["Amir II est tué près de Sanaa — fin de la dynastie des Tahirides", "713ae406"], "d": ["Amir II, dernier souverain des Tahirides, fut d'abord battu près de Zabid (novembre 1516), puis tué lors du combat près de Sanaa, dans la guerre née de la dégradation des relations avec la flotte mamelouke, les tribus du Yémen et les Zaydites ayant soutenu les Mamelouks. La dynastie tahiride, qui gouvernait le Yémen depuis 1454, prit ainsi fin ; les villes de la dynastie (Taëz comprise) ne relevaient plus de la souveraineté tahiride.", "4b9725ef"]},
"OLAYLAR_2S0920:1552-08-01:0":{"b": ["Conquête des forteresses de Lugoj et de Caransebeș — suite de la campagne de Timișoara", "1af5a2be"], "d": ["La forteresse de Timișoara se rendit le 26 juillet 1552 après trois semaines de résistance. En août, les forteresses de Lugoj et de Caransebeș furent également prises ; quinze forteresses furent enlevées le long de la vallée du Mureș, et un nouveau beylerbeylik, dont le centre était Timișoara, fut créé.", "ecd1e532"]},
"OLAYLAR_2S0920:1723-11-18:0":{"b": ["Fondation de la forge-forteresse d'Iekaterinbourg — centre de la région minière de l'Oural", "c416e12e"], "d": ["Sur le site choisi par Tatichtchev sur la rivière Iset, les marteaux de la forge achevée par de Gennin furent mis en marche ; Iekaterinbourg compte sa date de fondation à partir de ce jour. Futur centre de la région minière et sidérurgique de l'Oural, la ville devint la porte du tsarat russe vers la route de la Sibérie.", "8d081bcf"]},
"OLAYLAR_2S0920:1902-03-01:0":{"b": ["Zaria (Zazzau) passe sous contrôle administratif britannique — l'émirat de Zaria du califat de Sokoto est rattaché au protectorat du Nord-Nigeria", "c2e4131e"], "d": ["L'émirat de Zaria, dépendant du califat de Sokoto, fut placé en mars 1902 sous l'administration britannique du Nord-Nigeria ; les Britanniques installèrent à Zaria un résident et une garnison. L'émir Kwasau se rendit en juillet 1902 et fut destitué en septembre.", "d2ce29e8"]},
"OLAYLAR_2S0920:1903-02-01:0":{"b": ["Les Britanniques prennent Kano — le plus grand émirat du califat de Sokoto passe au protectorat du Nord-Nigeria", "0484009d"], "d": ["La force du colonel Morland, placée sous les ordres du haut-commissaire du Nord-Nigeria Lugard, partit de Zaria et s'empara de Kano en février 1903 ; l'émirat de Kano, dépendant du califat de Sokoto, passa sous administration britannique. Sokoto fut prise un mois plus tard, le 15 mars 1903.", "33350275"]},
"OLAYLAR_2S0920:1912-10-22:0":{"b": ["Pristina tombe aux mains de l'armée serbe", "2ef111c0"], "d": ["L'armée serbe, entrée au Kosovo durant la première guerre balkanique, prit Pristina, et une politique de re-serbisation commença dans la ville. La chute de Pristina est l'un des premiers maillons de l'effondrement de la résistance ottomane dans le vilayet du Kosovo.", "96fc25ba"]},
"OLAYLAR_2S0920:1912-11-18:0":{"b": ["Occupation de Monastir par les forces serbes", "db9b3353"], "d": ["Durant la première guerre balkanique, Monastir, l'un des plus importants centres administratifs et militaires de la Macédoine, tomba aux mains des forces serbes à l'issue de cinq jours de combats. La perte de la ville signifiait la fin effective de la présence de l'État ottoman en Macédoine.", "84736d79"]},
"OLAYLAR_2S0920:1912-11-28:0":{"b": ["Proclamation de l'indépendance de l'Albanie — İsmâil Kemali à Valona", "2cdbd4d9"], "d": ["Alors que les armées de la guerre balkanique pénétraient dans les vilayets albanais, İsmâil Kemali proclama à Valona l'indépendance de l'Albanie. La zone littorale et intérieure s'étendant de Durrës, Elbasan, Berat, Gjirokastër et Krujë jusqu'à Sarandë sortit ainsi de l'administration ottomane et forma le noyau du nouvel État albanais.", "bc8dc97c"]},
"OLAYLAR_2S0920:1912-11-29:0":{"b": ["Fin de la domination ottomane à Ohrid et à Debar", "5273f1ec"], "d": ["Onze jours après la chute de Monastir, l'armée serbe entra dans la région des lacs de la Macédoine occidentale ; à Ohrid, la domination ottomane, vieille de cinq siècles, prit fin, et Debar, au nord, fut perdue au cours de la même opération.", "7cabdd2f"]},
"OLAYLAR_2S0920:1913-04-23:0":{"b": ["Occupation de Scutari par les Monténégrins", "db704247"], "d": ["L'un des plus longs sièges de la première guerre balkanique eut lieu à Scutari ; au terme d'une résistance de plusieurs mois, la ville fut remise aux forces monténégrines. Scutari fut l'une des dernières forteresses ottomanes à tenir jusqu'à la fin de la guerre.", "418ed9d4"]},
"OLAYLAR_2S0920:1913-05-14:0":{"b": ["Le Monténégro évacue Scutari ; le corps international des grandes puissances entre dans la ville", "8a6593e9"], "d": ["Sous la pression des grandes puissances, le Monténégro évacua le 14 mai 1913 Scutari, qu'il avait prise le 23 avril 1913 ; un corps international entra dans la ville et celle-ci devint partie de l'administration constitutive de l'Albanie.", "5ef15370"]},
"OLAYLAR_2S0920:1913-07-08:0":{"b": ["Ibn Saoud prend Al-Hasa — fin de la domination ottomane sur la côte du Golfe", "505f26d5"], "d": ["L'émir du Nedjd, Abdelaziz ibn Saoud, expulsa la garnison ottomane, s'empara de la région d'Al-Hasa et établit son centre à Hofuf. Avec les débarcadères de Qatif et d'Uqair, la côte occidentale du Golfe passa sous l'administration saoudienne ; l'administration cinquantenaire de l'État ottoman dans la région prit fin.", "8ec53ab2"]},
"OLAYLAR_2S0920:1913-08-10:0":{"b": ["Traité de Bucarest — la Thrace occidentale et le bassin de Kavala passent de la Bulgarie à la Grèce", "56123a58"], "d": ["La seconde guerre balkanique prit fin par le traité de Bucarest, signé entre la Bulgarie, d'une part, la Serbie, la Grèce et le Monténégro, d'autre part. Le bassin de Kavala, Drama et Serrès, passé aux mains de la Bulgarie lors de la première guerre, fut cédé à la Grèce par ce traité. Par ce traité, Tutrakan (Turtukaya) passa à la Roumanie.", "dd427970"]},
"OLAYLAR_2S0920:1914-11-22:0":{"b": ["Débarquement au Chatt el-Arab — chute de Bassora et ouverture du front irakien", "c0a87d5d"], "d": ["À l'ouverture de la Première Guerre mondiale, le corps expéditionnaire britannique venu d'Inde débarqua à Fao, à l'embouchure du Chatt el-Arab, et prit rapidement Bassora. La chute de la ville signifiait l'ouverture du front d'Irak et le passage de l'extrémité nord du Golfe sous contrôle britannique.", "3b98576d"]},
"OLAYLAR_2S0920:1918-05-26:0":{"b": ["La Géorgie proclame son indépendance — dissolution du Seim transcaucasien", "6c79a8c7"], "d": ["La Géorgie, issue du Seim transcaucasien formé après Brest-Litovsk, proclama son indépendance, et la République démocratique de Géorgie fut fondée. Avec Koutaïssi, la Géorgie occidentale passa sous l'administration de ce nouvel État. Par cette proclamation, Soukhoumi, Poti, Zougdidi, Gori, Telavi et Douchéti passèrent à la République démocratique de Géorgie.", "5500d335"]},
"OLAYLAR_2S0920:1918-05-28:0":{"b": ["Proclamation de la République démocratique d'Azerbaïdjan", "8baecec3"], "d": ["Deux jours après la séparation de la Géorgie, la République démocratique d'Azerbaïdjan fut proclamée ; son premier centre fut Gandja. Le même jour, la République d'Arménie fut également fondée à Erevan, et la Transcaucasie fut divisée en trois États distincts. Par cette proclamation, Chamakhi, Gabala, Ereş, Chabran, Salyan, Kouba, Cheki et Barda passèrent à la République démocratique d'Azerbaïdjan.", "474c35d5"]},
"OLAYLAR_2S0920:1918-10-27:0":{"b": ["Occupation d'Alep par les forces arabes et britanniques", "00efb2da"], "d": ["Après l'effondrement du front de Palestine, les forces qui progressaient vers le nord entrèrent à Alep ; la ville passa d'abord aux troupes arabes, puis aux troupes britanniques. Cette occupation, survenue trois jours avant l'armistice de Moudros, mit fin de fait à l'administration quatre fois séculaire de l'État ottoman en Syrie.", "38b8fc55"]},
"OLAYLAR_2S0920:1920-04-27:0":{"b": ["L'Armée rouge occupe l'Azerbaïdjan — fin de la République démocratique", "ebbb4566"], "d": ["L'Armée rouge entra en Azerbaïdjan et dissolut le parlement et le gouvernement ; la République démocratique d'Azerbaïdjan, vieille de deux ans, prit fin. Le bassin pétrolier de Bakou et Gandja passèrent ainsi à l'administration soviétique. Par cette occupation, Chamakhi, Gabala, Ereş, Chabran, Salyan, Kouba, Cheki et Barda passèrent sous le contrôle de la Russie soviétique.", "e475b579"]},
"OLAYLAR_2S0920:1920-07-24:0":{"b": ["Khan Mayssaloun — fin de l'époque de Fayçal, la Syrie passe sous mandat français", "80a932b0"], "d": ["À Khan Mayssaloun, sur la route de Beyrouth à Damas, les Français infligèrent une lourde défaite aux forces syriennes et le royaume arabe de Fayçal à Damas prit fin. La France établit de fait l'autorité de mandat qui lui avait été confiée à San Remo ; la région allant d'Alep à Damas, d'Alexandrette à Deir ez-Zor fut rattachée à l'administration du mandat français.", "81c76451"]},
"OLAYLAR_2S0920:1921-02-01:0":{"b": ["Fondation de l'émirat de Transjordanie — Abdallah b. Hussein proclame son émirat", "5ef520c2"], "d": ["Abdallah, fils du chérif Hussein, vint vers le nord par Maan et proclama l'émirat de Transjordanie ; l'Angleterre reconnut peu après cette administration dans le cadre du mandat. Amman devint le centre de l'émirat, et le plateau de Jordanie, y compris Kerak, fut rattaché à cette nouvelle administration.", "113f01ba"]},
"OLAYLAR_2S0920:1941-05-03:0":{"b": ["L'Italie annexe la province de Ljubljana au Royaume — Ljubljana se détache de la Yougoslavie", "c451f492"], "d": ["L'Italie, qui avait occupé Ljubljana et la moitié occidentale de la Slovénie lors de l'effondrement de la Yougoslavie en avril 1941, annexa la région au Royaume sous le nom de province de Ljubljana par décret du 3 mai 1941 ; le haut-commissaire fut Grazioli. Ljubljana quitta la Yougoslavie pour passer sous administration italienne (jusqu'en septembre 1943).", "894bdb8c"]},
"OLAYLAR_2S0920:1941-05-05:0":{"b": ["Haïlé Sélassié rentre à Addis-Abeba — l'Abyssinie se détache de l'Afrique orientale italienne", "42470af3"], "d": ["Après la prise d'Addis-Abeba par les forces anglo-éthiopiennes début avril, l'empereur Haïlé Sélassié rentra triomphalement dans la capitale le 5 mai 1941 ; la fin officielle de l'occupation italienne (1936-41) est comptée à ce jour. L'Atlas utilise ce jour comme limite de retour de l'Abyssinie hors de l'Afrique orientale italienne.", "b9c24f62"]},
"OLAYLAR_2S0920:1942-01-01:0":{"b": ["Les forces japonaises occupent l'île de Labuan sans défense — la Malaya britannique (Straits Settlements) perd son île du nord de Bornéo", "a946e926"], "d": ["Lors de la campagne de Bornéo, une petite force japonaise débarqua sur l'île de Labuan, non défendue, et s'en empara ; l'île resta sous occupation militaire japonaise de janvier 1942 à septembre 1945. Selon les sources, la date varie entre le 1er et le 3 janvier.", "f83ac693"]},
"OLAYLAR_2S0920:1955-11-23:0":{"b": ["Les îles Cocos (Keeling) sont retirées de la colonie de Singapour et cédées à l'Australie", "5c2d70c7"], "d": ["Le 23 novembre 1955, jour de la proclamation (Proclamation) de l'Order in Council pris en vertu du Cocos Islands Act britannique de 1955 et du Cocos (Keeling) Islands Act 1955 de l'Australie, les îles cessèrent de faire partie de la colonie de Singapour et passèrent sous l'autorité du Commonwealth d'Australie. Home Island (propriété de la famille Clunies-Ross et établissement cocos-malais) est dès lors sous administration australienne.", "0edcf278"]},
"OLAYLAR_2S0920:1958-10-01:0":{"b": ["L'île Christmas est cédée par la Grande-Bretagne à l'Australie", "c971c518"], "d": ["Le Christmas Island (Transfer to Australia) Order in Council 1958 de la Grande-Bretagne entra en vigueur le 1er octobre 1958 ; la souveraineté de l'île passa de la colonie britannique de Singapour au Commonwealth d'Australie. Flying Fish Cove est le centre d'habitation et le port de l'île.", "7c935123"]},
"OLAYLAR_2S0920:1991-11-18:0":{"b": ["Vukovar tombe — l'Armée populaire yougoslave (JNA) et les unités serbes prennent la ville après trois mois de siège", "30db2698"], "d": ["Les défenseurs croates restants de Vukovar assiégée se rendirent le 18 novembre 1991 ; la ville tomba aux mains de l'Armée populaire yougoslave et des forces serbes. La ville passa par la suite sous l'Administration transitoire des Nations unies pour la Slavonie orientale (UNTAES).", "09aa356a"]},
"OLAYLAR_2S1019:1207-03-05:0":{"b": ["Gıyâseddin Keyhusrev conquiert Antalya — les Seldjoukides atteignent la Méditerranée", "9812e629"], "d": ["Antalya, passée aux mains de l'Italien Aldobrandini après la prise de Constantinople par les Latins, fut prise par le sultan des Seldjoukides d'Anatolie Gıyâseddin Keyhusrev Ier, avec le soutien des Grecs mécontents de l'administration latine.", "9d3888e0"]},
"OLAYLAR_2S1019:1216-01-22:0":{"b": ["İzzeddin Keykâvus reprend Antalya aux Chypriotes", "ec2446f9"], "d": ["Antalya, perdue en 1212 à la suite d'une révolte soutenue par le roi de Chypre, fut reconquise par İzzeddin Keykâvus Ier, qui en confia de nouveau le gouvernement à Mübârizüddin Ertokuş.", "62389ac4"]},
"OLAYLAR_2S1019:1268-03-08:0":{"b": ["Baybars prend Jaffa aux croisés — fin de la domination du royaume de Jérusalem à Jaffa", "c7629d70"], "d": ["Le sultan mamelouk Baybars Ier mit fin à la domination des croisés à Jaffa et fit détruire la ville ; il envoya le bois et le marbre de la citadelle pour la construction de sa mosquée au Caire.", "32ed8c27"]},
"OLAYLAR_2S1019:1268-05-18:0":{"b": ["Baybars prend Antioche — fin de la principauté d'Antioche", "da2b511a"], "d": ["L'armée mamelouke franchit les remparts d'Antioche par un assaut général ; la principauté croisée, vieille de 170 ans, prit fin et Alexandrette fut de nouveau rattachée aux terres de l'islam.", "7f091a6b"]},
"OLAYLAR_2S1019:1328-11-05:0":{"b": ["Les Karamanides reprennent Konya aux Ilkhanides", "057ec073"], "d": ["Après la fuite en Égypte du gouverneur ilkhanide d'Anatolie Demirtaş, Konya revint aux mains des Karamanides. La ville devait passer à Eretna en 1350.", "c2d583f3"]},
"OLAYLAR_2S1019:1344-03-26:0":{"b": ["Le roi de Castille Alphonse XI prend Algésiras (Cezîretülhadrâ) : fin de la domination mérinide après vingt mois de siège", "5de2a877"], "d": ["Après le siège d'environ vingt mois mené par le roi de Castille Alphonse XI, et au terme des négociations ouvertes le 21 mars 1344, le souverain mérinide Abu al-Hasan fit savoir aux musulmans qu'ils devaient quitter la ville ; le 26 mars Villa Nueva, le lendemain Villa Vieja furent évacuées et les Castillans prirent possession de la ville. Alphonse XI y fit une entrée solennelle le 28 mars 1344 (dimanche des Rameaux). Algésiras resta castillane jusqu'en 1369.", "ceda27c4"]},
"OLAYLAR_2S1019:1345-01-01:0":{"b": ["Étienne Dušan prend Serrès à Byzance", "2cc79d36"], "d": ["Profitant de la guerre civile byzantine, le roi serbe Étienne Dušan s'empara de Serrès et en fit la capitale de l'Empire serbe.", "24066996"]},
"OLAYLAR_2S1019:1375-01-01:0":{"b": ["Le comté de Feldkirch est vendu à l'Autriche des Habsbourg", "fe4a0306"], "d": ["Rodolphe, dernier comte de la branche Montfort-Feldkirch, vendit en 1375 toutes ses possessions aux Habsbourg, ducs d'Autriche ; le transfert effectif s'acheva à sa mort (1390). Feldkirch devint le premier grand morceau du Vorarlberg à passer aux Habsbourg.", "6f5d639e"]},
"OLAYLAR_2S1019:1389-07-01:0":{"b": ["Balčik et le littoral de la Dobroudja passent sous l'administration ottomane", "dfd348b9"], "d": ["Après la victoire de Kosovo, Balčik, sur le littoral de la Dobroudja, passa sous l'administration ottomane. Le voïévode de Valachie Mircea devait occuper la région aussitôt après, et la domination ottomane y serait rétablie en 1393.", "e99a023b"]},
"OLAYLAR_2S1019:1392-10-26:0":{"b": ["Les seyyids mar'ashides se rendent à Timur à Mâhâneser — le Mazandaran passe aux Timourides", "125dbed8"], "d": ["Timur, entré au Mazandaran lors de sa campagne de cinq ans, repoussa les Mar'ashides qui lui faisaient face à Karatogân dans la forteresse de Mâhâneser et reçut leur reddition. Un grand massacre eut lieu à Sârî et à Amol ; Sârî fut donnée à İskender Şeyhî, fils de Kiyâ Efrâsiyâb.", "0352c0d3"]},
"OLAYLAR_2S1019:1412-01-01:0":{"b": ["Šibenik passe de nouveau sous l'administration de la République de Venise", "9b7998bf"], "d": ["Après la vente à Venise, en 1409, des droits de Ladislas de Naples sur la Dalmatie, Šibenik, qui avait résisté, passa de nouveau en 1412 sous l'administration vénitienne. La ville resta possession vénitienne de Dalmatie jusqu'à la chute de la République en 1797.", "ed5b7778"]},
"OLAYLAR_2S1019:1417-02-18:0":{"b": ["Campagne de Çelebi Mehmed contre les Candaroğulları : Çankırı est donnée à Kasım Bey, placé sous protection ottomane", "da03b919"], "d": ["Marchant contre le Candaroğlu İsfendiyar Bey, qui avait aidé Şeyh Bedreddin à passer en Valachie, Çelebi Mehmed avança jusqu'à Kastamonu et assiégea Sinop, où İsfendiyar s'était retiré. İsfendiyar reconnut la suzeraineté ottomane ; le mont Ilgaz fut admis comme frontière, et Çankırı et ses environs furent donnés à son fils Kasım Bey, réfugié chez les Ottomans.", "f88b8d5e"]},
"OLAYLAR_2S1019:1439-08-27:0":{"b": ["Avec la prise de Semendire, Hisarcık (Grocka) passe aussi aux Ottomans", "ab724ec9"], "d": ["Semendire fut prise après un siège de trois mois. Hisarcık (Grocka), située à 17 km de Semendire, suit dans l'atlas le sort de Semendire, son centre principal, et passe le même jour du despotat serbe aux Ottomans (elle sera restituée en 1444).", "81989831"]},
"OLAYLAR_2S1019:1451-01-01:0":{"b": ["La première moitié du comté de Bregenz est vendue à l'Autriche des Habsbourg", "3a9598db"], "d": ["Élisabeth de Hochberg, héritière des Montfort-Bregenz, vendit en 1451 la moitié du comté de Bregenz aux Habsbourg ; l'autre moitié fut prise en 1523. Bregenz devint ainsi une partie du Vorarlberg des Habsbourg.", "c02a452c"]},
"OLAYLAR_2S1019:1458-08-06:0":{"b": ["Avec la reddition de Gördüs (Corinthe), Sicyone passe aussi aux Ottomans", "c7b0d22d"], "d": ["Lors de la campagne de Morée, le Conquérant prit Gördüs (Corinthe) par voie pacifique après un siège de trois mois. Sicyone, située à 17 km de Corinthe, suit dans l'atlas le sort de Gördüs, son centre principal, et passe le même jour aux Ottomans.", "42b1e20d"]},
"OLAYLAR_2S1019:1459-06-20:0":{"b": ["Avec la reddition de Semendire, Hisarcık (Grocka) passe aussi aux Ottomans", "e3d76f5c"], "d": ["Helena, veuve de Lazar Branković, remit la forteresse de Semendire aux Ottomans ; le despotat serbe prit fin. Hisarcık (Grocka), dont le centre principal est Semendire, passe le même jour aux Ottomans.", "13f15640"]},
"OLAYLAR_2S1019:1475-06-06:0":{"b": ["Reddition de Caffa et vassalité du khan de Crimée — la côte de Circassie (Sotchi, Touapse, Maïkop) rattachée au khanat de Crimée comme zone de protection lâche", "e99eb8e8"], "d": ["Après quatre jours de siège, Caffa se rendit à Ahmed Pacha et Mengli Giray reconnut la suzeraineté du sultan ottoman. La région de Sotchi, Touapse et Maïkop, patrie des tribus circassiennes qui reconnaissaient les khans de Crimée pour suzerains, est figurée dans l'atlas, à partir de cette date, comme rattachée au khanat de Crimée par un protectorat lâche.", "63b788a5"]},
"OLAYLAR_2S1019:1500-01-01:0":{"b": ["Moscou prend Briansk au grand-duché de Lituanie", "fb1c3a61"], "d": ["Lors de la guerre moscovito-lituanienne de 1500-1503, l'armée russe prit Briansk et la ville fut rattachée à l'État moscovite ; la trêve de 1503 reconnut ce gain.", "8e507991"]},
"OLAYLAR_2S1019:1516-08-24:0":{"b": ["Bıyıklı Mehmed Paşa prend Mossoul, Sinjar et İmâdiye aux Séfévides", "3039d6af"], "d": ["Bıyıklı Mehmed Paşa, qui avait battu Kara Han à Koçhisar, prit aux Séfévides les forteresses des environs pendant qu'il assiégeait Mardin : Mossoul, Ruha, Birecik et Sinjar furent prises, et İmâdiye ainsi que d'autres seigneurs kurdes acceptèrent la suzeraineté ottomane. La forteresse de Mardin ne devait être reçue qu'après le retour du pacha de Mercidabık.", "0ce2275b"]},
"OLAYLAR_2S1019:1523-06-06:0":{"b": ["Gustave Vasa est élu roi à Strängnäs — le royaume de Suède se sépare de l'Union de Kalmar", "a6e95f4c"], "d": ["Après le bain de sang de Stockholm (1520), Gustave Eriksson Vasa, qui s'était soulevé contre le roi de Danemark Christian II, fut élu roi le 6 juin 1523 par le Riksdag suédois réuni à Strängnäs en mai 1523. La Suède et la Finlande qui en dépendait sortirent ainsi définitivement de l'Union de Kalmar, en vigueur depuis 1397, et l'époque Vasa du royaume indépendant de Suède commença.", "64dcc4c4"]},
"OLAYLAR_2S1019:1526-12-05:0":{"b": ["Les États de Silésie reconnaissent Ferdinand Ier comme roi — la Silésie passe à l'Autriche des Habsbourg", "a28e10c2"], "d": ["Les États de Haute et de Basse Silésie, réunis en assemblée générale, reconnurent le 5 décembre 1526, sous réserve de la confirmation de leurs privilèges, le Habsbourg Ferdinand, élu en octobre 1526 à la couronne de Bohême laissée vacante par la mort de Louis II à Mohács, comme roi et son épouse Anne comme reine. Les duchés de Silésie entrèrent ainsi avec la couronne de Bohême sous l'administration des Habsbourg.", "bc2a3ff9"]},
"OLAYLAR_2S1019:1550-06-12:0":{"b": ["Le roi de Suède Gustave Vasa fonde Helsinki", "43468b54"], "d": ["Le roi de Suède Gustave Vasa fit fonder en 1550 Helsinki à l'embouchure de la Vantaa, comme nouvelle ville marchande destinée à concurrencer Reval (Tallinn) dans le commerce de la Baltique. La ville fut déplacée en 1640 vers son emplacement actuel, vers la mer.", "eb67b9f0"]},
"OLAYLAR_2S1019:1633-01-01:0":{"b": ["L'imam yaarubide d'Oman Nâsır b. Mürşid prend Julfar aux Portugais", "6ca9fb0c"], "d": ["Les Portugais, qui s'étaient maintenus à Julfar même après la chute d'Ormuz en 1622, furent chassés de la région par la prise de la ville en 1633 par l'imam yaarubide d'Oman Nâsır b. Mürşid.", "55e774dd"]},
"OLAYLAR_2S1019:1686-09-30:0":{"b": ["Perte de la forteresse de Sinj (Sin) au profit de Venise — arrière-pays dalmate", "3af8e103"], "d": ["Pendant la guerre de Morée, les forces vénitiennes prirent en 1686 aux Ottomans la forteresse de Sinj (Sin), dans l'arrière-pays dalmate ; la forteresse résista aussi au siège ottoman de 1715 et resta à Venise.", "9c5c08b5"]},
"OLAYLAR_2S1019:1687-09-06:0":{"b": ["Varadin et Baç passent au royaume de Hongrie (couronne des Habsbourg) — retrait de la Bačka après Harsány", "6bc2b1ac"], "d": ["L'armée de Sarı Süleyman Paşa, qui se retirait après la déroute de Harsány, passa à Varadin le 1er septembre 1687 et laissa la forteresse à Câfer Paşa ; peu après, Varadin et Baç, en Bačka, passèrent aux forces alliées des Habsbourg. Lorsque la Save fut admise comme frontière à Karlowitz, Varadin resta du côté autrichien.", "5ba42bd5"]},
"OLAYLAR_2S1019:1687-09-26:0":{"b": ["Osijek (Ösek) passe au royaume de Hongrie (couronne des Habsbourg) — début de la perte de la Slavonie", "7af97ffe"], "d": ["Après la déroute de Harsány, la forteresse-pont d'Osijek, sur la Drave, passa aux forces des Habsbourg le 26 septembre 1687. La présence militaire ottomane et la population turque de Slavonie se retirèrent progressivement entre 1686 et 1688 ; la région passa sous l'administration des Habsbourg.", "ae45a854"]},
"OLAYLAR_2S1019:1687-09-30:0":{"b": ["Perte de Herceg Novi au profit de Venise — entrée de la baie de Kotor", "b88046d8"], "d": ["Pendant la guerre de Morée, la flotte vénitienne et ses alliés assiégèrent et prirent en 1687 la forteresse de Herceg Novi, à l'entrée de la baie de Kotor ; la ville resta à Venise jusqu'à la chute de la République de Venise en 1797.", "aae8f2d8"]},
"OLAYLAR_2S1019:1794-06-15:0":{"b": ["La Corse est rattachée à la couronne britannique — royaume anglo-corse", "10f18bde"], "d": ["Paoli, qui s'était soulevé contre la France révolutionnaire, nettoya l'île des garnisons françaises avec l'appui de la flotte britannique ; la consulta réunie à Corte adopta une constitution rattachant la Corse au roi d'Angleterre. L'île resta deux ans sous le nom de royaume anglo-corse, sous l'administration du vice-roi britannique Gilbert Elliot.", "bdf0e618"]},
"OLAYLAR_2S1019:1796-10-01:0":{"b": ["Évacuation de la Corse par les Britanniques — l'île redevient française", "c9f986fe"], "d": ["Acculée en Méditerranée par les victoires de Bonaparte en Italie et par le passage de l'Espagne dans le camp de la France, l'Angleterre évacua la Corse. Le royaume anglo-corse prit fin et l'île fut de nouveau rattachée à la France.", "0338523e"]},
"OLAYLAR_2S1019:1878-09-18:0":{"b": ["L'armée austro-hongroise brise la résistance et prend Bihać", "ffec53e0"], "d": ["L'Autriche-Hongrie, qui avait obtenu par le traité de Berlin le droit d'occuper la Bosnie-Herzégovine, se heurta à Bihać à la résistance des musulmans locaux. Les forces commandées par le général Wilhelm von Reinländer prirent la ville le 18 septembre 1878 ; la garnison d'Ostrovica, dans la vallée de l'Una, sortit elle aussi des mains ottomanes lors de la même opération.", "207d2a2b"]},
"OLAYLAR_2S1019:1903-03-15:0":{"b": ["Les Britanniques occupent Sokoto — le califat de Sokoto perd sa capitale", "e744f986"], "d": ["Après avoir pris les émirats un à un, Lugard, gouverneur nommé par l'Angleterre, qui avait proclamé colonie le nord du Nigeria en 1900, infligea une lourde défaite à l'armée de Sokoto et occupa la capitale le 15 mars 1903. Avec l'assassinat à Burmi, en juillet, du calife en fuite Tâhir, la domination politique du califat prit fin.", "fe9507bb"]},
"OLAYLAR_2S1019:1906-04-13:0":{"b": ["Ibn Saoud bat l'émir rachidide — le Qasim passe de l'émirat de Shammar aux Saoudiens", "a32201dd"], "d": ["Abdelaziz ibn Saoud, qui avait repris Riyad en 1902, battit et tua l'émir rachidide Abdelaziz ibn Mutib le 13 avril 1906. À la suite de cette bataille, il s'empara de la région du Qasim (Buraydah, Unayzah) ; les Rachidides ne régnèrent plus ensuite que sur Haïl et ses environs.", "c99fc129"]},
"OLAYLAR_2S1019:1915-06-10:0":{"b": ["L'île de Kamaran est occupée par les Britanniques", "c514bb66"], "d": ["L'île de Kamaran, sur la côte du Yémen en mer Rouge, fut occupée par les Britanniques en 1915 pendant la Première Guerre mondiale et fut dès lors administrée depuis Aden.", "33e76176"]},
"OLAYLAR_2S1019:1918-09-21:0":{"b": ["Occupation de Naplouse par les Britanniques — effondrement du front de Palestine", "b5e85950"], "d": ["En septembre 1918, la grande offensive d'Allenby sur le front de Palestine disloqua les 7e et 8e armées ottomanes ; Naplouse passa aux mains des Britanniques et quatre siècles de domination ottomane y prirent fin. La ville resta sous administration militaire britannique jusqu'en 1920.", "d3195be1"]},
"OLAYLAR_2S1019:1918-11-08:0":{"b": ["Entrée des Britanniques à Mossoul — occupation du vilayet de Mossoul en violation de l'armistice", "ed5e8e33"], "d": ["Lorsque l'armistice de Moudros fut signé, Mossoul était aux mains des forces turques. S'appuyant sur l'article 7 de l'armistice, les Britanniques entrèrent dans la ville le 8 (ou le 10) novembre 1918, et le 15 novembre les troupes turques furent contraintes de se retirer du vilayet. La question de Mossoul ne fut pas non plus résolue à Lausanne et fut renvoyée au traité d'Ankara de 1926.", "168f5310"]},
"OLAYLAR_2S1114D5:1923-07-24:0":{"b": ["Traité de Lausanne — Patmos cédée à l'Italie, souveraineté grecque confirmée sur les îles de la mer Égée", "185960b3"], "d": ["Par l'article 15 de Lausanne, la Turquie renonça en faveur de l'Italie à tous ses droits et titres sur le Dodécanèse, Batnoz (Patmos) comprise ; les îles étaient de fait sous occupation italienne depuis 1912. L'article 12, lui, confirma la souveraineté grecque sur Lemnos, Samothrace, Mytilène, Chios, Samos et Ikaria. Bozbaba (Ay Strati) et Fornoz (Fourni) étaient aux mains des Grecs depuis 1912 et restèrent à la Grèce après Lausanne ; ces deux îles elles-mêmes ne sont pas nommées à l'article 12 de Lausanne.", "73a0b71c"]},
"OLAYLAR_2S1114D5:1935-12-25:0":{"b": ["Loi de Tunceli — le vilayet de Tunceli remplace le sandjak de Dersim (chef-lieu Kalan)", "1ae9ad50"], "d": ["Par la loi n° 2885, il fut décidé de créer dans la région de Dersim un nouveau vilayet nommé Tunceli ; le chef-lieu administratif du vilayet fut la localité de Kalan, qui prit par la suite le nom de Tunceli. La région resta au sein de la République de Turquie ; ce qui change, c'est le statut administratif et le nom.", "7970d4ac"]},
"OLAYLAR_2S1114D5:1956-03-02:0":{"b": ["Indépendance du Maroc : fin du protectorat français, Salé et Rabat reviennent au royaume du Maroc", "a62a3fdb"], "d": ["Par le traité d'indépendance signé le 2 mars 1956, le protectorat français, en vigueur depuis 1912, prit fin ; Salé et Rabat devinrent territoire du royaume indépendant du Maroc. L'Espagne reconnut l'indépendance du Maroc le 5 avril 1956.", "e888afb6"]},
"OLAYLAR_2S1114D5:1980-07-30:0":{"b": ["Les Nouvelles-Hébrides deviennent indépendantes : la République de Vanuatu est fondée", "cc93330f"], "d": ["Le condominium des Nouvelles-Hébrides, placé sous la souveraineté conjointe de la France et du Royaume-Uni, devint indépendant le 30 juillet 1980 sous le nom de Vanuatu. La capitale Port-Vila, sur l'île d'Efate, et la localité de Teouma passèrent de l'administration du condominium à Vanuatu.", "29b000d6"]},
"OLAYLAR_2S1114D5:1994-03-01:0":{"b": ["L'Afrique du Sud cède Walvis Bay à la Namibie", "96bb0184"], "d": ["Le 1er mars 1994, la République d'Afrique du Sud céda au gouvernement namibien le port de Walvis Bay et les douze îles du large ; quatre-vingt-quatre ans de contrôle sud-africain prirent fin.", "fdd93117"]},
"OLAYLAR_2S_0918:1284-01-01:0":{"b": ["Belgrade et Mačva données à Dragutin par le roi de Hongrie", "a4c2c535"], "d": ["Le roi de Hongrie donna en 1284 à Stefan Dragutin, roi de Serbie qui avait abdiqué en 1282, l'administration de Mačva et de Belgrade ; Belgrade resta plus de trente ans aux mains de Dragutin (royaume de Syrmie sous suzeraineté hongroise).", "2fb699cd"]},
"OLAYLAR_2S_0918:1293-01-01:0":{"b": ["Alanya (Alâiye) passe sous le contrôle d'une principauté locale à l'époque post-seldjoukide", "7b1489b3"], "d": ["Avec la désagrégation de fait de l'État des Seldjoukides d'Anatolie dans les années 1290, le port d'Alâiye (Alanya), sur la côte méditerranéenne, s'affranchit de l'autorité centrale et passa sous le contrôle des principautés de la région (à cette époque dans la zone d'influence des Karamanoğulları) ; la date exacte et la principauté qui dominait directement ne sont pas claires dans les sources.", "78a4ff46"]},
"OLAYLAR_2S_0918:1319-01-01:0":{"b": ["Les Hongrois reprennent Belgrade à Milutin", "16d254a2"], "d": ["Après la mort de Dragutin en 1316, la Serbie voulut garder Belgrade et la Hongrie en réclama la restitution ; en 1319, les Hongrois attaquèrent et, après des mois de combats, l'armée serbe se retira ; la ville, ruinée, fut rattachée au banat hongrois de Mačva. Belgrade resta sous administration hongroise jusqu'à sa cession à Stefan Lazarević en 1403-04.", "feb8ea91"]},
"OLAYLAR_2S_0918:1322-01-01:0":{"b": ["Sinop prise par Gazi Çelebi et passée sous l'influence des Candaroğulları", "f107586a"], "d": ["Avec l'affaiblissement de la domination ilkhanide, Gazi Çelebi, issu de la famille fondatrice de la principauté des Candaroğlu (İsfendiyaroğlu), qui se renforçait dans la région de Kastamonu et de Sinop, s'empara de Sinop vers 1322 et en fit un centre portuaire de la principauté.", "35c2fa9c"]},
"OLAYLAR_2S_0918:1322-03-01:0":{"b": ["Šibenik, entre les comtes Šubić et Venise, se rattache à Venise", "99b341e0"], "d": ["Šibenik, prise entre les comtes Šubić de Bribir, seigneurs croates, et Venise, se donna à Venise le 1er mars 1322 et resta sous administration vénitienne jusqu'en 1357.", "120581de"]},
"OLAYLAR_2S_0918:1322-04-17:0":{"b": ["Trogir se rattache à Venise contre les knez de Bribir", "4ccf9ce4"], "d": ["Trogir, sous la pression des comtes Šubić de Bribir, se donna à Venise le 17 avril 1322 pour préserver ses libertés et resta sous la protection de Venise jusqu'en 1357.", "e69237c1"]},
"OLAYLAR_2S_0918:1327-09-18:0":{"b": ["Fin de la souveraineté hongroise à Split — début de l'administration vénitienne", "4b04ca1a"], "d": ["La souveraineté hongroise, qui durait depuis 1133 dans la commune de Split, prit fin le 18 septembre 1327 ; la ville passa sous administration vénitienne et y resta jusqu'en 1357.", "75ef7dfc"]},
"OLAYLAR_2S_0918:1357-01-01:0":{"b": ["Fin de l'administration vénitienne à Split — la domination hongroise recommence", "e99628fc"], "d": ["L'administration vénitienne commencée à Split en 1327 prit fin en 1357 ; la ville passa de nouveau sous domination hongroise directe (jusqu'en 1420).", "84447172"]},
"OLAYLAR_2S_0918:1357-07-09:0":{"b": ["Trogir sort de la protection de Venise — la domination hongroise recommence", "7f112aa8"], "d": ["Trogir resta sous la protection et l'administration de Venise jusqu'au 9 juillet 1357 ; au moment où Louis d'Anjou commençait à arracher la Dalmatie à Venise, elle sortit de cette protection et revint sous la souveraineté du royaume croato-hongrois.", "6a7c7a44"]},
"OLAYLAR_2S_0918:1357-12-14:0":{"b": ["Šibenik se détache de Venise — passe sous domination hongroise", "adb9d6ca"], "d": ["Šibenik se détacha de Venise le 14 décembre 1357, alors que Louis d'Anjou arrachait la Dalmatie à Venise, et passa sous domination hongroise.", "7af69a3b"]},
"OLAYLAR_2S_0918:1358-02-18:0":{"b": ["Traité de Zadar — Dubrovnik passe de Venise à la protection de la Hongrie", "57fb81f9"], "d": ["Le traité de Zadar, signé le 18 février 1358, mit fin à 150 ans de domination vénitienne sur la Dalmatie ; Dubrovnik (Raguse) sortit ainsi de l'administration vénitienne et acquit le statut d'une république semi-autonome placée sous la protection du roi de Hongrie Louis Ier.", "e207c893"]},
"OLAYLAR_2S_0918:1358-05-27:0":{"b": ["Privilège de Višegrad — Dubrovnik rattachée au roi de Hongrie Louis Ier", "9d3d02a8"], "d": ["Lorsque Venise renonça à ses droits sur la Dalmatie par la paix de Zadar (février 1358), Dubrovnik négocia séparément avec le roi Louis Ier ; en mai 1358, par le privilège de Višegrad, elle fut rattachée à la couronne hongroise (allégeance en échange de la protection, tribut annuel et soldats).", "d37ccc8a"]},
"OLAYLAR_2S_0918:1390-06-01:0":{"b": ["Tvrtko Ier prend la souveraineté sur les villes côtières de Dalmatie (Šibenik comprise)", "c53aad4d"], "d": ["Le roi de Bosnie Tvrtko Ier prit en 1390 la souveraineté sur les villes côtières de Dalmatie, à l'exception de Zadar ; Šibenik sortit elle aussi de la domination hongroise et reconnut la suprématie du roi de Bosnie.", "dfb86467"]},
"OLAYLAR_2S_0918:1391-01-01:0":{"b": ["Mort de Tvrtko Ier ; Šibenik revient sous domination hongroise", "ef2d3b2f"], "d": ["Avec la mort en 1391 du roi de Bosnie Tvrtko Ier, la suprématie bosniaque sur Šibenik prit fin ; la ville passa sous la domination du roi de Hongrie Sigismond (1391-1402).", "0f8c4ab3"]},
"OLAYLAR_2S_0918:1408-01-01:0":{"b": ["La région d'Erzurum et d'Aşkale change de mains dans la rivalité qaraqoyunlu-timouride", "ca64775a"], "d": ["Dans le vide de pouvoir né après la mort de Tamerlan en 1405, le souverain qaraqoyunlu Kara Yûsuf se mit en mouvement de 1406 à 1408 contre les gouverneurs timourides de l'Anatolie orientale ; Erzurum et Aşkale, dans ses environs, sortirent dans cette lutte du contrôle timouride et entrèrent dans la sphère d'influence des Qaraqoyunlu.", "10b1b07c"]},
"OLAYLAR_2S_0918:1409-07-31:0":{"b": ["Zadar passe sous administration vénitienne — Santa Intrada", "820c9276"], "d": ["Après que Ladislas, roi de Naples, eut vendu la Dalmatie à Venise, la population de Zadar chassa de la ville les soldats napolitains ; le 31 juillet 1409, les provveditori vénitiens entrèrent dans la ville et établirent l'administration vénitienne, qui allait durer jusqu'en 1797.", "06e4d6fa"]},
"OLAYLAR_2S_0918:1420-06-22:0":{"b": ["Trogir passe sous administration vénitienne", "fbca501f"], "d": ["Pendant la guerre de Venise contre la Hongrie, avec l'arrivée de la flotte du capitaine général Piero Loredan, Trogir passa le 22 juin 1420 à Venise ; dernière des villes dalmates à se joindre à Venise, elle resta sous le pavillon vénitien jusqu'en 1797.", "8ebaf8eb"]},
"OLAYLAR_2S_0918:1462-01-01:0":{"b": ["Uzun Hasan des Aqqoyunlu supprime la branche ayyoubide de Hısnıkeyfâ", "2b464a1f"], "d": ["Hısnıkeyfâ (Hasankeyf) et Siirt, l'une des deux dernières branches survivantes de la dynastie ayyoubide dans le haut Tigre avec celle de Hama, furent annexées en 1462 par Uzun Hasan, souverain des Aqqoyunlu, mettant fin à la domination ayyoubide.", "8bf494b3"]},
"OLAYLAR_2S_0918:1515-04-01:0":{"b": ["Le Portugal achève sa domination sur les rives du détroit d'Ormuz", "bef031f0"], "d": ["L'expédition du golfe Persique lancée en 1507 par Afonso de Albuquerque s'acheva en 1515 en englobant l'île d'Ormuz et, sur la côte opposée, Qeshm et Buraimi ; le royaume d'Ormuz, tributaire de l'Iran, passa de fait sous protection portugaise, et le Portugal prit le contrôle du commerce du Golfe.", "117a5c7e"]},
"OLAYLAR_2S_0918:1569-07-01:0":{"b": ["Union de Lublin — les terres ukrainiennes passent de la Lituanie à la Pologne", "1881ceff"], "d": ["L'Union de Lublin, signée le 1er juillet 1569, fusionna le grand-duché de Lituanie et le royaume de Pologne en un seul État (la Rzeczpospolita). En vertu des conditions de l'accord, la Podolie, la Volhynie et la région de Kiev (Bar, Berdytchiv, Białystok, Braslav compris) furent cédées administrativement de la Lituanie directement au royaume de Pologne.", "184b03dd"]},
"OLAYLAR_2S_0918:1776-02-14:0":{"b": ["L'administration de Fiume transférée à la Croatie rattachée à la couronne hongroise", "dfedccf8"], "d": ["L'impératrice Marie-Thérèse confia par un édit du 14 février 1776 l'administration de Fiume à la Hongrie par l'intermédiaire du Conseil de Zagreb ; le Diplôme de 1779 fit de la ville un corps distinct (corpus separatum) directement rattaché à la couronne hongroise.", "bbf160dd"]},
"OLAYLAR_2S_0918:1809-10-14:0":{"b": ["Fiume cédée à la France par la paix de Schönbrunn (Provinces illyriennes)", "16bf1fca"], "d": ["Par la paix de Schönbrunn du 14 octobre 1809, Fiume passa de l'Autriche à la France et fit partie jusqu'en 1813 des Provinces illyriennes de Napoléon.", "417a8ae7"]},
"OLAYLAR_2S_0918:1813-01-01:0":{"b": ["Fiume revient des Provinces illyriennes françaises aux Habsbourg", "1b5b9954"], "d": ["En 1813, après la défaite de Napoléon en Russie, Fiume sortit des Provinces illyriennes et revint à l'Empire d'Autriche.", "5db16c92"]},
"OLAYLAR_2S_0918:1822-10-15:0":{"b": ["Fiume rendue au royaume de Hongrie", "aafdd0ee"], "d": ["À la suite de la décision de François Ier du 5 juillet 1822, le comte György Majláth reçut la ville au nom du gouvernement hongrois le 15 octobre 1822 ; Fiume revint au royaume de Hongrie.", "e30af380"]},
"OLAYLAR_2S_0918:1841-10-01:0":{"b": ["Les forces égyptiennes se retirent de la région d'Ahsâ (Lahsa)", "5ea75c8d"], "d": ["Les forces égyptiennes de Mehmed Ali Pacha avaient occupé en 1836 le Nedjd et l'Arabie orientale (Ahsâ, Qatif, Uqair, Djubail compris) ; la Convention des Détroits de Londres de 1840 ayant contraint l'Égypte à renoncer à ses conquêtes de la péninsule arabique, les forces se retirèrent de la région en 1841 et l'administration revint aux forces locales (influence des Saoud / des Al Khalifa).", "99ff8f81"]},
"OLAYLAR_2S_0918:1853-07-28:0":{"b": ["Forteresse d'Ak-Mechet prise par les forces russes — la ligne du Syr-Daria du khanat de Kokand s'effondre", "e9f9a9c7"], "d": ["Les forces russes commandées par le général Vassili Perovski s'emparèrent en juillet 1853, après un long siège, de la forteresse d'Ak-Mechet, sur les rives du Syr-Daria, qui appartenait au khanat de Kokand ; la forteresse devint ensuite, sous le nom de Perovsk, l'avant-poste du Turkestan russe.", "9e64a219"]},
"OLAYLAR_2S_0918:1881-01-24:0":{"b": ["Bataille de Göktepe — les Turkmènes Tekke de l'Akhal vaincus par la Russie", "76c7a102"], "d": ["Les forces russes commandées par le général Mikhaïl Skobelev brisèrent la résistance des Turkmènes Tekke de l'Akhal en faisant tomber, le 24 janvier 1881, la forteresse de Göktepe (Geok Tepe) ; la région turkmène transcaspienne, y compris la plaine du Dihistan, Abiverd et Nisa, entra dans le processus de rattachement à l'Empire russe (la province transcaspienne fut créée en 1881). Par cet événement, Kyzyl-Arvat et Achgabat (terres turkmènes de l'Akhal) passèrent à la Russie.", "f294fbe6"]},
"OLAYLAR_2S_0918:1881-03-26:0":{"b": ["Proclamation du royaume de Roumanie — la principauté devient royaume", "4d413f0c"], "d": ["La principauté de Roumanie, dont l'indépendance avait été reconnue au Congrès de Berlin après la guerre russo-turque de 1877-78, fut transformée en royaume le 26 mars 1881 (14 mars selon le calendrier julien) par le couronnement du roi Carol Ier ; tout le pays, y compris Babadag, Bârlad, Buzău et la capitale Bucarest, devint administrativement partie du nouveau royaume. Avec la proclamation du royaume, toute la Roumanie (Iași, Galați, Brăila, Constanța, Tulcea, Calafat et les autres villes) devint royaume de Roumanie.", "fbab3abf"]},
"OLAYLAR_2S_0918:1889-01-01:0":{"b": ["L'Italie annexe le plateau érythréen, Asmara et Keren comprises", "31308dc8"], "d": ["Profitant du vide de pouvoir né de la mort en 1889 de l'empereur d'Abyssinie Yohannes IV, l'Italie annexa de fait le plateau érythréen, Asmara et Keren comprises, à la suite du traité d'Uccialli (Wuchale) (2 mai 1889) ; le 1er janvier 1890, la colonie fut officiellement proclamée sous le nom d'« Érythrée ». Par cet événement, Kerene passa à l'administration italienne.", "b6bbb0a5"]},
"OLAYLAR_2S_0918:1895-07-01:0":{"b": ["Le nord-est du Kenya (ligne Garissa-Marsabit) rattaché au protectorat de l'Afrique orientale britannique", "e45c6d43"], "d": ["Avec le transfert en 1895 à la Couronne de la concession de l'Imperial British East Africa Company, le protectorat de l'Afrique orientale britannique ainsi créé s'étendit pour englober aussi des régions du nord-est telles que Garissa, Kitui, Marsabit et Wajir ; la prise en charge effective de ces régions intérieures s'étala sur la seconde moitié des années 1890.", "8cf3e473"]},
"OLAYLAR_2S_0918:1897-02-16:0":{"b": ["L'émirat d'Ilorin pris par les forces de la Royal Niger Company", "b111cb7d"], "d": ["L'émirat d'Ilorin, tributaire du califat de Sokoto, fut pris lors de la campagne de février 1897 des forces de la Royal Niger Company commandées par Sir George Goldie ; la puissance militaire de l'émirat fut brisée et la région entra de fait dans l'influence britannique (l'annexion officielle fut achevée avec la création du protectorat du Nigeria du Nord en 1900).", "95f49872"]},
"OLAYLAR_2S_0918:1899-04-09:0":{"b": ["Le roi du Bounyoro Kabalega fait prisonnier, le royaume rattaché au protectorat britannique d'Ouganda", "62bc7c64"], "d": ["Kabalega, roi du Bounyoro, qui résistait aux forces britanniques depuis 1894, fut capturé le 9 avril 1899 dans la région de Lango (près de Dokolo) et envoyé en exil aux Seychelles ; les terres du royaume, la capitale Hoima et Masindi comprises, furent rattachées au protectorat britannique d'Ouganda.", "87bc3dd6"]},
"OLAYLAR_2S_0918:1900-06-26:0":{"b": ["Traité de Toro — le royaume de Toro devient une partie autonome du protectorat britannique d'Ouganda", "c55340a2"], "d": ["Après la chute du Bounyoro en 1899, le royaume voisin de Toro officialisa dans le cadre de l'accord d'Ouganda de 1900 la protection britannique qu'il connaissait depuis 1896 ; le royaume, Fort Portal comprise, reçut dans le protectorat britannique d'Ouganda le statut d'une administration locale autonome.", "8459a73a"]},
"OLAYLAR_2S_0918:1901-09-02:0":{"b": ["L'émirat d'Adamaoua partagé entre l'Allemagne et l'Angleterre", "b9230d3d"], "d": ["L'émirat d'Adamaoua (Fombina), tributaire du califat de Sokoto, fut scindé en deux à l'issue des campagnes de 1899-1901 des forces coloniales allemandes et anglaises : la partie orientale (Garoua, Banyo, Maroua, Ngaoundéré comprises) fut rattachée au Cameroun allemand, la partie occidentale (capitale Yola) au Nigeria du Nord britannique ; l'émir Zubayr fut envoyé en exil. Par cet événement, Rey Bouba (Adamaoua (part allemande)) passa à l'administration du Cameroun allemand.", "e3ebfafa"]},
"OLAYLAR_2S_0918:1902-05-07:0":{"b": ["Bataille de Tit — les Touaregs de l'Ahaggar vaincus par les forces françaises", "831143d6"], "d": ["Lors de la bataille livrée le 7 mai 1902 près de l'oasis de Tit pendant l'expédition Cottenest, les forces françaises vainquirent définitivement les Touaregs Kel Ahaggar ; cette région intérieure du Sahara, y compris Abalessa, centre de l'Ahaggar, et Ideles, passa sous le contrôle de l'Algérie française.", "5c1e86d4"]},
"OLAYLAR_2S_0918:1903-01-01:0":{"b": ["Les forces françaises s'emparent de l'intérieur de l'Oubangui-Chari (ligne Bambari-Bria)", "0b9a9f72"], "d": ["Les campagnes vers le nord du Congo français placèrent de fait sous contrôle, au début des années 1900, l'intérieur de l'Oubangui-Chari, comprenant Bambari, Batangafo, Bossangoa et Bria ; la région fut officiellement organisée le 29 décembre 1903 en colonie d'Oubangui-Chari (partie de l'Afrique-Équatoriale française).", "ebbd38e7"]},
"OLAYLAR_2S_0918:1911-01-12:0":{"b": ["Le sultanat de Dâru'l-Kûtî du sultan Mohammed es-Senûsî supprimé par les forces françaises", "644b2c3f"], "d": ["Le sultanat de Dâru'l-Kûtî, fondé sur la traite des esclaves, de capitale Ndele, placé sous protection française en 1897, fut de fait supprimé par une expédition organisée en 1911, le sultan Mohammed es-Senûsî continuant de résister à l'autorité française ; Senûsî fut tué au combat, et le sultanat fut officiellement aboli en 1912.", "3f913340"]},
"OLAYLAR_2S_0919:1328-01-01:0":{"b": ["L'Ordre de Livonie cède les terres de Klaipėda (Memel) à la branche prussienne de l'Ordre teutonique", "e61e5d50"], "d": ["L'Ordre de Livonie céda à la branche prussienne de l'Ordre teutonique la forteresse de Klaipėda (Memel), à l'embouchure du Niémen, et ses terres environnantes ; l'évêque de Courlande céda sa part à la même branche en 1392. Klaipėda resta à l'Ordre par les paix de Toruń de 1411 et de Melno de 1422, et passa en 1525 au duché de Prusse.", "cad2853d"]},
"OLAYLAR_2S_0919:1329-01-01:0":{"b": ["Umur Bey prend aux Génois la forteresse portuaire de Smyrne", "ab92d96e"], "d": ["Aydınoğlu Umur Bey assiégea pendant deux ans et demi la forteresse portuaire de Smyrne, restée aux mains des Latins. L'administrateur génois de la forteresse, Martino Zaccaria, rendit la place et se rendit à Chio.", "1bec5de9"]},
"OLAYLAR_2S_0919:1343-01-01:0":{"b": ["Ibrahim Chah, des Sutayoghlu, s'impose à Diyarbakır", "179196cf"], "d": ["Après la dissolution de l'État ilkhanide, Ibrahim Chah, des Sutayoghlu, s'imposa dans la région de Diyarbakır, théâtre de luttes entre les Djalayirides et les Tchobanides ; sa domination dura jusqu'en 1353.", "6143de93"]},
"OLAYLAR_2S_0919:1343-01-01:1":{"b": ["Berat passe de Byzance aux Serbes — conquête de l'Albanie par Étienne Dušan", "1eba202e"], "d": ["La forteresse de Berat, qui avait brisé le siège angevin en 1281 et était depuis lors le chef-lieu de la dernière province byzantine de l'Adriatique, tomba aux mains des Serbes lors de l'avance d'Étienne Dušan en Albanie, pendant la guerre civile byzantine. Après la reddition de Krujë en mai ou juin 1343, Berat, Kanina et Valona devinrent serbes en deux ans ; John Komnenos Asen, beau-frère de Dušan, fut placé à la tête de la province.", "21876887"]},
"OLAYLAR_2S_0919:1348-01-01:0":{"b": ["Les Abdelwadides (Zayyânides) se libèrent de la domination mérinide à Tlemcen", "a4aa9573"], "d": ["Les Abdelwadides de Tlemcen, sous la conduite d'Osman II et de son frère Ebû Sâbit, se libérèrent de la domination des Mérinides. Cette indépendance fut brève.", "0afdf111"]},
"OLAYLAR_2S_0919:1351-01-01:0":{"b": ["Bayram Hoca conquiert son indépendance — naissance de la principauté des Qaraqoyunlu", "37964815"], "d": ["Bayram Hoca, considéré comme le premier bey des Qaraqoyunlu, conquit son indépendance en tuant Akçasakal Hüseyin Bey, souverain des Sutay. Il prit Mossoul et en confia l'administration à son frère Birdi Hoca.", "892dced7"]},
"OLAYLAR_2S_0919:1353-01-01:0":{"b": ["À la mort d'Ibrahim Chah, Diyarbakır passe sous l'administration des Djalayirides", "11c338ef"], "d": ["À la mort d'Ibrahim Chah, des Sutayoghlu, qui dominait la région de Diyarbakır depuis 1343, la région passa sous l'administration des Djalayirides.", "155719ec"]},
"OLAYLAR_2S_0919:1355-01-01:0":{"b": ["Enez passe sous administration génoise (famille Gattilusio)", "5dc12940"], "d": ["Enez, port important à l'époque byzantine, passa en 1355 sous administration génoise et fut gouvernée par la famille Gattilusio.", "33faefdd"]},
"OLAYLAR_2S_0919:1356-01-01:0":{"b": ["Le grand-duc de Lituanie Algirdas (Olgerd) prend Briansk", "3cad9caf"], "d": ["L'armée du grand-duc de Lituanie Algirdas prit Briansk. La ville resta rattachée au grand-duché de Lituanie jusqu'en 1500.", "03107c6d"]},
"OLAYLAR_2S_0919:1368-01-01:0":{"b": ["Les İnançoğulları reconnaissent la domination des Germiyanoğulları", "0679db27"], "d": ["La principauté des İnançoğulları, qui régnait dans la région de Denizli, reconnut vraisemblablement en 1368 la domination des Germiyanoğulları.", "55ce9f1f"]},
"OLAYLAR_2S_0919:1371-11-01:0":{"b": ["Manuel, despote de Thessalonique, place la région de Serrès et de Drama sous administration byzantine", "abb99c3e"], "d": ["Avec la mort à la Maritsa (Çirmen, 26 septembre 1371) du roi Vukašin et d'Uglješa, despote de Serrès, l'administration serbe de la région de Serrès prit fin. Le prince byzantin Manuel II Paléologue, qui régnait à Thessalonique, plaça en novembre 1371 Serrès et la région, Drama comprise, sous administration byzantine. La région passa aux Ottomans en septembre 1383.", "b0802648"]},
"OLAYLAR_2S_0919:1378-01-01:0":{"b": ["À la mort de Pir Hüseyin Bey, Erzincan et Bayburt passent à Mutahharten", "3269e55d"], "d": ["À la mort de Pir Hüseyin Bey, émir d'Erzincan, Erzincan et Bayburt passèrent aux mains de Mutahharten, l'un des émirs d'Eretna ; Mutahharten devint émir d'Erzincan.", "4993bac9"]},
"OLAYLAR_2S_0919:1379-01-01:0":{"b": ["Tâceddin Bey met en déroute l'armée d'Eretna à Niksar et agit désormais de façon indépendante", "42982ea7"], "d": ["Au printemps 1379, Tâceddin Bey mit en déroute les forces de Kadı Burhâneddin et du bey d'Eretna Alâeddin Ali, qui attaquaient Niksar. Il cessa de payer tribut à la principauté d'Eretna et agit de façon indépendante à partir de l'année 781 (1379).", "5d809820"]},
"OLAYLAR_2S_0919:1379-01-01:1":{"b": ["Tamerlan conquiert définitivement le Khwarezm", "ef76d2c9"], "d": ["Après sa première campagne du Khwarezm en 1371, Tamerlan en organisa trois autres. Lors de la campagne de 1379, il conquit définitivement la région, la pilla et revint avec un riche butin.", "f2ebd27a"]},
"OLAYLAR_2S_0919:1382-01-01:0":{"b": ["Le roi de Bosnie Tvrtko Ier fonde Herceg Novi", "1628221a"], "d": ["Le roi de Bosnie Tvrtko Ier fonda une nouvelle ville dans la baie de Topla pour faire concurrence à Dubrovnik dans le commerce du sel ; la ville fut appelée par la suite Novi (Herceg Novi).", "b970dc7f"]},
"OLAYLAR_2S_0919:1383-01-01:0":{"b": ["Tamerlan prend Kandahar aux Kert et la donne à son petit-fils Pir Muhammed", "84760f70"], "d": ["Kandahar, aux mains depuis 1281 des Kert de Hérat, vassaux des Ilkhans, fut prise lors des campagnes de Tamerlan au Khorassan et donnée à son petit-fils Pir Muhammed ; la ville fut dès lors gouvernée par des gouverneurs timourides.", "c2470eb5"]},
"OLAYLAR_2S_0919:1384-01-01:0":{"b": ["Dulkadıroğlu Halil Bey reprend Elbistan aux Mamelouks", "ee3da686"], "d": ["Elbistan, tombée aux mains des Mamelouks en 1381, fut reprise en 1384 par Dulkadıroğlu Halil Bey.", "104e231d"]},
"OLAYLAR_2S_0919:1394-04-25:0":{"b": ["Tamerlan prend et pille Diyarbakır (Amid)", "f8d200a8"], "d": ["Tamerlan prit Diyarbakır le 25 ou le 26 avril 1394 et pilla la ville.", "b1186b21"]},
"OLAYLAR_2S_0919:1399-02-13:0":{"b": ["Gherardo Appiani cède Pise aux Visconti et fonde la seigneurie de Piombino", "ac45a9dd"], "d": ["Le seigneur de Pise, Gherardo Appiani, céda la ville pour 200 000 florins au maître de Milan, Gian Galeazzo Visconti. Il se réserva la seigneurie de Piombino, composée de Piombino, Suvereto, Scarlino et des îles d'Elbe, de Pianosa et de Montecristo.", "68084c1c"]},
"OLAYLAR_2S_0919:1401-01-01:0":{"b": ["Diyarbakır est donnée à Karayülük Osman Bey — début de la domination aqqoyunlu", "38262401"], "d": ["Diyarbakır, prise par Tamerlan en 1394, fut donnée en 1401 à Karayülük Osman Bey, ce qui marqua le début de la domination des Aqqoyunlu dans la région.", "de407b9c"]},
"OLAYLAR_2S_0919:1410-01-01:0":{"b": ["Erzincan passe sous domination qaraqoyunlu", "5729a50b"], "d": ["Après Mutahharten, Erzincan tomba aux mains du souverain qaraqoyunlu Kara Yûsuf. Kara Yûsuf nomma d'abord gouverneur de la ville Pîr Ömer, l'un de ses hommes de confiance.", "69ef181d"]},
"OLAYLAR_2S_0919:1494-01-01:0":{"b": ["Askia Muhammad prend Zâgha (Dia)", "24561a8c"], "d": ["Monté sur le trône songhaï, Askia Muhammad s'empara, à la fin de l'année 899 de l'Hégire, par l'intermédiaire de son frère Kurmina-Fari Amar Komzagho, de la ville de Zâgha (Dia), à l'ouest du delta intérieur du Niger.", "f6d242d2"]},
"OLAYLAR_2S_0919:1500-01-01:0":{"b": ["Chaybani Khan prend Boukhara et Samarcande", "8f8f40eb"], "d": ["Muhammed Chaybani Khan, profitant du désordre parmi les Timourides, prit Boukhara et Samarcande et fonda la dynastie des Chaybanides (Ouzbeks). Entre 1500 et 1507, il s'empara de presque toutes les villes de la Transoxiane, du Khwarezm et du Khorassan.", "0e64ecae"]},
"OLAYLAR_2S_0919:1510-01-01:0":{"b": ["Les Espagnols occupent Béjaïa", "8faa0133"], "d": ["Une armée espagnole de 8 000 hommes, venue par mer, occupa Béjaïa ; la population de la ville, prise de panique, quitta son pays.", "364b6234"]},
"OLAYLAR_2S_0919:1515-01-01:0":{"b": ["Agadez est rattachée au Songhaï", "997362b0"], "d": ["Agadez, centre de la région de l'Aïr, fut rattachée à Gao par le sultan songhaï Askia Muhammad ; la ville demeura dans cette dépendance jusqu'à l'effondrement du Songhaï à Tondibi en 1591.", "b2b437a3"]},
"OLAYLAR_2S_0919:1522-01-01:0":{"b": ["Fondation du sultanat du Baguirmi", "03829f94"], "d": ["La tribu des Kenga, sous la conduite de Birni Besi, fonda un État puissant à l'est du lac Tchad, centré sur Masinya (Massenya). La fondation de la dynastie du Baguirmi est traditionnellement datée de 1522.", "2bd4497c"]},
"OLAYLAR_2S_0919:1535-11-01:0":{"b": ["Mort du dernier duc Sforza, Milan passe à Charles Quint", "53230b5c"], "d": ["Le duc de Milan Francesco II Sforza mourut sans enfant dans la nuit du 1er au 2 novembre 1535. Le duché passa à l'empereur Charles Quint et commença à être gouverné par un gouverneur espagnol.", "03b908c5"]},
"OLAYLAR_2S_0919:1544-01-01:0":{"b": ["Les Génois s'établissent sur l'île de Tabarka", "0cb474f8"], "d": ["À la suite de l'accord conclu par Charles Quint avec le souverain de Tunis, qui autorisait la construction d'une forteresse sur la côte et la pêche du corail, une communauté génoise originaire de Pegli fut installée sur l'île de Tabarka. L'île devint une base commerciale gouvernée par la famille Lomellini.", "74c7ab83"]},
"OLAYLAR_2S_0919:1556-01-01:0":{"b": ["Après la mort d'Humayun, les Séfévides prennent Kandahar aux Moghols", "318eabc8"], "d": ["Après la mort d'Humayun à Delhi en 1556, le chah Tahmasp tira parti de la rivalité entre les gouverneurs moghols de Kandahar et du Zamindawar ; une troupe séfévide venue à l'invitation du gouverneur du Zamindawar entra à Kandahar, et Tahmasp nomma son cousin, le sultan Hüseyin Mirza, gouverneur de la ville. La ville resta aux mains des Séfévides jusqu'en 1595.", "87ac27f5"]},
"OLAYLAR_2S_0919:1558-01-01:0":{"b": ["La Russie envahit la Livonie, Dorpat tombe", "dcb46a8a"], "d": ["Ivan IV envahit la Livonie pour atteindre la Baltique et déclencha la guerre de Livonie ; il s'empara de Narva et de Dorpat (Tartu) et assiégea Reval.", "37f1dd66"]},
"OLAYLAR_2S_0919:1579-07-13:0":{"b": ["Fondation de la forteresse de Karlovac", "9b28e6ad"], "d": ["La forteresse de Karlovac fut fondée dans la plaine inondable entre la Kupa et la Korana afin de protéger la Croatie et les terres héréditaires d'Autriche contre les Ottomans ; elle fut bâtie par l'archiduc Charles II, commandant de la Frontière militaire de Croatie.", "edc1a0fd"]},
"OLAYLAR_2S_0919:1580-04-10:0":{"b": ["Acte de fondation (location) de Zamość", "e1157f3b"], "d": ["Jan Zamoyski, grand chancelier de Pologne, délivra l'acte de fondation (location) de la ville de Zamość.", "90df0b1c"]},
"OLAYLAR_2S_0919:1582-01-15:0":{"b": ["Trêve de Iam Zapolski — la Livonie et Dorpat passent à la Pologne", "7d02d8ad"], "d": ["La trêve de Iam Zapolski est signée entre la Pologne-Lituanie et la Russie ; Moscou renonce à ses prétentions sur la Livonie et restitue les terres de Polotsk. Dorpat (Tartu) reste aux mains de la Pologne à partir de 1582.", "3aa35e5c"]},
"OLAYLAR_2S_0919:1589-07-02:0":{"b": ["La forteresse de Tsaritsyne est mentionnée pour la première fois dans un document", "ddf65b06"], "d": ["Un décret du tsar Fiodor Ivanovitch du 2 juillet 1589 mentionne la forteresse de Tsaritsyne, édifiée pour protéger la frontière méridionale de la Volga ; cette date est tenue pour le jour de fondation de la ville.", "fd3ba360"]},
"OLAYLAR_2S_0919:1590-07-12:0":{"b": ["Fondation de la forteresse de Saratov", "a3ca702c"], "d": ["Saratov fut fondée par le prince Zasekine comme forteresse-poste afin de protéger la route de la Volga et les frontières orientales de l'État contre les raids des nomades.", "07dcdc66"]},
"OLAYLAR_2S_0919:1593-01-01:0":{"b": ["Fondation de la forteresse de Pelym", "baf3e7eb"], "d": ["Le voïvode Piotr Gortchakov fonda Pelym sur les rives de la Tavda ; la forteresse devint l'un des points d'appui de l'avancée russe en Sibérie occidentale.", "7511aeab"]},
"OLAYLAR_2S_0919:1598-01-01:0":{"b": ["Fondation de la forteresse de Verkhotourié", "81be29bb"], "d": ["Le point fortifié de Verkhotourié fut fondé sur les rives de la Toura, à l'emplacement de l'ancienne localité de Neromkar ; sa fondation est liée à la recherche d'une route plus courte vers la Sibérie.", "ac40c773"]},
"OLAYLAR_2S_0919:1600-01-01:0":{"b": ["Fondation de la forteresse de Turinsk sur la Toura", "c1d8534e"], "d": ["En 1600, le fort cosaque de collecte du tribut (ostrog) de Turinsk fut fondé dans l'actuelle région de Turinsk ; la forteresse compte parmi les fortifications d'étape de l'avancée russe en Sibérie occidentale.", "82075fd3"]},
"OLAYLAR_2S_0919:1611-01-01:0":{"b": ["Le chah Abbas Ier fonde la ville de Ferahabad au Mazandéran", "cab4d0fe"], "d": ["Le souverain séfévide Abbas Ier fit fonder la ville de Ferahabad au Mazandéran, près de la côte de la Caspienne, et y installa des populations venues de toutes les parties du pays. La construction commença en 1020/1611.", "cc05c705"]},
"OLAYLAR_2S_0919:1631-01-01:0":{"b": ["Fondation de la forteresse russe de Bratsk sur l'Angara", "e7b4be59"], "d": ["Lors de l'avancée de la Russie vers la Sibérie orientale, la forteresse de Bratsk fut fondée sur le fleuve Angara.", "eb1a1abd"]},
"OLAYLAR_2S_0919:1658-03-08:0":{"b": ["Traité de Roskilde — la Scanie, le Halland, la Blékinge et Bornholm passent à la Suède", "afcae41b"], "d": ["Le traité de Roskilde, qui mit fin à la première guerre de Charles X Gustave, fut signé ; le Danemark-Norvège céda la Scanie, le Halland, la Blékinge et Bornholm à la Suède.", "ac397fd6"]},
"OLAYLAR_2S_0919:1663-01-01:0":{"b": ["La Russie fonde la forteresse de Penza sur la Soura", "49e8d90b"], "d": ["Penza fut fondée comme grande forteresse au confluent de la Penza et de la Soura ; après 1684, elle forma l'extrémité occidentale de la ligne de défense de Syzran.", "afba0eaa"]},
"OLAYLAR_2S_0919:1668-01-01:0":{"b": ["Marquette fonde la mission française de Sault-Sainte-Marie", "86612bcd"], "d": ["Le jésuite Jacques Marquette fonda une mission en tête des rapides de Sault-Sainte-Marie, entre les lacs Supérieur et Huron.", "e90cdea2"]},
"OLAYLAR_2S_0919:1668-01-01:1":{"b": ["Fondation du premier poste de la Compagnie de la baie d'Hudson (Waskaganish)", "07b32d57"], "d": ["Dans la baie James, à l'embouchure de la rivière Rupert, Médard Chouart des Groseilliers fonda l'établissement considéré par la suite comme le premier poste de la Compagnie de la baie d'Hudson.", "790b2f93"]},
"OLAYLAR_2S_0919:1700-01-01:0":{"b": ["L'administration coloniale espagnole fonde Pitic (Hermosillo)", "11e5cc04"], "d": ["L'administration coloniale espagnole fonda une bourgade à l'emplacement d'un ancien établissement autochtone ; en 1828, la bourgade prit le nom de José María González de Hermosillo.", "4724e13c"]},
"OLAYLAR_2S_0919:1716-01-01:0":{"b": ["Fondation de la forteresse russe d'Omsk au confluent de l'Irtych et de l'Om", "13dcce5e"], "d": ["Omsk fut fondée comme forteresse à l'extrémité orientale de la ligne fortifiée de l'Ichim, entre le Tobol et l'Irtych ; elle devint ville en 1804.", "45facb52"]},
"OLAYLAR_2S_0919:1717-11-30:0":{"b": ["Les Dzoungars prennent Lhassa — Lajang Khan est tué, le Tibet passe sous occupation dzoungare", "65beea29"], "d": ["L'armée dzoungare commandée par Tsering Döndup attaqua de toutes parts, après minuit, Lhassa défendue par Lajang Khan, souverain des Khoshuts ; aidés de l'intérieur, les Dzoungars s'emparèrent de la ville et la pillèrent, mettant aussi le Potala à sac. Lajang Khan fut tué dans sa fuite ; les Dzoungars installèrent un gouvernement tibétain fantoche dirigé par sTag-rtse-pa.", "b6dcede2"]},
"OLAYLAR_2S_0919:1720-09-24:0":{"b": ["L'armée Qing entre à Lhassa — fin de l'occupation dzoungare, début du protectorat Qing", "083358c1"], "d": ["Des deux armées envoyées au Tibet par Kangxi, la colonne du Sichuan commandée par Galbi atteignit Lhassa au terme d'une marche difficile et prit la ville sans résistance ; les Dzoungars avaient concentré toutes leurs forces à Dam face à l'armée du Kokonor venue du nord. Avec le retrait des Dzoungars du Tibet, les Qing instaurèrent à Lhassa un régime de protectorat durable.", "e5c9dcf8"]},
"OLAYLAR_2S_0919:1721-01-01:0":{"b": ["L'expédition d'Aguayo fonde le presidio de Los Adaes", "2031793a"], "d": ["L'expédition du marquis d'Aguayo fonda un presidio (poste militaire) à Los Adaes et repeupla la mission ; le poste devint le point frontière du Texas oriental de la Nouvelle-Espagne face à la Louisiane française.", "6ccb0ff2"]},
"OLAYLAR_2S_0919:1722-01-01:0":{"b": ["Fondation du poste russe de Kainsk dans la steppe de Baraba", "b14552a8"], "d": ["Parmi les trois fortifications russes permanentes (pas) établies dans la steppe de Baraba, le poste de Kainsk fut fondé sur le cours moyen de l'Om, au confluent du ruisseau Kainka.", "17a78ef2"]},
"OLAYLAR_2S_0919:1743-01-01:0":{"b": ["Fondation de la forteresse russe de Troïtsk sur l'Oui", "623d75f2"], "d": ["Troïtsk fut fondée comme forteresse au confluent de l'Uvelka et de l'Oui, et reçut sa charte de ville en 1784.", "49367d34"]},
"OLAYLAR_2S_0919:1749-12-15:0":{"b": ["Par décret d'Élisabeth, fondation de la douane de Temernik à l'embouchure du Don (noyau de Rostov)", "46519168"], "d": ["L'impératrice Élisabeth Petrovna promulgua le décret ordonnant l'établissement d'une douane sur le Don, à l'embouchure de la Temernik ; la douane de Temernik marque le début de l'histoire ancienne de la ville de Rostov-sur-le-Don.", "51a82ea9"]},
"OLAYLAR_2S_0919:1750-01-01:0":{"b": ["Les Français fondent un poste de traite à Toronto sur la Humber", "18975f4c"], "d": ["Les Français établirent un second poste sur la rivière Humber ; l'année suivante, ils construisirent le fort Rouillé, à l'emplacement de l'actuelle Exhibition Place.", "66aeb450"]},
"OLAYLAR_2S_0919:1750-01-01:1":{"b": ["Le Qadjar Muhammed Hasan Khan proclame son indépendance ; il prend le Mazandéran et le Gilan", "42fc62e8"], "d": ["À la suite de la déposition du chah afcharide Süleyman, le chef qadjar d'Esterabad, Muhammed Hasan Khan, proclama son indépendance ; outre Esterabad et le Gorgan, il plaça sous son autorité le Mazandéran et le Gilan.", "f5398386"]},
"OLAYLAR_2S_0919:1751-01-01:0":{"b": ["Ahmad Chah Durrani annexe Balkh", "12c6bbf1"], "d": ["Le souverain afghan Ahmad Chah Durrani rattacha Balkh à sa sphère de souveraineté.", "e3ef9016"]},
"OLAYLAR_2S_0919:1751-01-01:1":{"b": ["Karim Khan Zand s'impose à Ispahan — en Iran, la domination afcharide cède la place à l'administration zand", "73cdc1e8"], "d": ["Après la mort de Nader Chah (1747), Ispahan et l'Irak persan furent gouvernés au nom des chahs afchârides Adil Chah (6 juillet 1747) et Ibrahim Chah (8 décembre 1748). Karim Khan Zand revint à Ispahan en janvier 1751 et s'imposa. Le Khorassan resta aux Afchârides sous l'autorité de Chahrokh.", "daab8159"]},
"OLAYLAR_2S_0919:1752-01-01:0":{"b": ["Fondation de la forteresse russe de Petropavlovsk sur l'Ichim", "5d16ef42"], "d": ["Petropavlovsk fut fondée comme forteresse russe et devint rapidement un centre important du commerce entre la Russie, l'Asie centrale et la steppe kazakhe.", "f0724528"]},
"OLAYLAR_2S_0919:1759-01-01:0":{"b": ["Les Touareg d'Agadez prennent la saline de Bilma au Kanem-Bornou", "1a563a74"], "d": ["Le Kanem-Bornou, en déclin au XVIIIe siècle, perdit de nombreuses localités du Sahara lorsque les Touareg d'Agadez lui enlevèrent en 1759 la saline de Bilma.", "ebfc53c3"]},
"OLAYLAR_2S_0919:1759-02-13:0":{"b": ["Le Qadjar Muhammed Hasan Khan est vaincu par l'armée de Karim Khan Zand et tué ; Esterabad, le Mazandéran et le Gilan passent sous l'administration zand", "38f0a375"], "d": ["L'armée de Karim Khan infligea une lourde défaite aux Qadjars ; Muhammed Hasan Khan fut tué dans sa fuite, et son fils Agha Muhammed fut emmené à Chiraz. Les terres de la principauté qadjare sur la côte de la Caspienne passèrent sous l'administration zand.", "aa7e4a1e"]},
"OLAYLAR_2S_0919:1806-01-01:0":{"b": ["L'armée du djihad d'Osman dan Fodio prend Zaria", "41279ca7"], "d": ["Lors du djihad lancé par Osman dan Fodio, la première attaque contre la capitale du Gobir, Alkalawa, échoua, mais Zaria fut prise en 1806.", "680cebf3"]},
"OLAYLAR_2S_0919:1808-01-01:0":{"b": ["Fondation de la ville de Sultanabad (Arak)", "674237a0"], "d": ["À l'époque qadjare, le général Yusuf Khan le Géorgien fonda l'actuelle ville d'Arak et lui donna le nom de Sultanabad.", "6ff3f6de"]},
"OLAYLAR_2S_0919:1818-01-01:0":{"b": ["Fondation de la ville de Beaufort (Beaufort West)", "c5cb1776"], "d": ["Dans la colonie britannique du Cap, la ville de Beaufort fut fondée sur la ferme de Hooyvlakte, dans le Karoo.", "70ea5620"]},
"OLAYLAR_2S_0919:1826-01-01:0":{"b": ["Balkh est occupée par l'émir de Boukhara", "cd255a5d"], "d": ["Balkh, sous domination afghane durrani, fut occupée en 1826 par l'émir de Boukhara ; la ville fut reprise par les Afghans en 1841.", "a3ecb1be"]},
"OLAYLAR_2S_0919:1830-01-01:0":{"b": ["La Russie fonde la forteresse d'Akmola sur l'Ichim", "6c727ca9"], "d": ["La Russie construisit la forteresse d'Akmola à Karautkul, sur le fleuve Ichim, et en fit le chef-lieu du pays des Kirghiz de Sibérie (les Kazakhs).", "9e7d586f"]},
"OLAYLAR_2S_0919:1847-01-01:0":{"b": ["Fondation du fort de Kopal — le Semiretchié du Nord commence à être rattaché à la Russie", "8d4c24c6"], "d": ["À la demande des Kazakhs de la Grande Horde, la Russie fonda le fort de Kopal au pied de l'Alatau de Djoungarie. Selon la source, cela facilita le rattachement du Semiretchié du Nord à la Russie jusqu'au fleuve Ili.", "ebe25fc6"]},
"OLAYLAR_2S_0919:1852-01-01:0":{"b": ["Des marchands de la côte s'installent à Kazeh (Tabora)", "173223b0"], "d": ["À la suite d'un conflit avec un souverain local, des marchands venus de la côte d'Afrique orientale émigrèrent vers le sud ; Fundikira, chef d'Unyanyembe, leur donna un lieu d'établissement près de sa capitale Itetemia. Cet établissement devint le noyau du centre caravanier de Tabora.", "1261b92f"]},
"OLAYLAR_2S_0919:1861-01-01:0":{"b": ["Les Peuls d'El-Hadj Omar prennent Djenné", "aa4e37f8"], "d": ["Djenné, où l'État du Macina entretenait une garnison, tomba en 1861 aux mains des Peuls placés sous le commandement d'El-Hadj Omar.", "bfbc8ebe"]},
"OLAYLAR_2S_0919:1862-05-16:0":{"b": ["El-Hadj Omar prend Hamdallaye — fin de l'État du Macina", "542f1c0d"], "d": ["Les troupes alliées du Macina, où s'était réfugié Bina Ali, qui avait fui Ségou, furent vaincues ; Hamdallaye, capitale du Macina, tomba aux mains d'El-Hadj Omar, et Bina Ali et Ahmedu Ahmedu furent exécutés.", "213cc232"]},
"OLAYLAR_2S_0919:1880-06-13:0":{"b": ["Brazza fonde Franceville", "d28410d7"], "d": ["Pierre Savorgnan de Brazza fonda, au nom de la France, le poste de Franceville sur un éperon rocheux dominant la rivière Mpassa.", "c23dd54e"]},
"OLAYLAR_2S_0919:1885-02-14:0":{"b": ["Convention de frontière entre l'État libre du Congo et le Portugal — la rive sud de l'embouchure du Congo au Portugal", "08a16627"], "d": ["Par la convention signée pendant la conférence de Berlin, la frontière entre l'État libre du Congo et le Portugal fut tracée sur le fleuve lui-même, de l'embouchure du Congo (Zaïre) jusqu'au ruisseau Uango-Uango ; la rive sud, où se trouve Soyo, revint au Portugal, et Cabinda, au nord du fleuve, resta également au Portugal.", "947cb572"]},
"OLAYLAR_2S_0919:1888-05-01:0":{"b": ["La côte du Hadramaout (Moukalla) passe sous protection britannique", "dc824725"], "d": ["Un traité de protectorat fut signé entre l'Angleterre et les Yafi'i (Kaïti), maîtres de la côte du Hadramaout, y compris Chihr et Moukalla ; les Britanniques assumèrent entièrement les relations extérieures de l'administration yafi'ie de la côte.", "98bd94ee"]},
"OLAYLAR_2S_0919:1890-01-01:0":{"b": ["Les Français dominent l'ensemble du Djolof", "c6d28eaa"], "d": ["Les Français, qui colonisaient la région par des accords conclus avec les chefs de tribus, dominèrent l'ensemble du Djolof en 1890.", "15595659"]},
"OLAYLAR_2S_0919:1893-01-01:0":{"b": ["Djenné est occupée par les Français", "b207bf62"], "d": ["Djenné, aux mains de l'État fondé par El-Hadj Omar, fut occupée en 1893 par les forces françaises et rattachée au Soudan français.", "5739cdc4"]},
"OLAYLAR_2S_0919:1894-01-01:0":{"b": ["Fondation de Gweru comme poste militaire", "bd37b323"], "d": ["Dans le centre de l'actuel Zimbabwe, la ville de Gweru fut fondée comme poste militaire ; elle devint par la suite un centre agricole et obtint le statut de municipalité en 1914.", "a8f323b9"]},
"OLAYLAR_2S_0919:1897-01-01:0":{"b": ["Le sultanat du Baguirmi passe sous protection française", "59f20c32"], "d": ["Face à la menace de Rabih, Gavrang, souverain du Baguirmi, conclut avec la France un traité de protectorat contraint. Lorsque Rabih, réagissant à cet acte, marcha pour occuper le Baguirmi, Gavrang incendia de ses propres mains la capitale Massénya.", "fcb0958f"]},
"OLAYLAR_2S_0919:1897-10-01:0":{"b": ["Le royaume de Kaffa est rattaché à l'Abyssinie — le dernier roi, Gaki Cherotcho, est fait prisonnier", "c03c44c5"], "d": ["Les forces de Menelik II, sous le commandement de ras Walda Giyorgis, entrèrent à Kaffa en mars 1897. Après de durs combats, Kaffa fut conquise ; le dernier roi, Gaki Cherotcho, fut capturé et se rendit en octobre 1897.", "a434cc44"]},
"OLAYLAR_2S_0919:1898-01-01:0":{"b": ["Gao est occupée par les Français", "01eabb4c"], "d": ["Gao, ancienne capitale songhaï sur les rives du Niger, fut occupée par les Français en 1898 ; après l'occupation, la ville se développa de nouveau et devint le centre de la région.", "653ce49b"]},
"OLAYLAR_2S_0919:1899-01-01:0":{"b": ["Fondation du dépôt de ravitaillement de Nairobi sur le chemin de fer de l'Ouganda", "a3ce3389"], "d": ["Sur le site de l'actuelle Nairobi, zone marécageuse jusque-là en grande partie inhabitée, les Britanniques établirent le dépôt de ravitaillement du chemin de fer de l'Ouganda, qui reliait Mombasa à l'Ouganda.", "467c7577"]},
"OLAYLAR_2S_0919:1901-01-01:0":{"b": ["Partage de l'Adamaoua — Yola reste au Nigeria du Nord britannique", "11104686"], "d": ["L'Adamaoua fut partagé entre le Nigeria du Nord, rattaché à l'Angleterre, et le Cameroun, rattaché à l'Allemagne ; Bobbo Ahmedu, quatrième fils d'Adama, devint émir de Yola dans la zone britannique.", "aabd087e"]},
"OLAYLAR_2S_0919:1903-07-27:0":{"b": ["Bataille de Burmi — fin de la domination politique du califat de Sokoto", "c7d87e2c"], "d": ["Muhammed Tahir, calife qui avait fui après l'occupation de Sokoto par les Britanniques, fut tué dans un nouveau combat contre eux ; la domination politique du califat de Sokoto, qui avait duré environ un siècle, prit fin.", "b37ec3fb"]},
"OLAYLAR_2S_0919:1904-01-01:0":{"b": ["Nakuru est officiellement fondée comme ville", "d82a2d76"], "d": ["Grâce à sa position sur le chemin de fer de l'Ouganda, Nakuru fut officiellement fondée comme ville et devint le centre des produits agricoles de la région.", "bf30445b"]},
"OLAYLAR_2S_0919:1905-01-01:0":{"b": ["Ouverture de la gare de la mer d'Aral sur le chemin de fer Orenbourg-Tachkent — fondation de la localité d'Aralsk", "85803dcb"], "d": ["Lorsque le chemin de fer de l'Empire russe reliant Orenbourg à Tachkent passa par l'extrémité nord-est de la mer d'Aral, la gare « Aralskoïe More » fut ouverte sur la côte ; un établissement de pêcheurs naquit à côté de la gare. L'établissement reçut le statut de ville en 1938 et prit le nom d'Aralsk.", "99e15bce"]},
"OLAYLAR_2S_0919:1909-06-02:0":{"b": ["Les Français prennent Abéché — fin du sultanat du Ouaddaï", "3c9b117b"], "d": ["Poursuivant leur avance vers l'est, les Français s'emparèrent d'Abéché (Ebîşe), capitale du Ouaddaï, et mirent fin au sultanat du Ouaddaï ; le dernier sultan se retira sans avoir pu sauver sa capitale.", "1f305da8"]},
"OLAYLAR_2S_0919:1910-05-31:0":{"b": ["Fondation de l'Union sud-africaine", "7434a47f"], "d": ["En vertu du South Africa Act de 1909, les colonies du Cap, du Natal, du Transvaal et de l'Orange s'unirent le 31 mai 1910 sous le nom d'Union sud-africaine, rattachée à l'Empire britannique ; le siège de l'exécutif fut Pretoria, celui du législatif Le Cap. Par cette union, les villes des colonies du Cap, du Natal, du Transvaal et de l'Orange (Kimberley, Durban, Pietermaritzburg, Potchefstroom, Port Elizabeth, etc.) passèrent à l'Union sud-africaine.", "7fc35ce0"]},
"OLAYLAR_2S_0919:1911-01-01:0":{"b": ["Les Français occupent Djanet", "f32997c8"], "d": ["Canet, nahiye ottomane rattachée à Ghat, fut occupée par les Français en 1911. Le directeur de la nahiye, le cheikh Amud, avait jusqu'à cette date reçu un traitement de l'État ottoman.", "7075093e"]},
"OLAYLAR_2S_0919:1915-01-01:0":{"b": ["Anchorage est fondée comme centre de l'Alaska Railroad", "f5014711"], "d": ["Après l'adoption de l'Alaska Railroad Act par le Congrès le 12 mars 1914, la commission d'ingénierie de l'Alaska établit au printemps 1915 le chantier ferroviaire à Ship Creek ; une ville de tentes naquit sur la côte et, en avril 1915, le bureau de poste donna à la nouvelle ville le nom d'Anchorage. La ville devint le centre de l'Alaska Railroad, qui s'étend vers le nord jusqu'à Fairbanks.", "ffe4cba5"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["Rattachement de Djaghboub, centre désertique de la Senoussiya, à l'ordre ottoman — firman d'exemption d'Abdülmecid", "039fce6d"], "d": ["Après être retourné en Tripolitaine, Muhammad ibn Ali al-Sanusi, qui avait longtemps séjourné à La Mecque, s'installa dans l'oasis de Djaghboub, à la frontière égyptienne, et y fit construire une grande zawiya sur un rocher dominant ; ce lieu, qui n'était que quelques baraques, devint rapidement une ville. En 1856, par un firman du sultan Abdülmecid, les biens des membres de la confrérie furent exemptés d'impôt et les disciples reçurent le pouvoir de collecter la zakat. Ce firman fit de l'oasis, située sur la route caravanière reliant l'Afrique occidentale et le Soudan au Caire, une partie de l'ordre financier et administratif ottoman et renforça Djaghboub comme centre commercial. L'attachement de la population de la région au calife est aussi confirmé par le récit de voyage du colonel Sadiq al-Mu'ayyad, qui visita l'endroit en 1884 et 1893.", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["Début des travaux de creusement du canal de Suez et fondation de Port-Saïd", "cef0be8d"], "d": ["Les travaux de creusement du projet de Lesseps, approuvé par la Sublime Porte le 5 janvier 1856, commencèrent le 25 avril 1859 ; le canal serait achevé dix ans plus tard, le 16 novembre 1869. À l'extrémité méditerranéenne du chantier, sur le cordon littoral entre le lac Menzaleh et la mer, le village de baraques de cinq maisons établi pour les ouvriers forma le noyau de Port-Saïd. La ville reçut en 1860, de la part des responsables de la compagnie du canal, ce nom signifiant « port de Saïd » en hommage au vice-roi d'Égypte de l'époque, Saïd Pacha. Ainsi, sur la carte ottomane, un nouveau port naquit sur une bande côtière où ne se trouvait auparavant aucune localité.", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["Visite du sultan Abdülaziz en Égypte et fondation d'Ismaïlia sur l'isthme de Suez", "bcfacf38"], "d": ["Le sultan Abdülaziz se rendit en Égypte le 3 avril 1863, à l'instigation du grand vizir Yusuf Kamil Pacha, et y fut accueilli par de grandes manifestations ; le but était de renforcer l'attachement au centre de la province, qui depuis la révolte de Méhémet Ali de Kavala commençait à devenir de fait un État distinct. La même année, sur l'isthme, sur les collines de Tilal al-Djisr au bord du lac Timsah, fut établi le siège administratif de la compagnie du canal : d'abord le village de Qaryat al-Timsah pour les ingénieurs, puis celui de Qaryat al-'Arab pour les ouvriers. Le khédive Ismaïl Pacha s'étant vivement intéressé au canal d'eau douce et y ayant fait construire un pavillon sur cette colline, la localité fut appelée Ismaïlia d'après son nom. La fondation de la ville est datée de l'année 1863 ; le jour exact n'est pas connu.", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["Gouvernorat de Midhat Pacha à Bagdad et sédentarisation des tribus — fondation de Ramadi et de Nasiriyya", "0fa98f06"], "d": ["Midhat Pacha, retiré de la présidence du Conseil d'État (Şûrâ-yı Devlet) et éloigné d'Istanbul, administra de 1869 à 1872 avec de larges pouvoirs la province de Bagdad, qui comprenait aussi Mossoul et Bassora, tout en exerçant le commandement de la VIe armée. Y appliquant le Code foncier et la nouvelle loi sur les provinces, il distribua les terres par titres fonciers (tapu) et rattacha les tribus nomades à la vie sédentaire et à l'autorité de l'État. Fruits de cette politique de sédentarisation, Ramadi fut fondée en 1869 sur l'Euphrate pour la tribu des Dulaym et, au sud, Nasiriyya par le mutasarrif des Muntafiq, Nasir Pacha al-Sa'dun ; toutes deux naquirent en des lieux sans habitat jusque-là et entrèrent sur la carte à cette date.", "7babb36f"]},
"OLAYLAR_ALM1115B:1024-09-08:0":{"b": ["Conrad II est élu roi d'Allemagne et couronné à Mayence — début de la dynastie salienne", "c88123e8"], "d": ["Après la mort d'Henri II, les princes allemands se réunirent le 4 septembre 1024 à Kamba, sur la rive droite du Rhin ; l'élection fut dirigée par Aribon, archevêque de Mayence. Conrad l'Ancien l'emporta sur son neveu Conrad le Jeune et fut couronné roi à Mayence par Aribon le jour de la fête de la Nativité de la Vierge (8 septembre).", "1d5ce932"]},
"OLAYLAR_ALM1115B:1039-06-04:0":{"b": ["L'empereur Conrad II meurt à Utrecht", "f967406b"], "d": ["Conrad II, premier empereur de la dynastie salienne, mourut à Utrecht le 4 juin 1039 après une brève et douloureuse maladie.", "6af4f169"]},
"OLAYLAR_ALM1115B:1122-09-23:0":{"b": ["Concordat de Worms — fin de la querelle des Investitures", "8073e4a0"], "d": ["Grâce à la médiation de la délégation pontificale, la paix entre l'empereur Henri V et le pape Calixte II fut proclamée le 23 septembre 1122 à Worms (à Lobwiesen, tout près de la ville). Henri renonça à l'investiture par l'anneau et la crosse et accepta l'élection canonique des évêques et des abbés.", "a915c2e7"]},
"OLAYLAR_ALM1115B:1125-05-23:0":{"b": ["L'empereur Henri V meurt à Utrecht", "790cadc4"], "d": ["L'empereur Henri V mourut à Utrecht le 23 mai 1125 ; il est resté connu comme l'empereur du concordat de Worms (1122).", "8402ca28"]},
"OLAYLAR_ALM1115B:1152-03-05:0":{"b": ["Frédéric Ier Barberousse est élu roi d'Allemagne à Francfort", "b91f29a3"], "d": ["Les princes élevèrent Frédéric à la royauté à Francfort le 5 mars 1152 ; il fut couronné à Aix-la-Chapelle le 9 mars. L'époque de Barberousse de la dynastie des Hohenstaufen commença ainsi.", "26fcdb8c"]},
"OLAYLAR_ALM1115B:1156-09-17:0":{"b": ["Privilegium Minus — l'Autriche devient duché, la Bavière est donnée à Henri le Lion", "a64c125b"], "d": ["Par la sentence des princes à Ratisbonne, l'Autriche fut élevée au rang de duché et des droits particuliers furent reconnus à Henri Jasomirgott ; dans le même arrangement, Henri rendit la Bavière à l'empereur, et l'empereur la donna en fief à Henri le Lion.", "fe899d87"]},
"OLAYLAR_ALM1115B:1218-01-01:0":{"b": ["Avec l'extinction de la maison de Zähringen, Berne devient ville libre impériale", "1473c219"], "d": ["À l'extinction de la maison de Zähringen en 1218, Berne devint ville libre relevant directement de l'Empire ; elle entra en 1353 dans la Confédération suisse comme huitième membre.", "8bbdceab"]},
"OLAYLAR_ALM1115B:1264-01-01:0":{"b": ["Landgraviat de Hesse : Henri Ier de Brabant devient le premier landgrave de Hesse, paix avec la Misnie en 1264", "57067f04"], "d": ["L'histoire de la Hesse comme pays indépendant commence avec Henri Ier (« l'Enfant ») ; la paix avec la Misnie (Meißen) fut conclue en 1264. Henri fit bâtir un château à Cassel, qui devint les années suivantes sa résidence habituelle ; en 1292, il fut élevé à la dignité de prince d'Empire (Reichsfürstenstand).", "43d237e5"]},
"OLAYLAR_ALM1115B:1358-12-01:0":{"b": ["Le comté de Schwerin passe par accord à Albert II, duc de Mecklembourg", "013b6860"], "d": ["Par un contrat du 1er décembre 1358, Albert II acquit le comté de Schwerin en versant 10 000 marks d'argent au comte Nicolas ; la ville fut dès lors territoire du duché de Mecklembourg (son établissement comme capitale ne devint durable qu'au XVIe siècle).", "1d69a777"]},
"OLAYLAR_ALM1115B:1567-03-31:0":{"b": ["Le landgrave Philippe le Magnanime meurt à Cassel — la Hesse est partagée entre ses quatre fils", "c0cb27ed"], "d": ["Philippe Ier, landgrave de Hesse, l'un des chefs politiques de la Réforme, mourut à Cassel le 31 mars 1567. Conformément à son testament de 1562, le pays fut partagé entre ses quatre fils en Hesse-Cassel (Guillaume IV), Hesse-Marbourg (Louis IV), Hesse-Rheinfels (Philippe II) et Hesse-Darmstadt (Georges) ; le landgraviat de Hesse unifié prit ainsi fin.", "288ab83b"]},
"OLAYLAR_ALM1115B:1637-03-10:0":{"b": ["Bogislaw XIV, dernier duc de Poméranie, meurt à Stettin — la dynastie des Griffons s'éteint", "ab96746a"], "d": ["Le dernier duc de Poméranie, Bogislaw XIV, mourut à Stettin le 10 mars 1637, et avec lui s'éteignit la dynastie poméranienne indigène. Le partage effectif du duché (Brandebourg-Suède) fut entériné par la paix de Westphalie de 1648.", "2e5f6d25"]},
"OLAYLAR_ALM1115B:1646-01-01:0":{"b": ["Ferdinand III accorde à Brême les privilèges de ville libre impériale", "174142ee"], "d": ["L'empereur Ferdinand III reconnut en 1646 à Brême les privilèges de ville libre impériale ; la Suède s'y opposa et, en 1666, tenta de soumettre la ville par les armes, sans succès. Lorsque l'électeur de Hanovre obtint l'archevêché (1720), il reconnut Brême comme ville libre.", "4a574693"]},
"OLAYLAR_ALM1115B:1810-01-01:0":{"b": ["Brême est intégrée à l'Empire français — elle devient le chef-lieu du département des Bouches-du-Weser", "d5d149ae"], "d": ["Brême, prise par les Français en 1806, fut de 1810 à 1813 le chef-lieu du département des Bouches-du-Weser.", "0ac80a63"]},
"OLAYLAR_ALM1115B:1810-12-01:0":{"b": ["Napoléon annexe Lübeck à l'Empire français", "1ca78afe"], "d": ["Après la capitulation de Blücher près de Lübeck en novembre 1806, la ville avait été pillée par les Français ; en décembre 1810, Napoléon l'annexa à son empire. Lübeck était jusqu'à cette date ville libre impériale depuis 1226.", "b7bf744b"]},
"OLAYLAR_ALM1115B:1813-01-01:0":{"b": ["Lübeck se soulève contre la domination française et recouvre son statut de ville libre", "84e70d49"], "d": ["Soulevée en 1813 contre l'administration française, Lübeck fut reconnue en 1815 par le Congrès de Vienne comme ville libre et hanséatique de la Confédération germanique.", "f5432e01"]},
"OLAYLAR_ALM1115B:1813-01-01:1":{"b": ["Fin de la domination française — Brême recouvre son statut de ville libre", "4afa71be"], "d": ["Le maintien de Brême sous administration française comme chef-lieu du département des Bouches-du-Weser prit fin en 1813 ; la ville recouvra son indépendance en 1815 par le Congrès de Vienne et entra dans la Confédération germanique.", "b4e1a2ef"]},
"OLAYLAR_ALM1115B:1815-01-01:0":{"b": ["Le duché de Mecklembourg-Schwerin reçoit le titre de grand-duché", "3f5d05eb"], "d": ["Le duc de Mecklembourg-Schwerin Frédéric-François Ier reçut en 1815 le titre de grand-duc («großherzogliche Würde») ; la fiche du duché de Mecklembourg (1348-1815) s'achève ici, et le pays se poursuit comme grand-duché au sein de la Confédération germanique.", "bfbe2246"]},
"OLAYLAR_ALM1115B:1937-04-01:0":{"b": ["Entrée en vigueur de la loi du Grand-Hambourg — fin du statut d'État indépendant de Lübeck", "6df2f92a"], "d": ["La loi du Grand-Hambourg, promulguée le 26 janvier 1937, entra en vigueur le 1er avril 1937 ; Lübeck perdit une autonomie de plus de 700 ans et fut rattachée à la province prussienne de Schleswig-Holstein, tandis que les limites de Hambourg s'étendaient.", "b96594d2"]},
"OLAYLAR_AMERIKA0920:1511-08-15:0":{"b": ["Fondation de Baracoa — première ville de la conquête espagnole de Cuba", "8c033cf1"], "d": ["Diego Velázquez de Cuéllar commença en 1511 la conquête de Cuba avec une troupe venue d'Hispaniola et fonda Nuestra Señora de la Asunción de Baracoa, première ville espagnole de l'île. Baracoa devint la base des expéditions qui, durant les vingt années suivantes, se dirigèrent vers le Mexique (Hernández de Córdoba, Grijalva, Cortés).", "e3cd5e94"]},
"OLAYLAR_AMERIKA0920:1519-03-25:0":{"b": ["Bataille de Centla — la seigneurie maya de Potonchán tombe, fondation de Santa María de la Victoria", "8489a7d8"], "d": ["La flotte de Cortés, partie de Cuba, aborda à Potonchán, ville maya chontal à l'embouchure du río Grijalva. Vainqueurs de la bataille de la plaine de Centla grâce à leur supériorité en cavalerie et en armes à feu, les Espagnols fondèrent sur l'emplacement de la ville la bourgade de Santa María de la Victoria. C'est le premier établissement espagnol permanent sur le continent mexicain ; Malintzin (doña Marina), qui servirait d'interprète à Cortés, figurait parmi les présents offerts en ce lieu.", "8bbece52"]},
"OLAYLAR_AMERIKA0920:1519-08-15:0":{"b": ["Fondation de Panamá — première ville européenne sur la côte du Pacifique", "c0d86c22"], "d": ["Pedrarias Dávila, gouverneur du Darién, fonda la ville de Panamá sur le versant pacifique de l'isthme et y transféra l'administration coloniale depuis la côte caraïbe. La ville devint le port de départ des expéditions d'exploration et de conquête vers le sud ; les expéditions de Francisco Pizarro vers le Pérou y furent équipées.", "ce7e51d9"]},
"OLAYLAR_AMERIKA0920:1520-09-04:0":{"b": ["Prise de Tepeaca — première conquête de Cortés après la Noche Triste", "a9c27711"], "d": ["Cortés, qui s'était retiré de Tenochtitlan dans la nuit du 30 juin 1520 (Noche Triste) au prix de lourdes pertes, mena, après s'être réfugié à Tlaxcala, sa première attaque contre la seigneurie de Tepeaca, membre de la Triple Alliance. Il prit la ville et y fonda une bourgade espagnole sous le nom de Segura de la Frontera ; la route entre la côte de Veracruz et Tlaxcala fut ainsi sécurisée et la base de la seconde marche sur la capitale préparée.", "a7a4b070"]},
"OLAYLAR_AMERIKA0920:1523-07-25:0":{"b": ["Fondation de San Sebastián de Colima — ouverture de la Nouvelle-Espagne sur la côte du Pacifique", "30332cab"], "d": ["Gonzalo de Sandoval, l'un des capitaines de Cortés, soumit la vallée de Colima, dans l'ouest du Mexique, et y fonda la bourgade de San Sebastián de Colima. Celle-ci devint l'une des premières bases de la Nouvelle-Espagne sur la côte du Pacifique et fournit, dans les années suivantes, les chantiers navals des expéditions d'exploration de la mer du Sud.", "f5225860"]},
"OLAYLAR_AMERIKA0920:1534-12-06:0":{"b": ["Fondation de San Francisco de Quito — l'ordre espagnol dans l'ancienne capitale inca du nord", "7bb9f316"], "d": ["Le général inca Rumiñahui incendia Quito, capitale du nord, avant de la laisser aux Espagnols. Sebastián de Benalcázar fonda San Francisco de Quito sur les ruines ; ainsi, après Cuzco, le second centre de l'État inca passa lui aussi sous administration espagnole, et la conquête des Andes du Nord fut conduite depuis cette ville.", "569e8d50"]},
"OLAYLAR_AMERIKA0920:1535-01-18:0":{"b": ["Fondation de Lima — la capitale du Pérou espagnol transférée dans la vallée du Rimac", "1f15658c"], "d": ["Francisco Pizarro, constatant que Cuzco, dans les montagnes, était trop éloignée de la liaison maritime avec l'Espagne, fonda sur la côte, dans la vallée du Rimac, la Ciudad de los Reyes (Lima). La ville devint rapidement la capitale de la vice-royauté du Pérou et le centre de l'administration espagnole en Amérique du Sud.", "97bcf9d0"]},
"OLAYLAR_AMERIKA0920:1537-01-13:0":{"b": ["Fondation de Popayán — pont entre Quito et le pays des Muisca", "bf451979"], "d": ["Benalcázar, qui marchait vers le nord depuis Quito, fonda Popayán dans la vallée du Cauca. La ville devint l'extrémité nord de l'avancée espagnole venue du Pérou et ouvrit la voie à sa rencontre, l'année suivante, avec Quesada dans le pays des Muisca.", "fe54a6a7"]},
"OLAYLAR_AMERIKA0920:1537-08-01:0":{"b": ["Prise de Hunza — défaite du zaque Quemuenchatocha", "e8c1b661"], "d": ["Gonzalo Jiménez de Quesada, qui avait gravi le plateau depuis le río Magdalena, s'empara de Hunza, centre du zacazgo, l'une des deux têtes de la Confédération muisca, et fit prisonnier le zaque Quemuenchatocha. L'or saisi dans la ville fut le véritable butin qui nourrit la rumeur de l'Eldorado ; la moitié nord du pays des Muisca passa ainsi sous la domination espagnole.", "78bf5be1"]},
"OLAYLAR_AMERIKA0920:1537-08-15:0":{"b": ["Fondation d'Asunción — base espagnole sur le río Paraguay", "9a6dfa42"], "d": ["L'expédition du Río de la Plata n'ayant pu tenir à Buenos Aires, les Espagnols remontèrent le fleuve et Juan de Salazar de Espinosa fonda Nuestra Señora de la Asunción en s'appuyant sur l'alliance conclue avec les communautés guaranies. La bourgade demeura pendant un siècle le centre de l'administration espagnole dans le bassin du Río de la Plata.", "451f5b55"]},
"OLAYLAR_AMERIKA0920:1538-08-06:0":{"b": ["Fondation de Santa Fe de Bogotá — capitale espagnole dans le pays des Muisca", "3ed6c301"], "d": ["Quesada fonda Santa Fe de Bogotá à côté de Bacatá, centre du zipa. Aussitôt après cette fondation, les colonnes de conquête venues de trois directions différentes — Quesada, Benalcázar et le commandant allemand Federmann — se rencontrèrent sur le même plateau et convinrent de régler leurs prétentions en Espagne. La ville devint la capitale du royaume de Nouvelle-Grenade.", "cd8c76fd"]},
"OLAYLAR_AMERIKA0920:1539-01-09:0":{"b": ["Fondation de San Juan de la Frontera de Huamanga — verrou de la route Lima-Cuzco", "3f1cfdbf"], "d": ["La résistance menée par Manco Inca depuis Vilcabamba coupait la route entre Lima et Cuzco. Pour sécuriser cette route, Francisco Pizarro fonda San Juan de la Frontera de Huamanga à mi-chemin des deux capitales ; le mot « frontera » (frontière) dans le nom de la bourgade dit directement l'objectif de sa fondation.", "fcd683ec"]},
"OLAYLAR_AMERIKA0920:1539-08-06:0":{"b": ["Refondation de Tunja comme ville espagnole", "c3a12867"], "d": ["Après le retour de Quesada en Espagne, Gonzalo Suárez Rendón refonda la ville de Tunja selon le modèle espagnol, à l'emplacement de Hunza, centre du zaque. La moitié nord du pays des Muisca fut ainsi rattachée, comme Bogotá, à un régime durable de municipalité et d'encomienda.", "fdbb81cc"]},
"OLAYLAR_AMERIKA0920:1540-10-04:0":{"b": ["Fondation de San Francisco de Campeche — troisième tentative, durable, de conquête du Yucatán", "62af9901"], "d": ["Après deux expéditions infructueuses pour prendre le Yucatán, Francisco de Montejo (le fils) fonda la bourgade de San Francisco de Campeche à l'emplacement de la ville maya de Can Pech. Ce port devint la base de ravitaillement des forces qui allaient marcher à l'intérieur de la péninsule et le point de départ de l'expédition qui aboutit, deux ans plus tard, à la fondation de Mérida.", "079bb50a"]},
"OLAYLAR_AMERIKA0920:1541-02-12:0":{"b": ["Fondation de Santiago del Nuevo Extremo — début de la conquête du Chili", "04cd7c3b"], "d": ["Pedro de Valdivia, qui marchait vers le sud depuis le Pérou, fonda Santiago del Nuevo Extremo dans la vallée du Mapocho. La bourgade fut incendiée en septembre de la même année par une attaque autochtone conduite par Michimalonco, puis refondée ; malgré cela, la conquête espagnole du Chili fut menée depuis ce point.", "7cfe7c18"]},
"OLAYLAR_AMERIKA0920:1545-01-01:0":{"b": ["La seigneurie des Cocom à Sotuta passe sous la domination espagnole", "db6a6487"], "d": ["Sotuta, l'une des plus puissantes seigneuries mayas de l'intérieur du Yucatán, résista longtemps à l'avancée espagnole sous la dynastie des Cocom. Dans les années qui suivirent la fondation de Mérida en 1542, la seigneurie accepta la domination espagnole ; cette allégeance devint définitive après la répression de la grande révolte de l'est en 1546-47.", "461a3b98"]},
"OLAYLAR_AMERIKA0920:1571-08-15:0":{"b": ["Fondation de la Villa de Oropesa — peuplement de la vallée céréalière destinée à nourrir Potosí", "d6821cbf"], "d": ["Sur ordre du vice-roi Francisco de Toledo, la Villa de Oropesa fut fondée dans la vallée de Cochabamba. Les terres fertiles de la vallée furent organisées en région céréalière destinée à nourrir la nombreuse main-d'œuvre des mines d'argent de Potosí ; la bourgade devint le grenier du Haut-Pérou colonial.", "52cdfafe"]},
"OLAYLAR_AMERIKA0920:1572-06-24:0":{"b": ["Chute de Vilcabamba — fin de l'État inca indépendant", "31b5a95d"], "d": ["Après la chute de Cuzco en 1533, Manco Inca et ses successeurs maintinrent dans les montagnes de Vilcabamba, durant quarante ans, un État inca indépendant. L'expédition organisée par le vice-roi Francisco de Toledo s'empara de la capitale abandonnée ; le dernier souverain, Túpac Amaru, qui avait fui, fut capturé, amené à Cuzco et exécuté en ce lieu. L'existence politique de la dynastie inca, vieille de quatre siècles dans le monde andin, prit ainsi fin.", "957d76a8"]},
"OLAYLAR_AMERIKA0920:1596-09-20:0":{"b": ["Fondation de Monterrey — capitale du Nuevo León", "ec6e44bc"], "d": ["Après deux tentatives infructueuses, Diego de Montemayor fonda la Ciudad Metropolitana de Nuestra Señora de Monterrey près de la source de Santa Lucía. Cet établissement de la frontière nord devint le point d'appui de l'expansion durable de la Nouvelle-Espagne vers le nord-est (Nuevo León).", "6bfa991f"]},
"OLAYLAR_AMERIKA0920:1619-01-01:0":{"b": ["Fondation de San Francisco de Borja — domination espagnole à Maynas", "7ee32d19"], "d": ["Diego Vaca de Vega fonda San Francisco de Borja en aval du détroit du Pongo de Manseriche, sur le río Marañón, et rattacha ainsi la région de Maynas à l'administration espagnole. La bourgade devint le point de départ du réseau de missions jésuites qui se poursuivrait pendant le siècle suivant dans le haut Amazone.", "83ae5281"]},
"OLAYLAR_AMERIKA0920:1718-05-01:0":{"b": ["Fondation de la mission de San Antonio de Valero — noyau du Texas espagnol", "ca9bd147"], "d": ["En réponse à l'infiltration des Français depuis la Louisiane vers l'ouest, l'Espagne décida d'établir une implantation durable au Texas. Le père Olivares fonda la mission de San Antonio de Valero sur les rives du río San Antonio ; quelques jours plus tard, le gouverneur Alarcón établit à ses côtés le presidio de San Antonio de Béxar. Le bâtiment de la mission sera plus tard connu sous le nom d'Alamo.", "74e48544"]},
"OLAYLAR_AMERIKA0920:1774-01-01:0":{"b": ["Fondation de Refugio (l'actuelle Matamoros) — peuplement de l'embouchure du Rio Grande", "f3b86da7"], "d": ["Le programme de peuplement du Nuevo Santander mené par José de Escandón à partir des années 1740 couvrit de fermes et de bourgades le bas bassin du Rio Grande. Nuestra Señora del Refugio de los Esteros fut fondée sur la rive sud du fleuve comme l'un des derniers maillons de ce programme ; au XIXe siècle, elle prit le nom de Matamoros.", "913bb307"]},
"OLAYLAR_AMERIKA0920:1821-09-15:0":{"b": ["Acte d'indépendance de l'Amérique centrale — la capitainerie générale du Guatemala se sépare de l'Espagne", "f998089a"], "d": ["À la suite du plan d'Iguala au Mexique, l'assemblée réunie à Guatemala proclama l'indépendance de la capitainerie générale vis-à-vis de l'Espagne ; le capitaine général Gabino Gaínza demeura à la tête de l'administration de transition. La domination espagnole prit ainsi fin sur les territoires des actuels Guatemala, Salvador, Honduras, Nicaragua et Costa Rica. Après avoir brièvement été rattachée à l'Empire mexicain, la région fonda en 1823 les Provinces-Unies d'Amérique centrale.", "c4e39cd1"]},
"OLAYLAR_AMERIKA0920:1839-01-01:0":{"b": ["Fondation de Nueva Helvetia — le Mexique ouvre la vallée du Sacramento à la colonisation", "067a1f2a"], "d": ["L'immigrant suisse John Sutter, muni de l'autorisation et de la concession de terres obtenues des autorités mexicaines, fonda Nueva Helvetia au confluent du Sacramento et de l'American River. Cette ferme fortifiée devint le poste le plus avancé du Mexique dans l'intérieur de la Haute-Californie ; avec la découverte de l'or en 1848, elle deviendra le centre de la ruée vers la Californie.", "1c5eab3d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0014-01-01:0":{"b": ["La Rhétie et le Norique sont rattachés à Rome : Tibère et Drusus prennent le pays au-delà des Alpes", "be6f2a15"], "d": ["En 15 av. J.-C., Tibère et Drusus vainquirent les tribus alpines et achevèrent la Rhétie (et l'annexion du Norique) ; la rive supérieure du Danube devint la frontière romaine.", "b564c899"]},
"OLAYLAR_ANTIK_AKDENIZ:-0024-01-01:0":{"b": ["À la mort d'Amyntas, la Galatie devient province romaine", "e4250ad7"], "d": ["Lorsque le roi galate Amyntas, nommé par Antoine, fut tué en Cilicie (25 av. J.-C.), Auguste transforma la Galatie en province romaine et la réunit à la Pisidie et à la Lycaonie. Ancyre (Ankara) devint la capitale ; l'inscription des Res Gestae d'Auguste (Monumentum Ancyranum) y fut écrite.", "d9e5074f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0026-01-16:0":{"b": ["Octavien reçoit le titre d'« Auguste » : début du Principat (période impériale)", "310297b6"], "d": ["Le 16 janvier 27, le Sénat conféra à Octavien le titre d'Auguste ; Octavien reçut pour une longue durée le commandement (imperium) de la plus grande partie des provinces. Cette date est considérée comme le début de l'Empire romain.", "6a533271"]},
"OLAYLAR_ANTIK_AKDENIZ:-0032-01-01:0":{"b": ["Bocchus II meurt ; la Maurétanie passe sous le contrôle d'Octavien", "414fa36c"], "d": ["À la mort sans enfant de Bocchus II en 33, la Maurétanie passa sous administration romaine, Octavien la recueillant par testament ; elle resta un temps sous administration romaine directe et fut confiée à Juba II en 25.", "ab445b2d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0035-01-01:0":{"b": ["Antoine fait d'Archélaos le roi de Cappadoce", "1e83e691"], "d": ["En réorganisant l'Orient, Antoine donna le trône de Cappadoce à Archélaos ; celui-ci gouverna jusqu'à ce que Tibère le rappelle à Rome en 17 apr. J.-C. La Cappadoce devint province romaine en 17 apr. J.-C. (cet événement fait l'objet d'un article distinct de la chronologie).", "cdb79213"]},
"OLAYLAR_ANTIK_AKDENIZ:-0041-01-01:0":{"b": ["Philippes : Octavien et Antoine battent Brutus et Cassius", "4386016f"], "d": ["En octobre 42, deux batailles distinctes eurent lieu près de Philippes ; Cassius et Brutus se suicidèrent et la puissance républicaine disparut. Les triumvirs se partagèrent le monde romain.", "ee38e78c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:0":{"b": ["Jules César fait refonder Corinthe comme colonie romaine", "283a5daa"], "d": ["Peu avant l'assassinat de César, des colons citoyens romains (pour la plupart des affranchis) furent installés à Corinthe ; la ville devint l'un des centres importants de la province romaine d'Achaïe. La décision de refondation date de 44 av. J.-C., l'installation de 44/43 av. J.-C.", "237b35af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:1":{"b": ["Burebista est victime d'un assassinat : le royaume dace est démembré", "9b9edb14"], "d": ["Strabon écrit que Burebista fut tué dans un coup de force interne avant la mort de César et que le royaume fut divisé en cinq, puis en quatre parties. L'union dace ne put être reconstituée jusqu'à Décébale (87 apr. J.-C.).", "eaa97397"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-03-15:0":{"b": ["César est assassiné au Sénat aux ides de mars (15 mars)", "18649074"], "d": ["Proclamé dictateur perpétuel, César fut poignardé le 15 mars 44 par un groupe de sénateurs lors d'une séance du Sénat au théâtre de Pompée. Sa mort prépara le terrain de nouvelles guerres civiles et du pouvoir d'Auguste.", "4180e38f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0044-03-17:0":{"b": ["Munda : César bat les fils de Pompée", "e1e93362"], "d": ["Le 17 mars 45, à Munda, César vainquit l'armée de Gnaeus Pompée et de Sextus Pompée ; l'Hispanie resta aux mains de César. C'est la dernière grande bataille de la guerre civile.", "67dd7b63"]},
"OLAYLAR_ANTIK_AKDENIZ:-0045-01-01:0":{"b": ["Thapsus : César bat Juba Ier ; la Numidie orientale devient la province d'Africa Nova", "77b28c50"], "d": ["Au printemps 46, à Thapsus, César mit en déroute l'armée de Scipion et de Juba Ier ; Juba se suicida. La partie orientale de la Numidie devint la province d'Africa Nova, administrée par Salluste, et la partie occidentale fut donnée à Bocchus et à Sittius.", "a92567de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0046-05-21:0":{"b": ["Zéla : César bat Pharnace II (« veni vidi vici »)", "11bf082a"], "d": ["Pharnace II, fils de Mithridate, tenta de reprendre le Pont en profitant de la guerre civile ; César le vainquit à Zéla en 47 et réorganisa le Pont sous contrôle romain. Pharnace s'enfuit au Bosphore et y mourut.", "8dc5a21a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0047-01-01:0":{"b": ["Pharsale : César bat Pompée", "e821abe8"], "d": ["Après le repli de Dyrrachium, César mit en déroute à Pharsale l'armée plus nombreuse de Pompée. Pompée s'enfuit en Égypte où il fut tué ; les provinces d'Orient s'ouvrirent à César.", "c606b7e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0051-01-01:0":{"b": ["Alésia : César assiège et bat Vercingétorix, la résistance de la Gaule est brisée", "d57cab9f"], "d": ["En 52 av. J.-C., le soulèvement de la Gaule conduit par l'Arverne Vercingétorix fut réprimé par le siège d'Alésia mené par César et par la défense de sa ligne de siège ; Vercingétorix se rendit. L'année suivante, la Gaule passa entièrement sous contrôle romain.", "9e045798"]},
"OLAYLAR_ANTIK_AKDENIZ:-0057-01-01:0":{"b": ["Début de la guerre des Gaules de César : les Helvètes sont vaincus", "1e594bb3"], "d": ["En 58 av. J.-C., César, gouverneur de la Gaule cisalpine et transalpine, arrêta près de Bibracte la migration des Helvètes ; puis il vainquit les Germains d'Arioviste. La campagne devait durer huit ans et rattacher la Gaule à Rome.", "b0789047"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:0":{"b": ["Mithridate VI meurt à Panticapée ; le Bosphore revient à Pharnace", "0831b871"], "d": ["Mithridate, qui avait fui Pompée, se suicida dans la forteresse de Panticapée à la suite de la révolte de son fils Pharnace (63). Pharnace livra le Bosphore à Pompée et fut reconnu comme roi ami de Rome.", "13030863"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:1":{"b": ["Pompée unit la Bithynie à l'ouest du Pont et crée la province de Bithynie-Pont", "b2865ea8"], "d": ["Dans le règlement de l'Orient (65-63), Pompée créa la province de Bithynie-Pont en réunissant la Bithynie à la moitié occidentale du Pont ; les régions intérieures du Pont à l'est furent données à des princes locaux.", "2c7b03c0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0063-01-01:0":{"b": ["Pompée reconnaît la Commagène comme amie et alliée de Rome", "a48ba55c"], "d": ["Dans le règlement de l'Orient, Pompée confirma le royaume d'Antiochos Ier et une partie de la région de Séleucie (Zeugma), faisant de la Commagène un État tampon allié entre Rome et les Parthes. Le royaume fut rattaché à la province romaine en 17 apr. J.-C., puis définitivement en 72 apr. J.-C. (ces événements font l'objet d'articles distincts de la chronologie).", "47b7f8de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0065-01-01:0":{"b": ["Pompée bat Mithridate ; le Pont est rattaché à Rome", "8f3f50a6"], "d": ["En 66, dans la plaine du Lykos, Pompée mit en déroute de nuit l'armée de Mithridate ; Mithridate s'enfuit de Colchide au Bosphore. Les villes côtières du Pont passèrent sous contrôle romain et, en 63, la province unie à la Bithynie fut constituée.", "2e29932b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0069-01-01:0":{"b": ["Antiochos Ier Théos monte sur le trône de Commagène", "b1680d3f"], "d": ["Antiochos Ier, roi de Commagène, fit construire le tombeau-sanctuaire du Nemrut Dağı, qui unit les ascendances perse et macédonienne. Le royaume se trouvait en position d'État tampon entre Rome et les Parthes.", "c8db269f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:0":{"b": ["Cyrène devient province romaine (Cyrénaïque)", "f9993ffb"], "d": ["Vingt ans après le legs de son royaume à Rome par Ptolémée Apion (96), Rome soumit la Cyrénaïque au régime provincial ; en 67, elle fut unie à la Crète.", "214aba0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:1":{"b": ["Nicomède IV lègue son royaume à Rome", "e29d9fbc"], "d": ["À la mort de Nicomède IV (75/74), la Bithynie fut léguée par testament au Peuple romain ; Mithridate VI ne l'accepta pas et la troisième guerre mithridatique commença. La Bithynie devint province directe de Rome.", "b6ff7464"]},
"OLAYLAR_ANTIK_AKDENIZ:-0081-01-01:0":{"b": ["Burebista unit les tribus daces et gètes", "3648f92e"], "d": ["Selon Strabon, Burebista rassembla les Gètes et les Daces en un seul royaume et mena des expéditions au sud du Danube jusqu'aux confins de la Thrace et de l'Illyrie. Le royaume commença à menacer Rome le long du Danube.", "6eefe618"]},
"OLAYLAR_ANTIK_AKDENIZ:-0084-01-01:0":{"b": ["Paix de Dardanos : Mithridate se retire d'Asie et de Bithynie", "535818ed"], "d": ["Dans la paix de Dardanos conclue avec Sulla, Mithridate accepta d'évacuer toutes ses conquêtes (Asie, Bithynie, Cappadoce, Paphlagonie) et de livrer 70 navires et 2000-3000 talents. Mais la domination des ennemis de Sulla à Rome conduisit à la deuxième guerre mithridatique.", "baf04269"]},
"OLAYLAR_ANTIK_AKDENIZ:-0087-01-01:0":{"b": ["Mithridate envahit la province d'Asie ; Vêpres éphésiennes (massacre de 80 000 Romains)", "3986833b"], "d": ["Au début de la première guerre mithridatique (89/88), Mithridate envahit la Bithynie et la province d'Asie ; par un ordre donné à Éphèse, des citoyens romains furent massacrés en masse. Athènes passa elle aussi du côté du Pont (Aristion).", "1dc4fbbb"]},
"OLAYLAR_ANTIK_AKDENIZ:-0089-01-01:0":{"b": ["Lex Iulia : Rome accorde la citoyenneté aux alliés italiens (guerre sociale)", "f72ba27d"], "d": ["À la suite du soulèvement des alliés italiens de Rome (91-88), la Lex Iulia (90) et la Lex Plautia Papiria (89) accordèrent la citoyenneté romaine aux alliés restés fidèles et à ceux qui se soumettaient. La péninsule italienne jusqu'au Pô devint ainsi une seule société de citoyens.", "8b973270"]},
"OLAYLAR_ANTIK_AKDENIZ:-0094-01-01:0":{"b": ["Sulla installe Ariobarzane sur le trône de Cappadoce", "8bdd078c"], "d": ["Face au maintien de la Cappadoce par Mithridate VI par l'intermédiaire d'un roi enfant, Rome fit proclamer roi Ariobarzane pendant le gouvernement de Sulla en Cilicie. Au siècle suivant, la Cappadoce servit de tampon dans les rivalités entre Rome, la Perse et le Pont.", "d8f615b3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0095-01-01:0":{"b": ["Ptolémée Apion lègue Cyrène à Rome", "5edef477"], "d": ["Ptolémée Apion, qui gouvernait Cyrène, laissa en mourant sans enfant son royaume au Peuple romain (96) ; le Sénat laissa les villes libres, et Rome retarda jusqu'en 74 la transformation en province.", "14d9ff7c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0104-01-01:0":{"b": ["Bocchus livre Jugurtha à Rome ; l'ouest de la Numidie est rattaché à la Maurétanie", "7619ad15"], "d": ["Bocchus Ier, roi de Maurétanie et beau-père de Jugurtha, se réconcilia avec Rome en livrant Jugurtha à Sulla ; en échange, la partie occidentale de la Numidie lui fut laissée. Jugurtha mourut en prison à Rome en 104.", "0097a34f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0108-01-01:0":{"b": ["Pairisadès V cède son royaume à Mithridate VI : le Bosphore est rattaché au Pont", "835bbe74"], "d": ["Pairisadès V, sous la pression scythe, céda son royaume à Mithridate avec l'aide du général de Mithridate, Diophante ; le Bosphore devint ainsi le prolongement septentrional du Pont. Le commerce des céréales de la mer Noire passa alors au Pont, comme ressource de Mithridate.", "f9df6329"]},
"OLAYLAR_ANTIK_AKDENIZ:-0109-01-01:0":{"b": ["Diophante, général de Mithridate, bat les Scythes en Crimée", "d8d48c68"], "d": ["Diophante vainquit l'armée de Palakos, fils du roi scythe Skilouros, et prit les environs de Néapolis en Tauride ; le Bosphore et la Chersonèse furent rattachés au Pont.", "aa4118e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0111-01-01:0":{"b": ["Jugurtha prend Cirta : Rome intervient dans les affaires de Numidie", "660eb34a"], "d": ["En 112 av. J.-C., Jugurtha assiégea Cirta et tua Adherbal ; les marchands italiens massacrés dans la ville poussèrent Rome à déclarer la guerre à Jugurtha. La guerre dura jusqu'en 105.", "e2064bc2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0117-01-01:0":{"b": ["Fondation de Narbo Martius : la Gaule du Sud (Gaule transalpine) devient province romaine", "20c4bdfa"], "d": ["Rome, entrée en Gaule à l'appel de Massalia (125), prit la vallée du Rhône par ses victoires d'Aquae Sextiae (122) et sur les Allobroges ; en 118 av. J.-C., Narbo Martius fut fondée en Gaule comme première colonie romaine. La région devint la province de Gaule transalpine.", "41f61541"]},
"OLAYLAR_ANTIK_AKDENIZ:-0119-01-01:0":{"b": ["Mithridate VI Eupator monte sur le trône du Pont", "c2d5fd41"], "d": ["Mithridate VI, monté sur le trône encore enfant à la mort de Mithridate V (120/119), après quelques années de tutelle, fit du Pont une puissance rivale de Rome autour de la mer Noire.", "d5779c35"]},
"OLAYLAR_ANTIK_AKDENIZ:-0124-01-01:0":{"b": ["Rome entre en Gaule à l'appel de Massalia", "eaf7eb0a"], "d": ["Lorsque Massalia, pressée par les Salluvii et les Ligures, demanda l'aide de Rome, celle-ci envoya en 125 une armée en Gaule du Sud. Cette intervention conduisit à la fondation de Narbo Martius (118) et à la prise de la Gaule transalpine.", "2260c90e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0128-01-01:0":{"b": ["Aristonicos est vaincu ; la province d'Asie est créée à partir des terres de Pergame", "7ccdc59e"], "d": ["Aristonicos, qui revendiquait le trône sous le nom d'Eumène III, fut vaincu et capturé par l'armée romaine (129) ; par le règlement de Manius Aquillius, l'ancien royaume de Pergame devint la province d'Asie. Le système fiscal de la province (publicains) était pour Rome une grande source de revenus.", "c32277b7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0132-01-01:0":{"b": ["Numance tombe : la Celtibérie est rattachée à Rome", "ced07244"], "d": ["Scipion Émilien, après un siège de huit mois, réduisit Numance par la famine (133) ; la ville fut détruite. Les guerres celtibères prirent fin et l'intérieur de l'Hispanie citérieure fut rattaché à Rome.", "27b1db44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:0":{"b": ["Guerre d'Achaïe : la Ligue achéenne est vaincue par Rome, les ligues sont dissoutes", "e434cfe0"], "d": ["La Ligue achéenne, qui s'était dressée contre Rome à cause d'un différend frontalier avec Sparte, fut vaincue à Leucopetra en 146 ; Corinthe fut détruite et la Ligue dissoute de fait, une partie de la Grèce passant sous la surveillance de la province de Macédoine.", "5fc3bb08"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:1":{"b": ["Fin de la troisième guerre punique : Carthage est détruite, la province d'Afrique est créée", "522515b4"], "d": ["Après un siège de trois ans, P. Cornelius Scipion Émilien prit Carthage au printemps 146 ; la ville fut incendiée et détruite, ses terres rattachées à Rome. L'arrière-pays de Carthage devint la province d'Afrique ; la Numidie de Massinissa resta voisine à l'ouest.", "cbee045b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:2":{"b": ["La Macédoine devient province romaine", "dc6d2352"], "d": ["Après la répression de la révolte d'Andriscos (148), les quatre régions de la Macédoine furent réunies en une seule province romaine (146) ; au sud de la province, le contrôle de la Grèce fut aussi laissé à la surveillance du gouverneur de Macédoine. La via Egnatia fut construite dans les années suivantes de l'Adriatique à Thessalonique.", "ac02ecf5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0147-01-01:0":{"b": ["Révolte d'Andriscos : le royaume de Macédoine est brièvement rétabli, puis réprimé par Metellus", "0119ff73"], "d": ["Andriscos, qui se disait fils de Persée, réunifia la Macédoine en 150/149 et vainquit les premières forces romaines ; en 148, Metellus reprit la Macédoine. Le soulèvement fut la cause du rattachement de la Macédoine à l'administration directe de Rome.", "b03ea4e9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0148-01-01:0":{"b": ["Rome déclare la guerre à Carthage : début de la troisième guerre punique", "2e34c235"], "d": ["Face aux attaques de Massinissa, la défense de Carthage fut jugée violation du traité ; Rome déclara la guerre en 149 et rallia Utique. La ville de Carthage résista pendant trois ans sous le siège.", "89432e4f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0149-01-01:0":{"b": ["Massinissa attaque le territoire de Carthage : guerre de Numidie et de Carthage", "b47559a5"], "d": ["À la suite de la prise de territoires carthaginois par Massinissa (151/150), Carthage entra en guerre et fut vaincue par Massinissa ; Rome y vit une violation du traité et déclara la guerre en 149. Massinissa mourut en 148, à l'âge de quatre-vingt-dix ans.", "f6ed046f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:0":{"b": ["Rome ordonne à Rhodes de retirer ses gouverneurs de Lycie et de Carie ; la Ligue lycienne (Patara) échappe à la domination de Rhodes", "6bbe2b54"], "d": ["Après la troisième guerre de Macédoine, le Sénat romain ordonna à Rhodes de retirer avant un jour fixé ses gouverneurs de Lycie et de Carie ; Rhodes accepta ces pertes, les jugeant plus légères que la menace de guerre. La Ligue lycienne (centrée à Patara) échappa ainsi à la domination de Rhodes et subsista comme Ligue lycienne sous protection romaine.", "8f86b52d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:1":{"b": ["L'Épire est pillée par Rome : soixante-dix villes sont détruites", "456fb461"], "d": ["Après la troisième guerre de Macédoine, les villes molosses d'Épire restées proches de Persée furent pillées sur l'ordre d'Paul-Émile, et environ 150 000 personnes furent réduites en esclavage. L'Épire resta pauvre sous la domination romaine pendant le siècle suivant.", "0504e2ee"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:2":{"b": ["La Macédoine est divisée par Rome en quatre régions autonomes (mérides)", "7a795ba0"], "d": ["Par décision du Sénat (167 av. J.-C.), le royaume de Macédoine fut divisé en quatre régions centrées sur Amphipolis, Thessalonique, Pella et Pélagonie ; les mariages et l'acquisition de biens entre les régions furent interdits et l'exploitation des mines limitée.", "de7135d5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:3":{"b": ["Rome retire la Lycie et la Carie à Rhodes ; Délos est déclarée port franc", "09c8143f"], "d": ["Lors de la troisième guerre de Macédoine, la tentative de médiation de Rhodes entre Rome et Persée fut punie : le Sénat retira la Lycie et la Carie à Rhodes et les déclara libres, donna Délos à Athènes et en fit un port exempt de droits de douane. Les revenus commerciaux de Rhodes chutèrent lourdement.", "9636f108"]},
"OLAYLAR_ANTIK_AKDENIZ:-0167-06-22:0":{"b": ["Pydna : Paul-Émile bat Persée ; fin du royaume antigonide", "a59c5270"], "d": ["Le 22 juin 168, à Pydna, les légions romaines vainquirent la phalange macédonienne et mirent fin à la troisième guerre de Macédoine ; Persée se rendit à Samothrace et fut conduit à Rome pour la cérémonie du triomphe. La dynastie antigonide prit fin.", "d363d3f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:0":{"b": ["Paix d'Apamée : Eumène II obtient pour Pergame la Chersonèse de Thrace, la plus grande partie de la Phrygie, de la Lydie et de la Mysie", "f25ed9af"], "d": ["Après la défaite de Magnésie, Antiochos III signa la paix avec Rome en 188 : il abandonna le nord du Taurus. La plupart de ces terres furent données à la Pergame de son allié Eumène II (Chersonèse de Thrace, Grande Phrygie, Lydie, Mysie, une partie de l'Ionie).", "8ae36db5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:1":{"b": ["Paix d'Apamée : Rhodes reçoit la Lycie et le sud de la Carie", "aa5173c6"], "d": ["Après Magnésie, Rome donna à son alliée Rhodes la Lycie et la partie de la Carie située au sud du Méandre. Rhodes perdit ces terres en 167.", "74a2ccb5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:0":{"b": ["Manlius Vulso bat les tribus galates : l'indépendance des Galates passe sous la surveillance de Rome", "30ae73d7"], "d": ["Après Magnésie, Cn. Manlius Vulso envahit le pays galate et mit en déroute les Tolistoagiens et les Tectosages à l'Olympos et à Magaba ; par traité, les Galates acceptèrent de ne pas attaquer leurs voisins. La Galatie resta en grande partie indépendante, mais fut liée à l'équilibre romano-pergaménien.", "fb7daca7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:1":{"b": ["L'Étolie fait la paix avec Rome : elle perd Ambracie et Oiniadai et reconnaît la souveraineté de Rome", "f332c6bf"], "d": ["L'Étolie, qui s'était rangée aux côtés d'Antiochos pendant la guerre contre ce dernier, fit la paix avec Rome après le siège d'Ambracie par Fulvius Nobilior ; elle reconnut la « majesté » de Rome, paya une indemnité et abandonna des villes comme Ambracie et Oiniadai.", "a6d05b8b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0189-01-01:0":{"b": ["Magnésie du Sipyle : Rome et Pergame battent Antiochos III", "f650ef21"], "d": ["À l'hiver 190/189, à Magnésie, L. Scipion et Eumène II mirent en déroute l'armée d'Antiochos III. La paix d'Apamée (188) qui suivit la victoire conduisit Antiochos à abandonner le nord du Taurus.", "04d021ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0191-01-01:0":{"b": ["Sparte entre dans la Ligue achéenne : Philopœmen rattache la Laconie à la ligue après Nabis", "2629b6e1"], "d": ["Après l'assassinat du tyran spartiate Nabis (192), le stratège achéen Philopœmen fit entrer Sparte de force dans la Ligue achéenne. Sparte perdit tout à fait son indépendance en 188 avec la destruction de ses murailles.", "6ed14d83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0195-01-01:0":{"b": ["Flamininus proclame la liberté des Grecs aux Jeux isthmiques", "3d850bf2"], "d": ["Après Cynoscéphales, le commandant romain T. Quinctius Flamininus proclama, aux Jeux isthmiques de 196 av. J.-C., le retrait des garnisons macédoniennes de Corinthe, de Chalcis et de Démétriade, et que les cités grecques étaient « libres, exemptes de tribut et régies par leurs propres lois ». Rome s'installa ainsi en Grèce comme arbitre.", "41ba1fc4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:0":{"b": ["Cynoscéphales : Rome bat Philippe V ; la Macédoine est contrainte de se retirer de Grèce", "9cb44ca6"], "d": ["En juin 197, les légions romaines de Flamininus mirent en déroute la phalange macédonienne à Cynoscéphales. Dans la paix de 196, Philippe abandonna toutes ses positions en Grèce (Démétriade, Chalcis, Corinthe), livra sa flotte et paya 1000 talents.", "da059ad7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:1":{"b": ["Deux provinces romaines sont créées en Hispanie : Citérieure et Ultérieure", "1baa8383"], "d": ["Les terres d'Hispanie prises à Carthage furent divisées pour la première fois en deux provinces distinctes en 197, chacune gouvernée par un préteur. Après cette date, les guerres contre les Celtibères et les Lusitaniens dans la péninsule furent menées pour étendre le régime provincial romain.", "5b732530"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:0":{"b": ["Paix après Zama : Carthage perd l'Hispanie, les îles de la Méditerranée et sa flotte, et assume une indemnité de 10 000 talents", "8654422d"], "d": ["Après Zama (202), Rome confina Carthage à ses propres terres d'Afrique : les conditions acceptées furent l'abandon de l'Hispanie et des îles de la Méditerranée, la livraison de la flotte (à l'exception de 10 navires), le paiement de 10 000 talents pendant 50 ans et l'interdiction de faire la guerre sans l'accord de Rome. La Numidie de Massinissa devint un voisin indépendant.", "fcba363e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:1":{"b": ["Rome récompense Massinissa par le royaume de Syphax", "54ba7a64"], "d": ["Dans la paix de Zama, Rome attribua à Massinissa le royaume de Syphax et les terres frontalières prises à Carthage ; les revendications de Massinissa sur la région des « Emporia » et sur la frontière carthaginoise furent ensuite la cause de la guerre.", "106adff6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0201-01-01:0":{"b": ["Zama : Scipion et Massinissa battent Hannibal", "52e188e6"], "d": ["Lors de la bataille de Zama qui suivit le rappel d'Hannibal en Afrique, les légions de Scipion et la cavalerie numide de Massinissa vainquirent l'armée carthaginoise. La deuxième guerre punique s'acheva définitivement en faveur de Rome par cette bataille.", "0cd233b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0202-01-01:0":{"b": ["Syphax est vaincu et fait prisonnier ; Massinissa unifie la Numidie", "a42a3cb0"], "d": ["Scipion et Massinissa vainquirent l'armée de Syphax en 203 et firent Syphax prisonnier ; Massinissa s'empara de Cirta et du royaume de Syphax avec le soutien de Rome. La Numidie devint un royaume puissant par la réunion de ses parties orientale et occidentale.", "d6649bd5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0205-01-01:0":{"b": ["Ilipa et Gadès : l'Hispanie passe de Carthage à Rome", "31e5a50c"], "d": ["En 206, Scipion vainquit à Ilipa l'armée d'Hasdrubal Giscon et de Magon et mit fin au contrôle carthaginois en Hispanie ; Gadès passa elle aussi à Rome peu après. Carthage perdit les mines d'argent d'Hispanie et son réservoir de soldats.", "dd505492"]},
"OLAYLAR_ANTIK_AKDENIZ:-0208-01-01:0":{"b": ["Fabius Maximus reprend Tarente à Hannibal", "bd605091"], "d": ["Tarente, qui s'était rendue à Hannibal en 212, passa en 209 à Q. Fabius Maximus par une trahison. Avec la chute de la ville, Hannibal perdit son port le plus précieux d'Italie du Sud.", "33c6b48f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0210-01-01:0":{"b": ["Capoue tombe aux mains de Rome : la base campanienne d'Hannibal est perdue", "cfcb9c9a"], "d": ["Rome, qui assiégeait depuis deux ans Capoue passée à Hannibal après Cannes, prit la ville malgré la marche d'Hannibal sur Rome et la punit lourdement ; l'autonomie de Capoue fut supprimée. Hannibal se replia sur la défensive en Italie du Sud.", "9a129e81"]},
"OLAYLAR_ANTIK_AKDENIZ:-0215-01-01:0":{"b": ["Cannes : Hannibal encercle et anéantit l'armée romaine ; l'Italie du Sud commence à passer à Carthage", "94f5110a"], "d": ["En 216, à Cannes en Apulie, la manœuvre d'encerclement d'Hannibal anéantit une armée romaine d'environ soixante-dix mille hommes. Capoue, Tarente et de nombreuses villes d'Italie du Sud passèrent dans le camp de Carthage.", "1a19e07d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:0":{"b": ["L'armée romaine débarque en Hispanie : première base romaine à Emporion", "8cb47853"], "d": ["Après la marche d'Hannibal vers l'Italie, Cn. Cornelius Scipion débarqua à Emporion en 218 av. J.-C. et inaugura la présence romaine en Hispanie le long de l'Èbre ; la péninsule devint le second front de la deuxième guerre punique.", "ef7a1d28"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:1":{"b": ["Hannibal franchit les Alpes et pénètre en Italie", "a1d3bf5a"], "d": ["Hannibal traversa l'Èbre, les Pyrénées et le Rhône, franchit les Alpes en automne et descendit en Italie du Nord ; il battit les armées romaines au Tessin et à la Trébie. Le centre de gravité de la guerre d'Italie de Carthage fut ainsi porté au cœur de Rome.", "8a70efb1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0218-01-01:0":{"b": ["Hannibal prend Sagonte : l'étincelle de la deuxième guerre punique", "a497a334"], "d": ["Après un siège de huit mois, Hannibal prit Sagonte, alliée de Rome (219 av. J.-C.) ; Rome envoya des ambassadeurs exiger sa reddition et, devant son refus, la guerre fut déclarée. La guerre dura dix-sept ans en Italie, en Hispanie et en Afrique.", "8f80d7b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:0":{"b": ["Sellasie : Antigone Doson bat Cléomène, Sparte subit pour la première fois une occupation étrangère", "dc64a8db"], "d": ["À l'été 222, à Sellasie, l'alliance macédono-achéenne vainquit l'armée spartiate de Cléomène ; Cléomène s'enfuit en Égypte. Doson entra dans Sparte et la ramena à l'ordre de Lycurgue ; les Spartiates connurent pour la première fois de leur histoire l'occupation par une armée étrangère.", "575b0c9d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:1":{"b": ["Mediolanum (Milan) tombe aux mains de Rome : les Insubres sont vaincus, l'Italie du Nord s'ouvre à Rome", "d3ec639f"], "d": ["Après avoir vaincu les Gaulois à Télamon (225), Rome prit le contrôle de la plus grande partie de la plaine du Pô en 222 av. J.-C., par la victoire de Marcellus à Clastidium et la prise de Mediolanum. La région fut organisée en Gaule cisalpine.", "710258fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0223-01-01:0":{"b": ["La Ligue achéenne cède l'Acrocorinthe à Antigone Doson : Corinthe revient à la Macédoine", "c8ec9d0c"], "d": ["Pressée par Cléomène III, la Ligue achéenne, par l'entremise d'Aratos, demanda l'aide de la Macédoine et céda l'Acrocorinthe et Corinthe à Antigone Doson ; Doson fonda la Ligue hellénique (Hellenikos symmachia).", "4337420d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0225-01-01:0":{"b": ["Traité de l'Èbre : Carthage accepte de ne pas franchir l'Èbre vers le nord", "a199de0b"], "d": ["Hasdrubal, poursuivant la conquête de l'Hispanie commencée par Hamilcar, conclut avec Rome le traité de l'Èbre : Carthage ne franchirait pas l'Èbre en armes. L'attaque d'Hannibal contre Sagonte en 219 fut justifiée par une interprétation de ce traité.", "42aa3953"]},
"OLAYLAR_ANTIK_AKDENIZ:-0237-01-01:0":{"b": ["Rome enlève la Sardaigne et la Corse à Carthage", "4f7295ee"], "d": ["Lorsque les mercenaires rebelles de Carthage en Sardaigne demandèrent l'aide de Rome, Rome occupa l'île ; sous la menace de la guerre, Carthage dut abandonner les îles et payer 1 200 talents supplémentaires. Rome créa sa deuxième province (Sardinia et Corsica).", "60cb31ea"]},
"OLAYLAR_ANTIK_AKDENIZ:-0240-01-01:0":{"b": ["Îles Égates : la flotte carthaginoise est détruite ; la Sicile devient la première province romaine", "8bd16e8f"], "d": ["Lutatius Catulus défit en mars 241 la flotte carthaginoise de Hannon devant les Égates ; puis, par la paix de Lutatius, Carthage évacua la Sicile et accepta de payer une indemnité de guerre de 3 200 talents. La Sicile (hors la Syracuse de Hiéron) devint la première province de Rome.", "24ff35a3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0242-01-01:0":{"b": ["Aratos s'empare de l'Acrocorinthe : Corinthe passe de la Macédoine à la Ligue achéenne", "a88dfda6"], "d": ["Aratos de Sicyone neutralisa par un coup de main nocturne la garnison d'Antigone Gonatas dans l'Acrocorinthe et rattacha Corinthe à la Ligue achéenne ; Mégare, Trézène et Épidaure passèrent aussi à la Ligue. La Macédoine perdit sa forteresse clé dans le Péloponnèse.", "84d43a24"]},
"OLAYLAR_ANTIK_AKDENIZ:-0250-01-01:0":{"b": ["Aratos rattache Sicyone à la Ligue achéenne", "6f413f9c"], "d": ["Le jeune Aratos renversa le tyran de Sicyone et rattacha la cité à la Ligue achéenne ; ce geste étendit la Ligue aux rives nord et sud du golfe de Corinthe et conduisit Aratos à être élu stratège.", "1becea45"]},
"OLAYLAR_ANTIK_AKDENIZ:-0262-01-01:0":{"b": ["Hiéron II s'allie à Rome : la Sicile orientale devient l'alliée de Rome", "5e95a134"], "d": ["Au début de la première guerre punique, à cause de l'affaire de Messine, Hiéron s'était allié à Carthage contre Rome ; en 263, il conclut avec Rome la paix et une alliance, et resta jusqu'à sa mort (215) l'allié fidèle de Rome. Syracuse devint l'État allié de la Sicile romaine, resté en dehors de la province.", "4be7c84b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:0":{"b": ["Nicomède Ier fonde Nicomédie (İzmit)", "a89ed42a"], "d": ["Après la destruction d'Astacos, Nicomède fonda Nicomédie à l'extrémité orientale du golfe ; la ville devint au cours des siècles suivants le centre de la Bithynie et, sous Dioclétien, la capitale orientale de l'Empire romain.", "a172ed71"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:1":{"b": ["Début de la première guerre punique : Appius Claudius passe à Messine", "636e1533"], "d": ["Les Mamertins de Messine, menacés par Hiéron, roi de Syracuse, ayant demandé de l'aide à Carthage puis à Rome, le consul romain Appius Claudius Caudex passa en Sicile en 264 et prit Messine à la garnison carthaginoise. Rome entra ainsi en guerre hors d'Italie pour la première fois.", "de7b7f25"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:2":{"b": ["Volsinies tombe : la dernière grande cité indépendante d'Étrurie passe à Rome", "b6aed092"], "d": ["Volsinies, qui avait fait appel à Rome à cause d'un soulèvement d'esclaves, fut prise par Rome en 264 ; ses habitants furent transférés dans un nouveau site. L'Étrurie entra dès lors de fait sous la domination romaine.", "4384ae1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:0":{"b": ["Pyrrhos meurt à Argos", "2b4996fa"], "d": ["Lors de sa campagne dans le Péloponnèse, Pyrrhos fut blessé par une tuile dans un combat de rues à Argos et mourut (272). L'Épire perdit son poids face à la Macédoine et renoua des relations avec Rome.", "2e7f4937"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:1":{"b": ["Tarente se rend à Rome : l'Italie du Sud rejoint Rome", "6e87c924"], "d": ["Après le départ de Pyrrhos, la garnison épirote de Tarente se retira et la ville se rendit à Rome (272). Avec le Bruttium et la Lucanie, les cités grecques d'Italie du Sud devinrent alliées de Rome ; Rome devint ainsi maîtresse de la péninsule italienne jusqu'à la plaine du Pô.", "b7f98699"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:0":{"b": ["Maleventum (Bénévent) : Pyrrhos se retire d'Italie", "ab67e9f5"], "d": ["L'attaque renouvelée de Pyrrhos contre Rome, à son retour de la campagne de Sicile, échoua à Maleventum devant Manius Curius Dentatus ; Pyrrhos retourna en Épire en 275. Il laissa une petite garnison à Tarente ; Rome resta sans rival en Italie.", "f2c89575"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:1":{"b": ["Antiochos Ier bat les Galates lors de la « bataille des Éléphants »", "1e88c2d0"], "d": ["Antiochos Ier vainquit les Galates grâce à ses éléphants et reçut le surnom de Sôter (« sauveur ») ; les Galates revinrent en Anatolie centrale à un régime de tribut et de razzias, dans un cadre sédentaire. Les affrontements avec Pergame et la Bithynie se poursuivirent au cours des siècles suivants.", "f925c4fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0275-01-01:0":{"b": ["Antigone Gonatas devient roi de Macédoine : la dynastie antigonide s'installe durablement", "4b907dd6"], "d": ["Gonatas acquit sa renommée en battant les Galates à Lysimacheia en 277 et s'établit sur le trône de Macédoine en 276. La dynastie gouverna la Macédoine jusqu'en 168 ; en Grèce, elle garda en main les forteresses de Corinthe, de Chalcis et du Pirée.", "d13f42b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0277-01-01:0":{"b": ["Nicomède Ier fait passer les Galates en Anatolie", "9e5ab10b"], "d": ["Le roi de Bithynie Nicomède Ier, contre son frère Zipoitès et la pression séleucide, fit passer le Bosphore aux tribus galates (celtes) pour les prendre à son service ; les Galates s'installèrent ensuite en Anatolie centrale ; la branche des Tectosages fit d'Ankara (Ancyre) sa capitale (TDV « Ankara » : «milattan önce 278-189 yılları arasında Trakya’dan gelen Galatlar’ın Tektosages kolunun başşehri oldu»). La date du passage est 278/277.", "b9f3dcc3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0278-01-01:0":{"b": ["La Ligue étolienne défend Delphes contre l'invasion galate", "5488966a"], "d": ["L'armée galate de Brennos franchit les Thermopyles et avança vers Delphes ; la résistance des Étoliens et des Phocidiens dispersa l'invasion. Le poids de l'Étolie dans l'Amphictionie de Delphes grandit grâce à cette victoire.", "af3aba53"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:0":{"b": ["Pyrrhos passe en Italie au secours de Tarente ; il bat les Romains à Héraclée", "55f18e85"], "d": ["Pyrrhos, débarqué en Italie en 280 à l'appel de Tarente contre Rome, vainquit à Héraclée l'armée de Valerius Laevinus avec ses éléphants et sa cavalerie, mais au prix de lourdes pertes. Il l'emporta de nouveau à Asculum en 279, puis passa en Sicile en 278-276.", "60cab05c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:1":{"b": ["La Ligue achéenne est refondée : Patras, Dymé, Tritée, Phares", "81bba071"], "d": ["En Achaïe sous contrôle antigonide, quatre cités (Dymé, Patras, Tritée, Phares) refondèrent en 280 av. J.-C. une ligue fédérale ; Égion et d'autres cités la rejoignirent les années suivantes. Sous la direction d'Aratos, la Ligue devint la grande puissance du Péloponnèse.", "2426b2cc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0280-01-01:0":{"b": ["Philétairos passe à Séleucos après Couroupédion ; Pergame fonde une dynastie de fait indépendante", "ac6b3e31"], "d": ["Après la chute de Lysimaque, Philétairos se rallia à Séleucos avec le trésor, protégea et enrichit Pergame ; à la mort de Séleucos (281), il devint de fait indépendant. Tite-Live donne la durée de gouvernement de la dynastie attalide sur Pergame, de 283 à 129.", "cbc3946d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0284-01-01:0":{"b": ["Lysimaque chasse Pyrrhos de Macédoine et devient seul roi de Macédoine", "a83e6c64"], "d": ["Après l'hiver 285, où Démétrios se rendit à Séleucos, Lysimaque expulsa Pyrrhos de Macédoine et gouverna seul le pays. Son royaume atteignit une vaste étendue couvrant la Thrace, la Macédoine et l'Anatolie occidentale.", "8ba7b764"]},
"OLAYLAR_ANTIK_AKDENIZ:-0286-01-01:0":{"b": ["Pyrrhos et Lysimaque se partagent la Macédoine ; Démétrios Poliorcète est renversé", "63371ab8"], "d": ["À l'été 287, Démétrios étant passé en Asie, Pyrrhos et Lysimaque divisèrent la Macédoine en deux zones qu'ils se partagèrent ; Démétrios fut abattu. Ce partage ne dura que deux ans.", "9e4b93b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0289-01-01:0":{"b": ["Le Samnium rejoint Rome : fin de la troisième guerre samnite", "bede9942"], "d": ["Manius Curius Dentatus infligea une défaite décisive aux Samnites et aux Sabins ; le Samnium devint l'allié de Rome. Rome devint maîtresse de l'Italie centrale et se trouva face aux cités grecques d'Italie du Sud (Tarente).", "9c7619a6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0293-01-01:0":{"b": ["Démétrios Poliorcète est proclamé roi de Macédoine", "a2b1eba3"], "d": ["Profitant de la querelle de succession dans la dynastie de Cassandre, Démétrios fut proclamé roi de Macédoine par l'armée à l'automne 294. C'est la première souveraineté de la lignée d'Antigone en Macédoine ; elle s'effondra en 288, et Gonatas la rendit durable en 276.", "959705f1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0294-01-01:0":{"b": ["Sentinum : l'alliance des Étrusques, des Ombriens, des Samnites et des Gaulois est vaincue par Rome", "b5affc1b"], "d": ["Dans la troisième guerre samnite, cette bataille de Sentinum détruisit la dernière grande alliance anti-romaine d'Italie ; les cités étrusques furent contraintes une à une à l'alliance avec Rome.", "b5bfb032"]},
"OLAYLAR_ANTIK_AKDENIZ:-0295-01-01:0":{"b": ["Pyrrhos remonte sur le trône d'Épire avec l'appui de Ptolémée", "6288bf69"], "d": ["Pyrrhos, retenu comme otage en Égypte après Ipsos, retourna en Épire avec l'aide de Ptolémée et reprit le trône. L'Épire eut dès lors son mot à dire dans les affaires de Macédoine et d'Italie.", "e15989dd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0300-01-01:0":{"b": ["Lysimaque dépose son trésor à Pergame ; Philétairos devient gardien de la forteresse", "e1b4ab77"], "d": ["Après Ipsos, Lysimaque fit garder son trésor dans la forteresse de Pergame, sur la colline, et en confia la garde à l'eunuque Philétairos. Philétairos passa à Séleucos en 281 et jeta les bases de la dynastie.", "6fabb342"]},
"OLAYLAR_ANTIK_AKDENIZ:-0301-01-01:0":{"b": ["Mithridate Ier Ctistès fonde la dynastie du Pont", "490c338c"], "d": ["Mithridate, rapproché d'Antigone le Borgne, échappa en 302 au danger d'être assassiné et se réfugia à Cimiata, dans la région montagneuse du Pont de Cappadoce, où il constitua le noyau du royaume du Pont. La dynastie dura jusqu'en 63.", "e0d99a55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0303-01-01:0":{"b": ["Le siège de Rhodes par Démétrios Poliorcète se termine par un échec", "dae6f4d6"], "d": ["Démétrios assiégea en 305, avec d'énormes machines de siège, Rhodes restée aux côtés de Ptolémée contre Antigone ; les Rhodiens résistèrent un an et la paix fut obtenue à l'été 304. Le Colosse de Rhodes, représentant le dieu-soleil Hélios, fut érigé avec le produit de cette victoire.", "013a6951"]},
"OLAYLAR_ANTIK_AKDENIZ:-0305-01-01:0":{"b": ["Salamine de Chypre : Démétrios bat Ptolémée ; Antigone et Démétrios prennent le titre de roi", "cc308941"], "d": ["Au printemps 306, Démétrios Poliorcète vainquit la flotte de Ptolémée devant Chypre et mit Chypre aux mains d'Antigone ; durant l'été, Antigone et Démétrios prirent le titre de roi, et les autres Diadoques assumèrent bientôt le même titre. Ptolémée reprit Chypre en 294.", "0720c1b6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0308-01-01:0":{"b": ["Lysimaque fonde Lysimacheia : une capitale dans la Chersonèse de Thrace", "83b83160"], "d": ["Lysimaque fit de Lysimacheia, qu'il avait fondée à l'étranglement de la presqu'île de Gallipoli, la capitale de son royaume de Thrace ; le contrôle du Bosphore et du passage des Dardanelles se concentra entre ses mains. La ville fut ruinée par un tremblement de terre au IIIe siècle av. J.-C.", "8ff0e638"]},
"OLAYLAR_ANTIK_AKDENIZ:-0310-01-01:0":{"b": ["Paix des Diadoques : Antigone reconnu pour l'Asie, Cassandre pour l'Europe, Ptolémée pour l'Égypte", "811c80f0"], "d": ["Dans la paix signée en décembre 311, Antigone fut reconnu comme commandant de l'Asie, Cassandre comme stratège de l'Europe, Lysimaque de la Thrace, Ptolémée comme gouverneur de l'Égypte et de ses environs ; le principe de la liberté des cités grecques fut adopté. La Babylone de Séleucos resta en dehors de cette paix.", "3c9a7c4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0313-01-01:0":{"b": ["Tyr passe à Antigone : la Phénicie est enlevée à Ptolémée", "30f78257"], "d": ["Antigone entra en Syrie en 315, prit la Phénicie et assiégea Tyr ; la ville tomba en 314. La côte phénicienne et le littoral jusqu'à Gaza tombèrent entre ses mains (Gaza fut rendue à Ptolémée en 312, lors de la bataille de Gaza).", "54b4c2dc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0314-01-01:0":{"b": ["Cassandre fonde Thessalonique", "7043bd8a"], "d": ["Cassandre réunit plus de vingt localités au nord du golfe Thermaïque et fonda une ville au nom de son épouse Thessalonikè (fille de Philippe II). Thessalonique devint pour le millénaire suivant le port le plus important de Macédoine.", "b6a8e171"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:0":{"b": ["Cassandre fait reconstruire Thèbes", "0167e784"], "d": ["Thèbes, détruite par Alexandre, fut reconstruite avec le soutien de Cassandre et l'aide venue d'Athènes et d'Eubée, ses remparts étant relevés. Un centre fut de nouveau assuré à la Ligue béotienne.", "8f93a07f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:1":{"b": ["Gabiène : Antigone bat Eumène et devient maître de l'Asie jusqu'à l'Iran", "d2990dfd"], "d": ["À l'hiver 316/5, l'armée d'Eumène fut défaite à Gabiène ; son chef fut livré à Antigone par ses propres soldats et exécuté. Antigone devint seul maître d'une vaste région s'étendant du plateau perse à l'Anatolie ; Séleucos s'enfuit en Égypte.", "afa9a54f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0319-01-01:0":{"b": ["Accord de Triparadisos : Antigone le Borgne devient stratège d'Asie", "69f6fafb"], "d": ["Après l'assassinat de Perdiccas en Égypte (mai 320), Antipater redistribua les satrapies à Triparadisos ; Antigone fut placé à la tête des forces d'Asie, et Séleucos prit Babylone. À partir de cette position, Antigone entreprit de fonder son propre empire.", "17f6bc6b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0321-09-05:0":{"b": ["Crannon : la guerre lamiaque est perdue ; une garnison macédonienne entre à Athènes, la démocratie est suspendue", "6931c4f6"], "d": ["Le 5 septembre 322, à Crannon, l'alliance grecque fut vaincue par Antipater et Cratère ; Athènes accepta de recevoir une garnison macédonienne à Munychie et de limiter le critère de citoyenneté aux détenteurs de biens. Démosthène se suicida ; la démocratie athénienne classique prit fin de fait.", "ee0f58da"]},
"OLAYLAR_ANTIK_AKDENIZ:-0322-01-01:0":{"b": ["Guerre lamiaque : les cités grecques se soulèvent contre l'hégémonie macédonienne après la mort d'Alexandre", "c31c7da4"], "d": ["À la nouvelle de la mort d'Alexandre (juin 323), Athènes et la Ligue étolienne se soulevèrent contre Antipater ; Antipater fut assiégé à Lamia. La guerre s'acheva par la victoire macédonienne à Crannon (septembre 322) ; la suprématie macédonienne fut rétablie dans le cadre de la Ligue de Corinthe.", "57d15260"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:0":{"b": ["Hydaspe : Poros est vaincu ; le Pendjab est rattaché à Alexandre", "abab206b"], "d": ["En mai 326, avec le soutien d'Ambhi, rajah de Taxila, Alexandre franchit le Jhelum et vainquit Poros ; le royaume de Poros fut laissé à Alexandre en tant que vassal. À partir de ce point Alexandre avança vers l'est, mais s'arrêta à l'Hyphase devant l'opposition de l'armée.", "b8f65fb3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:1":{"b": ["L'armée refuse d'avancer sur les rives de l'Hyphase (Beas) : la limite orientale d'Alexandre", "17b23afc"], "d": ["À cause des pluies de mousson et de la fatigue, l'armée macédonienne refusa de passer au-delà de l'Hyphase ; Alexandre fit ériger douze autels et dut rebrousser chemin. L'Hyphase fut l'extrémité orientale des conquêtes macédoniennes en Inde.", "14c7c1e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0326-01-01:0":{"b": ["La Bactriane et la Sogdiane se soumettent à Alexandre ; Alexandre épouse Roxane", "a050508d"], "d": ["Entre 329 et 327, la région au-delà de l'Oxus fut conquise au prix d'une intense guérilla ; Spitaménès fut tué, le Rocher de Sogdiane et la forteresse de Chorienès se rendirent. Alexandre épousa la princesse bactrienne Roxane et rattacha ainsi les nobles locaux à son administration.", "918611e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0333-01-01:0":{"b": ["La côte de l'Anatolie occidentale passe à Alexandre : Éphèse, Milet et Halicarnasse", "f67084a4"], "d": ["Éphèse ouvrit ses portes avec un régime démocratique, Milet fut prise à l'issue d'un siège (été 334) ; le siège d'Halicarnasse se conclut à l'automne par la chute de la ville, et la satrapie de Carie fut donnée à Ada. Alexandre appliqua ainsi sa stratégie de s'emparer par la terre des ports de la flotte perse.", "8ad1fb18"]},
"OLAYLAR_ANTIK_AKDENIZ:-0334-01-01:0":{"b": ["Thèbes est détruite sur l'ordre d'Alexandre", "26c4193c"], "d": ["Alexandre prit à l'automne Thèbes, soulevée à la mort de Philippe ; il plaça une garnison macédonienne dans la Cadmée, fit raser la ville et réduisit sa population en esclavage (hormis la maison de Pindare). La Ligue béotienne prit fin de fait avec cette destruction (Cassandre la rétablit en 316).", "1aac0f0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0335-01-01:0":{"b": ["Philippe II est assassiné à Aigai ; Alexandre monte sur le trône", "417d909e"], "d": ["À la place de Philippe, tué au théâtre par son garde du corps Pausanias lors des noces de sa fille Cléopâtre, son fils Alexandre fut proclamé roi par l'armée. La campagne contre la Perse et le contrôle de la Grèce revinrent à Alexandre.", "29a2af26"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:0":{"b": ["Fondation de la Ligue de Corinthe : les cités grecques réunies sous l'hégémonie de Philippe II", "c38074dc"], "d": ["Après Chéronée, Philippe réunit à Corinthe les cités grecques sous un serment de paix commune (koine eirene) et de défense commune ; l'on décida des troupes pour une campagne contre la Perse et du commandement du hégémon. Seule Sparte n'y participa pas.", "753c39e6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:1":{"b": ["Chéronée : Philippe bat l'armée d'Athènes et de Thèbes et prend le contrôle de la Grèce", "5e5d77e7"], "d": ["En août 338, dans la plaine de Chéronée, l'armée athéno-thébaine fut défaite par la charge de cavalerie que commandait le jeune Alexandre ; une garnison macédonienne fut placée à Thèbes, Athènes fut épargnée avec clémence. La victoire mit fin à l'indépendance des cités grecques et ouvrit la voie à la Ligue de Corinthe.", "b2f75989"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:2":{"b": ["Dissolution de la Ligue latine : le Latium est rattaché à Rome", "58849f84"], "d": ["À la fin de la guerre latine (340-338), Rome dissout la Ligue latine ; les cités furent intégrées à la citoyenneté romaine ou rattachées une à une à Rome, et toute alliance entre elles fut interdite. C'est le fondement du modèle d'expansion de Rome en Italie.", "5ebbdf2e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0338-01-01:0":{"b": ["Philippe II bat Atéas, roi des Scythes", "e4dee658"], "d": ["La guerre du roi Atéas contre Philippe, sur les rives de l'Istros (Danube), se termina par la mort d'Atéas ; au retour, Philippe fut attaqué par les Triballes. La puissance scythe se déplaça à l'ouest, au-delà du Danube.", "29f62ac6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0340-01-01:0":{"b": ["Philippe soumet la Thrace avec la dynastie des Odryses", "b543427a"], "d": ["Lors de ses campagnes de 342-341 av. J.-C., Philippe avança à l'intérieur de la Thrace, rendit Kersobleptès, roi des Odryses, tributaire et fonda des villes comme Philippoupolis (Plovdiv). La Thrace devint le prolongement oriental de la Macédoine.", "82201f3c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0347-01-01:0":{"b": ["Destruction d'Olynthe : la Ligue chalcidienne passe à la Macédoine", "89d77301"], "d": ["Bien qu'Olynthe eût demandé l'aide d'Athènes, Philippe prit la ville par trahison et la détruisit ; la péninsule chalcidique fut rattachée à la Macédoine. Les discours olynthiens de Démosthène reposent sur cet appel.", "c69e91c8"]},
"OLAYLAR_ANTIK_AKDENIZ:-0354-01-01:0":{"b": ["Fin de la guerre sociale : Byzance, Chios, Rhodes et Cos quittent la seconde Ligue athénienne", "856a9763"], "d": ["La révolte commencée en 357 av. J.-C. s'acheva lorsque les commandants athéniens furent battus à Chios, que l'appui perse se tourna contre Athènes et qu'Athènes accepta la paix ; quatre membres importants gagnèrent leur indépendance. La Ligue s'affaiblit et resta sans défense devant la Macédoine.", "170647af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0356-01-01:0":{"b": ["Philippe enlève Amphipolis à Athènes", "2c793bc6"], "d": ["Philippe, qui assiégea et prit Amphipolis, cité athénienne à l'embouchure du Strymon, accéda aux mines d'or et d'argent et aux ressources en bois de la ville et s'ouvrit sur la côte de Thrace. Cette conquête déclencha le conflit entre Athènes et la Macédoine.", "731bf35a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0358-01-01:0":{"b": ["Philippe II devient roi de Macédoine", "d557268d"], "d": ["À la mort de Perdiccas III dans la guerre contre les Illyriens (360/359 av. J.-C.), Philippe devint d'abord régent puis roi ; il écarta les menaces illyrienne, péonienne et thrace et réforma l'armée (phalange de sarisses). L'ascension de la Macédoine commence avec ce règne.", "417218f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0361-01-01:0":{"b": ["Mantinée : Épaminondas meurt, l'hégémonie béotienne prend fin", "94be8d5c"], "d": ["L'armée thébaine gagna la bataille, mais Épaminondas, blessé, mourut ; Xénophon conclut par « l'incertitude et la confusion furent plus grandes en Grèce qu'auparavant ». La brève hégémonie de Thèbes prit fin la même année ; l'équilibre Athènes–Sparte–Thèbes fut maintenu.", "42ad0729"]},
"OLAYLAR_ANTIK_AKDENIZ:-0368-01-01:0":{"b": ["Fondation de la Ligue arcadienne : cette partie de la Ligue du Péloponnèse se disloque", "42fdc676"], "d": ["Après Leuctres, les cités d'Arcadie fondèrent, avec le soutien de Thèbes, une ligue fédérale et édifièrent la nouvelle capitale, Mégalopolis. La Ligue du Péloponnèse de Sparte se disloqua ainsi de fait ; Sparte se replia sur la seule Laconie.", "4cf7dd83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0369-01-01:0":{"b": ["La Messénie se sépare de Sparte ; Messène est fondée", "e4ef9302"], "d": ["Lors de la campagne d'Épaminondas dans le Péloponnèse après Leuctres (hiver 370/69), les hilotes de Messénie furent libérés et la ville fortifiée de Messène fut fondée au pied du mont Ithôme. Sparte perdit pour la première fois depuis des siècles les terres de Messénie qui formaient son assise économique.", "fe6af875"]},
"OLAYLAR_ANTIK_AKDENIZ:-0370-01-01:0":{"b": ["Leuctres : l'armée thébaine bat les Spartiates ; Sparte perd sa suprématie terrestre", "e7829597"], "d": ["L'ordre oblique à aile droite profonde d'Épaminondas mit en déroute à Leuctres la force spartiate du roi Cléombrote ; avec la mort d'environ 400 Spartiates, Sparte ne put plus compenser ses pertes démographiques. Une période d'hégémonie sous la direction de Thèbes commença.", "41f8774e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0376-01-01:0":{"b": ["Fondation de la seconde Ligue athénienne (décret d'Aristote)", "0e5dcaf2"], "d": ["Athènes appela les cités de la mer Égée à la Ligue, contre Sparte, sur le principe de l'autonomie et de l'absence de tribut ; le décret fut pris sur la proposition d'Aristote et la liste des cités membres fut gravée sur la pierre. La fondation de la Ligue refit d'Athènes une puissance navale.", "20a9657f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0378-01-01:0":{"b": ["Pélopidas libère Thèbes ; la garnison spartiate est chassée de la Cadmée", "eb15a9d7"], "d": ["La Cadmée de Thèbes, que Sparte avait prise et où elle avait laissé une garnison en 382 av. J.-C., fut reprise par un coup de main nocturne des exilés ; Thèbes redevint le centre de la Ligue béotienne. L'événement marque le début de la dislocation de l'hégémonie spartiate.", "4cd862c2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0388-01-01:0":{"b": ["L'Allia : les Gaulois battent l'armée romaine et pillent la ville", "db864bc9"], "d": ["Sur les bords de l'Allia, affluent du Tibre, les Gaulois Sénons mirent en déroute l'armée romaine ; Rome fut occupée et pillée, hormis le Capitole. Tite-Live écrit que le « jour de l'Allia » (18 juillet) fut tenu pour néfaste par les Romains.", "7babd2e7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0391-01-01:0":{"b": ["Corinthe s'unit à Argos (isopolitie Argos–Corinthe)", "135a3d3a"], "d": ["Pendant la guerre de Corinthe (395-387 av. J.-C.), Corinthe forma avec Argos une union de citoyenneté commune ; la garnison argienne resta à Corinthe. Sparte fit rompre cette union par la paix du Roi (386).", "9f979507"]},
"OLAYLAR_ANTIK_AKDENIZ:-0395-01-01:0":{"b": ["Véies tombe aux mains de Rome : première grande cité d'Étrurie perdue au sud", "0d1c4fe4"], "d": ["Après un siège de dix ans, Camille prit Véies (396 av. J.-C. selon la tradition) ; sa population fut réduite en esclavage, ses terres rattachées à Rome, et l'ager Romanus de Rome fut presque doublé. La puissance des cités étrusques au sud du Tibre fut brisée.", "7571ce55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0403-01-01:0":{"b": ["Athènes se rend à Sparte ; fin de l'empire maritime athénien et de la Ligue de Délos", "43f2ddf9"], "d": ["Athènes, qui avait perdu sa flotte à Aigos Potamos, se rendit par la famine ; les Longs Murs furent abattus, l'empire maritime se dissout, et le régime des Trente, mis en place par les Spartiates, s'installa dans la ville. Dans les îles et sur les côtes de Thrace, anciens membres de la Ligue, s'installèrent les régimes de décarchies et les garnisons spartiates établis par Lysandre.", "3d808acd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:0":{"b": ["Denys Ier devient tyran de Syracuse", "1ad10305"], "d": ["Dans les années où Carthage prenait Agrigente et Géla, Denys devint en 405 stratège puis tyran de Syracuse ; il fit la paix avec Carthage (405) et soumit à son autorité les cités grecques de Sicile. Le pouvoir de Denys, qui allait durer 38 ans, fit de la Sicile l'une des grandes puissances de la Méditerranée.", "3068782f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:1":{"b": ["Aigos Potamos : la flotte athénienne est détruite ; la Ligue de Délos au bord de l'effondrement", "ce62187c"], "d": ["En septembre 405, Lysandre s'empara par surprise, à Aigos Potamos, de la flotte athénienne au mouillage ; presque toute la flotte et des milliers de prisonniers furent perdus. La route de l'Hellespont fut fermée et l'approvisionnement en blé d'Athènes coupé ; quelques mois plus tard, Athènes se rendit.", "d42a037e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0407-01-01:0":{"b": ["Fondation de la ville de Rhodes : Lindos, Ialysos et Camiros s'unissent", "2de55901"], "d": ["En 408 av. J.-C., les trois cités de l'île de Rhodes formèrent un État commun et s'unirent dans la nouvelle ville de Rhodes ; construite selon le plan d'Hippodamos, la ville devint l'une des principales bases navales et places de commerce du monde hellénistique.", "0db6207d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0408-01-01:0":{"b": ["Hannibal Magon détruit Sélinonte et Himère : Carthage s'établit en Sicile occidentale", "358f4417"], "d": ["Débarqué en Sicile à l'appel de Ségeste, Hannibal Magon prit Sélinonte et Himère en 409 av. J.-C. ; la région devint l'épicratie de Carthage. Le conflit Carthage–Syracuse dura deux siècles.", "58abf6b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0412-01-01:0":{"b": ["L'expédition de Sicile se termine en catastrophe : l'armée athénienne anéantie devant Syracuse", "b363df0d"], "d": ["L'expédition de Sicile lancée par Athènes en 415 av. J.-C. s'acheva, après l'échec du blocus de Syracuse, par la reddition de Nicias et de Démosthène lors de leur retraite sur les bords de l'Assinaros (automne 413 av. J.-C.). Athènes perdit son armée et la plus grande partie de sa flotte.", "2d1f3d05"]},
"OLAYLAR_ANTIK_AKDENIZ:-0429-01-01:0":{"b": ["Sitalcès s'allie à Athènes : le royaume des Odryses entre dans la guerre du Péloponnèse", "4562f13d"], "d": ["Athènes fit du fils de Sitalcès un citoyen athénien et s'allia avec lui ; Sitalcès attaqua la Macédoine en 429. La puissance odryse atteignit alors son apogée.", "64e00572"]},
"OLAYLAR_ANTIK_AKDENIZ:-0430-01-01:0":{"b": ["Début de la guerre du Péloponnèse : la Ligue du Péloponnèse se mobilise contre Athènes", "2adee4a1"], "d": ["La paix fut de fait rompue par l'attaque nocturne de Thèbes contre Platées (printemps 431) ; au début de l'été, l'armée de la Ligue du Péloponnèse, sous le commandement du roi Archidamos, envahit l'Attique. La guerre dura 27 ans entre l'empire maritime d'Athènes et la ligue terrestre de Sparte.", "6d950c3b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0432-01-01:0":{"b": ["Sybota : la guerre Corinthe–Corcyre entraîne Athènes dans l'intervention", "dc07b0ac"], "d": ["Dans la bataille navale que Corinthe livra à sa colonie Corcyre à propos d'Épidamne, Athènes soutint Corcyre. La colère de Corinthe contre Athènes devint l'une des causes directes de la guerre du Péloponnèse.", "f4639e4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0437-01-01:0":{"b": ["Spartocos devient archonte du Bosphore : la dynastie des Spartocides", "ddc76f79"], "d": ["À la dynastie des Archéanactides de Panticapée succéda le Thrace Spartocos (438/7) ; la dynastie des Spartocides fonda le royaume du Bosphore et administra l'exportation de blé vers Athènes. La dynastie dura jusqu'en 109 av. J.-C.", "36cf3454"]},
"OLAYLAR_ANTIK_AKDENIZ:-0445-01-01:0":{"b": ["Paix de Trente Ans : Athènes perd son empire continental (Béotie, Mégare, Achaïe)", "4f33ff13"], "d": ["Après la victoire des Béotiens sur l'armée athénienne à Coronée (447), puis les révoltes d'Eubée et de Mégare et l'invasion de l'Attique par Sparte, Athènes signa la paix de Trente Ans. Athènes abandonna Mégare, Nisée, Pagai ainsi que Trézène et l'Achaïe dans le Péloponnèse ; elle ne garda que son empire maritime.", "fc720780"]},
"OLAYLAR_ANTIK_AKDENIZ:-0449-01-01:0":{"b": ["Térès fonde le royaume des Odryses : premier grand État de Thrace", "83caf189"], "d": ["Thucydide écrit que Térès fonda le premier grand royaume en Thrace ; son fils Sitalcès porta le royaume du Danube à la mer Égée. Le royaume odryse mena une politique d'équilibre entre Athènes, la Macédoine et la Perse.", "442e0b64"]},
"OLAYLAR_ANTIK_AKDENIZ:-0453-01-01:0":{"b": ["Le trésor de la Ligue est transféré de Délos à Athènes", "173f2e5b"], "d": ["Sous prétexte de la défaite de l'expédition d'Égypte et de la crainte de la flotte perse, le trésor commun fut transporté de Délos à Athènes ; les listes de la « soixantième » versée à la déesse d'Athènes commencent cette année-là. Cette mesure est interprétée comme le signe que la Ligue s'était transformée en pratique en empire athénien.", "c7c6b1db"]},
"OLAYLAR_ANTIK_AKDENIZ:-0462-01-01:0":{"b": ["La révolte de Thasos est réprimée ; la Ligue de Délos devient un empire que les membres ne peuvent quitter", "d24bd124"], "d": ["Thasos, en conflit avec Athènes à propos de mines, tenta de quitter la Ligue ; après un siège de deux ans (463 av. J.-C.), elle vit ses murs rasés, livra sa flotte et perdit la région minière de la côte de Thrace. L'événement est le premier précédent montrant que l'appartenance à la Ligue ne pouvait être abandonnée.", "eb9beb44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0473-01-01:0":{"b": ["Bataille navale de Cumes : Syracuse bat la flotte étrusque, la puissance navale étrusque est brisée", "2e81670b"], "d": ["À l'appel de Cumes, Hiéron Ier, tyran de Syracuse, défit la flotte étrusque devant Cumes ; Hiéron célébra la victoire par l'offrande d'un casque à Delphes (le casque étrusque mentionné par Tite-Live). La domination étrusque en Campanie fut ébranlée.", "db3832ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0477-01-01:0":{"b": ["Fondation de la Ligue de Délos : alliance égéenne sous la présidence d'Athènes", "f0de153a"], "d": ["Après la conduite de Pausanias, les cités ioniennes demandèrent la direction d'Athènes ; avec le tribut fixé par Aristide (460 talents), un trésor commun fut établi à Délos. La Ligue procura à Athènes une flotte permanente et une base fiscale sur la mer Égée.", "bb661e1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0478-01-01:0":{"b": ["Salamine (29 septembre 480) et Platées : l'invasion perse est repoussée", "479b17e6"], "d": ["Après que Xerxès eut pris et incendié Athènes, la flotte perse fut défaite dans le détroit de Salamine par le piège de Thémistocle (29 septembre 480) ; l'année suivante, à Platées, l'armée terrestre grecque commandée par Pausanias vainquit Mardonios et mit fin à l'invasion. La Grèce égéenne fut ainsi délivrée de la domination perse.", "dd5f48b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0479-01-01:0":{"b": ["Himère : les Grecs de Sicile battent l'armée carthaginoise", "ece09580"], "d": ["L'alliance de Gélon et de Théron défit devant Himère l'armée carthaginoise d'Hamilcar ; Carthage ne put plus lancer pendant un demi-siècle de grande expédition en Sicile. Selon Hérodote et Diodore, Salamine fut gagnée le même jour (tradition).", "1706c09a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0489-01-01:0":{"b": ["Marathon : Athènes arrête l'offensive perse", "0967ce7c"], "d": ["Les hoplites d'Athènes et de Platées, sous le commandement de Miltiade, vainquirent la force perse dans la plaine de Marathon et empêchèrent son débarquement en Attique. La victoire nourrit la confiance de la démocratie athénienne et la politique navale qui mena ensuite à la Ligue de Délos.", "1b107bcd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0490-01-01:0":{"b": ["Mardonios soumet la Macédoine à la Perse", "7bde569c"], "d": ["Mardonios, gendre de Darius, traversa la Thrace et plaça la Macédoine sous la domination perse ; le roi de Macédoine donna à la Perse la terre et l'eau. La Macédoine se défit de cette dépendance après Platées (479).", "04f10eac"]},
"OLAYLAR_ANTIK_AKDENIZ:-0492-01-01:0":{"b": ["Foedus Cassianum : Rome s'allie à la Ligue latine", "56db407d"], "d": ["Par le traité qui porte le nom de Spurius Cassius, Rome et la Ligue latine formèrent une alliance fondée sur la défense mutuelle, le partage du butin et une armée commune. Ce traité est le cadre des relations Rome–Latium jusqu'à la guerre latine (340-338).", "cb723394"]},
"OLAYLAR_ANTIK_AKDENIZ:-0504-01-01:0":{"b": ["Avec le retrait de Corinthe, l'expédition de la Ligue du Péloponnèse contre Athènes se disloque", "b44adf6b"], "d": ["Sparte lança l'armée de la Ligue du Péloponnèse en Attique contre l'Athènes démocratique de Clisthène ; le retrait de l'armée corinthienne à Éleusis et le désaccord des deux rois de Sparte firent échouer l'expédition. L'événement passe pour le premier exemple connu où le droit de vote des alliés commença à fonctionner dans l'assemblée de la Ligue.", "f54c0949"]},
"OLAYLAR_ANTIK_AKDENIZ:-0507-01-01:0":{"b": ["Réforme de Clisthène : les bases institutionnelles de la démocratie athénienne sont posées", "b2421c86"], "d": ["Après la chute d'Hippias, Clisthène organisa les citoyens par les dèmes, unités d'habitat, et dix nouvelles tribus ; le Conseil des Cinq-Cents devint le centre de ce système. C'est l'aménagement d'où naquirent les notions d'isonomia et de demokratia.", "f3da7080"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:0":{"b": ["Le dernier roi, Tarquin le Superbe, est chassé ; la royauté prend fin, la République commence", "5a4a9061"], "d": ["Selon Tite-Live, Tarquin le Superbe et sa famille furent chassés de la ville en 509 av. J.-C. et les premiers consuls (Brutus, Collatin) furent élus. Polybe rattache le premier traité entre Rome et Carthage à l'année des premiers consuls ; bien que cette date soit tenue pour une « tradition » par l'historiographie moderne, elle se situe à la fin du VIe siècle av. J.-C.", "b86ee69b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:1":{"b": ["Premier traité entre Rome et Carthage (Polybe 3.22)", "cdef940f"], "d": ["Polybe rapporte, avec son texte, le traité conclu entre Rome et Carthage l'année des premiers consuls, qui séparait les côtes du Latium, pour Rome, de la Sicile occidentale et de la Libye, pour Carthage. Rome y est désignée comme maîtresse du Latium.", "d5a9571d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0534-01-01:0":{"b": ["Bataille navale d'Alalia : Étrusques et Carthaginois chassent les Phocéens de Corse", "25efbea8"], "d": ["À Alalia, les Grecs phocéens l'emportèrent sur le papier mais perdirent la plus grande partie de leur flotte ; ils abandonnèrent la Corse et se retirèrent à Élée, en Italie du Sud. La domination étrusque (de Caere) s'établit dans l'île.", "50ab95a1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0549-01-01:0":{"b": ["Traité Sparte–Tégée : le noyau de la Ligue du Péloponnèse se forme", "57098e47"], "d": ["Sparte vainquit Tégée en Arcadie et lui fit accepter une alliance perpétuelle (symmachia) en échange de ne pas ravager ses terres ; le même modèle se répandit aux cités du Péloponnèse et la Ligue du Péloponnèse naquit sous la présidence de Sparte. La Ligue fonctionnait en interne sous la forme de Sparte et d'une assemblée des alliés (sous le commandement de Sparte).", "b9500385"]},
"OLAYLAR_ANTIK_AKDENIZ:-0598-01-01:0":{"b": ["Les Phocéens fondent Massalia (Marseille)", "5d46bdf2"], "d": ["Des colons phocéens fondèrent Massalia à l'embouchure du Rhône vers 600 av. J.-C. ; la ville devint le centre du commerce grec en Méditerranée occidentale et du contact avec le monde celte.", "f4a73ff9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0630-01-01:0":{"b": ["Battos de Théra fonde Cyrène", "67fd477f"], "d": ["Des colons venus de Théra fondèrent Cyrène sous la conduite de Battos, selon l'oracle de Delphes ; la dynastie des Battiades régna jusqu'en 440. Tite-Live donne la date de fondation « c. 630 ».", "e51d3a78"]},
"OLAYLAR_ANTIK_AKDENIZ:-0719-01-01:0":{"b": ["Sparte gagne la première guerre de Messénie : la Messénie est rattachée à Sparte", "74ad461c"], "d": ["Dans la tradition rapportée par Pausanias, la première guerre de Messénie dura vingt ans et, avec la chute d'Ithôme, la plaine de Messénie passa à Sparte ; la population fut réduite au statut d'hilotes. Cette conquête est tenue pour l'événement fondateur qui détermina la puissance agricole et la société militaire de Sparte.", "2066959e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0732-01-01:0":{"b": ["Syracuse est fondée par Archias de Corinthe", "10217104"], "d": ["Selon Thucydide, un an après Naxos, Archias de Corinthe fonda Syracuse. La ville devint la plus grande cité grecque de Sicile.", "e5643a95"]},
"OLAYLAR_ANTIK_AKDENIZ:-0813-01-01:0":{"b": ["Fondation traditionnelle de Carthage (Timée : 814/813 av. J.-C.)", "908099b5"], "d": ["Selon Timée, Carthage fut fondée en 814/813 av. J.-C. par des colons de Tyr ; Justin donne 825. Les couches archéologiques indiquent la fin du VIIIe siècle av. J.-C.", "c7e72545"]},
"OLAYLAR_ANTIK_AKDENIZ:-1199-01-01:0":{"b": ["Destruction des centres palatiaux mycéniens : l'ordre palatial s'effondre dans le Péloponnèse", "d2c79152"], "d": ["À la fin de l'Helladique récent IIIB / au début de l'HR IIIC, les centres palatiaux de Pylos, Tirynthe et Mycènes présentent une couche de destruction ou d'abandon ; l'économie palatiale fondée sur l'écriture linéaire B prend fin. La cause de la destruction (séisme, conflit interne, Peuples de la Mer, sécheresse) est débattue ; les couches de destruction ne se limitent pas à une seule année mais s'étendent sur quelques décennies.", "53e45d98"]},
"OLAYLAR_ANTIK_AKDENIZ:-1449-01-01:0":{"b": ["Destruction des palais minoens de Crète ; le contrôle mycénien commence à Cnossos", "1a7f7f2b"], "d": ["À la fin du Minoen récent IB (milieu du XVe siècle av. J.-C.), les centres palatiaux et les villas de Crète subissent des destructions ; à Cnossos, les tablettes en linéaire B de la phase suivante, écrites en grec, attestent une administration palatiale, c'est-à-dire un contrôle mycénien. La domination minoenne prend ainsi fin en Crète.", "2b9cf7f8"]},
"OLAYLAR_ANTIK_AKDENIZ:0009-01-01:0":{"b": ["Forêt de Teutoburg : les trois légions de Varus sont anéanties ; Rome abandonne la ligne de l'Elbe", "1684ae43"], "d": ["En 9 apr. J.-C., la coalition germanique conduite par Arminius anéantit dans la forêt de Teutoburg les XVIIe, XVIIIe et XIXe légions de P. Quinctilius Varus. Auguste renonça aux conquêtes au-delà du Rhin et la frontière du Rhin devint durable.", "842869dc"]},
"OLAYLAR_ANTIK_AKDENIZ:0014-08-19:0":{"b": ["Mort d'Auguste ; Tibère devient empereur", "0221344d"], "d": ["Auguste mourut à Nola le 19 août 14 ; Tibère lui succéda. Le principe de succession dans le principat (adoption au sein de la famille) devint ainsi durable.", "e55fc404"]},
"OLAYLAR_ANTIK_AKDENIZ:0040-01-01:0":{"b": ["Le roi Ptolémée est tué par Caligula ; fin de l'indépendance de la Maurétanie", "11337627"], "d": ["Ptolémée, fils de Juba II, fut tué à Lugdunum en 40 apr. J.-C. sur l'ordre de Caligula ; la révolte d'Aedemon éclata alors en Maurétanie, et Claude divisa en 44 le pays en deux provinces, la Tingitane et la Césarienne.", "87e30934"]},
"OLAYLAR_ANTIK_AKDENIZ:0043-01-01:0":{"b": ["Claude envahit la Bretagne", "f42ba7f7"], "d": ["En 43 apr. J.-C., quatre légions sous le commandement d'Aulus Plautius débarquèrent sur la côte du Kent ; Camulodunum (Colchester) fut prise et Claude séjourna brièvement dans la ville. Le sud de la Bretagne devint une nouvelle province romaine.", "96a1d864"]},
"OLAYLAR_ANTIK_AKDENIZ:0046-01-01:0":{"b": ["Rome fait de la Thrace une province : fin de la dynastie des Odryses", "af2ba1b2"], "d": ["Après le meurtre du roi de Thrace Rhœmétalcès III par son épouse, puis le désordre, Claude transforma en 46 la Thrace en province romaine. C'est l'un des derniers actes qui achevèrent l'organisation provinciale romaine à l'est des Balkans.", "4d5f0125"]},
"OLAYLAR_ANTIK_AKDENIZ:0106-01-01:0":{"b": ["Trajan conquiert la Dacie : Sarmizegetusa tombe, Décébale meurt, la province de Dacie est créée", "a9277172"], "d": ["Dans la seconde guerre dacique (105-106), Trajan prit Sarmizegetusa ; Décébale se suicida pour échapper à la capture. La Dacie devint une province romaine et ses mines d'or furent rattachées à l'économie romaine. Les phases antérieures de la guerre (101-105) font l'objet d'articles distincts dans la chronologie..", "ba1d2c29"]},
"OLAYLAR_ANTIK_AKDENIZ:0122-01-01:0":{"b": ["Hadrien commence la construction du Mur sur la frontière nord de la Bretagne", "f4a886ec"], "d": ["Après sa visite en Bretagne en 122 apr. J.-C., Hadrien fit construire un mur frontière sur la ligne Tyne-Solway. Le Mur symbolise la politique frontalière défensive de Rome ; l'avancée fut tentée avec le mur d'Antonin (142), mais ne fut pas durable.", "1486c2c9"]},
"OLAYLAR_ANTIK_AKDENIZ:0198-01-01:0":{"b": ["Septime Sévère fait de la Mésopotamie une province ; Ctésiphon est pillée", "df466924"], "d": ["Dans la guerre parthe (195-198), Sévère prit Nisibe, pilla Ctésiphon et organisa la Haute Mésopotamie en province romaine. La province porta jusqu'au IIIe siècle la plus grande avancée orientale de Rome.", "1707eedd"]},
"OLAYLAR_ANTIK_AKDENIZ:0212-01-01:0":{"b": ["Constitutio Antoniniana : la citoyenneté romaine est accordée à tous les habitants libres de l'Empire", "dd4e4024"], "d": ["Caracalla fit en 212 apr. J.-C. des habitants libres des provinces des citoyens romains ; la distinction entre citoyens et étrangers disparut dans l'Empire. La mesure élargit aussi l'assiette fiscale.", "b9e20124"]},
"OLAYLAR_ANTIK_AKDENIZ:0260-01-01:0":{"b": ["Postumus fonde en Gaule l'Empire gaulois sécessionniste", "4dcda41d"], "d": ["À la capture de Valérien par les Parthes (260), Postumus proclama avec les armées du Rhin un empire en Gaule ; la Gaule, la Bretagne et la plus grande partie de l'Hispanie se détachèrent de Rome jusqu'en 274. Gallien ne put résorber la sécession.", "f1eada99"]},
"OLAYLAR_ANTIK_AKDENIZ:0271-01-01:0":{"b": ["Aurélien évacue la Dacie : le nord du Danube est abandonné", "db2ca714"], "d": ["Sous la pression des Goths, Aurélien évacua la province de Dacie et replia les légions et la population civile au sud du Danube (Dacie ripuaire). Rome abandonna, après 165 ans, son premier grand territoire au nord du Danube.", "3e19ae74"]},
"OLAYLAR_ANTIK_AKDENIZ:0272-01-01:0":{"b": ["Aurélien vainc l'Empire de Palmyre : les territoires orientaux de Zénobie reviennent à Rome", "0a358790"], "d": ["En 272, Aurélien battit l'armée de Zénobie à Antioche et à Émèse et assiégea Palmyre ; Zénobie fut capturée. La Syrie, l'Égypte et le sud de l'Anatolie furent de nouveau rattachés à Rome.", "7b626384"]},
"OLAYLAR_ANTIK_AKDENIZ:0274-01-01:0":{"b": ["Aurélien vainc l'Empire gaulois : Rome est de nouveau unifiée", "c1a6a642"], "d": ["En 274, Aurélien battit Tetricus à Catalaunum ; la Gaule, la Bretagne et l'Hispanie revinrent à Rome. L'Empire fut réunifié après 14 ans de division, et Aurélien prit le titre de « Restitutor Orbis » (« restaurateur du monde »).", "872ee29d"]},
"OLAYLAR_ANTIK_AKDENIZ:0358-01-01:0":{"b": ["Julien établit les Francs saliens en Toxandrie comme foederati de Rome", "0fb618fe"], "d": ["Le César Julien, après avoir vaincu les Francs saliens en 358, leur permit de s'installer sur le territoire romain, en Toxandrie (aujourd'hui à la frontière des Pays-Bas et de la Belgique). C'est le début de l'établissement sous protection romaine de la région où naîtrait le royaume franc.", "ab1db90c"]},
"OLAYLAR_ANTIK_AKDENIZ:0375-01-01:0":{"b": ["Les Huns franchissent le Don et attaquent les Alains et les Ostrogoths : début des Grandes Invasions", "659eb875"], "d": ["Selon Ammien, les Huns franchirent le Don en 375 et vainquirent les Alains, puis détruisirent le royaume du roi ostrogoth Ermanaric ; les Wisigoths (Tervingi) furent alors refoulés jusqu'au Danube. L'âge de la domination hunnique commença ainsi en Europe.", "bc56aef2"]},
"OLAYLAR_ANTIK_AKDENIZ:0376-01-01:0":{"b": ["Les Goths Tervingi franchissent le Danube et s'installent en terre romaine", "3e9de0e6"], "d": ["Sous la pression des Huns, les Goths Tervingi de Fritigern obtinrent en 376 de Valens l'autorisation de franchir le Danube et de s'établir en terre romaine ; les problèmes de ravitaillement et d'administration dégénérèrent en révolte. Le résultat fut la défaite d'Andrinople (Edirne) en 378.", "ce90a65f"]},
"OLAYLAR_ANTIK_AKDENIZ:0406-12-31:0":{"b": ["Les Vandales, les Alains et les Suèves franchissent le Rhin et entrent en Gaule", "2b3354ba"], "d": ["À la date traditionnelle du 31 décembre 406 (sur le Rhin gelé), les Vandales, les Alains et les Suèves entrèrent en Gaule romaine ; la défense du Rhin s'effondra. Leur passage en Espagne (409) détacha ensuite des provinces essentielles de l'Empire romain d'Occident.", "2dbbe2e6"]},
"OLAYLAR_ANTIK_AKDENIZ:0409-01-01:0":{"b": ["Les Vandales, les Alains et les Suèves passent en Espagne : partage de l'Hispanie", "b7036608"], "d": ["À l'automne 409, les groupes vandales, alains et suèves qui avaient franchi les Pyrénées depuis la Gaule se partagèrent la péninsule en 411 : les Hasdings et les Suèves prirent la Gallaecia, les Silings la Bétique, les Alains la Lusitanie et la Carthaginoise. Les Wisigoths (416-418) écrasèrent les Silings et les Alains, préparant le passage des Vandales en Afrique.", "28caca34"]},
"OLAYLAR_ANTIK_AKDENIZ:0418-01-01:0":{"b": ["Rome établit les Wisigoths en Aquitaine seconde : royaume wisigoth centré sur Toulouse", "38a7699e"], "d": ["Après avoir employé les Wisigoths de Wallia contre les Vandales et les Alains en Hispanie, Rome, sous le commandement de Constance, les établit en 418 comme fédérés en Aquitaine seconde, dans la vallée de la Garonne. Le royaume wisigoth centré sur Toulouse est considéré comme le premier royaume germanique en terre romaine.", "49ca3c3f"]},
"OLAYLAR_ANTIK_AKDENIZ:0434-01-01:0":{"b": ["Traité de Margus : les Huns reçoivent de Rome 700 livres d'or par an", "833d8854"], "d": ["Après la mort du roi hun Rua (433/4), Attila et Bléda conclurent à Margus un traité avec l'Empire romain d'Orient : le tribut annuel fut porté de 350 à 700 livres d'or et les réfugiés huns furent restitués. Les Huns obtinrent le droit de commercer sur la frontière du Danube.", "d18e188d"]},
"OLAYLAR_ANTIK_AKDENIZ:0435-01-01:0":{"b": ["Traité d'Hippone : Rome reconnaît les Vandales comme fédérés en Numidie et dans une partie de la Maurétanie", "f7dba59f"], "d": ["Après son passage en Afrique en 429, le roi vandale Genséric conclut en 435 le traité d'Hippone avec Rome ; les Vandales conservèrent la Numidie et une partie de la Maurétanie en qualité de fédérés. Le traité fut rompu en 439 par la prise de Carthage.", "1cde8863"]},
"OLAYLAR_ANTIK_AKDENIZ:0441-01-01:0":{"b": ["Attila prend les forteresses du Danube : Viminacium et Singidunum (Belgrade) passent aux Huns", "0abb2c54"], "d": ["L'armée romaine d'Orient étant engagée dans l'expédition de Sicile contre les Vandales, Attila franchit le Danube en 441 ; Margus, Viminacium et Singidunum furent prises. Sirmium tomba aussi au cours de ces campagnes et les Huns atteignirent l'intérieur des Balkans.", "93414c5c"]},
"OLAYLAR_ANTIK_AKDENIZ:0442-01-01:0":{"b": ["Rome et les Vandales concluent un nouveau traité : l'Africa Proconsularis, la Byzacène et une partie de la Numidie restent aux Vandales", "e5700ddc"], "d": ["Genséric, qui avait pris Carthage (439), fit en 442, par un traité conclu avec Valentinien III, de l'Africa Proconsularis, de la Byzacène, de l'Abaritane et d'une partie de la Numidie une terre juridiquement vandale ; Rome ne conserva que la Maurétanie et l'ouest de la Numidie.", "3910a28d"]},
"OLAYLAR_ANTIK_AKDENIZ:0448-01-01:0":{"b": ["Paix d'Anatolius : une large bande au sud du Danube est abandonnée aux Huns", "ee8ad838"], "d": ["Après la défaite romaine d'Orient à l'Utus, Anatolius conclut la paix avec Attila en 447 : Rome céda aux Huns, au sud du Danube, une bande large de cinq jours de marche allant de Singidunum à Novae, et le tribut annuel fut porté à 2100 livres d'or.", "591853fc"]},
"OLAYLAR_ANTIK_AKDENIZ:0451-01-01:0":{"b": ["Bataille des Champs Catalauniques (Châlons) : Aetius et Théodoric Ier chassent Attila de la Gaule", "80f10e32"], "d": ["En 451, Attila entra en Gaule et assiégea Orléans ; la coalition d'Aetius et du roi wisigoth Théodoric Ier le repoussa dans la plaine des Champs Catalauniques (Théodoric y trouva la mort). L'avance des Huns en Europe occidentale fut ainsi stoppée.", "89c6bc9e"]},
"OLAYLAR_ANTIK_AKDENIZ:0452-01-01:0":{"b": ["Attila entre en Italie ; Aquilée est détruite", "1349c67a"], "d": ["En 452, Attila entra en Italie du Nord par-delà les Alpes, rasa Aquilée et pilla la plaine du Pô ; la maladie et la contre-attaque de l'Orient l'obligèrent à se retirer. Les habitants d'Aquilée, réfugiés dans les lagunes, formèrent le noyau de Venise.", "cb78da70"]},
"OLAYLAR_ANTIK_AKDENIZ:0453-01-01:0":{"b": ["Mort d'Attila ; dissolution de l'État hun", "47009384"], "d": ["Attila mourut en 453 la nuit de ses noces ; le partage entre ses fils et le soulèvement des sujets germaniques mirent fin un an plus tard, au Nedao (454), à la suprématie hunnique. Les Huns se retirèrent en Europe orientale.", "f5a5a41d"]},
"OLAYLAR_ANTIK_AKDENIZ:0475-01-01:0":{"b": ["Le royaume wisigoth d'Euric se sépare de fait de Rome : l'Auvergne est cédée aux Wisigoths", "4bbe7b0c"], "d": ["Euric étendit son royaume par des conquêtes en Hispanie et en Gaule depuis 466 ; en 475, Julius Nepos, en cédant l'Auvergne, reconnut de fait sa souveraineté indépendante. Le royaume wisigoth contrôla les terres de l'Empire d'Occident de la Loire à la Méditerranée.", "06af5e95"]},
"OLAYLAR_ANTIK_AKDENIZ:0480-01-01:0":{"b": ["Julius Nepos est assassiné en Dalmatie : dernier empereur légitime d'Occident", "3b965f33"], "d": ["Nepos, qui s'était retiré en Dalmatie après la chute de Romulus, fut assassiné en 480 ; après sa mort, plus personne ne revendiqua le trône d'Occident et Odoacre poursuivit son pouvoir de fait en Italie au nom de Zénon.", "4f4d9885"]},
"OLAYLAR_ANTIK_AKDENIZ:0489-08-28:0":{"b": ["Théodoric fait entrer les Ostrogoths en Italie : Odoacre est vaincu sur l'Isonzo et à Vérone", "6a998bf8"], "d": ["Avec l'accord de l'empereur d'Orient Zénon, Théodoric entra en Italie en 489 et vainquit Odoacre sur l'Isonzo et à Vérone ; Odoacre s'enferma dans Ravenne. Le siège de trois ans prit fin en 493 avec la reddition de Ravenne.", "092f7492"]},
"OLAYLAR_ANTIK_AKDENIZ:0493-03-05:0":{"b": ["Théodoric fait tuer Odoacre à Ravenne ; l'Italie devient royaume ostrogoth", "5a2db0ed"], "d": ["Fin du royaume d'Italie d'Odoacre : toute l'Italie (y compris des villes comme Gênes, Brindisi et Aricie) passa au royaume des Goths de l'Est (Ostrogoths). Après trois ans de siège de Ravenne, Odoacre et Théodoric s'accordèrent en mars 493 sur un gouvernement conjoint ; Théodoric tua ensuite Odoacre lors d'un banquet. L'Italie devint, avec l'assentiment de l'Orient, un royaume ostrogoth dont la capitale est Ravenne.", "1024674c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0020-01-01:0":{"b": ["Paix de Samos : les ambassadeurs de Koush obtiennent la paix d'Auguste ; Rome supprime le tribut imposé à Koush, la frontière est fixée en Basse-Nubie (Hiera Sykaminos)", "c3c4c20d"], "d": ["Les ambassadeurs de la Candace, sur les indications de Pétronius, se rendirent à Samos où se trouvait Auguste ; Auguste accepta toutes leurs demandes et supprima aussi les tributs que Pétronius avait imposés à Koush. À la suite de cette paix, la frontière romano-koushite se fixa au sud de Philæ, sur la ligne de Hiera Sykaminos (Maharraqa), et il n'y eut pas de conflit sérieux pendant environ trois cents ans.", "4ff5e832"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0022-01-01:0":{"b": ["Pétronius mène campagne contre Koush et prend Pselkis, Premnis et Napata ; il installe une garnison à Ibrim", "4884ed51"], "d": ["Le préfet Pétronius, avec dix mille fantassins et huit cents cavaliers, vainquit trente mille soldats koushites, prit Pselkis, s'empara de la forteresse de Premnis (Qasr Ibrim) dès le premier assaut et rasa Napata, où se trouvait le palais de la Candace. Jugeant difficile d'aller plus loin, il laissa à Premnis, en repartant, une garnison de quatre cents hommes avec deux ans de vivres. Lorsque la Candace tenta de reprendre Premnis, Pétronius accourut et défendit la forteresse.", "672f8f4e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0024-01-01:0":{"b": ["Sous la conduite de la Candace, Koush prend Éléphantine, Syène et Philæ ; les statues d'Auguste sont renversées", "aa665fad"], "d": ["Une partie des troupes romaines d'Égypte ayant été retirée pour l'expédition d'Aelius Gallus en Arabie, les Koushites pénétrèrent dans la Thébaïde ; ils vainquirent la garnison de trois cohortes de Syène, prirent Syène, Éléphantine et Philæ, réduisirent la population en esclavage et abattirent les statues de César. Strabon écrit que la reine qui gouvernait alors Koush portait le titre de « Candace » et était une femme borgne.", "63e07dc6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0028-01-01:0":{"b": ["Cornélius Gallus devient le premier préfet d'Égypte ; il réprime les révoltes d'Héroonpolis et de Thèbes, la frontière avec Koush est assurée", "9f688855"], "d": ["Octavien fit de l'Égypte une province spéciale tributaire et en confia le gouvernement non à un sénateur, mais à un préfet de rang équestre ; le premier préfet fut Cornélius Gallus. Strabon écrit que Gallus prit avec peu de soldats une ville révoltée d'Héroonpolis et réprima rapidement à Thèbes le soulèvement provoqué par l'impôt. La stèle de Gallus à Philæ indique que les envoyés du souverain de Koush y furent reçus et que la région du Triacontaschoene fut placée sous protection.", "ae3f8fab"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0029-08-01:0":{"b": ["Octavien entre à Alexandrie ; fin de l'État ptolémaïque, l'Égypte passe à Rome", "553804ca"], "d": ["Après le passage de la flotte et de la cavalerie d'Antoine à Octavien, Octavien entra à Alexandrie ; Antoine se donna la mort et Cléopâtre mourut peu après. Octavien épargna les Alexandrins et, disant « j'ai voulu voir un roi, non des morts », ne visita pas les tombeaux des Ptolémées ; il confia l'Égypte, comme pays tributaire, à Cornélius Gallus. Avec cette date prit fin le royaume ptolémaïque, vieux de trois cents ans.", "c1595889"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0030-09-02:0":{"b": ["Bataille d'Actium : Octavien bat Antoine et Cléopâtre", "7e46cc73"], "d": ["La flotte d'Octavien vainquit à Actium celle d'Antoine et de Cléopâtre ; le couple se retira en Égypte. Dion, auteur qui évite de donner des dates, signale spécialement ce jour parce qu'à partir de là Octavien tint seul l'empire et que les années de son pouvoir furent comptées depuis ce jour.", "7747a2e5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0033-01-01:0":{"b": ["Donations d'Alexandrie : Antoine proclame Cléopâtre et ses enfants souverains des royaumes d'Orient", "24e24981"], "d": ["Antoine, ayant fait dresser des trônes d'or devant la foule réunie au Gymnase, proclama Cléopâtre reine d'Égypte, de Chypre, de Libye et de Cœlé-Syrie, Césarion co-souverain avec elle, et ses enfants rois d'Arménie, de Médie, de Parthie et de Phénicie-Syrie-Cilicie. À Rome, cette cérémonie fut transformée en propagande contre Antoine et précipita la guerre civile.", "dc9e5d73"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0035-01-01:0":{"b": ["Antoine offre à Cléopâtre Chypre, la Phénicie, la Cœlé-Syrie et une partie de la Cilicie", "cf19a357"], "d": ["Selon Plutarque, lorsqu'il vint en Syrie, Antoine donna à Cléopâtre la Phénicie, la Cœlé-Syrie, Chypre, la plus grande partie de la Cilicie, le côté de la Judée qui produit le baume et la partie de la Nabatée qui s'étend jusqu'à la mer. Ainsi l'État ptolémaïque contrôla, pour la première fois depuis Ptolémée III, un vaste espace de la Méditerranée orientale (malgré le courroux de Rome).", "2c5122e4"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0046-01-01:0":{"b": ["Guerre d'Alexandrie : César bat Ptolémée XIII et laisse l'Égypte à Cléopâtre", "96c9b516"], "d": ["Lorsque César vint à Alexandrie et voulut arbitrer entre Cléopâtre et Ptolémée XIII, les forces du palais l'assiégèrent ; au cours des combats de rue qui durèrent tout l'hiver, des renforts parvinrent à César et Ptolémée XIII se noya lors de la bataille du Nil. César donna l'Égypte à Cléopâtre et à son jeune frère Ptolémée XIV ; les légions romaines restèrent à Alexandrie.", "bc41a5ff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0054-01-01:0":{"b": ["Gabinius rétablit Ptolémée XII sur le trône d'Égypte avec l'armée romaine ; une garnison romaine reste à Alexandrie", "41d8f47d"], "d": ["Ptolémée XII (Aulète), chassé, acheta l'entrée en Égypte en versant un énorme pot-de-vin à Gabinius, gouverneur de Syrie ; Gabinius abandonna l'expédition contre les Parthes, entra en Égypte par Péluse et ramena Aulète sur le trône. C'est le moment où l'indépendance de l'Égypte fut de fait placée sous la garantie de Rome. Gabinius fut plus tard jugé à Rome.", "2ebc08ef"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0057-01-01:0":{"b": ["Rome prend Chypre aux Ptolémées et l'annexe ; Caton est envoyé dans l'île", "678b2115"], "d": ["Le roi de Chypre, frère de Ptolémée XII, ne s'opposa pas à la prise de l'île par Rome sur proposition de Clodius ; Caton fut envoyé pour en prendre possession. L'État ptolémaïque perdit Chypre et son dernier port de guerre sur la côte. Plutarque évoque l'« envoi de Caton à Chypre » dans la vie de Pompée.", "2ec72ea2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0167-01-01:0":{"b": ["« Jour d'Éleusis » : l'envoyé romain Popilius Laenas contraint Antiochos IV à se retirer d'Égypte", "e6883e6a"], "d": ["Immédiatement après la bataille de Pydna (22 juin 168 av. J.-C.), l'envoyé romain Caius Popilius Laenas transmit à Antiochos, qui assiégeait Alexandrie, l'ordre du Sénat de cesser la guerre ; il traça un cercle autour du roi afin qu'il réfléchisse à sa réponse. Antiochos se retira. L'Égypte maintint son indépendance, sans la perdre, sous la protection de Rome.", "4831dad7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0168-01-01:0":{"b": ["Antiochos IV attaque l'Égypte ; lors de la sixième guerre de Syrie, il avance vers Memphis et Naucratis", "b85e6712"], "d": ["En réponse aux préparatifs de Ptolémée VI pour reprendre la Cœlé-Syrie, Antiochos IV entra en Égypte et descendit de Péluse vers le Nil ; il défendit son droit sur la Cœlé-Syrie et traita bien la population à Naucratis. La guerre, sans détruire l'Égypte mais en affaiblissant l'État, prit fin un an plus tard par l'intervention de Rome.", "f329f8b1"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0185-01-01:0":{"b": ["La révolte de Thèbes est réprimée : Komanos remet la Haute-Égypte sous la domination ptolémaïque", "4c0e4f10"], "d": ["Après environ vingt ans de gouvernement sécessionniste, le commandant ptolémaïque Komanos reprit Thèbes au pharaon indigène Ânkhouennéfer et la Haute-Égypte fut de nouveau rattachée à l'État ptolémaïque.", "24386cc8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0195-03-27:0":{"b": ["Le synode de Memphis promulgue le décret de Rosette : Ptolémée V accorde aux temples une remise d'impôts", "5643b91f"], "d": ["Le synode réuni à Memphis par les prêtres égyptiens confirma l'avènement de Ptolémée V et proclama les remises d'impôts accordées par le roi aux temples, la répression des révoltes et l'institution du culte royal. Le décret fut rédigé en grec, en démotique et en hiéroglyphes ; la pierre de Rosette est ce texte trilingue. Le texte signale aussi la répression des rebelles du Delta (Lycopolis).", "80eb0165"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0199-01-01:0":{"b": ["Bataille de Panion : Antiochos III bat Scopas ; la Cœlé-Syrie passe des Ptolémées aux Séleucides", "97e30e58"], "d": ["Lors de la cinquième guerre de Syrie, Antiochos III mit en déroute à Paneion le commandant ptolémaïque Scopas l'Étolien ; selon Flavius Josèphe, Antiochos reprit les villes de Cœlé-Syrie conquises par Scopas et prit aussi la Samarie, et les Juifs se joignirent à Antiochos de leur plein gré. La Cœlé-Syrie (Syrie-Palestine) passa dès lors sous la domination séleucide ; l'État ptolémaïque se retira de la région.", "930d7d22"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0204-01-01:0":{"b": ["Des pharaons indigènes sécessionnistes apparaissent à Thèbes : la Haute-Égypte se détache de la domination ptolémaïque", "d10abb36"], "d": ["Les Égyptiens indigènes armés après la victoire de Raphia, enflés de leur succès selon l'expression de Polybe, cessèrent d'obéir aux ordres du roi ; des soulèvements éclatèrent dans le Delta et en Haute-Égypte. À Thèbes, des pharaons indigènes (Horwennefer, puis Ânkhouennéfer) tinrent la Haute-Égypte contre les Ptolémées pendant environ vingt ans.", "aed92c1c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0216-01-01:0":{"b": ["Bataille de Raphia : Ptolémée IV bat Antiochos III ; la Cœlé-Syrie reste aux Ptolémées", "34362178"], "d": ["À Raphia, l'armée de Ptolémée IV, dont la composition comprenait un grand nombre d'Égyptiens indigènes dans la phalange (hoplites), vainquit l'armée d'Antiochos III ; Antiochos se retira de Cœlé-Syrie et la région resta aux mains des Ptolémées jusqu'en 200. L'armement des Égyptiens indigènes alimenta par la suite les révoltes sécessionnistes de Haute-Égypte.", "e5e7e848"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0218-01-01:0":{"b": ["Antiochos III reprend Séleucie de Piérie aux Ptolémées", "39ee3a52"], "d": ["Antiochos III assiégea Séleucie de Piérie, tenue par les Ptolémées, et la prit en corrompant des officiers ; Polybe écrit que la ville était tenue depuis l'époque de Ptolémée III par une garnison appartenant aux rois d'Égypte. Par cette victoire, les Séleucides retrouvèrent le port d'Antioche et se préparèrent à marcher sur la Cœlé-Syrie (quatrième guerre de Syrie).", "6964f9b2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0245-01-01:0":{"b": ["Lors de la guerre laodicéenne, Ptolémée III envahit la Syrie et la Mésopotamie ; Séleucie de Piérie passe aux Ptolémées", "04472253"], "d": ["Ptolémée II mourut le 28 janvier 246 av. J.-C. ; Ptolémée III attaqua l'État séleucide pour protéger sa sœur Bérénice. Il fut accueilli à Séleucie de Piérie et à Antioche ; la Chronique babylonienne (BCHP 11) indique que son armée atteignit Babylone à partir de décembre 246 av. J.-C. L'inscription d'Adoulis affirme qu'il conquit l'ouest de l'Euphrate, la Cilicie, la Pamphylie et la Thrace. Séleucie de Piérie resta de longues années aux mains des Ptolémées.", "54ffdc9c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0300-01-01:0":{"b": ["Après Ipsos, Ptolémée occupe la Cœlé-Syrie ; Séleucos proteste (origine des guerres de Syrie)", "a109388f"], "d": ["Après la bataille d'Ipsos (301 av. J.-C.), Séleucos, Lysimaque et Cassandre s'accordèrent pour donner toute la Syrie à Séleucos ; Ptolémée, lui, occupa la Cœlé-Syrie avec ses troupes et la garda. Ce différend donna naissance, au cours des deux siècles suivants, à six guerres de Syrie. Antiochos III défendit plus tard cette thèse, comme le rapporte Polybe.", "21348480"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0304-01-01:0":{"b": ["Ptolémée se proclame roi ; la dynastie ptolémaïque est officiellement fondée", "008c723a"], "d": ["Après qu'Antigone et Démétrios eurent pris le titre de roi (306 av. J.-C.), Ptolémée prit à son tour le titre royal ; l'Égypte commença à être désignée comme un royaume hellénistique indépendant. La présentation de la dynastie comme pharaons d'Égypte accéléra aussi l'accord avec la classe sacerdotale indigène.", "318a8821"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0311-01-01:0":{"b": ["Bataille de Gaza : Ptolémée et Séleucos battent Démétrios (la Syrie passe brièvement aux Ptolémées)", "ea0d264f"], "d": ["Démétrios, fils d'Antigone, fut battu devant Gaza par l'armée combinée de Ptolémée et de Séleucos ; Ptolémée entra en Cœlé-Syrie. Par la contre-offensive d'Antigone, la région échappa de nouveau peu après, et la paix (311 av. J.-C.) fixa cette situation.", "619ae833"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0320-01-01:0":{"b": ["L'expédition de Perdiccas en Égypte échoue au passage du Nil ; Perdiccas est tué par son armée", "c1792117"], "d": ["Lors de la guerre des Diadoques, Perdiccas, régent d'Alexandre, entra en Égypte contre Ptolémée, qui avait enlevé le cortège funèbre d'Alexandre, mais il ne put franchir le Nil, perdit beaucoup d'hommes et fut tué par ses officiers. Ptolémée conserva l'Égypte.", "0057b746"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0321-01-01:0":{"b": ["Ptolémée annexe Cyrène (Cyrénaïque) à l'Égypte", "65316c50"], "d": ["Intervenant dans les querelles intestines de Cyrène, Ptolémée rattacha à l'Égypte la région libyenne de la Cyrénaïque sous le commandement d'Ophellas. L'Égypte de Ptolémée s'étendit ainsi aussi vers l'ouest ; la Cyrénaïque resta, au cours des siècles suivants, aux mains d'une branche de la dynastie ptolémaïque.", "5d0e2ba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0330-01-01:0":{"b": ["Alexandre consulte l'oracle d'Ammon à l'oasis de Siwa", "c437ced0"], "d": ["Alexandre, quittant la côte pour le désert, se rendit à l'oasis de Siwa, où se trouve le temple d'Ammon, et consulta l'oracle ; Arrien écrit qu'il reçut la réponse qui lui plaisait. Cette visite nourrit la légitimité d'Alexandre en Égypte et, plus tard, les récits qui le tinrent pour fils du dieu.", "40603afa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0331-01-01:0":{"b": ["Alexandre entre en Égypte ; le satrape perse Mazakès se rend, l'Égypte passe sous domination macédonienne", "c4a5f014"], "d": ["Parti de Gaza, Alexandre arriva à Péluse le septième jour, où sa flotte l'avait aussi rejoint. Le satrape Mazakès, privé de tout soutien perse après Issos, ne résista pas et accueillit Alexandre amicalement dans les villes. Alexandre mit une garnison à Péluse et avança vers Memphis ; il laissa le gouvernement à deux gouverneurs indigènes (Doloaspis, Pétisis) et nomma des commandants macédoniens à Memphis et à Péluse. L'Égypte sortit de la domination perse et fut intégrée à l'empire d'Alexandre.", "08c837eb"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0342-01-01:0":{"b": ["Artaxerxès III reconquiert l'Égypte ; Nectanébo II s'enfuit en Nubie", "55d78a8d"], "d": ["Lors de la marche d'Artaxerxès III sur l'Égypte après la prise de Sidon, la défense de Péluse s'effondra ; Nectanébo II, sans attendre d'être assiégé à Memphis, s'enfuit en Haute-Égypte et en Nubie. L'Égypte devint pour la seconde fois une satrapie perse ; le sort du dernier pharaon indigène est inconnu.", "373a5f39"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0359-01-01:0":{"b": ["Tachos part en campagne en Syrie ; Nectanébo II prend le trône par un coup d'État, Agésilas change de camp", "4e1e9804"], "d": ["Tachos réunit des mercenaires grecs (le roi de Sparte Agésilas et l'Athénien Chabrias) pour attaquer la Syrie perse ; pendant l'expédition, son neveu Nectanébo II se proclama roi. Agésilas se rangea aux côtés de Nectanébo ; Plutarque écrit qu'en Grèce on critiqua qu'Agésilas, dans sa vieillesse, se battît contre salaire pour un « rebelle barbare ».", "d9ffa449"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0372-01-01:0":{"b": ["Nectanébo Ier repousse l'invasion perse (Pharnabaze-Iphicrate)", "0a8bc67d"], "d": ["Nectanébo Ier, fondateur de la XXXe dynastie, repoussa le débarquement dans le Delta de l'armée perse commandée par Pharnabaze et de l'Athénien Iphicrate, grâce à la crue du Nil et aux désaccords entre les commandants. Ce succès prolongea de trente ans l'indépendance de l'Égypte.", "edb11f45"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0459-01-01:0":{"b": ["Révolte d'Inaros : le soulèvement égyptien soutenu par Athènes met les Perses en difficulté à Memphis, puis s'effondre à Prosopitis en 454", "0cd93c33"], "d": ["Le Libyen Inaros souleva presque toute l'Égypte contre Artaxerxès et demanda l'aide des Athéniens ; la flotte athénienne entra dans le Nil et prit les deux tiers de Memphis, puis assiégea le « Mur Blanc » restant. Le commandant perse Mégabyze assiégea les Athéniens dans l'île de Prosopitis pendant un an et six mois et les anéantit (en asséchant le canal) ; Inaros fut capturé et crucifié. Amyrtée, dans les marais du Delta, ne put en revanche être pris.", "452e1e06"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0485-01-01:0":{"b": ["L'Égypte se révolte contre la domination perse ; Xerxès Ier réprime la révolte et gouverne l'Égypte plus durement", "9d3d7462"], "d": ["La révolte d'Égypte, commencée avant la mort de Darius Ier, fut réprimée dans les premières années de Xerxès Ier ; Xerxès nomma satrape son frère Achéménès et se mit à gouverner l'Égypte plus durement qu'à l'époque de Darius.", "db4dbf1d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0522-01-01:0":{"b": ["L'expédition de Cambyse contre Koush échoue faute d'eau et de vivres ; la frontière sud de l'Égypte reste à Éléphantine", "4ebbad8c"], "d": ["Après l'Égypte, Cambyse projeta une expédition contre les « Éthiopiens Longue-Vie » (Koush) ; selon Hérodote, le roi de Koush envoya son arc aux ambassadeurs perses et leur dit de l'attaquer « lorsqu'ils pourraient bander l'arc aisément ». L'armée, à court de vivres dans le désert, fit demi-tour. Strabon mentionne aussi le lieu où l'armée de Cambyse périt dans une tempête du désert. Koush resta indépendant ; la frontière sud des Perses s'arrêta à Éléphantine.", "141a4dc5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0569-01-01:0":{"b": ["Amasis bat Apriès et accède au trône d'Égypte ; les marchands grecs sont installés à Naucratis", "75a24b0b"], "d": ["Apriès, de retour d'une campagne de Libye avec des mercenaires grecs, fut battu à Momemphis par Amasis, qui avait pris la tête des troupes indigènes de l'armée ; Amasis gouverna l'Égypte depuis Saïs et assigna aux Grecs Naucratis comme unique port de commerce. À la fin de son pouvoir (526 av. J.-C.), la menace perse grandit.", "821328d0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0592-01-01:0":{"b": ["Psammétique II mène une expédition en Nubie : la pression de Koush à la frontière égyptienne est brisée", "8f0aaf9d"], "d": ["L'expédition de Psammétique II en Nubie est évoquée chez Hérodote comme une « expédition en Éthiopie » ; l'armée égyptienne et des mercenaires grecs et cariens laissèrent des inscriptions grecques à Abou Simbel. La stèle de l'an 3 à Thèbes (Karnak) rapporte qu'une lourde défaite fut infligée au royaume de Koush, et la stèle de victoire de Kalabcha la commémore ; on considère que l'expédition alla jusqu'à la troisième ou à la quatrième cataracte. Selon les sources, le centre politique de Koush se déplaça par la suite (Aspelta, vers 591 av. J.-C.) vers le sud, à Méroé.", "17c955db"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0600-01-01:0":{"b": ["Nabuchodonosor attaque la frontière égyptienne ; en bataille rangée, les deux camps subissent de lourdes pertes, Babylone se retire", "45655313"], "d": ["Le roi de Babylone Nabuchodonosor marcha sur l'Égypte la 4e année de son règne ; le roi d'Égypte rassembla son armée et lui fit face, et dans la bataille en rase campagne les deux camps s'épuisèrent mutuellement. Nabuchodonosor retourna à Babylone pour rééquiper son armée. L'Égypte défendit sa frontière, mais la Syrie-Palestine était restée à Babylone.", "c561b28b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0604-01-01:0":{"b": ["Bataille de Karkemish : Nabuchodonosor bat l'armée égyptienne ; l'Égypte perd la Syrie", "ba486ac1"], "d": ["Le prince héritier Nabuchodonosor, avec l'armée babylonienne, franchit l'Euphrate contre l'armée égyptienne qui se trouvait à Karkemish et la mit en déroute ; il anéantit les fuyards dans la région de Hamath et s'empara de toute la région de Hamath. L'Égypte se retira de Syrie et revint derrière la frontière du Sinaï ; Babylone devint maîtresse de la Syrie-Palestine.", "61bb7c47"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0608-01-01:0":{"b": ["Néchao II pénètre en Syrie-Palestine ; il bat Josias à Megiddo et avance vers l'Euphrate", "f887d6fd"], "d": ["Néchao II, visant à s'emparer des provinces occidentales de l'Assyrie en ruine, marcha sur la Syrie ; il fit tuer à Megiddo Josias, roi de Juda, qui se trouvait sur son chemin. Hérodote dit : « Néchao vainquit les Syriens à Magdolos et prit la grande ville syrienne de Kadytis ». L'Égypte contrôla ainsi brièvement la Syrie-Palestine jusqu'à l'Euphrate.", "573a58de"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0655-01-01:0":{"b": ["Psammétique Ier fait adopter sa fille Nitocris par l'Épouse du Dieu de Thèbes et prend le contrôle de la Haute-Égypte", "bf768452"], "d": ["Psammétique Ier fit envoyer à Thèbes, dans sa 9e année, sa fille Nitocris pour qu'elle soit adoptée par Chépénoupet, fille du roi de Koush Taharqa (l'Épouse du Dieu de Thèbes) ; Chépénoupet transmit son domaine à Nitocris et le patrimoine des temples de Thèbes passa ainsi aux mains des Saïtes. La stèle d'adoption montre que Psammétique obtint le plein contrôle de Thèbes dans sa 9e année et que Tanoutamon avait perdu la Haute-Égypte jusqu'à cette date.", "f750f320"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0662-01-01:0":{"b": ["L'armée assyrienne pille Thèbes ; Tanoutamon se retire vers le sud, la domination koushite en Égypte s'effondre", "777fc1a5"], "d": ["Les armées d'Assurbanipal poursuivirent Tanoutamon depuis Memphis jusqu'à Thèbes et pillèrent la ville ; les trésors des temples de Thèbes furent transportés à Ninive. Tanoutamon se retira en Nubie ; la domination koushite se dissolut en Haute-Égypte. Ce pillage est mentionné dans l'Ancien Testament sous le nom de « No-Amon » (Nahum 3:8).", "3d4dea25"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:0":{"b": ["Début de la XXVIe dynastie : Psammétique Ier accède au pouvoir en Basse-Égypte à Saïs comme vassal de l'Assyrie", "f270eac3"], "d": ["Parmi les princes du Delta que l'Assyrie avait établis en Égypte, le souverain de Saïs Psammétique Ier inaugura la XXVIe dynastie (saïte). Selon Hérodote, Psammétique, sorti du lot des « douze rois » et chassé dans les marais, reprit le Delta. Après l'Assyrie et Koush, l'Égypte passa de nouveau aux mains d'une dynastie indigène ; la conquête de Thèbes et de la Haute-Égypte prit plusieurs années.", "eaebf639"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:1":{"b": ["Tanoutamon descend de Koush et reprend Thèbes et Memphis ; il assiège les vassaux de l'Assyrie", "f84c87a4"], "d": ["Tanoutamon, successeur de Taharqa, après son couronnement à Napata selon la Stèle du Songe, descendit le fleuve vers le nord : il fit une offrande à Khnoum à Éléphantine, vint à Thèbes et à Memphis, où il prit la ville après avoir massacré ceux qui s'opposaient à lui, tandis que les princes du Delta se cachèrent ou se soumirent. Cette entreprise menaça l'ordre établi dans le Delta par Psammétique Ier et l'Assyrie et amena l'expédition punitive de l'Assyrie.", "d8ce2798"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0670-01-01:0":{"b": ["Assarhaddon entre en Égypte et prend Memphis ; Taharqa se retire vers le sud", "a138bcac"], "d": ["Le roi d'Assyrie Assarhaddon marcha sur l'Égypte la 10e année ; l'armée assyrienne fit un grand massacre en Égypte et le roi de Koush Taharqa s'enfuit vers le sud. Les principautés du Delta devinrent vassales de l'Assyrie, Memphis et la Basse-Égypte passèrent provisoirement aux mains des Assyriens. Assarhaddon mourut en route, deux ans plus tard, alors qu'il partait pour une nouvelle campagne.", "4c58b398"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0700-01-01:0":{"b": ["Sennachérib rencontre l'armée koushito-égyptienne à Eltékéh lors de la campagne de Juda", "7f423351"], "d": ["Lors de la campagne de Canaan du roi d'Assyrie Sennachérib, l'armée égyptienne de Koush vint au secours de Juda et combattit les Assyriens à Eltékéh ; l'armée assyrienne se retira sans avoir pu prendre Jérusalem. Flavius Josèphe raconte que Sennachérib, apprenant que le roi de Koush Tirhaka arrivait avec une grande armée, quitta Péluse. C'est le premier affrontement direct entre Koush-Égypte et l'Assyrie.", "0bc942e3"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0724-01-01:0":{"b": ["Piyé (Piankhi) descend en Égypte : il bat la coalition de Tefnakht et soumet les souverains de Memphis et du Delta", "bb36f7c4"], "d": ["Tefnakht de Saïs avait formé une alliance allant du Delta à Memphis et à la Moyenne-Égypte et assiégé Héracléopolis. Piyé, partant en campagne de Napata, descendit au nord la 21e année, prit les villes alliées (Hermopolis, Memphis, Héliopolis) et accepta la soumission des princes du Delta ; puis il retourna à Napata. Koush devint ainsi maître de toute l'Égypte (XXVe dynastie).", "8a8bbba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0749-01-01:0":{"b": ["Kashta, roi de Koush (Napata), avance en Haute-Égypte ; il étend son influence jusqu'à Éléphantine et Thèbes", "b0f5be7f"], "d": ["Les rois de Koush à Napata, profitant du morcellement de l'Égypte à la Troisième Période intermédiaire, se renforcèrent vers le nord. Les monuments montrent que Kashta établit son influence en Haute-Égypte jusqu'à Éléphantine ; Aménirdis Ire (sœur de Piyé), de la dynastie koushite, fut installée à Thèbes avec le titre d'« Épouse du Dieu » d'Amon, et cette charge devint l'intermédiaire de Koush sur Thèbes. Le terrain fut ainsi préparé pour la fondation de la XXVe dynastie.", "3540bb2c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0924-01-01:0":{"b": ["Chéchonq mène campagne à Canaan : Jérusalem et des villes d'Israël et de Juda figurent sur la liste de Karnak", "1607ae3a"], "d": ["La campagne de Chéchonq à Canaan concorde avec le récit biblique rapportant qu'il prélevait un tribut à Jérusalem la 5e année du roi Roboam (1 Rois 14:25) ; sur la porte bubastite de Karnak sont énumérés environ 150 noms de villes (à peu près cinquante à soixante appartenant à Israël, une centaine à Juda). Flavius Josèphe raconte lui aussi que Sésac prit Jérusalem et emporta le trésor. C'est la plus longue opération extérieure de l'Égypte de la Troisième Période intermédiaire.", "13f6482e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0944-01-01:0":{"b": ["Chéchonq Ier (d'origine méchouech/libyenne) fonde la XXIIe dynastie ; capitale Bubastis", "dae122c7"], "d": ["Les généraux méchouech d'origine libyenne s'étaient établis dans le Delta après le Nouvel Empire ; parmi eux, Chéchonq Ier réunifia l'Égypte après la XXIe dynastie de Tanis. En faisant de son fils le Grand Prêtre d'Amon, il rattacha aussi Thèbes à la dynastie. Cette époque procura à l'Égypte un bref redressement qui la tourna de nouveau vers la politique extérieure (campagne de Canaan).", "09d0b8f9"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1068-01-01:0":{"b": ["Fin du Nouvel Empire : dans les dernières années de Ramsès XI, Smendès (Tanis) dans le Delta et le grand prêtre d'Amon à Thèbes sont de fait indépendants", "1828ceb0"], "d": ["À la dernière période de Ramsès XI, l'État central s'effondra : à Thèbes, le Grand Prêtre d'Amon Herihor contrôle la Haute-Égypte, tandis qu'à Tanis, dans le Delta, gouverne Nesbanebdjed (Smendès) ; le Récit d'Ounamon consigne cette division (voyage d'Ounamon d'Herihor à Smendès). Smendès fonda finalement la XXIe dynastie ; la Nubie échappa elle aussi au contrôle de l'Égypte dans ce désordre.", "2317479f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1176-01-01:0":{"b": ["Ramsès III bat les Peuples de la Mer sur terre (Djahy) et en mer dans le Delta", "9068ae7b"], "d": ["La 8e année de Ramsès III, les Peleset, Tjekker, Denyen, Shardanes et autres Peuples de la Mer se dirigèrent par terre et par mer vers la frontière égyptienne ; l'armée égyptienne les arrêta d'abord à la frontière de Canaan, puis dans la bataille navale aux bouches du Delta. Les bas-reliefs de Médinet Habou en témoignent. L'Égypte garda Canaan, mais à partir de cette époque son influence en Méditerranée orientale commença à s'éroder.", "a7654a37"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1208-01-01:0":{"b": ["Merenptah bat la coalition des Libyens et des Peuples de la Mer dans le Delta occidental ; le nom d'« Israël » est mentionné pour la première fois à Canaan", "e512311e"], "d": ["La 5e année de Merenptah, les Méchouech, sous la direction des Libou, et les « Peuples venus de la mer » (Ekwesh, Teresh, Lukka, Shardanes, Shekelesh) envahirent le Delta occidental ; l'armée égyptienne les dispersa à Perire en une bataille de six heures. La stèle de victoire, qui relate ces mêmes événements, désigne en outre à Canaan Ascalon, Gézer, Yénoam et « Israël » ; c'est la plus ancienne mention connue du nom d'Israël.", "6a9d6afc"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1258-01-01:0":{"b": ["« Traité éternel » entre Ramsès II et Hattousili III : fin de la guerre égypto-hittite", "100f2a75"], "d": ["La 21e année de Ramsès II, des envoyés hittites apportèrent à Pi-Ramsès la tablette du traité. Le traité mit fin à la guerre de Syrie, longue d'environ quinze ans : les deux parties renoncèrent à de nouveaux projets de conquête en Syrie, formèrent une alliance défensive et acceptèrent l'extradition des fugitifs et l'aide mutuelle. Selon le résumé de Breasted, la frontière n'est pas précisée dans le texte ; les sphères d'influence des deux États restèrent dans la situation de fait (la bande Qadesh-Amourrou chez Hatti, Canaan chez l'Égypte).", "9b723519"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1273-01-01:0":{"b": ["Ramsès II affronte à Qadesh les Hittites de Mouwatalli II ; le résultat reste indécis", "f5ad96db"], "d": ["Ramsès II rencontra l'armée hittite devant Qadesh, sur l'Oronte ; l'embuscade des chars de guerre hittites mit l'armée égyptienne au bord de la déroute, mais Ramsès contre-attaqua avec sa garde et les repoussa. La bataille ne donna pas de résultat décisif ; Qadesh et l'Amourrou restèrent sous contrôle hittite et la frontière nord de l'Égypte demeura de nouveau sur les côtes de Canaan.", "b58cad94"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1293-01-01:0":{"b": ["Séthi Ier mène campagne du sud de Canaan jusqu'à la côte phénicienne : l'Égypte domine de nouveau Canaan et la côte libanaise, il prend Qadesh", "ad7bf1cd"], "d": ["Selon les bas-reliefs de Karnak, la campagne de la 1re année de Séthi Ier soumit d'abord les Bédouins Shasou, puis, remontant vers le nord par la Palestine, Péher et Beth-Shéan, Yénoam, Tyr et les princes du Liban. La prise de Qadesh est aussi figurée sur le registre supérieur des bas-reliefs. Breasted note que la frontière nord durable ne s'étendit pas au-delà de la ligne est-ouest le long de la côte phénicienne et que la puissance hittite ne fut pas brisée ; c'est l'arrière-plan de la bataille de Qadesh de Ramsès II.", "aa320c30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1339-01-01:0":{"b": ["À l'époque d'Amarna, la domination égyptienne sur la Syrie du Nord se désagrège ; l'Amourrou et Qadesh passent dans la sphère d'influence hittite", "90d00c5a"], "d": ["Les lettres d'Amarna (EA) montrent que les vassaux de Syrie du Nord (Aziru d'Amourrou, les souverains de Qadesh) jouaient entre l'Égypte, le Mitanni et Hatti, et que l'Égypte ne pouvait intervenir dans la région. À la suite des campagnes du roi hittite Souppilouliouma Ier, qui usèrent le Mitanni, l'Amourrou et Qadesh entrèrent dans l'influence hittite ; ainsi la frontière nord de l'Égypte en Syrie fut ramenée à Canaan.", "c876708d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1347-01-01:0":{"b": ["Aménophis IV (Akhenaton) transfère la capitale de l'Égypte à Akhetaton (Amarna)", "53cadac3"], "d": ["Akhenaton fit du culte d'Aton la religion d'État et proclama capitale une ville nouvelle (Akhetaton) ouverte dans le désert, en Moyenne-Égypte ; les « stèles frontières » qui en fixent les limites sont datées des années 4-5. Les lettres d'Amarna montrent qu'à cette époque les vassaux de Syrie demandaient de l'aide mais que l'Égypte ne répondait pas.", "a7911bcf"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1424-01-01:0":{"b": ["Amenhotep II atteint Napata en Nubie et érige une stèle frontière sud : point le plus méridional de l'Égypte", "2f61f824"], "d": ["Au retour de sa campagne de Syrie (en juillet), Amenhotep II passa en Nubie ; selon les inscriptions des temples d'Éléphantine et d'Amada, il fit suspendre six des sept princes ramenés de Syrie aux murailles de Thèbes et le septième aux murailles de Napata. Selon Breasted, le roi érigea à Napata, ou juste au-dessus, une stèle marquant la frontière sud : la souveraineté de fait de l'Égypte en Nubie s'étendit ainsi, au-delà de Tombos (troisième cataracte), jusqu'à la région de la quatrième cataracte.", "31d51fb0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1446-01-01:0":{"b": ["Thoutmosis III franchit l'Euphrate et pénètre sur les terres du Mitanni ; il érige une stèle frontière au Naharin", "ebdbeebe"], "d": ["La 33e année, Thoutmosis III, avançant depuis le Retenou, franchit l'Euphrate, pilla les villes du Naharin et érigea une stèle frontière à l'est du fleuve ; il plaça une seconde stèle à côté de celle de son père. Cette campagne est le point le plus septentrional de l'influence égyptienne et marque le seuil d'un conflit direct avec le Mitanni.", "e7a917e6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1456-01-01:0":{"b": ["Thoutmosis III bat à Megiddo la coalition cananéenne conduite par Qadesh ; Canaan-Syrie passe sous domination égyptienne", "439dc6e8"], "d": ["Le 21e jour du 1er mois de Shemou de la 23e année de Thoutmosis III, devant Megiddo, il vainquit la coalition cananéenne que dirigeait le souverain de Qadesh ; l'ennemi s'enfuit dans la ville et Megiddo se rendit après un long siège. Cette campagne, consignée dans les Annales de Karnak, rendit durable la dépendance de Canaan et de la Syrie du Sud envers l'Égypte et fut le début de l'expansion de l'empire.", "8c75d558"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1498-01-01:0":{"b": ["Thoutmosis Ier mène une campagne en Asie jusqu'à la rive de l'Euphrate (Naharin)", "50ce0679"], "d": ["Selon les inscriptions d'Ahmosis fils de Pennekhbet et d'Ahmosis fils d'Ebana, Thoutmosis Ier, après sa campagne de Nubie, conduisit une grande expédition au Naharin ; Thoutmosis III ajoutera plus tard sa propre stèle à côté de celle que son aïeul avait dressée sur l'Euphrate. C'est la première période attestée où l'influence égyptienne s'étendit jusqu'à l'Euphrate.", "bc058844"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1524-01-01:0":{"b": ["Ahmosis mène une campagne en Basse-Nubie et soumet les montagnards nubiens", "dbbd94b7"], "d": ["Après avoir vaincu les Asiatiques, Ahmosis remonta le fleuve vers le sud jusqu'à Khent-hen-nefer et soumit les montagnards nubiens. Cette campagne est la première étape du processus d'intégration à l'Égypte de la Basse-Nubie, que Kerma tenait depuis la ligne de forteresses du Moyen Empire.", "df3be70d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1529-01-01:0":{"b": ["Ahmosis prend Avaris, capitale des Hyksôs, puis assiège et fait tomber Sharouhen", "b7bb3099"], "d": ["Ahmosis assiégea et prit Avaris, dans le Delta oriental ; les Hyksôs s'enfuirent en Asie et il les poursuivit jusqu'à Sharouhen, dans le sud de Canaan. L'inscription d'Ahmosis fils d'Ebana indique que Sharouhen fut assiégée pendant 6 ans. Ainsi le Delta d'Égypte sortit du contrôle hyksôs et l'Égypte fut en mesure d'exercer une influence politique sur Canaan.", "48e6f876"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1549-01-01:0":{"b": ["Ahmosis Ier monte sur le trône à Thèbes ; début de la XVIIIe dynastie et du Nouvel Empire", "0798cfa3"], "d": ["Ahmosis, frère de Kamosé, dernier roi de la XVIIe dynastie de Thèbes, monta sur le trône dans son enfance ; au cours de son règne, il devait chasser les Hyksôs d'Égypte et rétablir la domination sur la Nubie et Canaan, inaugurant la XVIIIe dynastie et le Nouvel Empire. L'avènement n'est pas la fin des Hyksôs, mais le début de la dernière phase de la lutte.", "a003c4aa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1649-01-01:0":{"b": ["L'Égypte se scinde en deux : les Hyksôs (XVe dynastie) gouvernent depuis Avaris la Basse et la Moyenne-Égypte, la XVIIe dynastie de Thèbes la Haute-Égypte", "cd743737"], "d": ["Les « souverains étrangers » (Hyksôs) d'origine cananéenne, installés à Avaris dans le Delta oriental, fondèrent la XVe dynastie et gouvernèrent la Basse-Égypte et la Moyenne-Égypte jusqu'à Cusae (Kousae) ; la XVIIe dynastie indigène de Thèbes tenait la Haute-Égypte. Au sud de Thèbes, le royaume de Kerma se dressait comme puissance indépendante. Le fait qu'Avaris fut la capitale hyksôs est confirmé chez Breasted par le récit du siège d'Ahmosis.", "6bb8eb9b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1866-01-01:0":{"b": ["Sésostris III ramène à Semna la frontière sud de l'Égypte à la deuxième cataracte ; il interdit le passage aux Nubiens", "753ef5fd"], "d": ["La stèle de Semna de l'an 8 de Sésostris III fixe la « frontière sud » : il est interdit aux Nubiens, sauf à ceux qui viennent commercer à Iken, de franchir cette ligne par terre ou par le fleuve. Le roi établit en Basse-Nubie une chaîne de forteresses (Bouhen, Semna, Kumma, Ouronarti, etc.) et arrêta l'expansion de Kerma vers le nord. C'est la frontière durable la plus méridionale du Moyen Empire en Nubie.", "e50a591d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1984-01-01:0":{"b": ["Amenemhat Ier fonde la XIIe dynastie ; la capitale est transférée à Itjtaouy", "26c43dad"], "d": ["Amenemhat Ier, devenu roi alors qu'il était vizir, fonda la XIIe dynastie et transféra la capitale de Thèbes à une ville nouvelle (Itjtaouy) entre Memphis et le Fayoum. Cette dynastie établit la période la plus stable du Moyen Empire et le système de forteresses tourné vers la Nubie.", "55432fe0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2015-01-01:0":{"b": ["Montouhotep II vainc Héracléopolis et réunifie l'Égypte (Sémattaouy)", "dbc6136f"], "d": ["Vers la 39e année de son règne, Montouhotep II supprima Héracléopolis, plaça la Haute et la Basse-Égypte sous une seule administration et ajouta à sa titulature le nom de « celui qui unit les Deux Terres » (Sémattaouy). L'administration centrale fut transférée à Thèbes ; les pouvoirs des nomarques furent réduits.", "d3ad8b02"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2054-01-01:0":{"b": ["Montouhotep II monte sur le trône à Thèbes ; début du Moyen Empire, la guerre contre Héracléopolis s'intensifie", "edde038d"], "d": ["Le long règne de Montouhotep II (51 ans) est regardé comme le début du Moyen Empire. Dans la première moitié de son règne, Thèbes était en guerre avec Héracléopolis ; la 14e année, les forces héracléopolitaines ayant profané le cimetière sacré d'Abydos, le roi envoya une armée vers le nord. L'unification effective de l'Égypte n'eut lieu que bien plus tard, vers la 39e année de son règne (notice ci-dessous).", "5db4eeba"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2124-01-01:0":{"b": ["Début de la XIe dynastie à Thèbes : la dynastie des Antef fonde un royaume indépendant en Haute-Égypte", "0e021743"], "d": ["Les nomarques de Thèbes, issus de la lignée des Antef, prirent le titre royal et fondèrent leur propre royaume à l'extrémité sud de la Haute-Égypte (d'Éléphantine à Abydos). Un Antef suivant indique dans son inscription qu'il s'empara du nome de Thinis, où se trouve Abydos, et qu'il « ouvrit toutes ses forteresses » ; ainsi la frontière thébano-héracléopolitaine fut tracée autour d'Abydos.", "eddec482"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2159-01-01:0":{"b": ["IXe-Xe dynasties à Héracléopolis (Hénen-nésout) : la dynastie des Khéty gouverne l'Égypte du Nord", "9dde2d0c"], "d": ["À la Première Période intermédiaire, la dynastie d'Héracléopolis combla le vide laissé par Memphis ; des nomarques fidèles, tel Tefibi, gouverneur de Siout en Moyenne-Égypte, combattirent aux côtés de ce royaume contre le sud (Thèbes). L'inscription funéraire de Siout rapporte l'avance des gens du Sud vers le nord depuis Éléphantine et leur repoussement jusqu'à la « frontière sud ». L'Égypte se divisa ainsi en deux grandes puissances, Héracléopolis (Nord) et Thèbes (Sud).", "5e8484b5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2180-01-01:0":{"b": ["Effondrement de l'Ancien Empire : après Pépi II, l'État central se disloque, début de la Première Période intermédiaire", "0339e96b"], "d": ["Après le très long règne de Pépi II, la VIe dynastie prit fin ; le royaume se divisa en régions où les nomarques (gouverneurs de province) restaient de fait indépendants. Les inscriptions funéraires (Siout, Éléphantine, etc.) montrent que les gouverneurs locaux donnaient des dates en leur propre nom et mobilisaient leurs propres troupes. Les VIIe-VIIIe dynasties éphémères de Memphis ne purent contrôler tout le pays.", "67f3dd29"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2279-01-01:0":{"b": ["Expéditions du gouverneur d'Éléphantine Herkhouf au pays de Yam : lien diplomatique et commercial au-delà de la Nubie", "705b9808"], "d": ["Le gouverneur d'Éléphantine Herkhouf fit plusieurs expéditions vers le sud, au pays de Yam, pour Mérenrê et Pépi II ; son inscription décrit la route qu'il maîtrisait et les produits qu'il rapporta. La lettre que le roi enfant Pépi II lui écrivit est aussi conservée dans l'inscription funéraire. Ces expéditions sont les témoignages des contacts avec les communautés pré-Kerma et de l'ancien Kerma à la frontière sud de l'Ancien Empire.", "31a49890"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2299-01-01:0":{"b": ["Sous la VIe dynastie, grande expédition conduite par Ouni vers la frontière de Canaan avec des troupes nubiennes", "69c94c55"], "d": ["Selon l'autobiographie d'Ouni, le roi leva contre les « Asiatiques habitants des sables » une armée de dizaines de milliers d'hommes ; l'armée était composée de troupes recrutées en Haute-Égypte (jusqu'à Éléphantine), au Nord, et aussi chez les tribus nubiennes (Irtjet, Medjay, Yam, Ouaouat, Kaou). Le texte montre que l'Ancien Empire utilisait la Nubie comme réservoir de soldats et pouvait mener des campagnes jusqu'au sud de Canaan.", "4a1574fe"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2559-01-01:0":{"b": ["La Grande Pyramide de Houfou (Khéops) est construite à Gizeh", "282359fc"], "d": ["La pyramide de Houfou, souverain de la IVe dynastie, à Gizeh, est le symbole de la mobilisation de main-d'œuvre et de ressources de l'Ancien Empire. Le récit des prêtres égyptiens rapporté par Hérodote dépeint Houfou en tyran qui ferma les temples et contraignit le peuple à transporter la pierre ; en cela, c'est le regard de l'époque suivante et non un document contemporain.", "6bc26700"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2685-01-01:0":{"b": ["Djéser (IIIe dynastie) monte sur le trône ; Ancien Empire et pyramide à degrés de Saqqarah", "23e99ef4"], "d": ["L'Ancien Empire, centré sur Memphis, commence avec le pouvoir de Djéser (Netjerykhet) ; la pyramide à degrés, premier grand exemple d'architecture en pierre, fut édifiée pour lui. À cette époque, l'État administre depuis le centre la vallée du Nil et le Delta ; les mines du Sinaï et la frontière de Nubie (Éléphantine) sont sous le contrôle de l'État.", "3b6eb1c6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-3099-01-01:0":{"b": ["Narmer (Ménès) unifie la Haute et la Basse-Égypte ; Ire dynastie, Memphis devient capitale", "cd3fadb1"], "d": ["Narmer, souverain de Haute-Égypte (région de Thinis/Abydos), est selon la plupart des égyptologues la même personne que Ménès. En rattachant la Basse-Égypte à son gouvernement, la vallée du Nil et le Delta formèrent pour la première fois un seul État. Selon la tradition ancienne, Ménès fonda l'emplacement de Memphis en détournant le lit du Nil ; l'unification n'est pas un événement unique, mais le résultat d'un long processus se poursuivant depuis Nagada III.", "f5802ba8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0069-07-01:0":{"b": ["Vespasien est proclamé empereur à Alexandrie : le blé d'Égypte décida du sort de la guerre civile", "02b78348"], "d": ["Le préfet d'Égypte Tiberius Alexander fit prêter serment aux légions d'Alexandrie au nom de Vespasien ; le serment fut prêté le 1er juillet et Vespasien tint ce jour pour celui de son avènement. L'armée de Judée prêta serment deux jours plus tard en présence de Vespasien. La production de blé de l'Égypte est regardée comme l'appui stratégique de cette entreprise.", "da411a30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0115-01-01:0":{"b": ["Révolte juive en Égypte, à Cyrène et à Chypre : sous le règne de Trajan, Rome réprime la région à grand-peine", "54787782"], "d": ["Pendant la campagne parthe de Trajan, à Cyrène, les Juifs, sous la conduite d'Andréas, massacrèrent Romains et Grecs ; selon Dion, des événements semblables eurent lieu en Égypte et à Chypre, et le nombre des morts est exprimé en centaines de milliers. Lusius Quietus, envoyé par Trajan, réprima la révolte ; l'entrée des Juifs à Chypre fut interdite.", "40f5a14f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0172-01-01:0":{"b": ["Révolte des Boukoloi : un soulèvement dans le Delta menace Alexandrie, Avidius Cassius le réprime", "5f94e6bf"], "d": ["Les habitants du Delta appelés Boukoloi (bouviers) se soulevèrent sous la conduite d'un prêtre nommé Isidore ; selon Dion, les rebelles vainquirent une unité romaine et faillirent s'emparer d'Alexandrie. Cassius, envoyé de Syrie, désagrégea l'unité des rebelles et réprima le soulèvement.", "ab9f3aff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0175-01-01:0":{"b": ["Avidius Cassius se proclame empereur en Syrie et en Égypte ; il est tué trois mois plus tard", "ce33ca9d"], "d": ["Cassius, commandant des provinces orientales, proclama l'empire à la nouvelle de la mort de Marc Aurèle ; la révolte s'étendit à la Syrie et à l'Égypte (chez Dion, le gouverneur d'Égypte Flavius Calvisius, à cause de sa liaison avec la révolte, ne fut pas mis à mort par la suite mais exilé dans une île). Cassius, après un « rêve d'empire » de trois mois et six jours selon Dion, fut tué par l'un de ses propres officiers ; Marc Aurèle visita l'Égypte et la Syrie sans punir personne.", "d3821bc7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0270-01-01:0":{"b": ["Palmyre (Zénobie) envahit l'Égypte ; le général romain Probus est vaincu", "54568441"], "d": ["Zabdas, général palmyrénien agissant au nom de Zénobie, entra en Égypte avec une armée de soixante-dix mille hommes ; le général romain Tenagino Probus reprit un temps Alexandrie, mais, vaincu, il s'enferma dans la forteresse de Babylone et se suicida après avoir été fait prisonnier. L'Égypte fut regardée pendant un an ou deux comme faisant partie de l'État de Palmyre au nom de Zénobie.", "ea44ec63"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0297-01-01:0":{"b": ["Domitius Domitianus est proclamé empereur en Égypte ; Dioclétien assiège Thèbes puis Alexandrie et réprime la révolte", "3c765005"], "d": ["En réaction à la réforme fiscale et au retrait des troupes romaines vers le front parthe, Domitius Domitianus fut proclamé Auguste en Égypte en juillet-août 297 ; la plus grande partie de l'Égypte, Alexandrie comprise, le reconnut. À l'automne, Dioclétien réprima les rebelles de Thèbes et assiégea Alexandrie ; Domitianus mourut en décembre 297, Aurelius Achilleus poursuivit la défense de la ville, et la cité se rendit, après un siège d'environ huit mois, très probablement en mars 298.", "8d6ec081"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0298-01-01:0":{"b": ["Dioclétien ramène la frontière sud de l'Égypte à la ligne Éléphantine/Philæ ; la Basse-Nubie est laissée aux Nobates", "725574bb"], "d": ["Procope raconte que Dioclétien, voyant le coût de la conservation du vaste désert le plus méridional de l'Égypte (Dodécaschène), laissa le sud d'Éléphantine aux Nobates et aux Blemmyes et fixa la frontière à Éléphantine (on rapporte aussi qu'un paiement annuel fut établi en contrepartie). L'administration romaine recula ainsi de la frontière de Hiera Sykaminos tracée par Auguste.", "bba78e53"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0349-01-01:0":{"b": ["Le roi d'Aksoum Ézana bat Koush ; fin du royaume de Méroé (vers 350 apr. J.-C.)", "7c9d95d7"], "d": ["Le royaume de Koush, affaibli par la pression des Noba et des Blemmyes, fut attaqué par le roi d'Aksoum Ézana ; les inscriptions d'Ézana relatent sa campagne contre les peuples Noba et Kasou (Koush), et deux inscriptions grecques fragmentaires relatives à la victoire d'Aksoum ont été trouvées à Méroé. Les dernières pyramides de Méroé sont datées du milieu du IVe siècle ; l'État de Koush se disloqua et se divisa en royaumes de Nobatie, de Makourie et d'Alodie.", "49687083"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0391-01-01:0":{"b": ["Théophile fait détruire le Sérapéum d'Alexandrie : le centre du culte païen en Égypte est fermé", "119a26c7"], "d": ["À la suite des édits de Théodose Ier interdisant les cultes païens, l'évêque d'Alexandrie Théophile fit détruire le temple de Sérapis (Sérapéum) ; la tension entre chrétiens et païens dans la ville atteignit son comble avec cet événement. Le sort des textes sacrés et des collections de livres est controversé.", "5128d07a"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0395-01-17:0":{"b": ["Mort de Théodose Ier ; l’Empire est définitivement partagé en deux, l’Égypte demeure dans l’Empire romain d’Orient (Arcadius)", "54a12472"], "d": ["À la mort de Théodose, ses fils Arcadius et Honorius reçoivent respectivement l’Orient et l’Occident ; bien qu’elle soit le principal fournisseur de blé de Rome, l’Égypte reste une province de l’Empire d’Orient (byzantin) et devient, aux siècles suivants, la source d’approvisionnement en grain de Constantinople.", "c418b085"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0451-10-08:0":{"b": ["Concile de Chalcédoine : Dioscore, patriarche d’Alexandrie, est condamné ; l’Église d’Égypte se sépare de l’Église impériale", "5d2d05c6"], "d": ["Lorsque le concile de Chalcédoine condamne Dioscore, patriarche d’Alexandrie d’Égypte, la plupart des chrétiens d’Égypte refusent d’accepter ses décisions ; l’Église copte (d’Égypte) et l’Église impériale (les melkites) se séparent ainsi. Cette division prépare, au cours des siècles suivants, l’éloignement politique de l’Égypte vis-à-vis de Byzance.", "0d1827cd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0019-01-01:0":{"b": ["Traité entre Auguste et Phraatès IV : restitution des enseignes romaines de Crassus", "be5f8bda"], "d": ["Les enseignes romaines perdues de Crassus et d’Antoine sont rendues à Auguste par Phraatès IV, en un geste diplomatique. Le traité consolide l’Euphrate comme frontière romano-parthe et laisse l’Arménie comme tampon.", "8cca70ad"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0039-01-01:0":{"b": ["Pacoros et Labiénus envahissent la Syrie et la Palestine", "68669aa1"], "d": ["Le prince parthe Pacoros et Labiénus, qui a fui Rome pour se réfugier chez les Parthes, envahissent les provinces romaines de Syrie, prennent Antioche et la Palestine. Ventidius, général d’Antoine, bat les Parthes à Gindaros en 38 et reconquiert la région.", "c3d65f7c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0052-01-01:0":{"b": ["Bataille de Carrhes (Harran) : Surénas anéantit l’armée romaine de Crassus", "3a91cd75"], "d": ["Les légions romaines de Crassus sont vaincues près de Harran par la cavalerie et les archers à cheval parthes ; Crassus est tué. Cette bataille est l’une des plus lourdes défaites de Rome en Orient et consolide la frontière de l’Euphrate en faveur des Parthes.", "3f9d31bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0091-01-01:0":{"b": ["Sylla rencontre sur l’Euphrate l’envoyé parthe Orobaze ; premier contact diplomatique romano-parthe", "f8913f2b"], "d": ["Sylla, gouverneur de Cappadoce, rencontre sur les rives de l’Euphrate Orobaze, envoyé du roi parthe Mithridate II ; Rome et les Parthes établissent pour la première fois un contact officiel. L’Euphrate deviendra plus tard la frontière des deux États.", "64f67e31"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0128-01-01:0":{"b": ["Antiochos VII Sidétès meurt en campagne contre les Parthes ; les Séleucides ne reprennent pas la Mésopotamie", "e5897112"], "d": ["Antiochos VII Sidétès reprend aux Parthes la Mésopotamie et la Médie en 130-129, mais perd son armée et sa propre vie à la suite d’une révolte pendant les quartiers d’hiver et d’une attaque parthe. Cet échec met fin aux prétentions séleucides en Orient.", "0ceb2108"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0137-01-01:0":{"b": ["Les Parthes capturent Démétrios II Nicator ; les Séleucides perdent définitivement Babylone et la Mésopotamie", "94a764ce"], "d": ["L’armée parthe de Mithridate Ier capture le roi séleucide Démétrios II et le retient à la cour parthe. Mithridate rattache la Mésopotamie à l’Empire parthe ; l’État séleucide, acculé à la côte, se replie sur la Syrie.", "d53eb877"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0166-01-01:0":{"b": ["Révolte des Maccabées : en Judée, soulèvement contre les interdits religieux d’Antiochos IV", "41c25b76"], "d": ["Lorsqu’Antiochos IV Épiphane dédie le Temple de Jérusalem à Zeus Olympien et interdit les pratiques religieuses juives, Mattathias et ses fils se soulèvent à Modin. Judas Maccabée reprend et purifie le Temple en 164 (Hanoukka) ; l’État hasmonéen naît.", "ad039b3f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0170-01-01:0":{"b": ["Mithridate Ier monte sur le trône parthe ; début de la période d’expansion de l’empire parthe", "cc77639b"], "d": ["Mithridate Ier transforme les Parthes en un empire : il prend la Médie (147), Babylone et Séleucie (141), et établit sa souveraineté sur l’Élymaïde et la Perside. Ctésiphon deviendra par la suite la capitale d’hiver.", "248f554a"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0187-01-01:0":{"b": ["Traité d’Apamée : les Séleucides se retirent à l’ouest du Taurus et paient une indemnité", "f5197a70"], "d": ["Le traité entre Rome et Antiochos III attribue aux alliés de Rome (Pergame, Rhodes) l’Anatolie à l’ouest du Taurus ; la flotte séleucide et le nombre d’éléphants sont limités, et une indemnité de 15 000 talents est payée. Les Séleucides deviennent désormais un État syro-mésopotamien.", "08e214af"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0204-01-01:0":{"b": ["Expédition orientale d’Antiochos III (209-204) : les rois parthe et bactrien sont soumis au tribut séleucide", "5c81f302"], "d": ["Antiochos III marche contre la Médie, les Parthes et la Bactriane pour reprendre les terres orientales perdues des Séleucides : Arsace II et Euthydème sont astreints au tribut. Après cette expédition, Antiochos prend le titre de « le Grand ».", "473faaed"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:0":{"b": ["Arsace Ier et Tiridate prennent Parthava et fondent l’État parthe (arsacide)", "2cd572ca"], "d": ["Arsace, chef de la tribu nomade des Parnes, renverse le satrape séleucide Andragoras, s’empare de Parthava et devient le premier roi du royaume parthe ; sa capitale est Hécatompylos. L’État parthe dominera la Mésopotamie et l’Iran pendant les trois siècles suivants.", "1fb67f39"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:1":{"b": ["Diodote, satrape de Bactriane, se détache des Séleucides ; naissance du royaume gréco-bactrien", "52faafa6"], "d": ["Diodote, satrape de Bactriane et de Sogdiane, profite de la faiblesse d’Antiochos II pour proclamer son indépendance. La Bactriane gréco-bactrienne oblige l’État séleucide à reculer sa frontière orientale de Parthava et de la Bactriane.", "ac02ccda"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0273-01-01:0":{"b": ["Première guerre de Syrie (274-272) : les forces séleucides reprennent Damas ; la paix est conclue", "0c17ee3d"], "d": ["Après avoir vaincu les Galates par la « bataille des éléphants » (275) et s’être mis en sécurité, Antiochos Ier combat de nouveau Ptolémée II : le général séleucide reprend Damas, Magas attaque l’Égypte, et la paix est enfin conclue en 272. Cette guerre marque le début de la rivalité ptolémaïco-séleucide pour la Cœlé-Syrie.", "20ab588f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0279-01-01:0":{"b": ["Guerre de Carie : Ptolémée II prend à Antiochos Ier l’Ionie, la Carie, la Lycie, la Pamphylie et une partie de la Cilicie", "afe190ca"], "d": ["Par une campagne brève et réussie, Ptolémée II prend les côtes sud et ouest de l’Anatolie et atteint Damas ; voyant qu’Antiochos n’est pas inférieur en force à son père, il conclut une trêve. Antiochos accepte la perte, car il devait organiser les conquêtes de son père à l’intérieur de l’Anatolie.", "868966e1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0280-01-01:0":{"b": ["Séleucos Ier est assassiné par Ptolémée Kéraunos ; Antiochos Ier monte sur le trône", "4703b674"], "d": ["Séleucos, qui avait vaincu Lysimaque à Couroupédion et pris l’Anatolie, est poignardé par Ptolémée Kéraunos alors qu’il passait en Europe. Son fils Antiochos Ier hérite de l’État, mais connaîtra des difficultés en Anatolie occidentale.", "18a3f3a5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0299-01-01:0":{"b": ["Séleucos Ier fonde Antioche (Antakya)", "f4b98967"], "d": ["Après Ipsos, Séleucos fonde en Syrie, sur les rives de l’Oronte, Antioche, du nom de son propre père ; la ville devient la capitale occidentale du royaume séleucide et l’une des plus grandes cités de l’Antiquité. Séleucie du Tigre avait été fondée auparavant comme capitale orientale.", "0ab29d65"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0300-01-01:0":{"b": ["Bataille d’Ipsos : Séleucos et Lysimaque battent Antigone ; la Syrie passe à Séleucos", "93bf2aa9"], "d": ["Dans la bataille décisive des guerres des Diadoques, Séleucos et Lysimaque battent Antigone (Antigone meurt au combat). L’ensemble de l’Orient et la Syrie échoient à Séleucos ; Ptolémée, lui, occupe la Cœlé-Syrie, posant la cause des premières guerres de Syrie.", "a2ab17a8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:0":{"b": ["Séleucos Ier fonde Séleucie sur le Tigre", "032efabd"], "d": ["Séleucos fonde Séleucie sur les rives du Tigre, près de Babylone, et commence à y transférer la population babylonienne. Avec environ 300 000 habitants, Séleucie devient la plus grande ville hellénistique d’Orient, puis la voisine de la capitale de l’empire parthe.", "a1aa43e3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:1":{"b": ["Séleucos Ier conclut un traité avec Chandragupta Maurya en Inde ; l’Arachosie, la Gédrosie et les Paropamisades sont cédées aux Maurya", "3ef3bdee"], "d": ["Séleucos marche vers l’Inde pour reprendre les satrapies indiennes d’Alexandre, mais s’accorde avec Chandragupta et échange une partie des terres orientales contre 500 éléphants de guerre. Le traité porte la frontière occidentale de l’Empire maurya jusqu’à l’Hindou Kouch et procure à Séleucos des éléphants pour l’Occident.", "95b2b8bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0309-01-01:0":{"b": ["Alexandre IV est tué avec sa mère Roxane ; fin de la dynastie argéade", "3be9d974"], "d": ["Après la paix de 311, sur ordre de Cassandre (le bourreau étant Glaucias selon Diodore), Alexandre IV, âgé de douze ans, et sa mère Roxane sont assassinés. L’Empire d’Alexandre n’a plus de souverain nominal ; les Diadoques se tournent vers la proclamation de leurs propres royaumes (306-305 av. J.-C.).", "46aa8fb2"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-01-01:0":{"b": ["Alexandre atteint Persépolis ; la ville et le trésor passent aux mains des Macédoniens", "c1dbaada"], "d": ["Après Suse, Alexandre franchit les Portes persiques et atteint Persépolis fin janvier 330 ; la ville se rend sans résistance. La possession achéménide de Persépolis prend fin cette année-là (le palais est incendié en mai 330).", "de8726c8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-01-01:1":{"b": ["Incendie des palais de Persépolis (avril)", "6e6cdfe0"], "d": ["En avril 330, Alexandre fait incendier plusieurs bâtiments palatiaux à Persépolis ; on invoque comme raisons que le trésor ne devait pas tomber aux mains de l’ennemi et qu’il n’était pas encore seul souverain. Il est établi archéologiquement que le palais de Xerxès a aussi brûlé ; la ville entière fut abandonnée.", "c22d037f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-07-01:0":{"b": ["Darius III est assassiné par les hommes de Bessos, satrape de Bactriane ; fin de la dynastie achéménide", "bedcca87"], "d": ["Darius III, qui avait fui Ecbatane vers l’est, est blessé puis abandonné en Parthie par Bessos et ses partisans en juillet 330, et meurt ; Alexandre envoie le corps à Persépolis. Fin de fait de l’Empire achéménide.", "dc8ceef3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-10-01:0":{"b": ["Bataille de Gaugamèles : Alexandre bat définitivement l’armée de Darius III", "a5b082d7"], "d": ["À Gaugamèles, l’armée de Darius, composée d’un grand nombre de chars de guerre et de cavaliers, est dispersée par une charge qu’Alexandre lance en perçant la défense de son aile gauche ; Darius s’enfuit de nouveau. La bataille scelle la fin de l’Empire perse ; Babylone et Suse ouvrent leurs portes.", "b31c6746"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-10-22:0":{"b": ["Alexandre entre à Babylone ; Mazaios livre la ville et la satrapie de Babylone passe à Alexandre", "c8d2afb3"], "d": ["Après Gaugamèles, Mazaios, satrape de Babylone, ouvre les portes à Alexandre ; celui-ci ordonne la restauration du temple de Marduk et séjourne 34 jours dans la ville. Babylone passe de la domination perse à la domination macédonienne.", "b84160e8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-12-15:0":{"b": ["Alexandre prend Suse ; le trésor perse est saisi", "fbf417db"], "d": ["Quittant Babylone, Alexandre entre à Suse ; le satrape Abulitès lui livre la ville et le grand trésor. Suse devient la base financière de la campagne orientale de la Macédoine.", "b65699b7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0331-01-01:0":{"b": ["Siège de Tyr : Alexandre prend la ville insulaire au moyen d’une jetée et la détruit", "89ede146"], "d": ["Alexandre prend en sept mois l’île de Tyr, base de la flotte perse, en construisant une chaussée artificielle ; la ville est pillée, et la plus grande partie de sa population est tuée ou réduite en esclavage. La puissance navale perse s’effondre ainsi et la route de l’Égypte s’ouvre.", "22842728"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0332-11-01:0":{"b": ["Bataille d’Issos : Alexandre bat Darius III ; Darius abandonne sa famille et s’enfuit", "3803fc30"], "d": ["Dans une étroite plaine côtière, la grande armée de Darius III est vaincue par Alexandre ; le roi perse s’enfuit en abandonnant sa famille et son trésor. La victoire d’Issos livre à Alexandre la Syrie et la côte phénicienne, puis l’Égypte.", "a711a81e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0333-01-01:0":{"b": ["Bataille du Granique : Alexandre bat les satrapes perses", "1aae30d4"], "d": ["Le roi de Macédoine Alexandre passe en Asie en mai 334 et bat les satrapes perses au Granique début juin. Les portes de l’Anatolie occidentale s’ouvrent ; Sardes et les cités d’Ionie se rendent à Alexandre.", "8cc08bd9"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0335-01-01:0":{"b": ["Darius III monte sur le trône perse (assassinat d’Arsès)", "706f8a9f"], "d": ["Le courtisan Bagoas assassine Artaxerxès IV ; Artašata, satrape d’Arménie, devient roi sous le nom de Darius III (Codoman). En octobre 336, Philippe est assassiné en Macédoine et Alexandre monte sur le trône.", "c082bdae"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0337-01-01:0":{"b": ["Mort d’Artaxerxès III ; Artaxerxès IV (Arsès) monte sur le trône", "d38e2edc"], "d": ["Artaxerxès III meurt de cause naturelle à l’été 338 (malgré le récit d’empoisonnement de Diodore) ; Arsès monte sur le trône. Les révoltes d’Égypte et de Babylone et les préparatifs de Philippe, roi de Macédoine, en Anatolie coïncident avec la même période.", "09f24497"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0344-01-01:0":{"b": ["Artaxerxès III prend et détruit Sidon ; la révolte de Tennès est réprimée", "d1b533cc"], "d": ["Lors de la révolte antiperse de Tennès, roi de Sidon, soutenue par l’Égypte, Artaxerxès III s’empare de la ville ; Tennès trahit les Perses, la ville s’incendie elle-même et de nombreuses personnes périssent. Les cités phéniciennes repassent sous le contrôle perse et la voie de la conquête de l’Égypte est ouverte.", "050b8e4e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0386-01-01:0":{"b": ["Paix du Roi (Antalcidas) : les cités grecques d’Anatolie et Chypre sont abandonnées aux Perses", "17e871ad"], "d": ["Par la paix dictée par le roi perse Artaxerxès II, les cités grecques d’Asie et Chypre sont considérées comme perses, et l’autonomie est reconnue aux cités grecques. Sparte applique la paix en tant que porte-parole de la Perse.", "7bf00868"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0400-01-01:0":{"b": ["Bataille de Counaxa : Cyrus le Jeune est vaincu par son frère Artaxerxès II et meurt", "90346087"], "d": ["Cyrus le Jeune marche sur Babylone avec les Dix-Mille, mercenaires grecs, est vaincu à Counaxa par son frère Artaxerxès II et meurt au combat. La marche de retour des Dix-Mille vers la mer Noire est racontée dans l’Anabase de Xénophon.", "664d8d4f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:0":{"b": ["Xerxès franchit l’Hellespont ; les Thermopyles et la prise d’Athènes", "9bf22df1"], "d": ["Avec sa grande armée, Xerxès bat aux Thermopyles la troupe spartiate et alliée de Léonidas et pénètre en Attique ; Athènes est évacuée puis incendiée avec l’Acropole. L’armée perse avance jusqu’au centre de la Grèce.", "3b81a962"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:1":{"b": ["Bataille navale de Salamine : la flotte grecque met en déroute la flotte perse", "010e3aab"], "d": ["La flotte grecque, commandée par Thémistocle, bat la flotte perse dans le détroit de Salamine et conquiert la supériorité navale. Xerxès repart pour l’Asie avec la majeure partie de l’armée de terre, Mardonios reste en Grèce.", "f55ed3ca"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0483-01-01:0":{"b": ["Les révoltes de Bêl-šimânni et de Šamaš-eriba à Babylone sont réprimées par Xerxès Ier", "ebcef5a9"], "d": ["Au début du règne de Xerxès Ier, deux révoltes éclatent à Babylone (Bêl-šimânni, Šamaš-eriba). Xerxès les réprime ; il divise la satrapie de Babylone et réduit les privilèges de la ville.", "015c253c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0493-01-01:0":{"b": ["Bataille navale de Ladé : la flotte perse bat la flotte ionienne ; Milet tombe", "86396cf1"], "d": ["La flotte perse, à dominante phénicienne, met en déroute la flotte ionienne à Ladé ; Milet est assiégée et détruite, et sa population déportée en Mésopotamie. La révolte d’Ionie prend fin et l’Ionie repasse sous contrôle perse.", "b72ba00d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0497-01-01:0":{"b": ["Les Ioniens incendient Sardes", "adf677bd"], "d": ["Les Ioniens et les troupes athéniennes et érétriennes marchent sur Sardes, siège de la satrapie perse, et incendient la ville. Darius décide dès lors de punir Athènes ; l’événement est la raison de l’expédition de Marathon.", "32e33dce"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0498-01-01:0":{"b": ["Début de la révolte d’Ionie : l’expédition d’Aristagoras contre Naxos ayant échoué, les cités grecques d’Ionie se soulèvent contre les Perses", "aab8ff2f"], "d": ["L’expédition d’Aristagoras, tyran de Milet, contre Naxos s’étant effondrée, les cités d’Ionie renversent leurs tyrans et demandent l’aide d’Athènes et d’Érétrie. Cette révolte est la mèche des guerres médiques.", "7d70c2ee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0512-01-01:0":{"b": ["Darius franchit l’Istros (Danube) et part en expédition contre les Scythes ; la Thrace est rattachée à la satrapie perse", "a5891101"], "d": ["Darius passe en Thrace par un pont sur le Bosphore, soumet les Gètes, franchit le Danube et part en campagne contre les Scythes. Bien qu’il ne puisse vaincre les Scythes, Mégabaze rattache la Thrace et la côte de Macédoine à la souveraineté perse.", "f464fbf8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0520-05-08:0":{"b": ["L’armée de Darius bat Fravartiš (Phraortès), le rebelle mède", "4a9c4633"], "d": ["L’armée de Fravartiš, qui s’était proclamé roi en Médie en se disant de la descendance de Cyaxare, est vaincue ; Fravartiš, en fuite, est capturé à Ragai (près de Téhéran) et mis à mort sous la torture. La Médie redevient une province perse.", "efea5aea"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0520-12-28:0":{"b": ["Le général de Darius bat Frada, le rebelle de Margiane ; le dernier grand soulèvement est réprimé", "76e0ea1c"], "d": ["Dâdarši, satrape de Bactriane, marche sur 300 km à travers le désert du Karakoum et bat Frada, le rebelle de Margiane, le 28 décembre 521. Au cours de la première année du règne de Darius, tous les soulèvements ont été réprimés en dix-neuf batailles.", "5c0c9cfa"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-03-11:0":{"b": ["Gaumata (Bardiya) s’empare du trône perse ; Cambyse meurt à son retour d’Égypte", "1606d9c1"], "d": ["Selon l’inscription de Behistun, le prêtre Gaumata, se proclamant Bardiya (Smerdis), fils de Cyrus, monte sur le trône en mars 522 ; Cambyse meurt en Syrie. Darius et six nobles tuent Gaumata le 29 septembre 522.", "f143e726"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-09-29:0":{"b": ["Darius et six nobles tuent Gaumata ; Darius Ier monte sur le trône perse", "08897d54"], "d": ["Darius, avec six nobles compagnons, tue le faux Bardiya dans la forteresse de Sikayauvati, en Médie. La mort de Gaumata déclenche des soulèvements en de nombreux endroits de l’empire ; Darius les réprime en dix-neuf batailles en un an.", "daebf974"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-12-18:0":{"b": ["Darius reprend Babylone ; Nidintu-Bêl (Nabuchodonosor III) est capturé et mis à mort", "365cdd51"], "d": ["À la mort de Gaumata, Nidintu-Bêl se proclame fils de Nabonide et Nabuchodonosor III, et détache Babylone des Perses. L’armée de Darius traverse le Tigre le 13 décembre sur des outres gonflées et met en déroute l’armée rebelle ; Babylone est reprise le 18 décembre et Nidintu-Bêl est tué. La révolte élamite de Suse est réprimée à ce moment.", "4bd29dc6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0529-01-01:0":{"b": ["Mort de Cyrus ; son fils Cambyse monte sur le trône", "de69f4d5"], "d": ["Cyrus meurt au combat au pays des Massagètes selon Hérodote (selon Xénophon, il meurt dans son palais) ; la nouvelle de sa mort atteint Babylone en décembre 530 et les documents sont datés de « la première année de Cambyse ». Cambyse étend l’empire par la conquête de l’Égypte.", "9900a295"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0537-01-01:0":{"b": ["Édit de Cyrus : les Juifs exilés à Babylone peuvent retourner à Jérusalem, la reconstruction du Temple est autorisée", "715eac6b"], "d": ["Après avoir pris Babylone, Cyrus renvoie les statues divines des peuples déportés et leur permet de retourner chez eux (Cylindre de Cyrus). La Torah (Esdras 1:1-4) rapporte aussi cet édit à propos des Juifs : les exilés peuvent retourner à Jérusalem et rebâtir le Temple. La région devient la satrapie perse de « Yehud ».", "a8c7f81c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0537-01-01:1":{"b": ["Les cités-États phéniciennes (Tyr, Sidon, Byblos) acceptent la domination perse ; elles deviennent le noyau de la flotte perse", "d9f7f277"], "d": ["Avec la chute de Babylone, la côte phénicienne passe sous domination perse au sein de la satrapie « Au-delà du Fleuve » (Ebir-Nari). Les flottes phéniciennes deviennent l’épine dorsale de la puissance navale perse ; Sidon et Tyr conservent un droit d’administration interne privilégié.", "bb0c17fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-01-01:0":{"b": ["Bataille d’Opis : Cyrus bat l’armée babylonienne sur les rives du Tigre", "d91708c6"], "d": ["Les Perses de Cyrus affrontent et battent l’armée akkadienne à Opis, sur le Tigre ; la population babylonienne se replie, on pille et massacre. La bataille ouvre la voie à la chute de Babylone deux semaines plus tard.", "20739fbd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-10:0":{"b": ["Sippar passe aux Perses sans combat ; Nabonide s’enfuit", "47f6d3a5"], "d": ["Après la bataille d’Opis, le 14 Tašritu, Sippar tombe aux mains de Cyrus sans combat, et Nabonide s’enfuit. Les Perses entreront à Babylone deux jours plus tard.", "5a23a85c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-12:0":{"b": ["L’armée perse commandée par Gobryas (Ugbaru) entre à Babylone sans combat ; fin de l’empire néo-babylonien", "f67bf0e3"], "d": ["Ugbaru (Gobryas), gouverneur du Gutium, et l’armée de Cyrus entrent à Babylone le 16 Tašritu sans combat ; Nabonide est capturé. Les rites ne furent pas interrompus à l’Esagila. Cyrus entre dans la ville le 3 Arahsamnu (29 octobre) et l’empire babylonien passe sous domination perse.", "891c267b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-29:0":{"b": ["Cyrus entre à Babylone ; le contrôle de Babylone passe aux Achéménides et Gobryas est nommé gouverneur", "fd45fa83"], "d": ["Cyrus entre à Babylone le 3 Arahsamnu ; il salue la population de la ville et fait de Gubaru (Gobryas) le gouverneur de la ville. Les statues des dieux akkadiens que Nabonide avait rassemblées dans la ville sont remises à leur place en Kislîmu-Addaru. Son fils Cambyse participe, en qualité de prince héritier, au rituel de Nabû.", "17d2bc46"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0546-01-01:0":{"b": ["Crésus franchit l’Halys et prend Ptéria ; la bataille de Ptéria contre Cyrus s’achève sans vainqueur", "eee7aef1"], "d": ["Fort de l’oracle de Delphes, Crésus franchit l’Halys, assiège Ptéria et chasse les Syriens de Cappadoce. La sanglante bataille livrée contre Cyrus restant sans résultat, Crésus retourne à Sardes et rassemble des armées alliées ; Cyrus, par une campagne soudaine, le bat à Thymbrée et Sardes tombe.", "419ac6ed"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0551-01-01:0":{"b": ["Nabonide s’installe dans l’oasis de Tayma (Arabie) et ne vient pas à Babylone ; la fête de l’Akitu ne peut avoir lieu", "2ce93701"], "d": ["Tandis que Nabonide séjourne dans l’oasis de Tayma, le prince héritier Balthazar attend avec l’armée en Akkad ; le roi ne venant pas au mois de Nisan, Marduk n’entre pas à Babylone et la fête du Nouvel An (Akitu) ne peut être célébrée. Ce fut l’une des raisons pour lesquelles les prêtres des temples ont soutenu Cyrus contre Nabonide.", "d1e857db"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0555-01-01:0":{"b": ["Nabonide monte sur le trône de Babylone par un coup d’État", "b7ab73ce"], "d": ["Après la mort de Nabuchodonosor (562) étaient venus Amel-Marduk, Neriglissar (559-556) et Labaši-Marduk, au règne bref ; bien qu’il ne fût pas de lignée royale, Nabonide fit un coup d’État en 556. Son attachement particulier au dieu-lune Sîn mécontenta les prêtres de Marduk.", "6b2f9204"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0559-01-01:0":{"b": ["Crésus monte sur le trône de Lydie ; il rend tributaires Éphèse et les cités grecques d’Ionie", "5544cfa4"], "d": ["Après la mort de son père Alyatte, Crésus rend tributaire Éphèse, puis les autres cités grecques d’Ionie, d’Éolide et de Carie. La Lydie est la seule unité politique de l’Anatolie occidentale jusqu’à l’Halys ; le trésor de Crésus et ses offrandes à Delphes sont devenus légendaires.", "88136bde"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0584-01-01:0":{"b": ["Bataille de l’Halys (Kızılırmak) : à la suite d’une éclipse de soleil, Alyatte et Cyaxare font la paix ; l’Halys devient la frontière lydo-mède", "9ababdd3"], "d": ["La guerre de cinq ans entre Alyatte et Cyaxare, roi des Mèdes, s’achève par la paix à la suite d’une éclipse de soleil survenue en plein jour ; Syennésis, roi de Cilicie, et « Labynétos », roi de Babylone, jouent le rôle de médiateurs. Le fleuve Halys devient la frontière des deux royaumes et la Médie est considérée comme étendue jusqu’à l’intérieur de l’Anatolie.", "ddab1c12"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0585-01-01:0":{"b": ["Nabuchodonosor commence le siège de Tyr ; le siège dure treize ans", "5b753ca0"], "d": ["Selon Flavius Josèphe (Contre Apion 1.156), Nabuchodonosor assiégea Tyr treize ans, du temps du roi Ithobaal. La ville finit par un arrangement de paix ou de vassalité ; Tyr entre dans l’orbite babylonienne, tandis que l’administration indépendante de la cité insulaire se poursuit.", "0975583d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0585-01-01:1":{"b": ["Jérusalem est détruite, le Temple de Salomon brûle ; fin du royaume de Juda, le peuple est déporté à Babylone", "c9f78b2a"], "d": ["À la suite de la révolte de Sédécias contre Babylone, Nabuchodonosor prend Jérusalem pour la seconde fois et l’incendie ; le Temple est détruit et la plus grande partie du peuple est déportée à Babylone (captivité de Babylone). L’existence de Juda comme État indépendant prend fin.", "f53414ac"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0596-03-16:0":{"b": ["Nabuchodonosor prend Jérusalem ; le roi Joaquin est emmené captif, Sédécias lui succède", "55b14c31"], "d": ["L’armée babylonienne assiège la « ville de Juda » et la prend le 2 Addaru ; le roi Joaquin est fait prisonnier et emmené à Babylone, et Sédécias (Mattanya), choisi par Babylone, est mis à sa place. La ville passe pour la première fois sous la souveraineté babylonienne.", "12a9d088"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0599-01-01:0":{"b": ["Les forteresses d’Urartu sont détruites et incendiées ; l’État s’effondre", "6be90688"], "d": ["La couche d’incendie observée dans des forteresses telles que Karmir-blur indique qu’avant 600 av. J.-C. une invasion scythe/cimmérienne, les Mèdes ou un autre ennemi ont détruit Urartu. Les sources assyriennes ayant cessé, la date est incertaine après le dernier roi, Rusa III ; Urartu devint un peu plus tard une satrapie achéménide (Arménie).", "1e7ff200"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0603-12-01:0":{"b": ["Nabuchodonosor II prend Ascalon, capture son roi et réduit la ville en ruines", "7429839d"], "d": ["La première année de Nabuchodonosor, « tous les rois du pays de Hatti » lui apportèrent le tribut ; seule Ascalon résista. La ville fut prise au mois de Kislîmu, le roi fut capturé et la ville fut transformée en tertre de ruines.", "a455db32"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0604-09-07:0":{"b": ["Mort de Nabopolassar, Nabuchodonosor II monte sur le trône de Babylone", "bce88c5a"], "d": ["Nabopolassar, roi de Babylone, meurt le 8 Abu (15 août 605) au terme d’un règne de 21 ans ; Nabuchodonosor, vainqueur à Karkemish, retourne au pays et s’assoit sur le trône le 1er Ulûlu (7 septembre 605). Quatre années de campagnes rattachent à Babylone le pays de Hatti (Syrie-Palestine).", "b519ffaa"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0609-01-01:0":{"b": ["Harran tombe ; Aššur-uballit II se replie vers l’Égypte", "b2d122c2"], "d": ["Après la chute de Ninive, Aššur-uballit II, dernier roi d’Assyrie, s’était replié à Harran ; quand les Mèdes et les Babyloniens marchent sur Harran, les troupes assyriennes et égyptiennes abandonnent la ville et se retirent au-delà de l’Euphrate. Nabopolassar prend Harran et la pille.", "cb81464b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0609-01-01:1":{"b": ["Alyatte monte sur le trône de Lydie ; il chasse les Cimmériens d’Anatolie et étend le royaume", "160e291d"], "d": ["Au cours de son long règne, Alyatte nettoie l’Anatolie occidentale des Cimmériens et fait la guerre à Milet ; il porte les frontières du royaume jusqu’au centre de l’Anatolie, où il rencontre la Médie sur l’Halys.", "54aee50b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0613-01-01:0":{"b": ["Cyaxare et Nabopolassar concluent un traité d’alliance devant Assur", "650f0e5a"], "d": ["Nabopolassar, roi de Babylone, arrivé en retard lors de la prise d’Assur par les Mèdes, rencontre le roi des Mèdes près de la ville et conclut une alliance. Selon Bérose, le lien fut renforcé par le mariage de Nabuchodonosor avec Amytis, fille de Cyaxare.", "450ae215"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0624-01-01:0":{"b": ["Cyaxare (Umakištar) monte sur le trône de Médie", "67896ea0"], "d": ["Selon la tradition d’Hérodote, Cyaxare régna quarante ans, unifia la Médie et partit en campagne contre l’Assyrie. L’alliance avec Babylone (614) et la prise de Ninive (612) relèvent de son règne ; la Médie atteignit alors ses frontières les plus larges.", "4094aac8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0630-01-01:0":{"b": ["Mort d’Assurbanipal ; en Assyrie, début de la querelle de succession et du soulèvement de Babylone", "dbe19d8c"], "d": ["La mort d’Assurbanipal laisse l’Assyrie divisée entre deux héritiers. Les gouverneurs de Babylone se révoltent contre Sîn-šum-lišir et Sîn-šar-iškun ; l’effondrement de l’empire commence en dix ans.", "9537e9f3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0644-01-01:0":{"b": ["Assurbanipal détruit Suse ; le royaume néo-élamite s’effondre", "cb341293"], "d": ["En châtiment de la révolte de l’Élam contre l’Assyrie avec Babylone, Assurbanipal prend et ravage Suse, détruit les temples et emporte les statues des dieux à Ninive. L’Élam passe sous l’influence perse/anshanite sous forme de principautés semi-indépendantes.", "327f1322"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0647-01-01:0":{"b": ["Babylone se soumet à Assurbanipal après la révolte de Šamaš-šuma-ukin", "d6964932"], "d": ["Šamaš-šuma-ukin, frère d’Assurbanipal et roi de Babylone, se révolte contre l’Assyrie en 652 ; ses alliés élamites et arabes lui apportent un soutien temporaire. La guerre, qui dure quatre ans, s’achève par la chute de Babylone et Šamaš-šuma-ukin meurt.", "b038173f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0651-01-01:0":{"b": ["Les Cimmériens pillent Sardes ; Gygès meurt", "950e5f80"], "d": ["Après Gordion (696/695), l’invasion cimmérienne atteint aussi la Lydie et pille la ville basse de Sardes. Les sources assyriennes rapportent que Gugu (Gygès), roi de Lydie, cherchait l’aide assyrienne contre les Cimmériens ; Gygès mourut pendant ou après ces guerres.", "93736177"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0652-01-01:0":{"b": ["Bataille de Til-Tuba/Ulaï : Assurbanipal bat et tue Teumman, roi d’Élam", "177e87cf"], "d": ["Assurbanipal bat et tue Teumman, roi d’Élam, sur les rives de l’Ulaï (Karun/Karkheh), près de Suse ; sa tête est portée à Ninive. La bataille prépare la fin du rôle joué par l’Élam dans la rivalité assyro-babylonienne.", "3aa28a86"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0663-01-01:0":{"b": ["Assurbanipal pille Thèbes", "179269c7"], "d": ["Après la mort d’Assarhaddon, la révolte koushite en Égypte s’étant ranimée avec Tanoutamon, Assurbanipal entre en Haute-Égypte et pille Thèbes. L’Assyrie eut du mal à tenir réellement l’Égypte et s’en retira en peu de temps.", "c292bcf0"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0676-01-01:0":{"b": ["Assarhaddon détruit Sidon et la refonde sous le nom de Kar-Assarhaddon", "bd713ae6"], "d": ["Lorsque Abdi-Milkutti, roi de Sidon, se révolte contre l’Assyrie, Assarhaddon détruit la ville, fait décapiter le roi et fonde à la place de la ville un centre de province assyrien nommé Kar-Assarhaddon (« le port d’Assarhaddon »).", "2a506319"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0684-01-01:0":{"b": ["Gygès renverse Candaule et fonde la dynastie des Mermnades", "37e46a38"], "d": ["Selon Hérodote, Gygès, alors garde du palais, renverse le roi Candaule, s’empare du trône de Lydie et fonde la dynastie des Mermnades. Après l’effondrement de la Phrygie sous l’attaque cimmérienne, la Lydie commence à devenir la principale puissance de l’Anatolie occidentale.", "e477b6b5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0688-01-01:0":{"b": ["Sennachérib détruit Babylone, pille les temples et y lâche l’Euphrate", "82265d98"], "d": ["À la suite des révoltes répétées de Babylone, Sennachérib prend la ville et la détruit, emporte la statue de Marduk et fait couler dans la ville l’eau des canaux. Babylone resta en ruines un demi-siècle, jusqu’à sa restauration par Assarhaddon ; la destruction est le geste le plus dur de la politique assyrienne à l’égard de Babylone.", "e4312fee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0700-01-01:0":{"b": ["Sennachérib envahit Juda ; il prend Lakish et assiège Jérusalem", "dc11fa2d"], "d": ["Sennachérib, qui réprime la révolte d’Ézéchias contre l’Assyrie, prend quarante-six villes de Juda, conquiert Lakish et assiège Jérusalem. Ézéchias sauve la ville en payant un lourd tribut ; les reliefs de Lakish à Ninive représentent cette campagne.", "ebc2ce02"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0700-01-01:1":{"b": ["Sennachérib prend Sidon ; le roi Luli s’enfuit à Chypre", "41bb1358"], "d": ["En 701, Sennachérib soumet les cités phéniciennes : Luli (Elulaios), roi de Sidon, s’enfuit à Chypre, et les villes dépendantes de Sidon et de Tyr passent à l’Assyrie. Avant la campagne de Juda, la côte occidentale fut assurée par ces conquêtes.", "3b2c6518"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0704-01-01:0":{"b": ["Sargon II meurt au combat à Tabal ; Sennachérib monte sur le trône", "2f6ae581"], "d": ["Sargon II meurt, en Anatolie, au cours d’une campagne contre Gurdi, roi de Tabal, et son corps ne put être récupéré. Son fils Sennachérib transfère sa cour à Ninive ; la ville de son père, Dur-Sharrukin, est abandonnée et de nombreuses provinces se soulèvent.", "21ee2771"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0711-01-01:0":{"b": ["Sargon II prend Malatya (Mélid) ; Gunzinanu est déporté", "3ef6a5c9"], "d": ["Gunzinanu, roi de Mélid (Malatya), est vaincu par Sargon pour avoir collaboré avec Tabal et Urartu, et son royaume devient une province assyrienne. La domination néo-hittite sur l’est de l’Anatolie prend ainsi fin.", "281f75fd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0713-01-01:0":{"b": ["Sargon II entre en Urartu : Rusa Ier est vaincu, Musasir est pillée et la statue de Haldi emportée", "38992d24"], "d": ["La huitième campagne de Sargon ravage Urartu à partir des abords du lac d’Ourmia ; le temple de Haldi à Musasir est pillé. Le roi Rusa Ier, devant l’ampleur de la défaite, se donne la mort (selon la tradition). Urartu ne put plus jamais tenter de grande entreprise contre l’Assyrie.", "7d05af4c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0716-01-01:0":{"b": ["Sargon II prend Karkemish ; le royaume de Pisiris devient une province assyrienne", "cfcc3ee4"], "d": ["Pisiris, roi de Karkemish, tenta de former une alliance avec Midas (Mita) contre l’Assyrie ; Sargon prend la ville et procède à des déportations. L’indépendance d’un siècle et demi de Karkemish prend fin, et la frontière de l’Euphrate passe à l’Assyrie.", "87f1f2e6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0719-01-01:0":{"b": ["Sargon II bat Hama (Hamath), tue Yau-bidi à Qarqar et fait du royaume une province", "aeca8edc"], "d": ["Yau-bidi, roi de Hamath, était à la tête de la coalition syro-palestinienne formée contre Sargon ; Sargon le bat à Qarqar et détruit la ville, et Hamath est transformée en province assyrienne.", "70e2d509"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0732-01-01:0":{"b": ["Teglath-Phalasar III prend la Galilée et Galaad à Israël et en fait des provinces assyriennes", "0b59ead2"], "d": ["Lorsque l’Israël de Péqah se dresse contre l’Assyrie avec Damas, Teglath-Phalasar III transforme le nord d’Israël (Galilée, Galaad, environs de Megiddo) en provinces assyriennes et procède à des déportations ; Osée remplace Péqah. Le royaume d’Israël est réduit à Samarie et à la région montagneuse environnante.", "28d3a30e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0733-01-01:0":{"b": ["Teglath-Phalasar III prend Gaza ; la côte palestinienne passe sous contrôle assyrien", "1c89131f"], "d": ["Teglath-Phalasar se tourne vers la bande côtière de Palestine, fait fuir en Égypte Hanunu, roi de Gaza, et soumet la ville à son autorité. Les cités-États de Palestine deviennent, dans les années suivantes, une bande vassale de l’Assyrie.", "ff623a4d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0742-01-01:0":{"b": ["Teglath-Phalasar III bat près d’Arpad Sarduri II, roi d’Urartu", "7478a232"], "d": ["La tentative de Sarduri II de pousser les États syriens vers l’indépendance se solde par la victoire de Teglath-Phalasar III. Urartu perd son influence en Syrie ; l’Assyrie ne laisse aucun rival pour l’Anatolie et la Syrie.", "b851f23b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0744-01-01:0":{"b": ["Teglath-Phalasar III monte sur le trône ; le système provincial assyrien est mis en place", "b5889059"], "d": ["Teglath-Phalasar III, qui accède au trône par une révolte à Kalhu, établit le système provincial en remplaçant les royaumes vassaux par des gouverneurs assyriens ; il lie Babylone à lui par union personnelle et mène des campagnes contre Damas, Gaza et Israël. C’est de là que vient le système d’administration utilisé par les empires suivants (babylonien, perse, séleucide).", "7deb8187"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0795-01-01:0":{"b": ["Adad-nirari III bat Mari, roi de Damas, et reçoit le tribut", "3e01dbfa"], "d": ["Adad-nirari III bat Mari (Bar-Hadad), roi de Damas, et reçoit un lourd tribut ; la puissance intérieure d’Aram-Damas s’affaiblit et Israël respire un temps.", "c5c0a66d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0809-01-01:0":{"b": ["Minua étend Urartu du lac de Van à la vallée de l’Araxe et au lac d’Ourmia", "d77231e4"], "d": ["Sous Minua et son fils Argišti Ier, Urartu devient un royaume qui couvre tout le haut pays, du lac de Van aux abords de l’Araxe et du lac d’Ourmia. Touchpa (Van) est agrandie par de nouvelles installations et des travaux d’irrigation.", "289fc554"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0839-01-01:0":{"b": ["Mesha, roi de Moab, proclame son indépendance vis-à-vis d’Israël (stèle de Mesha)", "e9c264b2"], "d": ["La stèle de Mesha raconte la libération du roi de Moab, Mesha, de la tutelle d’Israël et ses victoires contre la dynastie d’Omri. La Torah et la stèle montrent ensemble la période d’affaiblissement de la dynastie d’Omri.", "ffefe5fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0840-01-01:0":{"b": ["Salmanasar III bat Hazaël et assiège Damas ; Jéhu, roi d’Israël, paie le tribut", "93aacc56"], "d": ["Salmanasar III bat Hazaël, roi d’Aram-Damas, sur le mont Sanir (Hermon) et assiège Damas ; Jéhu, roi d’Israël, est représenté sur l’Obélisque noir en train d’offrir le tribut à l’Assyrie. La coalition de Qarqar se dissout et l’Assyrie devient la puissance dominante à l’ouest.", "2992ec0c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0852-01-01:0":{"b": ["Bataille de Qarqar : Salmanasar III affronte la coalition de Damas, Hamath et Israël", "9a736e92"], "d": ["Salmanasar III combat à Qarqar une coalition de douze rois, dont Hadad-ézer (Adad-idri), roi de Damas, Irhuleni, roi de Hamath, et Akhab, roi d’Israël. Bien que les documents assyriens revendiquent la victoire, il dut renoncer à son avancée ; la coalition arrêta l’Assyrie pendant des années.", "524874c7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0857-01-01:0":{"b": ["Salmanasar III lance des campagnes contre Urartu (Arame) ; Urartu apparaît pour la première fois dans les sources assyriennes", "375ce993"], "d": ["Dans les premières années de son règne, Salmanasar III marche sur les terres d’Urartu du roi Arame ; les annales assyriennes mentionnent pour la première fois lors de ces campagnes Urartu sous le nom de « pays d’Urartu ». C’est la première mention datée de l’État qui sera, dans les siècles suivants, le principal rival de l’Assyrie dans cette région.", "759a75b7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0876-01-01:0":{"b": ["Assurnasirpal II franchit l’Euphrate et reçoit le tribut de Karkemish et des États néo-hittites/araméens", "5e385948"], "d": ["Lors de sa campagne vers l’ouest, Assurnasirpal II franchit l’Euphrate, atteint Karkemish, Patina et la côte phénicienne et collecte le tribut. Cette campagne marque le début du processus de rattachement à l’Assyrie des cités-États néo-hittites et araméennes.", "8432c2ea"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0878-01-01:0":{"b": ["Assurnasirpal II fait de Kalhu (Nimroud) la nouvelle capitale de l’Assyrie", "fbb17248"], "d": ["Assurnasirpal II transforme Kalhu, une petite bourgade, en une grande capitale avec 47 000 ouvriers ; dans cette ville six fois plus vaste qu’Assur, on construit le palais du nord-ouest. Kalhu reste la capitale de l’Assyrie jusqu’en 706.", "5a0f00b6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0879-01-01:0":{"b": ["Omri fait de Samarie la capitale, prend Moab", "e060c4b7"], "d": ["Omri fonde le premier véritable État d’Israël : il conquiert la Transjordanie (Moab compris), renforce les forteresses frontalières et fait de Samarie la nouvelle capitale. Son fils Akhab épouse Jézabel, fille d’Ethbaal, roi de Sidon, et lie ainsi Israël au commerce phénicien.", "14f7df9d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0910-01-01:0":{"b": ["Adad-nirari II monte sur le trône ; début du redressement néo-assyrien", "e6887ba9"], "d": ["Après un déclin d’environ un siècle et demi, Adad-nirari II commence à rassembler de nouveau les terres assyriennes ; il mène des campagnes contre les Araméens et vers la frontière babylonienne. Sous ses successeurs Assurnasirpal II et Salmanasar III naît l’Empire néo-assyrien.", "beab377b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0929-01-01:0":{"b": ["Le royaume de Salomon est divisé ; Jéroboam Ier fonde au nord le royaume d’Israël", "cfbbc025"], "d": ["Selon la Torah, à la mort de Salomon, l’augmentation des impôts par son fils Roboam entraîne la séparation des dix tribus du nord ; Jéroboam est élu roi et fait de Tirtsa la capitale. Au sud, Juda continue avec la dynastie de David. L’histoire séparée des deux États commence.", "7e2e066d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1099-01-01:0":{"b": ["Teglath-Phalasar Ier marche vers l’ouest et reçoit le tribut des cités phéniciennes de la côte méditerranéenne", "0b2822b7"], "d": ["Teglath-Phalasar Ier atteint les forêts du Liban et des ports tels qu’Arwad, Byblos (Joubaïl) et Sidon, collecte le tribut et fait un voyage en bateau sur la Méditerranée. Comme, après l’effondrement hittite, aucune puissance ne pouvait l’arrêter à l’ouest, ces campagnes inaugurent l’orientation occidentale de l’Assyrie.", "60dc7824"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1109-01-01:0":{"b": ["Nabuchodonosor Ier (Isin II) marche sur l’Élam et reprend la statue de Marduk", "3c551c03"], "d": ["Nabuchodonosor Ier, de la dynastie d’Isin II, marche sur l’Élam et ramène à Babylone la statue de Marduk emportée par Kutir-Nahhunte. La victoire est évoquée dans l’histoire de Babylone comme « le retour de Marduk » et fait du culte de Marduk un culte central.", "fdd1a6a4"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1157-01-01:0":{"b": ["Šutruk-Nahhunte pille le pays de Babylone ; il emporte à Suse les stèles de Hammurabi et de Naram-Sîn", "3d499fcc"], "d": ["Šutruk-Nahhunte, roi du moyen-élamite, attaque Babylone et pille des villes comme Sippar ; des butins tels que la stèle du Code de Hammurabi et la stèle de la Victoire de Naram-Sîn sont transportés à Suse. Son fils Kutir-Nahhunte mettra fin à la dynastie kassite en 1155 av. J.-C.", "2179c21e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1174-01-01:0":{"b": ["À Karkemish, Kuzi-Teshub perpétue l’héritage hittite avec le titre de « Grand Roi »", "0bda7a64"], "d": ["Après la destruction de Hattusa, le royaume de Karkemish se maintient grâce à une branche de la dynastie hittite ; Kuzi-Teshub se proclame « Grand Roi ». Les cités-États louvito-araméennes telles que Karkemish, Malatya (Mélid) et Hama forment le monde « néo-hittite ».", "214de0bd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1179-01-01:0":{"b": ["Hattusa est incendiée et abandonnée ; l’Empire hittite s’effondre", "64d58b6b"], "d": ["La ville de Hattusa est incendiée et abandonnée au temps de Suppiluliuma II, dernier roi hittite ; elle fait partie de l’effondrement de l’âge du Bronze récent, dans un contexte de famine, de conflits internes et de Peuples de la Mer. L’État hittite cède la place aux cités-États néo-hittites telles que Karkemish et Malatya.", "34ee5436"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1224-01-01:0":{"b": ["Tukulti-Ninurta Ier, roi d’Assur, conquiert Babylone ; il emporte la statue de Marduk à Assur", "2cc39251"], "d": ["Tukulti-Ninurta Ier (c. 1243-1207) bat le roi kassite Kaštiliaš IV, s’empare de Babylone, en fait abattre les murailles et transporte la statue de Marduk à Assur. Babylone reste environ sept ans sous le contrôle d’Assur ; l’Assyrie devient l’État le plus puissant du Moyen Âge (du Bronze).", "8abcb249"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1259-01-01:0":{"b": ["Salmanasar Ier fonde la ville de Kalhu (Nimroud)", "e0bf279a"], "d": ["Salmanasar Ier fonde Kalhu sur les rives du Tigre ; la ville sera refondée en 883 par Assurnasirpal II et deviendra la capitale de l’Assyrie.", "8a213755"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1269-01-01:0":{"b": ["Salmanasar Ier annexe Hanigalbat ; Mitanni disparaît", "88620feb"], "d": ["Salmanasar Ier, qui réprime la révolte de Shattuara II, roi de Hanigalbat, rattache directement le pays à l’Assyrie et déporte la population. L’État de Mitanni est effacé de la scène historique par les coups successifs des Hittites et des Assyriens.", "c6c8615e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1274-01-01:0":{"b": ["Untash-Napirisha fonde la ville de Dur-Untash (Tchogha Zanbil) et son ziggourat", "117fbc13"], "d": ["Untash-Napirisha, roi du moyen-élamite, fonde près de Suse, pour le dieu Inshushinak, une ville cultuelle dotée d’un ziggourat ; bien qu’inachevée, la ville fut utilisée plus de deux siècles. Tchogha Zanbil est le ziggourat le mieux conservé d’Iran.", "fe8afd09"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1294-01-01:0":{"b": ["Adad-nirari Ier bat Hanigalbat (reste de Mitanni) et en fait un vassal", "1adb5969"], "d": ["Adad-nirari Ier, petit-fils d’Aššur-uballit Ier, bat le royaume de Hanigalbat, reste de Mitanni frappé par les Hittites, et le réduit à la vassalité ; sous le roi suivant, Salmanasar Ier, le pays sera transformé en province assyrienne. L’Assyrie s’étendit jusqu’à l’Euphrate.", "24941786"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1317-01-01:0":{"b": ["Mursili II bat Arzawa (Anatolie occidentale) et la divise", "4a204e42"], "d": ["Au début de son règne, Mursili II bat la puissante confédération d’Arzawa, en Anatolie occidentale, la divise en sous-royaumes et en fait un vassal hittite. La frontière hittite de l’Anatolie occidentale se rapproche de la côte égéenne.", "c2f9977c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1327-01-01:0":{"b": ["Suppiluliuma place ses fils à la tête des royaumes de Karkemish et d’Alep", "1c5bc8b3"], "d": ["Suppiluliuma administre la Syrie conquise par des « rois » issus de la dynastie hittite : Karkemish et Alep sont donnés à ses fils. La vice-royauté de Karkemish se perpétuera environ 500 ans, même après l’effondrement hittite.", "40eeaf84"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1344-01-01:0":{"b": ["Suppiluliuma Ier bat Mitanni (Tushratta) et prend Alep et Karkemish ; la Syrie du nord passe aux Hittites", "52f9627a"], "d": ["Suppiluliuma bat Tushratta, roi de Mitanni, prend les villes de Syrie, dont Karkemish et Alep ; la partie occidentale des terres de Mitanni est rattachée à l’Empire hittite. Les problèmes intérieurs de l’Égypte au temps d’Akhenaton facilitèrent cette expansion.", "c80de115"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1349-01-01:0":{"b": ["La Babylone kassite figure dans la diplomatie d’Amarna comme grande puissance égale de l’Égypte", "5e7b31a2"], "d": ["Les rois kassites Kadashman-Enlil Ier et Burna-Buriash II appartenaient à la ligue des « grands rois » qui pratiquaient une diplomatie de mariages et de présents avec les pharaons d’Égypte. Les lettres d’Amarna énumèrent les membres de cette ligue : Égypte, Babylone, Mitanni, Hatti et Assur.", "8ecd665d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1349-01-01:1":{"b": ["Suppiluliuma Ier monte sur le trône hittite ; début du Nouvel Empire", "58b301b7"], "d": ["Suppiluliuma Ier est le fondateur du Nouvel Empire hittite et le créateur d'une armée professionnelle de chars de guerre. Son règne de trente-cinq ans transforma les Hittites en un empire s'étendant de l'Anatolie à la Syrie.", "72c7f3af"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1362-01-01:0":{"b": ["Assur-uballit Ier s'affranchit de la tutelle du Mitanni ; l'Assyrie devient indépendante et « grand roi »", "5f280058"], "d": ["Assur, vassale du Mitanni, profita sous Assur-uballit Ier du coup porté par les Hittites au Mitanni pour conquérir son indépendance. Le roi écrivit au pharaon d'Égypte avec le titre de « grand roi » ; cela marque le début de la période médio-assyrienne.", "690fb956"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1399-01-01:0":{"b": ["Alliance du Mitanni et de l'Égypte : paix entre Artatama Ier et Thoutmôsis IV, une princesse mitannienne est envoyée en Égypte comme épouse", "017f13d2"], "d": ["Après l'hostilité, le roi du Mitanni Artatama Ier fit la paix avec le pharaon d'Égypte et envoya sa fille en Égypte. Face à la menace hittite, cette alliance établit l'équilibre égypto-mitannien en Syrie du Nord et prépara la diplomatie de l'époque d'Amarna.", "72df719d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1499-01-01:0":{"b": ["Fondation du royaume du Mitanni (Hanigalbat) dans la région du Khabour et de l'Euphrate", "04920d91"], "d": ["Le royaume hurro-mitannien s'éleva en Haute Mésopotamie dans le vide laissé par l'effondrement de l'ancien Babylone et par le déclin hittite. Sa capitale était Washshukanni ; en quelques décennies, le royaume fit d'Assur et de la Syrie du Nord ses vassaux.", "c6aa0237"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1524-01-01:0":{"b": ["Télipinu monte sur le trône et promulgue un édit ; les relations avec le Kizzuwatna sont fixées par un traité", "e1f0895b"], "d": ["Télipinu refonda le droit hittite par son édit réglant la succession ; le traité conclu avec le Kizzuwatna reconnut ce pays non comme dépendant, mais comme partenaire indépendant. L'Ancien Royaume hittite prend fin avec cet édit.", "47b927f1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1569-01-01:0":{"b": ["La dynastie kassite relève Babylone sous Agum-kakrime ; la statue de Marduk revient de la captivité hittite", "0d525e02"], "d": ["Après le sac de Babylone par le roi hittite Mursili Ier (1595 av. J.-C.), la dynastie kassite domina la ville. La tradition rapporte qu'Agum-kakrime reprit aux Hittites la statue de Marduk ; les Kassites adoptèrent rapidement la culture babylonienne et fondèrent une dynastie qui allait durer environ quatre siècles.", "d91fcc1e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1589-01-01:0":{"b": ["Mursili Ier est assassiné ; le royaume hittite s'affaiblit dans les luttes intestines", "fa5a6ea9"], "d": ["Au retour de Babylone, Mursili Ier fut tué par son beau-frère Hantili et par Zidanta. Les querelles de succession et la nouvelle puissance hurrite/mitannienne laissèrent le royaume affaibli pendant un demi-siècle ; Télipinu ne put rétablir l'ordre que vers 1525 av. J.-C.", "90711b8c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1599-01-01:0":{"b": ["Mursili Ier prend et détruit Alep (Yamhad)", "78c81e82"], "d": ["Mursili Ier, petit-fils et successeur de Hattusili, s'empara du royaume d'Alep, qui avait résisté pendant des décennies, et le détruisit. La fin du Yamhad assura la suprématie hittite en Syrie du Nord et ouvrit la voie à l'expédition de Mursili contre Babylone.", "327a9d55"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1629-01-01:0":{"b": ["Hattusili Ier franchit le Taurus et mène campagne en Syrie du Nord ; Alalakh est détruite, le royaume d'Alep (Yamhad) est attaqué", "92b0d44b"], "d": ["Hattusili Ier (vers 1650-1620) franchit le Taurus et mena campagne en Syrie du Nord ; Alalakh fut détruite et le royaume d'Alep (Yamhad) attaqué, mais Alep ne fut pas prise. L'annexion du Kizzuwatna (Cilicie) n'eut pas lieu lors de cette campagne : le Kizzuwadna oscilla par la suite entre le Hatti et le Mitanni, et l'annexion hittite date du début du Nouvel Empire.", "cf12effe"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1749-01-01:0":{"b": ["Anitta, roi de Kushshara, fait de Kanesh sa capitale et détruit Hattusa", "1eea344b"], "d": ["Selon le Texte d'Anitta, Anitta, roi de Kushshara, unifia plusieurs cités-États d'Anatolie, fit de Nesha (Kanesh) sa capitale, détruisit Hattusa et prononça une malédiction sur son site. Il est cité comme la première tentative d'unification politique des Hittites.", "01d03ad4"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1753-01-01:0":{"b": ["Érection de la stèle du Code de Hammurabi", "b4c80ab9"], "d": ["Le recueil juridique de 282 articles de Hammurabi fut inscrit sur une stèle de basalte et dressé dans les temples. La stèle fut emportée à Suse au XIIe siècle av. J.-C. par le roi élamite Shutruk-Nahhunte et y fut retrouvée en 1901 ; elle se trouve aujourd'hui au Louvre.", "e37255ee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1760-01-01:0":{"b": ["Hammurabi prend Mari ; deux ans plus tard, il en fait raser les remparts", "4f4114b4"], "d": ["Hammurabi, qui s'empara de la Mari de son ancien allié Zimri-Lim, fit aussi détruire les remparts de la ville. La destruction de Mari marque la fin du royaume amorrite de la vallée de l'Euphrate ; Babylone devint la puissance dominante jusqu'à Assur et Eshnunna au nord.", "5bbc9e99"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1762-01-01:0":{"b": ["Hammurabi prend Larsa et bat Rim-Sin Ier ; le sud de la Mésopotamie est rattaché à Babylone", "6f95399b"], "d": ["Hammurabi, après avoir combattu l'Élam et Eshnunna la même année, se tourna vers Larsa et vainquit Rim-Sin Ier. Le sud de la Mésopotamie (Sumer) fut incorporé au royaume de Babylone ; dès lors, cette région est appelée « pays d'Akkad » (Babylonie).", "4be6f89b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1793-01-01:0":{"b": ["Rim-Sin Ier, roi de Larsa, conquiert Isin ; fin de la dynastie d'Isin", "88964ca6"], "d": ["Le roi de Larsa Rim-Sin Ier conquit Isin, sa rivale de longue date, et fit de Larsa la seule grande puissance du sud de la Mésopotamie. La dynastie d'Isin prit ainsi fin après 223 ans de domination.", "f1928082"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1794-01-01:0":{"b": ["Shamshi-Adad prend Mari et nomme son fils Yasmah-Adad roi de Mari", "a428b4eb"], "d": ["Shamshi-Adad, roi d'Assur et d'Ekallatum, s'empara du royaume de Mari sur l'Euphrate, écarta la dynastie de Yahdun-Lim et nomma son fils cadet Yasmah-Adad à Mari. Le « Royaume de Haute Mésopotamie » devint ainsi un empire amorrite allant du Zagros à l'Euphrate.", "8d0ec094"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1799-01-01:0":{"b": ["Alep est mentionnée comme capitale du royaume du Yamhad", "9ad40400"], "d": ["Alep apparaît comme capitale du royaume du Yamhad au XVIIIe siècle av. J.-C. ; la source ne donne pas l'année exacte de la fondation du royaume.", "f9ad9832"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1821-01-01:0":{"b": ["Rim-Sin Ier monte sur le trône de Larsa", "a24e891e"], "d": ["Rim-Sin Ier (vers 1822-1763), au cours d'un règne de 60 ans, rattacha Uruk, Isin et Nippur à Larsa et fit d'une dynastie d'origine élamite la seule maîtresse du sud. Son règne prit fin avec la conquête de Larsa par Hammurabi (1763 av. J.-C.).", "dcc872e1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1835-01-01:0":{"b": ["Destruction du niveau II du karum de Kanesh (Kültepe) ; Anitta s'élève parmi les cités-États d'Anatolie", "084f9472"], "d": ["La destruction du niveau II de Kültepe marque la fin de la première grande période des karum de marchands assyriens. Ensuite, Anitta, roi de Kushshara, fit de Kanesh sa capitale et ouvrit la voie à la fondation politique des Hittites.", "c3514f06"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1899-01-01:0":{"b": ["Des marchands assyriens fondent le karum de Kanesh (Kültepe) ; le réseau commercial de l'ancien assyrien s'étend à l'Anatolie", "b81b0cb9"], "d": ["Les marchands de la ville d'Assur fondèrent en Anatolie, pour le commerce du cuivre, de l'étain et des étoffes, des karum (comptoirs commerciaux) centrés sur Kanesh. Les dizaines de milliers de tablettes cunéiformes découvertes à Kültepe marquent le début de l'écriture et de l'histoire écrite en Anatolie.", "2311e7a7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1924-01-01:0":{"b": ["Gungunum, roi de Larsa, prend Ur à Isin", "6c857c01"], "d": ["Gungunum (vers 1932-1906) fit pour la première fois de Larsa une grande puissance : ses noms d'années proclament la prise d'Ur et un succès contre l'Élam. Avec le passage d'Ur à Larsa commence le confinement d'Isin au nord.", "0108b079"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1960-01-01:0":{"b": ["Naplanum fonde à Larsa une dynastie amorrite indépendante", "86a820f8"], "d": ["Le chef amorrite Naplanum proclama sa souveraineté à Larsa et fonda la seconde grande dynastie du sud après Ur III. Dans sa rivalité séculaire avec Isin, Larsa soumettra d'abord Ur, puis Uruk et Isin.", "ab808712"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2001-01-01:0":{"b": ["Ishbi-Erra chasse la garnison élamite d'Ur ; il soumet Isin, Ur et Nippur", "a68018b2"], "d": ["Après la prise d'Ur par l'Élam (vers 2004), Ishbi-Erra chassa la garnison élamite d'Ur et rattacha Ur et Nippur à Isin. Isin, héritière politique d'Ur, porta pendant des siècles le titre de roi de Sumer et d'Akkad.", "77884c9c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2016-01-01:0":{"b": ["Ishbi-Erra se détache d'Ur III à Isin ; fondation de la dynastie d'Isin", "8d9e3116"], "d": ["Ishbi-Erra, général d'Ibbi-Sin, fonda une dynastie indépendante à Isin tandis que l'État d'Ur III s'effondrait. Dynastie portant le titre de « roi de Sumer et d'Akkad » et perpétuant l'héritage culturel d'Ur, Isin fut pendant environ 220 ans l'une des principales puissances du sud de la Mésopotamie.", "b28db4ec"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2025-01-01:0":{"b": ["Ibbi-Sin monte sur le trône comme dernier roi d'Ur III", "0afa3ef5"], "d": ["Ibbi-Sin (vers 2028-2004), successeur de Shu-Sin, présida au processus de désintégration de l'État : pression amorrite, famine, perte de Suse et des provinces orientales, indépendance d'Ishbi-Erra à Isin. Son règne s'acheva par le sac d'Ur lors de l'attaque élamite/de Simashki.", "19e45ed0"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2031-01-01:0":{"b": ["Shu-Sin construit contre les Amorrites le mur « Muriq-tidnim »", "a09bfd57"], "d": ["Le roi d'Ur III Shu-Sin établit entre le Tigre et l'Euphrate une longue ligne de muraille (Muriq-tidnim, « celui qui tient à distance les Occidentaux ») pour arrêter les nomades amorrites (Martu) venus de l'ouest. Ce mur montre que la pression amorrite mettait l'État en difficulté ; Ur III s'effondra peu après sous cette pression et l'attaque élamite.", "e5ec4e9a"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2091-01-01:0":{"b": ["Shulgi monte sur le trône d'Ur III ; il établit le système administratif centralisé de l'État", "06ea0c7b"], "d": ["Shulgi (vers 2094-2047), fils d'Ur-Nammu, centralisa l'État d'Ur III au cours d'un règne de 48 ans : système de livraison des impôts et du bétail (Puzrish-Dagan), réforme de l'armée, gouvernorats urbains et nouveau calendrier. Ur III est considéré comme l'État ancien le plus avancé de l'histoire mésopotamienne sur le plan bureaucratique.", "d6f42381"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2099-01-01:0":{"b": ["Puzur-Inshushinak, dernier roi awan en Élam (Suse), se libère de la tutelle d'Akkad", "cd91f4a2"], "d": ["Puzur-Inshushinak, dernier roi de la dynastie d'Awan, unifia Suse et le plateau élamite lors de l'effondrement de l'État d'Akkad, sortit de la tutelle akkadienne et laissa des inscriptions en écriture « élamite linéaire » en plus du cunéiforme. Avec l'ascension d'Ur-Nammu, l'Élam repassa sous le contrôle de la Mésopotamie.", "d16fe5e9"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2110-01-01:0":{"b": ["Utu-hegal, roi d'Uruk, bat Tirigan, roi du Gutium, et met fin à la domination gutienne", "aa67620c"], "d": ["Utu-hegal, roi d'Uruk, vainquit et captura sur les bords du Tigre Tirigan, roi du Gutium qui gouvernait Sumer ; les Gutis se retirèrent de Sumer et la souveraineté sumérienne fut rétablie au sud sous la conduite d'Uruk. Ur-Nammu, général d'Utu-hegal, fondera peu après la dynastie d'Ur III.", "45b2db48"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2152-01-01:0":{"b": ["Gutium : selon la Liste royale sumérienne, les Gutis exercèrent la royauté à Sumer après Akkad", "506ad1cb"], "d": ["Descendus du Zagros, les Gutis dominèrent la plus grande partie de la Mésopotamie après l'effondrement de l'État d'Akkad. La Liste royale sumérienne range le Gutium parmi les dynasties situées entre Akkad et Uruk V puis Ur III (21 rois, environ 91-124 ans) ; même si la source est déformée, la domination des Gutis est attestée comme une succession faible plutôt que comme une forte menace extérieure.", "8ee58415"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2229-01-01:0":{"b": ["Naram-Sin bat dans le Zagros les montagnards lullubi (Stèle de la Victoire)", "de84161d"], "d": ["La stèle en relief montrant la victoire de Naram-Sin sur le peuple lullubi (Zagros) est l'œuvre la plus connue de l'art akkadien. La stèle fut ensuite emportée à Suse par le roi élamite Shutruk-Nahhunte et y fut retrouvée en 1898.", "5e6a3ff7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2249-01-01:0":{"b": ["Naram-Sin réprime la « Grande Révolte » : la coalition de cités-États menée par Kish et Uruk est vaincue", "6e9373e8"], "d": ["Au début du règne de Naram-Sin, les cités du sud se soulevèrent contre Akkad sous la direction d'Iphur-Kish, roi de Kish. Naram-Sin vainquit les rebelles en neuf batailles et rétablit la domination akkadienne ; il relata sa victoire dans l'inscription qu'il consacra aux temples des villes.", "c9f67d8c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2260-01-01:0":{"b": ["Naram-Sin monte sur le trône d'Akkad ; il prend le titre de « roi des quatre rives du monde »", "e9e5261d"], "d": ["Naram-Sin (vers 2254-2218), petit-fils de Sargon, dirigea l'État d'Akkad à son apogée. Il fut le premier souverain mésopotamien à utiliser pour lui-même le titre de roi divinisé et l'épithète de « roi des quatre rives ».", "b56983fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2299-01-01:0":{"b": ["Sargon soumet l'Élam (Awan, Suse, Parahshum)", "1b7806f5"], "d": ["Les noms d'années et les inscriptions de Sargon rapportent la défaite de l'Élam (Awan, Parahshum) ; Suse devint une ville akkadienne administrée par des gouverneurs akkadiens et des documents en akkadien. C'est la première fois que l'Élam est rattaché à un empire centré sur la Mésopotamie.", "7214e566"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2299-01-01:1":{"b": ["Sargon bat Lugalzagesi, roi d'Uruk, et rattache les cités-États de Sumer à Akkad", "aad96bc9"], "d": ["Sargon, roi d'Agadé (Akkad), vainquit Lugalzagesi, roi d'Uruk, et réunit en une seule main les cités sumériennes (Uruk, Ur, Lagash, Umma, les environs de Kish). Akkad devint le premier empire à gouverner l'ensemble du sud de la Mésopotamie.", "4ff76ffe"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0231-01-01:0":{"b": ["Ardashir Ier attaque la Mésopotamie romaine ; début des guerres romano-sassanides", "576ebb06"], "d": ["Ardashir Ier, qui avait renversé les Parthes, attaqua en 230-231 les environs de Nisibe et de Carrhae et engagea la lutte avec Rome qui durerait des siècles ; l'expédition de Sévère Alexandre en 232 resta sans résultat.", "7040e38b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0240-01-01:0":{"b": ["Hatra passe aux Sassanides (240-241)", "4f8a58ad"], "d": ["Hatra, cité caravanière et forteresse du désert, fut prise et détruite en 240-241 par Ardashir Ier et Shapur Ier au terme du long conflit romano-parthe. La chute de Hatra priva Rome d'un important allié en Mésopotamie.", "12f25195"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0244-01-01:0":{"b": ["Gordien III meurt près de Ctésiphon ; Philippe l'Arabe conclut avec Shapur une paix pesante", "25d270ee"], "d": ["Gordien III, après une campagne de Mésopotamie d'abord victorieuse, fut vaincu par Shapur et mourut. Son successeur Philippe l'Arabe fit la paix avec les Perses ; dans son inscription (ŠKZ), Shapur s'attribue l'accession de Philippe au trône et déclare avoir reçu un tribut.", "d975e0ec"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0256-01-01:0":{"b": ["Shapur Ier envahit la Syrie et pille Antioche", "6f938d07"], "d": ["Shapur Ier mena une grande expédition contre la province romaine de Syrie, pilla des dizaines de villes dont Antioche et installa les captifs en Iran. Le récit de cette campagne figure dans l'inscription ŠKZ de Naqsh-e Rostam.", "17b20275"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0256-01-01:1":{"b": ["Doura-Europos est prise par les Sassanides", "c7f39e98"], "d": ["La garnison frontalière romaine de Doura-Europos, sur l'Euphrate, tomba après un long siège et fut abandonnée ; les tunnels de siège sassanides et les contre-tunnels romains sont attestés archéologiquement. La ville ne fut plus jamais habitée.", "889d9ece"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0260-01-01:0":{"b": ["Bataille d'Édesse : Shapur Ier capture l'empereur romain Valérien", "654d57e3"], "d": ["Shapur Ier mit en déroute l'armée de l'empereur Valérien près d'Édesse et fit l'empereur lui-même prisonnier. Les reliefs de Bishapur et de Naqsh-e Rostam racontent cette victoire ; la mort de Valérien en captivité sassanide est la plus grande humiliation de l'histoire romaine.", "2da6ab5d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0298-01-01:0":{"b": ["Traité de Nisibe (Nusaybin) : Galère bat Narseh ; les territoires au-delà du Tigre passent à Rome", "3046c0f4"], "d": ["L'attaque de Narseh contre la Mésopotamie romaine s'acheva par la victoire de Galère ; par la paix de 298, cinq régions au-delà du Tigre (Transtigritane) et Nisibe furent cédées à Rome. Le traité fixa pendant un demi-siècle la frontière romano-sassanide.", "4c01c338"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0309-01-01:0":{"b": ["Shapur II monte sur le trône sassanide dès sa naissance (309-379)", "aeed05eb"], "d": ["Shapur II, né de la reine laissée enceinte au milieu de la querelle de succession qui suivit la mort d'Hormizd II, fut couronné avant sa naissance et régna 70 ans. Son règne est la période de la reprise de la lutte avec Rome et de l'entrée des Kouchans sous l'administration sassanide.", "a2b5cb22"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0359-01-01:0":{"b": ["Shapur II assiège et prend Amida (août-octobre 359)", "0b812592"], "d": ["Shapur II, avec ses alliés kouchano-chionites, prit Amida au terme d'un siège de 73 jours, puis s'empara de Singara et de Bézabde. Ammien Marcellin, présent lors du siège, le décrit en détail.", "a86e216d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0363-01-01:0":{"b": ["Traité de Jovien : Nisibe et cinq régions au-delà du Tigre sont cédées aux Sassanides", "6e619831"], "d": ["Pour sauver son armée encerclée, Jovien consentit à céder aux Sassanides Nisibe, Singara et les cinq régions au-delà du Tigre ; Rome perdit les acquis de 298 qui duraient depuis un demi-siècle. La population de Nisibe se replia sur Rome.", "21055f84"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0363-06-26:0":{"b": ["Julien meurt près de Samarra ; la guerre contre les Sassanides tend vers sa fin", "86970a50"], "d": ["Après l'arrêt de l'expédition de Julien contre Ctésiphon par des inondations, alors que l'armée romaine se repliait, l'empereur, blessé lors d'une attaque sassanide à Maranga, mourut. Jovien, choisi par l'armée, fut contraint de conclure un traité avec Shapur II.", "9de62fd5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0387-01-01:0":{"b": ["Traité romano-sassanide de partage de l'Arménie (Théodose Ier – Shapur III)", "228f4d6b"], "d": ["La majeure partie de l'Arménie (l'est) fut laissée à l'influence sassanide et la petite partie occidentale à l'influence romaine ; le royaume arménien des Arsacides s'engagea de fait vers sa fin. Ce partage fixe pendant environ deux siècles la frontière romano-iranienne.", "d65941ae"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0451-01-01:0":{"b": ["Bataille d'Avarayr : Yazdgird II réprime la révolte arménienne", "1bf1df2d"], "d": ["Les nobles arméniens, sous la direction de Vardan Mamikonian, se soulevèrent contre l'imposition du zoroastrisme par les Sassanides ; l'armée fut vaincue à Avarayr et Vardan mourut. Malgré la défaite politique, les Arméniens purent conserver leur christianisme.", "453512fe"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0484-01-01:0":{"b": ["Peroz Ier meurt dans la guerre contre les Hephthalites ; les Sassanides commencent à payer tribut aux Huns", "a418d8ae"], "d": ["Peroz fut anéanti avec son armée face aux Hephthalites (Huns blancs) conduits par Akhshunvar. L'État sassanide se soumit à un lourd tribut et au maintien de son fils Kavad en otage à la cour hephthalite ; la frontière orientale s'affaiblit durablement.", "0e4bc9f8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0496-01-01:0":{"b": ["Kavad Ier est déposé à cause de sa politique favorable aux mazdakites ; il revient en 498-499 avec l'aide des Hephthalites", "9101bfe7"], "d": ["Kavad Ier (roi depuis 488), renversé par la réaction de la noblesse et du clergé, se réfugia chez les Hephthalites et, avec leur soutien militaire, retourna à Ctésiphon en 498-499 et reprit le trône. Le soutien hephthalite fit naître le tribut qu'il devait payer ; la guerre de 502 contre Rome est née de ce besoin.", "06883ad8"]},
"OLAYLAR_ARKEOLOJI_AFRIKA_IRAN:-0299-01-01:0":{"b": ["Djenné-Djenno (Jenne-jeno) : commence", "0eea41b6"], "d": ["Dans le delta intérieur du Niger central, une communauté utilisant le fer est sédentaire depuis le IIIe siècle av. J.-C. ; croissance rapide au Ier millénaire apr. J.-C., apogée de >33 ha en 750-1100 apr. J.-C.", "21f1bbfd"]},
"OLAYLAR_ARKEOLOJI_AFRIKA_IRAN:-0538-01-01:0":{"b": ["Passage de Babylone à Cyrus : commence", "9b9192a1"], "d": ["La 17e année de Nabonide (539/538), Ugbaru et l'armée de Cyrus entrent à Babylone sans combat ; Cyrus entre dans la ville le 3 Arahsamna.", "edeb9ec5"]},
"OLAYLAR_ARKEOLOJI_AFRIKA_IRAN:-0549-01-01:0":{"b": ["Ecbatane (Hamadan) : prise de la capitale mède par Cyrus : commence", "e5219263"], "d": ["La 6e année de Nabonide (550/549 av. J.-C.), Cyrus marche sur Ecbatane, la « ville royale » du roi des Mèdes ; la tradition de 550 comme date du passage de l'État mède à Cyrus et de la fondation de l'Empire achéménide repose sur cette notice.", "198bdfc2"]},
"OLAYLAR_ARKEOLOJI_AFRIKA_IRAN:-0944-01-01:0":{"b": ["Teouma (cimetière lapita), Efate : commence", "03c8a09b"], "d": ["Le plus ancien cimetière connu de l'Océanie lointaine ; établissement lapita à Efate vers 2920-2870 BP (environ 970-920 av. J.-C.). Le même article, d'après une carotte sédimentaire indépendante, dit : « première trace humaine certaine il y a 2800 ans ».", "93f6c6ef"]},
"OLAYLAR_ARKEOLOJI_AFRIKA_IRAN:-4744-01-01:0":{"b": ["Kuk : agriculture sur buttes (mound), phase 2 : commence", "d766025e"], "d": ["Début le plus tardif de l'agriculture indépendante en Nouvelle-Guinée : culture intensive de la banane (Musa), transformation de la forêt en prairie.", "250398ad"]},
"OLAYLAR_ARKEOLOJI_AFRIKA_IRAN:-8114-01-01:0":{"b": ["Marais de Kuk (zone d'agriculture ancienne) : commence", "8aaf2896"], "d": ["Utilisation de plantes et un peu de culture en bordure de marais sur les hauts plateaux de Nouvelle-Guinée (phase 1 : 10220-9910 cal BP = environ 8270-7960 av. J.-C.). Agriculture indépendante au plus tard 6950-6440 cal BP (environ 5000-4490 av. J.-C., phase 2, buttes/mound), agriculture à fossés 4350-3980 cal BP (environ 2400-2030 av. J.-C., phase 3).", "d984e3e0"]},
"OLAYLAR_ARKEOLOJI_AMERIKA:-0099-01-01:0":{"b": ["Teotihuacan : commence", "25bad066"], "d": ["Première occupation au nord-est du bassin de Mexico, phase Patlachique (100 av. J.-C.–1 apr. J.-C.) ; en un siècle, elle devient une ville d'environ 20 000 habitants ; phase Tzacualli (1–100 apr. J.-C.), construction monumentale.", "7208fc3a"]},
"OLAYLAR_ARKEOLOJI_AMERIKA:-0499-01-01:0":{"b": ["Chavín de Huántar : prend fin", "9e7677cd"], "d": ["Centre cérémoniel d'Ancash, dans les Andes ; la céramique noire polie à décor estampé (Janabarroide) se concentre dans l'intervalle 800–500 av. J.-C. (calibré) ; selon Rick et al., le centre perd sa fonction de temple vers 500 av. J.-C., la grande construction ayant décliné auparavant.", "14e680db"]},
"OLAYLAR_ARKEOLOJI_AMERIKA:-0799-01-01:0":{"b": ["La Venta (Olmèque) : commence", "b8278799"], "d": ["Centre olmèque du Formatif moyen dans la plaine côtière du Tabasco ; Complexe A, pyramide et monuments. Son déclin se situe à la fin du Préclassique moyen.", "35d3f75e"]},
"OLAYLAR_ARKEOLOJI_AMERIKA:-0799-01-01:1":{"b": ["El Mirador : commence", "91003976"], "d": ["Dans le bassin du Mirador, accumulation primaire de déchets du Préclassique moyen dans le Groupe Trogón (800–400 av. J.-C.) ; en outre, le complexe pyramidal de Danta (72 m) fut construit au Préclassique récent et final (350 av. J.-C.–250 apr. J.-C.).", "f2c8f716"]},
"OLAYLAR_ARKEOLOJI_AMERIKA:-0899-01-01:0":{"b": ["Aguada Fénix : commence", "aa9d8549"], "d": ["Plus ancienne construction monumentale connue de l'aire maya, au Tabasco : plateau artificiel de 1400 m de long et de 10–15 m de haut, avec 9 chaussées qui en partent.", "687bb6cf"]},
"OLAYLAR_ARKEOLOJI_AMERIKA:-0999-01-01:0":{"b": ["Nakbe : commence", "ec7b1ce2"], "d": ["Ancien centre maya à plateformes monumentales du Préclassique moyen dans le bassin du Mirador (Petén) ; l'un des principaux centres antérieurs à El Mirador.", "1a51ccca"]},
"OLAYLAR_ARKEOLOJI_AMERIKA:-1199-01-01:0":{"b": ["Chavín de Huántar : commence", "9f0c3308"], "d": ["Centre cérémoniel d'Ancash, dans les Andes ; la céramique noire polie à décor estampé (Janabarroide) se concentre dans l'intervalle 800–500 av. J.-C. (calibré) ; selon Rick et al., le centre perd sa fonction de temple vers 500 av. J.-C., la grande construction ayant décliné auparavant.", "14e680db"]},
"OLAYLAR_ARKEOLOJI_AMERIKA:-12599-01-01:0":{"b": ["Monte Verde II : commence", "1f879ca8"], "d": ["Camp de plein air conservé sous la tourbe sur les rives du ruisseau Chinchihuapi, dans le centre-sud du Chili (MV-II) ; site de référence principal pour le peuplement ancien des Amériques. Comme il s'agit d'un camp de courte durée, l'intervalle est une « incertitude sur le moment de formation », et non une durée d'occupation.", "0774af36"]},
"OLAYLAR_ARKEOLOJI_AMERIKA:-1399-01-01:0":{"b": ["San Lorenzo Tenochtitlan (Olmèque) : commence", "5b00af28"], "d": ["Première capitale olmèque, dans le bassin du Coatzacoalcos, au sud du Veracruz ; connue pour son plateau artificiel, ses 20 plateformes latérales et ses sculptures monumentales en pierre.", "9d5a03d1"]},
"OLAYLAR_ARKEOLOJI_AMERIKA:-1649-01-01:0":{"b": ["Poverty Point : commence", "20673dda"], "d": ["Complexe de tertres de terre et de crêtes concentriques en demi-cercle de l'Archaïque récent dans la basse vallée du Mississippi ; plus grand site monumental de chasseurs-cueilleurs du continent.", "6d6551fc"]},
"OLAYLAR_ARKEOLOJI_AMERIKA:-2301-01-01:0":{"b": ["Caral : commence", "c2d12e32"], "d": ["Grand établissement sans céramique, à 23 km à l'intérieur des terres dans la vallée de Supe, avec une architecture monumentale et résidentielle centrale de 65 ha ; l'un des 18 grands établissements sans céramique de la vallée de Supe.", "03008dc0"]},
"OLAYLAR_ARKEOLOJI_AMERIKA:-2999-01-01:0":{"b": ["Complexe de l'Archaïque récent de Norte Chico (Caral-Supe) : commence", "bc725c19"], "d": ["Complexe de grands établissements sans céramique, à architecture monumentale, sur la côte nord-centrale du Pérou ; au cœur du débat sur le seuil de formation des premiers États en Amérique du Sud.", "d322f124"]},
"OLAYLAR_ARKEOLOJI_AMERIKA:-4499-01-01:0":{"b": ["Culture Valdivia (Loma Alta / Real Alto) : commence", "81a3041e"], "d": ["Culture villageoise à céramique du Valdivia, du Formatif ancien, sur la côte sud-ouest de l'Équateur ; Loma Alta, l'un des plus anciens villages de la vallée de Valdivia (deux premières phases), traces de maïs, de manioc, de marante et de piment.", "6b1955ad"]},
"OLAYLAR_ARKEOLOJI_AVRUPA:-2491-01-01:0":{"b": ["Skara Brae : fin", "33b36ea2"], "d": ["Village du Néolithique final en pierre sur le Mainland des Orcades (Grooved Ware) ; la phase 1 débute en 2920–2885, la phase 2 (début en 2840–2685) s'achève vers 2545–2440.", "3897585b"]},
"OLAYLAR_ARKEOLOJI_AVRUPA:-2526-01-01:0":{"b": ["Cercle de sarsens et trilithes de Stonehenge (phase 2) : début", "26e2dd7e"], "d": ["Un fer à cheval de 5 trilithes de sarsen et un cercle de sarsen de 30 montants + 30 linteaux sont dressés ; un double cercle de pierres bleues est ajouté ; l'ensemble de la phase 2 s'étend de 2760–2510 à 2470–2300 cal BC.", "6812d253"]},
"OLAYLAR_ARKEOLOJI_AVRUPA:-2871-01-01:0":{"b": ["Stonehenge (phase 1 : fossé et talus) : début", "9f034b4d"], "d": ["Monument circulaire en terre de 110 m de diamètre (talus + fossé, trous d'Aubrey) ; sépultures à crémation. L'ensemble de la phase 1 commence et s'achève entre 3100–2920 / 2965–2755 cal BC ; les pierres sont dressées aux phases suivantes.", "f05a7dd4"]},
"OLAYLAR_ARKEOLOJI_AVRUPA:-2901-01-01:0":{"b": ["Skara Brae : début", "9b97d2af"], "d": ["Village du Néolithique final en pierre sur le Mainland des Orcades (Grooved Ware) ; la phase 1 débute en 2920–2885, la phase 2 (début en 2840–2685) s'achève vers 2545–2440.", "3897585b"]},
"OLAYLAR_ARKEOLOJI_AVRUPA:-4514-01-01:0":{"b": ["Vinča-Belo Brdo : fin", "0bba5957"], "d": ["Tell du Néolithique récent sur la rive du Danube près de Belgrade ; horizons de maisons incendiées dans la couche supérieure ; l'établissement de culture Vinča prend fin dans la seconde moitié du XLVIe siècle av. J.-C.", "1c22772b"]},
"OLAYLAR_ARKEOLOJI_AVRUPA:-4586-01-01:0":{"b": ["Vinča-Belo Brdo : début", "79e2533a"], "d": ["Tell du Néolithique récent sur la rive du Danube près de Belgrade ; horizons de maisons incendiées dans la couche supérieure ; l'établissement de culture Vinča prend fin dans la seconde moitié du XLVIe siècle av. J.-C.", "1c22772b"]},
"OLAYLAR_ARKEOLOJI_AVRUPA:-4790-01-01:0":{"b": ["Complexe mégalithique de Carnac, secteur du Plasker (Plouharnel) : début", "ad699a9d"], "d": ["Au Plasker, après un hiatus d'environ 300 ans suivant un établissement du Mésolithique final (phase 1 : 5699–5621), sépulture monumentale « pré-mégalithique » du Néolithique moyen ; immédiatement après ou simultanément, alignements de menhirs nord-sud (phase 4 : 4668–4368, 95.4) et fosses de cuisson.", "aefcf3df"]},
"OLAYLAR_ARKEOLOJI_AVRUPA:-5779-01-01:0":{"b": ["Lepenski Vir : fin", "c36b1426"], "d": ["Établissement de chasseurs-cueilleurs mésolithiques dans les Portes de Fer du Danube ; la phase la plus tardive relève du Néolithique ancien (céramique de Starčevo, premiers animaux domestiques). Le début n'est pas un établissement « continu » : la phase Proto-LV peut avoir été discontinue.", "87828629"]},
"OLAYLAR_ARKEOLOJI_AVRUPA:-5974-01-01:0":{"b": ["Phase d'habitat à constructions trapézoïdales de Lepenski Vir (transition Mésolithique-Néolithique, LV I-II) : fin", "eb0f9b81"], "d": ["Phase des sols de constructions trapézoïdales en calcaire et des blocs de roche ornés (sculptures en pierre) ; dans l'article elle est brève (80–210 ans, modèle 2) et suivie du Néolithique ancien de Starčevo.", "f9dec4a3"]},
"OLAYLAR_ARKEOLOJI_AVRUPA:-6119-01-01:0":{"b": ["Phase d'habitat à constructions trapézoïdales de Lepenski Vir (transition Mésolithique-Néolithique, LV I-II) : début", "a365d7f4"], "d": ["Phase des sols de constructions trapézoïdales en calcaire et des blocs de roche ornés (sculptures en pierre) ; dans l'article elle est brève (80–210 ans, modèle 2) et suivie du Néolithique ancien de Starčevo.", "f9dec4a3"]},
"OLAYLAR_ARKEOLOJI_AVRUPA:-6699-01-01:0":{"b": ["Knossos (établissement néolithique) : début", "59ceded0"], "d": ["Premier établissement d'agriculteurs (acéramique) en Crète ; village pionnier de courte durée (~400 ans au plus), suivi d'un long hiatus, puis d'une réoccupation au Néolithique ancien I à céramique.", "52d476a5"]},
"OLAYLAR_ARKEOLOJI_AVRUPA:-9589-01-01:0":{"b": ["Lepenski Vir : début", "ef05f13b"], "d": ["Établissement de chasseurs-cueilleurs mésolithiques dans les Portes de Fer du Danube ; la phase la plus tardive relève du Néolithique ancien (céramique de Starčevo, premiers animaux domestiques). Le début n'est pas un établissement « continu » : la phase Proto-LV peut avoir été discontinue.", "87828629"]},
"OLAYLAR_ARKEOLOJI_CIN:-1009-01-01:0":{"b": ["Nord du Kyushu (amas coquillier d'Uki-Kunden), arrivée de la riziculture : commence", "cfa8d14c"], "d": ["Estimation bayésienne de l'arrivée de la riziculture au nord du Kyushu, au Japon (fin du Jomon / début du Yayoi) ; point d'origine du modèle : l'amas coquillier d'Uki-Kunden (date de riz brûlé la plus ancienne du jeu de données).", "87191a81"]},
"OLAYLAR_ARKEOLOJI_CIN:-1080-01-01:0":{"b": ["Yinxu (Anyang, capitale des Shang tardifs) : phase Di Yi/Di Xin : fin de la dynastie Shang (dernière phase de Yinxu)", "12414bad"], "d": ["Capitale des Shang tardifs ; les os oraculaires (oracle bones) ont été datés par 14C bayésien selon les phases royales : phase Wu Ding 1254-1197, phase Di Yi/Di Xin 1121-1041 ; fin des Shang vers 1041.", "9e06c0ff"]},
"OLAYLAR_ARKEOLOJI_CIN:-1224-01-01:0":{"b": ["Yinxu (Anyang, capitale des Shang tardifs) : phase Wu Ding (14C des os oraculaires) : première phase royale datée de Yinxu", "f5e30523"], "d": ["Capitale des Shang tardifs ; les os oraculaires (oracle bones) ont été datés par 14C bayésien selon les phases royales : phase Wu Ding 1254-1197, phase Di Yi/Di Xin 1121-1041 ; fin des Shang vers 1041.", "9e06c0ff"]},
"OLAYLAR_ARKEOLOJI_CIN:-14914-01-01:0":{"b": ["Grotte de Yuchanyan : commence", "54dee93a"], "d": ["Fragments de céramique dans un camp de chasseurs-cueilleurs en grotte du sud de la Chine (Hunan) ; âge calibré de la céramique : 18 300-15 430 cal BP. Les couches de la grotte couvrent au total ~21 000-13 800 cal BP.", "0f5e9bb2"]},
"OLAYLAR_ARKEOLOJI_CIN:-17549-01-01:0":{"b": ["Grotte de Xianrendong : commence", "b53b4b4f"], "d": ["Dans la grotte du Jiangxi, le contexte des plus anciens fragments de céramique date de 20 000-19 000 cal BP ; chasseurs-cueilleurs du Dernier Maximum glaciaire (avant l'agriculture).", "ab0ae96d"]},
"OLAYLAR_ARKEOLOJI_CIN:-3549-01-01:0":{"b": ["Culture de Liangzhu : commence", "e43cfba3"], "d": ["Culture du Néolithique final du bas Yangzi, à jade et riziculture ; intervalle du modèle : c. 5500-4000 cal BP (~3550-2050 av. J.-C.).", "352ad075"]},
"OLAYLAR_ARKEOLOJI_CIN:-4999-01-01:0":{"b": ["Culture de Yangshao : commence", "1b5a45f3"], "d": ["Culture néolithique fondée sur la culture du millet dans le moyen Fleuve Jaune ; à la phase de Miaodigou, communauté culturelle centrée sur les Plaines centrales.", "2bacf02d"]},
"OLAYLAR_ARKEOLOJI_CIN:-5149-01-01:0":{"b": ["Culture de Hemudu : début", "dca711db"], "d": ["Culture néolithique à riziculture du cours inférieur du Yangzi (baie de Hangzhou) ; fourchette du modèle : c. 7100-5200 cal BP (~5150-3250 av. J.-C.).", "7746fbc3"]},
"OLAYLAR_ARKEOLOJI_CIN:-5949-01-01:0":{"b": ["Culture de Kuahuqiao : début", "0b093ce9"], "d": ["Culture du Néolithique ancien de la baie de Hangzhou, c. 7900-7200 cal BP (~5950-5250 av. J.-C.).", "cd01b412"]},
"OLAYLAR_ARKEOLOJI_CIN:-7049-01-01:0":{"b": ["Culture de Peiligang : début", "c9b31d35"], "d": ["Culture de transition de la chasse-cueillette vers un Néolithique fondé sur l'agriculture sèche, dans la région du cours moyen du fleuve Jaune ; à Tanghu, agriculture mixte de millet et de riz à 7800 cal BP (phytolithes).", "6850970f"]},
"OLAYLAR_ARKEOLOJI_CIN:-8849-01-01:0":{"b": ["Culture de Shangshan : début", "553a041e"], "d": ["Phase ancienne de l'usage du riz dans le cours inférieur du Yangzi, c. 10800-8600 cal BP (~8850-6650 av. J.-C.).", "05825e1e"]},
"OLAYLAR_ARKEOLOJI_D2_AFRIKA_AMERIKA:-0374-01-01:0":{"b": ["Incendie de la première place de San Martín Tilcajete par Monte Albán : la place est incendiée (attaque de Monte Albán)", "718e1374"], "d": ["À la fin de Monte Albán I ancien, la première place du centre rival de Tilcajete fut incendiée ; une nouvelle place fut ensuite établie sur une crête plus défendable. Son palais (structure 7) brûla avec des dates calibrées de 100 av. J.-C.-140 apr. J.-C., son temple (structure 16) de 165 av. J.-C.-155 apr. J.-C.", "bf888151"]},
"OLAYLAR_ARKEOLOJI_D2_AFRIKA_AMERIKA:-0659-01-01:0":{"b": ["San José Mogote : temple incendié (structure 28) : le temple de la structure 28 brûle", "c677f22f"], "d": ["Au milieu de la phase Rosario, le temple principal de San José Mogote (structure 28) fut incendié lors d'une attaque ; à sa place fut édifiée la structure 37 (840-400 av. J.-C.).", "3c142b66"]},
"OLAYLAR_ARKEOLOJI_D2_AFRIKA_AMERIKA:-0999-01-01:0":{"b": ["Ceibal (Seibal, Pasión, Guatemala) : phase Real 1 : première communauté sédentaire", "dd836649"], "d": ["Au Préclassique moyen, premier complexe cérémoniel formel avec céramique (groupe E) ~950 av. J.-C. ; l'un des plus anciens exemples d'architecture monumentale des basses terres mayas dans la région de la Pasión. Préclassique moyen ancien : Real 1 (1000-850), Real 2 (850-800), Real 3 (800-700) ; Préclassique moyen récent : Escoba 1 (700-600), 2 (600-450), 3 (450-350).", "a82b67e5"]},
"OLAYLAR_ARKEOLOJI_D2_AFRIKA_AMERIKA:-2549-01-01:0":{"b": ["Kerma ancien (Kerma Ancien) : début du Kerma ancien", "20c8acd2"], "d": ["Première phase de la culture de Kerma (Kerma ancien, phase distinguée par Honegger avant Kerma ancien 0, en 2800 av. J.-C.) ; cette phase se situe entre le Pré-Kerma et le Kerma moyen.", "a023541c"]},
"OLAYLAR_ARKEOLOJI_D2_AFRIKA_AMERIKA:-2799-01-01:0":{"b": ["Tradition religieuse de Kotosh (Kotosh, Pérou) : début de la tradition religieuse de Kotosh", "3a89f318"], "d": ["Tradition religieuse reconnaissable à un bâtiment circulaire, un foyer central et un conduit de ventilation souterrain ; site éponyme : Kotosh (Huánuco). La Seductora est un petit mausolée familial.", "ceb0e477"]},
"OLAYLAR_ARKEOLOJI_D2_AFRIKA_AMERIKA:-2834-01-01:0":{"b": ["Gobero (cercle du Ténéré, Niger) : la plus récente sépulture ténéréenne", "c42fb27f"], "d": ["Nécropole lacustre saharienne présentant deux phases d'occupation distinctes au paléolac : chasseurs-pêcheurs-cueilleurs de l'Holocène ancien (Kiffien), plus ancien cimetière connu du Sahara vers 7500 av. J.-C. ; intervalle aride (6200-5200 av. J.-C.) ; puis pasteurs ténéréens (5200-2500 av. J.-C.).", "95283ef9"]},
"OLAYLAR_ARKEOLOJI_D2_AFRIKA_AMERIKA:-3001-01-01:0":{"b": ["Lothagam North Pillar Site (lac Turkana, Kenya) : début de l'utilisation de la plateforme funéraire monumentale", "12c308db"], "d": ["Le plus ancien et le plus grand cimetière monumental d'Afrique de l'Est : cavité funéraire de >=580 personnes (119,5 m2), plateforme bordée de pierres ; premiers pasteurs du bassin du Turkana.", "4608bf05"]},
"OLAYLAR_ARKEOLOJI_D2_AFRIKA_AMERIKA:-3184-01-01:0":{"b": ["Vallée de Tehuacán, grotte de San Marcos - plus ancien maïs (partiellement domestiqué) : le plus ancien maïs (San Marcos, Tehuacán)", "23af2d5a"], "d": ["Parmi les 3 épis de la grotte de San Marcos, refouillée en 2012, les plus anciens datent de 5 300-4 970 cal BP ; ils correspondent à la plus ancienne phase culturelle de Tehuacán.", "c75bbbbe"]},
"OLAYLAR_ARKEOLOJI_D2_AFRIKA_AMERIKA:-3749-01-01:0":{"b": ["Los Morteros (vallée de Chao, Pérou) - plus ancienne architecture monumentale en adobe : la plus ancienne architecture monumentale en adobe des Amériques", "1ddb48c2"], "d": ["Plus ancienne structure monumentale en adobe connue sur la côte du nord du Pérou (vallée de Chao) ; résumé : « invention of adobe architecture before 5,100 calendar years B.P. » Liée aux pluies d'El Niño. Cet article ne fournit pas de données pour Sechín Alto/Sechín Bajo.", "16c7015b"]},
"OLAYLAR_ARKEOLOJI_D2_AFRIKA_AMERIKA:-7699-01-01:0":{"b": ["Gobero (cercle du Ténéré, Niger) : début de l'occupation de l'Holocène ancien (Kiffien)", "b78f5299"], "d": ["Nécropole lacustre saharienne présentant deux phases d'occupation distinctes au paléolac : chasseurs-pêcheurs-cueilleurs de l'Holocène ancien (Kiffien), plus ancien cimetière connu du Sahara vers 7500 av. J.-C. ; intervalle aride (6200-5200 av. J.-C.) ; puis pasteurs ténéréens (5200-2500 av. J.-C.).", "95283ef9"]},
"OLAYLAR_ARKEOLOJI_D2_ANADOLU_EGE:-0546-01-01:0":{"b": ["Sardes — prise par les Perses : le roi perse Cyrus prend Sardes (fin de la Lydie)", "d37e3614"], "d": ["Sardes, capitale de la Lydie, tomba aux mains du Perse Cyrus ; dans la couche de destruction furent trouvés des remparts et des maisons brûlés ainsi que, sous le niveau de destruction, des monnaies de l'époque de Crésus.", "4ec7b32f"]},
"OLAYLAR_ARKEOLOJI_D2_ANADOLU_EGE:-0739-01-01:0":{"b": ["Gordion — tumulus MM (tumulus de Midas) : tumulus de Midas (MM) : année d'abattage des arbres de la chambre funéraire (dendrochronologie)", "e017e788"], "d": ["Le plus grand tumulus phrygien de Gordion ; l'année d'abattage est datée par les cernes du bois de la chambre intérieure (genévrier ; année de l'écorce conservée), abattage ≈ année de construction du tumulus.", "8ba1386d"]},
"OLAYLAR_ARKEOLOJI_D2_ANADOLU_EGE:-1612-01-01:0":{"b": ["Akrotiri (Théra/Santorin) — éruption minoenne : éruption volcanique de Théra (Santorin)", "d7e07e20"], "d": ["Akrotiri (établissement de Théra de culture minoenne) fut enseveli sous la téphra lors de l'éruption du volcan ; l'éruption a été datée au radiocarbone à partir d'un rameau d'olivier et de l'assemblage de graines d'Akrotiri.", "06354b35"]},
"OLAYLAR_ARKEOLOJI_D2_ANADOLU_EGE:-7999-01-01:0":{"b": ["Pınarbaşı (bassin de Konya, Karaman) : l'occupation prend fin", "a1774f7a"], "d": ["Tell d'habitat ancien commencé à la transition Pléistocène/Holocène et ayant duré tout le IXe millénaire cal BC ; la culture des céréales semble n'y être jamais entrée (contrairement à Boncuklu).", "b357ccb2"]},
"OLAYLAR_ARKEOLOJI_D2_ANADOLU_EGE:-8099-01-01:0":{"b": ["Boncuklu Höyük (bassin de Konya, Çumra) : l'occupation prend fin (phase tardive)", "7a2767fe"], "d": ["À Boncuklu, la culture fut adoptée par les chasseurs-cueilleurs locaux dans la seconde moitié du IXe millénaire ; la communauté est interprétée comme l'ancêtre de Çatalhöyük Est (Çatalhöyük East à partir de 7100 cal BC).", "1c59c47d"]},
"OLAYLAR_ARKEOLOJI_D2_ANADOLU_EGE:-8299-01-01:0":{"b": ["Boncuklu Höyük (bassin de Konya, Çumra) : l'occupation néolithique commence (phase ancienne)", "2c1735f9"], "d": ["À Boncuklu, la culture fut adoptée par les chasseurs-cueilleurs locaux dans la seconde moitié du IXe millénaire ; la communauté est interprétée comme l'ancêtre de Çatalhöyük Est (Çatalhöyük East à partir de 7100 cal BC).", "1c59c47d"]},
"OLAYLAR_ARKEOLOJI_D2_ANADOLU_EGE:-9599-01-01:0":{"b": ["Pınarbaşı (bassin de Konya, Karaman) : l'occupation néolithique commence (première phase attestée)", "fbd1fd79"], "d": ["Tell d'habitat ancien commencé à la transition Pléistocène/Holocène et ayant duré tout le IXe millénaire cal BC ; la culture des céréales semble n'y être jamais entrée (contrairement à Boncuklu).", "b357ccb2"]},
"OLAYLAR_ARKEOLOJI_D2_CIN_DOGU_ASYA:-0208-01-01:0":{"b": ["Empire xiongnu (Hunnu) : fondation de l'Empire xiongnu (sources han)", "aeebffbc"], "d": ["Premier empire des steppes d'Asie centrale, fondé avec l'ascension du chanyu Modu (Maodun) en 209 av. J.-C. ; longue rivalité avec les Han ; l'empire formel prend fin en 91 apr. J.-C. avec la défaite des Xiongnu du Nord.", "e8d38a61"]},
"OLAYLAR_ARKEOLOJI_D2_CIN_DOGU_ASYA:-1049-01-01:0":{"b": ["Civilisation de Sanxingdui (Guanghan, Sichuan) : la civilisation de Sanxingdui prend fin", "ada0676b"], "d": ["Civilisation du bassin du Sichuan, indépendante des Shang, qui produisit du bronze, de l'or, du jade et des masques de bronze. Selon Zhu, la civilisation prend forme à la phase 2 (période II ; grande enceinte urbaine) et s'achève à la fin des Shang / au début des Zhou (~1050).", "e4cc7166"]},
"OLAYLAR_ARKEOLOJI_D2_CIN_DOGU_ASYA:-1105-01-01:0":{"b": ["Fosses sacrificielles de Sanxingdui (K3, K4, K6, K8) — événement d'enfouissement : les fosses sacrificielles (K3/K4/K6/K8) sont comblées (AMS)", "50b4078d"], "d": ["Les fosses nos 3, 4, 6 et 8 (nouvellement fouillées) ont été comblées, avec une probabilité de 95,4 %, entre 1201 et 1012 av. J.-C. ; fin des Shang. Les fragments qui se raccordent montrent que les fosses 1, 2, 3, 4, 7 et 8 ont été comblées à la même époque.", "330ba607"]},
"OLAYLAR_ARKEOLOJI_D2_CIN_DOGU_ASYA:-13749-01-01:0":{"b": ["Début du Jōmon : période Sōsōki (Incipient) : la phase Sōsōki (phase initiale du Jomon) commence", "a893e4a1"], "d": ["Phase initiale de la culture Jōmon (archipel japonais) : céramique, chasse-cueillette à sédentarité temporaire. Le début est placé il y a ~15 500 ans, avec les premiers vases à décor appliqué en relief linéaire (Ryūsenmon).", "d2298f8f"]},
"OLAYLAR_ARKEOLOJI_D2_CIN_DOGU_ASYA:-13799-01-01:0":{"b": ["Ōdai Yamamoto I (Aomori) — l'un des plus anciens sites à céramique du Japon : invention de la plus ancienne céramique (pré-Jomon/ancien)", "70363174"], "d": ["À Soto-ga-hama, des fragments de céramique sans décor (46 pièces) associés à des outils de pierre ; parmi les plus anciens récipients d'argile cuite de l'archipel japonais et de l'Asie orientale. Les dépôts de suie/charbon sur les fragments ont été datés par AMS.", "f15b99aa"]},
"OLAYLAR_ARKEOLOJI_D2_CIN_DOGU_ASYA:-1519-01-01:0":{"b": ["Erlitou (culture d'Erlitou, Yanshi) : la phase IV s'achève", "0a0f4627"], "d": ["Site éponyme de la culture d'Erlitou, dans le xian de Yanshi (Henan) ; grand centre à quatre phases (I–IV). Dates 14C sériées des phases : I 1750–1680, II 1680–1610, III 1610–1560, IV 1560–1520 av. J.-C.", "ddac0886"]},
"OLAYLAR_ARKEOLOJI_D2_CIN_DOGU_ASYA:-1599-01-01:0":{"b": ["Dynastie Xia (tradition écrite / chronologie du Projet de périodisation — PAS une date archéologique) : les Xia prennent fin, les Shang commencent (tradition écrite)", "ffbacfbe"], "d": ["Dans la périodisation traditionnelle, les Xia vont d'environ 2070 à 1600 av. J.-C. (471 ans). Cette date est le produit d'une tradition écrite de type Shiji/Zhushu Jinian et du calcul du projet ; il n'existe aucun document écrit contemporain.", "814997db"]}
});
